package legacy.expecteddrops;

/** How the player usually kills a boss you can do solo or duo (Royal Titans, Yama). */
public enum DuoMode
{
	DUO("Duo"),
	SOLO("Solo"),
	MIXED("Some of each");

	private final String name;

	DuoMode(String name)
	{
		this.name = name;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package legacy.expecteddrops;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import legacy.expecteddrops.ui.ItemView;
import net.runelite.client.config.Range;

@ConfigGroup(ExpectedDropsConfig.GROUP)
public interface ExpectedDropsConfig extends Config
{
	String GROUP = "expecteddrops";

	@ConfigItem(
		keyName = "autoSwitch",
		name = "Follow last kill",
		description = "Switch the panel to the boss you just killed",
		position = 1
	)
	default boolean autoSwitch()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showWelcome",
		name = "Show welcome guide",
		description = "Show the getting-started guide at the top of the panel",
		position = 2
	)
	default boolean showWelcome()
	{
		return true;
	}

	@ConfigSection(
		name = "Chat messages",
		description = "What On Rate says in your chat box",
		position = 3
	)
	String chatSection = "chat";

	@ConfigItem(
		keyName = "syncReminders",
		name = "Sync reminders",
		description = "After you kill a boss that isn't loaded yet, say in chat which collection log page to open. Once per boss each session.",
		position = 4,
		section = chatSection
	)
	default boolean syncReminders()
	{
		return true;
	}

	@ConfigItem(
		keyName = "dropMessages",
		name = "Drop messages",
		description = "When a unique drops, say in chat how many kills it took against the drop rate. Also sums up each trip when it ends.",
		position = 5,
		section = chatSection
	)
	default boolean dropMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "milestoneMessages",
		name = "Dry milestone messages",
		description = "Say in chat when an item passes 2x, 3x, 5x or 10x its drop rate without dropping",
		position = 6,
		section = chatSection
	)
	default boolean milestoneMessages()
	{
		return true;
	}

	@ConfigSection(
		name = "Display",
		description = "What the panel and overlay show",
		position = 6
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "itemView",
		name = "Item view",
		description = "How items (and bosses in the account overview) are drawn: bars, tabs, a table, rings or a gauge",
		position = 7,
		section = displaySection
	)
	default ItemView itemView()
	{
		return ItemView.TARGET_BARS;
	}

	@ConfigItem(
		keyName = "accountPage",
		name = "Account overview page",
		description = "The account overview page that was open last (tab, sort order and Items list). "
			+ "Changed from the panel, so it's not listed here",
		position = 7,
		section = displaySection,
		hidden = true
	)
	default String accountPage()
	{
		return "";
	}

	@ConfigItem(
		keyName = "showGeValue",
		name = "GP value",
		description = "Show the GP value tile on boss pages and the account overview: your uniques weighed by their GE price",
		position = 8,
		section = displaySection
	)
	default boolean showGeValue()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTopItems",
		name = "Items tab",
		description = "Show the Items tab on the account overview: your driest and luckiest items, pets and single drops across every boss",
		position = 9,
		section = displaySection
	)
	default boolean showTopItems()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showLuckGraph",
		name = "Luck graph",
		description = "Whether the Luck over time section in the account overview is open. Opened and closed "
			+ "by clicking its title in the panel, so it's not listed here",
		position = 10,
		section = displaySection,
		hidden = true
	)
	default boolean showLuckGraph()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showTripCard",
		name = "Trip card",
		description = "Show kills, uniques and expected for your current trip on the boss page",
		position = 11,
		section = displaySection
	)
	default boolean showTrip()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "In-game overlay",
		description = "Show a small box on the game screen with this trip's kills, uniques, expected and luck while you kill a boss. Not shown at raids, the Inferno or the Fight Caves.",
		position = 13,
		section = displaySection
	)
	default boolean showOverlay()
	{
		return false;
	}

	@ConfigItem(
		keyName = "colourBlind",
		name = "Colour-blind colours",
		description = "Use orange to blue instead of red to green for dry to spooned",
		position = 14,
		section = displaySection
	)
	default boolean colourBlind()
	{
		return false;
	}

	@ConfigSection(
		name = "Team bosses",
		description = "At team bosses your chance of a unique scales with your share of the damage",
		position = 20
	)
	String teamSection = "team";

	@ConfigItem(
		keyName = "detectTeamSize",
		name = "Count your team",
		description = "At Nex, Yama, the Hueycoatl and the Corporeal Beast, count the players who hit the boss with you; at Zalcano, "
			+ "the players around you. You get an even share of the kill (a quarter with four players). Also counts your team at the end of each "
			+ "Fractured Archive raid. Kills from before use the first team On Rate counted (Yama: the setting below).",
		position = 50,
		section = teamSection
	)
	default boolean detectTeamSize()
	{
		return true;
	}

	@ConfigItem(
		keyName = "royalTitansTeam",
		name = "Royal Titans: how you kill them",
		description = "Counted as duo kills unless you change it. A duo gets about half the uniques of a solo kill; the pet chance stays the same.",
		position = 51,
		section = teamSection
	)
	default DuoMode royalTitansMode()
	{
		return DuoMode.DUO;
	}

	@ConfigItem(
		keyName = "royalTitansSoloKills",
		name = "Royal Titans: solo kills",
		description = "Only used with 'Some of each': how many of your Royal Titans kills were solo. The rest count as duo.",
		position = 52,
		section = teamSection
	)
	@Range(min = 0)
	default int royalTitansSoloKills()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "yamaTeam",
		name = "Yama: earlier kills",
		description = "How you killed Yama before On Rate counted your team (it counts it from now on). "
			+ "Counted as duo kills unless you change it. A duo gets about half the uniques of a solo kill; the pet chance stays the same.",
		position = 53,
		section = teamSection
	)
	default DuoMode yamaMode()
	{
		return DuoMode.DUO;
	}

	@ConfigItem(
		keyName = "yamaSoloKills",
		name = "Yama: solo kills",
		description = "Only used with 'Some of each': how many of those earlier Yama kills were solo. The rest count as duo.",
		position = 54,
		section = teamSection
	)
	@Range(min = 0)
	default int yamaSoloKills()
	{
		return 0;
	}

	@ConfigSection(
		name = "Raids",
		description = "How On Rate works out each raid's purple chance",
		position = 30
	)
	String raidsSection = "raids";

	@ConfigSection(
		name = "Raid purple chances",
		description = "Used where On Rate has no raid points: raids from before you installed it, and Theatre of Blood. "
			+ "The Fractured Archive team chance is used for every Archive raid. Most players can leave these alone.",
		position = 40
	)
	String raidChancesSection = "raidChances";

	@ConfigItem(
		keyName = "readRaidPoints",
		name = "Use raid points",
		description = "Work out each raid's purple chance as it ends: from your points (Chambers of Xeric, Tombs of Amascut), the end-of-raid team size (Theatre of Blood) or your share of the damage (The Fractured Archive). Raids without them use the chances below.",
		position = 31,
		section = raidsSection
	)
	default boolean readRaidPoints()
	{
		return true;
	}

	@ConfigItem(
		keyName = "importRaidTimes",
		name = "Import times from Raid Data Tracker",
		description = "If you also use the Raid Data Tracker plugin, read your Chambers of Xeric, Tombs of Amascut and Theatre of Blood "
			+ "raid times from its saved files when you log in, so those raids use your own times straight away. Only read, nothing in that plugin changes.",
		position = 32,
		section = raidsSection
	)
	default boolean importRaidTimes()
	{
		return true;
	}

	@ConfigItem(
		keyName = "coxUniqueChance",
		name = "CoX Normal (%)",
		description = "Your chance of a unique per normal Chambers raid, for raids without points. Every 8,676 of your personal points is 1%, so 30,000 points is about 3.5%.",
		position = 32,
		section = raidChancesSection
	)
	default double coxUniqueChance()
	{
		return 3.5;
	}

	@ConfigItem(
		keyName = "coxCmPurpleChance",
		name = "CoX Challenge Mode (%)",
		description = "Your chance of a unique per Challenge Mode raid, for raids without points. Same formula as normal mode; a Challenge Mode raid is usually 6.3 to 6.9%.",
		position = 33,
		section = raidChancesSection
	)
	default double coxCmUniqueChance()
	{
		return 6.6;
	}

	@ConfigItem(
		keyName = "tobTeamChance",
		name = "ToB Normal team (%)",
		description = "The team's chance of a unique per normal Theatre of Blood raid: about 1 in 9.1 raids (11%) with no deaths. On Rate divides it by the team size to get yours.",
		position = 34,
		section = raidChancesSection
	)
	default double tobTeamChance()
	{
		return 11.0;
	}

	@ConfigItem(
		keyName = "tobHmTeamChance",
		name = "ToB Hard Mode team (%)",
		description = "The team's chance of a unique per Hard Mode raid: about 1 in 7.7 raids (13%). On Rate divides it by the team size to get yours.",
		position = 35,
		section = raidChancesSection
	)
	default double tobHmTeamChance()
	{
		return 13.0;
	}

	@ConfigItem(
		keyName = "tobTeamSize",
		name = "ToB team size",
		description = "How many players you usually raid Theatre of Blood with. Your share of the team's purples is 1 / team size. Raids where On Rate read the end-of-raid board use their real team size.",
		position = 36,
		section = raidsSection
	)
	@Range(min = 1, max = 5)
	default int tobTeamSize()
	{
		return 4;
	}

	@ConfigItem(
		keyName = "toaEntryUniqueChance",
		name = "ToA Entry Mode (%)",
		description = "Your chance of a unique per Entry Mode raid without points. Very low: at low raid levels most uniques turn into other loot.",
		position = 37,
		section = raidChancesSection
	)
	default double toaEntryUniqueChance()
	{
		return 0.75;
	}

	@ConfigItem(
		keyName = "toaNormalUniqueChance",
		name = "ToA Normal (%)",
		description = "Your chance of a unique per normal Tombs raid without points. It depends on raid level and your points; the OSRS Wiki's ToA page has a calculator.",
		position = 38,
		section = raidChancesSection
	)
	default double toaUniqueChance()
	{
		return 2.5;
	}

	@ConfigItem(
		keyName = "toaExpertUniqueChance",
		name = "ToA Expert Mode (%)",
		description = "Your chance of a unique per Expert Mode raid without points. It depends on raid level and your points; the OSRS Wiki's ToA page has a calculator.",
		position = 39,
		section = raidChancesSection
	)
	default double toaExpertUniqueChance()
	{
		return 5.0;
	}

	@ConfigItem(
		keyName = "tfaTeamSize",
		name = "TFA team size",
		description = "How many players you usually do The Fractured Archive with (1 to 8), for raids where On Rate couldn't count your team. "
			+ "Assumes an even share of the damage. Raids from now on use the players around you at the end.",
		position = 45,
		section = raidsSection
	)
	@Range(min = 1, max = 8)
	default int tfaTeamSize()
	{
		return 2;
	}

	@ConfigItem(
		keyName = "tfaTeamChance",
		name = "TFA team (%)",
		description = "The team's chance of a unique per Fractured Archive raid for a solo or duo with no deaths: 1 in 14 (7.14%). "
			+ "Each player beyond two adds 4% of it (x1.24 for eight), and you get your share of the damage. Every raid uses it, including ones where On Rate counted your team.",
		position = 46,
		section = raidChancesSection
	)
	default double tfaTeamChance()
	{
		return 100 / 14.0;
	}
}

