	/** This trip at the boss you are killing, for the overlay. */
	private void updateOverlayInfo()
	{
		TripStats trip = tracker.tripStats();
		if (trip == null)
		{
			overlayInfo = null;
			return;
		}
		BossStats stats = tracker.stats(trip.getBoss(), raidSettings());
		if (stats == null || Tracker.isLongRun(stats.getBoss()))
		{
			// a raid, the Inferno or the Fight Caves takes too long for the box to stay up to date
			overlayInfo = null;
			return;
		}
		Palette.setColourBlind(config.colourBlind());
		String units = Tracker.unit(stats.getBoss());
		String one = Tracker.unitOne(stats.getBoss());
		String tripText = String.format(java.util.Locale.ROOT, "%,d %s \u00b7 %d unique%s", trip.getKills(), trip.getKills() == 1 ? one : units,
			trip.getReceived(), trip.getReceived() == 1 ? "" : "s");
		double tripLuck = trip.getLuck();
		String tripExpected = trip.getExpected() >= 10 ? String.format(java.util.Locale.ROOT, "%.1f", trip.getExpected())
			: String.format(java.util.Locale.ROOT, "%.2f", trip.getExpected());
		overlayInfo = new OverlayInfo(trip.getBoss(), tripText, tripExpected,
			Double.isNaN(tripLuck) ? "-" : DropMath.verdict(tripLuck),
			Double.isNaN(tripLuck) ? java.awt.Color.WHITE : Palette.luck(tripLuck).brighter(),
			trip.getLastMillis());
	}

	/** Item names that fit the overlay: cut at a word, "Deadeye prayer scroll" becomes "Deadeye prayer...". */
	static String shortName(String label)
	{
		return shortName(label, 18);
	}

	/** Same, cut to {@code max} characters (the overlay's driest line shares its row with the streak). */
	static String shortName(String label, int max)
	{
		if (label.length() <= max)
		{
			return label;
		}
		int cut = label.lastIndexOf(' ', max - 3);
		return label.substring(0, cut > 0 ? cut : max - 3) + "...";
	}

	RaidSettings raidSettings()
	{
		return new RaidSettings()
		{
			@Override
			public double uniqueChance(String raid)
			{
				return raidChance(raid);
			}

			@Override
			public int teamSize(String raid)
			{
				if (raid.startsWith("tob"))
				{
					return tobTeamSize();
				}
				return "fractured".equals(raid) ? tfaTeamSize() : 1;
			}

			@Override
			public double tfaBaseChance()
			{
				return ExpectedDropsPlugin.this.tfaBaseChance();
			}

			@Override
			public double contribution(String team, int kills)
			{
				if (!isDuoTeam(team) || kills <= 0)
				{
					return 1.0;
				}
				int duo = duoKills(team, kills);
				return (kills - duo + 0.5 * duo) / kills;
			}

			@Override
			public String contributionNote(String team, int kills)
			{
				if (!isDuoTeam(team))
				{
					return null;
				}
				int duo = duoKills(team, kills);
				if (duo == 0)
				{
					return "Counted as solo kills. If you duo, change it under Team bosses in the settings.";
				}
				if (duo >= kills)
				{
					return "Counted as duo kills: about half the uniques of a solo kill (the pet chance stays the same). "
						+ "If you solo, change it under Team bosses in the settings.";
				}
				return String.format(java.util.Locale.ROOT, "Counted as %,d solo and %,d duo kills (a duo gives about half the uniques).",
					kills - duo, duo);
			}
		};
	}

	private int tobTeamSize()
	{
		return Math.max(1, Math.min(5, config.tobTeamSize()));
	}

	private int tfaTeamSize()
	{
		return Math.max(1, Math.min(RaidChance.TFA_MAX_TEAM, config.tfaTeamSize()));
	}

	/** The Fractured Archive's team chance for a duo with no deaths, from the settings. */
	private double tfaBaseChance()
	{
		return Math.max(0, Math.min(100, config.tfaTeamChance())) / 100.0;
	}

	private static boolean isDuoTeam(String team)
	{
		return "royalTitans".equals(team) || "yama".equals(team);
	}

	/** How many of these kills count as duo kills, from the boss's solo/duo setting. */
	private int duoKills(String team, int kills)
	{
		boolean yama = "yama".equals(team);
		DuoMode mode = yama ? config.yamaMode() : config.royalTitansMode();
		int solo = yama ? config.yamaSoloKills() : config.royalTitansSoloKills();
		switch (mode)
		{
			case DUO:
				return kills;
			case SOLO:
				return 0;
			case MIXED:
				return kills - Math.max(0, Math.min(kills, solo));
			default:
				return kills;
		}
	}

	private double raidChance(String raid)
	{
		double percent;
		switch (raid)
		{
			case "cox":
				percent = config.coxUniqueChance();
				break;
			case "coxCm":
				percent = config.coxCmUniqueChance();
				break;
			case "tob":
				percent = config.tobTeamChance() / tobTeamSize();
				break;
			case "tobHm":
				percent = config.tobHmTeamChance() / tobTeamSize();
				break;
			case "toaEntry":
				percent = config.toaEntryUniqueChance();
				break;
			case "toa":
				percent = config.toaUniqueChance();
				break;
			case "toaExpert":
				percent = config.toaExpertUniqueChance();
				break;
			case "fractured":
				// an even share of the damage, no deaths, at the usual team size
				return RaidChance.tfaEven(tfaTeamSize(), 0, tfaBaseChance());
			default:
				percent = 0;
		}
		return Math.max(0, Math.min(100, percent)) / 100.0;
	}

	/** Your real Slayer level (not boosted), -1 until the game has sent it. Set on the client thread, read by the panel. */
	private volatile int slayerLevel = -1;

	/** Per account: the last Slayer level seen, so the Time page can hide the Slayer bosses before the game sends the stats. */
	private static final String SLAYER_LEVEL_KEY = "slayerLevel";

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == Skill.SLAYER)
		{
			setSlayerLevel(event.getLevel());
		}
	}

	/** Takes a Slayer level (from the game, or the one remembered) and redraws the Time page when it changed. */
	private void setSlayerLevel(int level)
	{
		if (level < 1 || level == slayerLevel)
		{
			return;
		}
		slayerLevel = level;
		if (configManager.getRSProfileKey() != null)
		{
			configManager.setRSProfileConfiguration(ExpectedDropsConfig.GROUP, SLAYER_LEVEL_KEY, String.valueOf(level));
		}
		if (panel != null)
		{
			// the Time page hides the Slayer bosses above it
			SwingUtilities.invokeLater(panel::refresh);
		}
	}

	/**
	 * Finds the Slayer level when logged in: from the game when it already has the stats (turning the
	 * plugin on while logged in sends no stat event), else the one remembered for this account.
	 * Runs on the client thread.
	 */
	private void readSlayerLevel()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		int real = client.getRealSkillLevel(Skill.SLAYER);
		if (real > 1)
		{
			setSlayerLevel(real);
			return;
		}
		if (slayerLevel < 1 && configManager.getRSProfileKey() != null)
		{
			String saved = configManager.getRSProfileConfiguration(ExpectedDropsConfig.GROUP, SLAYER_LEVEL_KEY);
			try
			{
				setSlayerLevel(saved == null ? -1 : Integer.parseInt(saved));
			}
			catch (NumberFormatException e)
			{
				// not a level: wait for the game's
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// another account may log in: its level is not known yet
			slayerLevel = -1;
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			// a new login sends the counters again: that's not collecting rewards
			lastRewards.clear();
		}
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadProfile();
			resolveItemIds();
		}
	}

	/**
	 * Content with loot per reward roll: its boss name, the game's counter of rewards not
	 * collected yet (permits, cart rewards) and its total subdues.
	 */
	private static final Object[][] ROLL_COUNTERS = {
		{"Tempoross", VarbitID.TEMPOROSS_REWARDPERMITS, VarPlayerID.TOTAL_TEMPOROSS_KILLS},
		{"Wintertodt", VarbitID.WINT_REWARD_POOL, VarPlayerID.TOTAL_WINTERTODT_KILLS},
	};

	/** Each roll counter's value last seen this login; a drop means rewards were collected. */
	private final java.util.Map<String, Integer> lastRewards = new java.util.HashMap<>();

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (tracker == null)
		{
			return;
		}
		for (Object[] c : ROLL_COUNTERS)
		{
			String boss = (String) c[0];
			int rewardsVarbit = (Integer) c[1];
			int subduesVarp = (Integer) c[2];
			if (event.getVarbitId() != rewardsVarbit && event.getVarpId() != subduesVarp)
			{
				continue;
			}
			int held = client.getVarbitValue(rewardsVarbit);
			int subdues = client.getVarpValue(subduesVarp);
			String baseline = tracker.onRollBaseline(boss, subdues, held);
			if (baseline != null)
			{
				changed(baseline, false);
			}
			Integer last = lastRewards.get(boss);
			if (last != null && held < last)
			{
				// each reward collected is one reward roll
				String rolled = tracker.onRewardRolls(boss, last - held, System.currentTimeMillis());
				if (rolled != null)
				{
					changed(rolled, true);
				}
			}
			lastRewards.put(boss, held);
		}
	}

