package legacy.expecteddrops;

import legacy.expecteddrops.tracking.KillEntry;
import legacy.expecteddrops.tracking.RaidRecord;
import legacy.expecteddrops.tracking.SaveData;
import legacy.expecteddrops.tracking.Tracker;
import legacy.expecteddrops.tracking.TrackerState;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.List;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Loads and saves one account's data (the main data, plus the History and raids of each
 * boss under their own keys) in the settings of the current RuneScape profile.
 */
final class ProfileStore
{
	private static final Logger log = LoggerFactory.getLogger(ProfileStore.class);
	private static final Type RAIDS_TYPE = new TypeToken<List<RaidRecord>>()
	{
	}.getType();
	private static final Type KILLS_TYPE = new TypeToken<List<KillEntry>>()
	{
	}.getType();

	/** The settings of the current profile. */
	interface Backend
	{
		String get(String key);

		void set(String key, String value);

		void unset(String key);
	}

	static final String BACKUP_SUFFIX = ".corrupt";

	private final Backend backend;
	private final Gson gson;
	private String loadedProfile;

	ProfileStore(Backend backend, Gson gson)
	{
		this.backend = backend;
		this.gson = gson;
	}

	/**
	 * Replaces the tracker's data with the one saved for this profile.
	 *
	 * @return false when nothing was done: no profile yet, or it is already the one loaded
	 */
	synchronized boolean load(String profile, Tracker tracker)
	{
		if (profile == null || profile.equals(loadedProfile))
		{
			return false;
		}
		loadedProfile = profile;
		TrackerState state = null;
		String json = backend.get(ExpectedDropsPlugin.DATA_KEY);
		if (json != null && !json.isEmpty())
		{
			try
			{
				state = gson.fromJson(json, TrackerState.class);
			}
			catch (Exception e)
			{
				log.warn("Could not read saved On Rate data, starting fresh", e);
				backup(ExpectedDropsPlugin.DATA_KEY, json);
			}
		}
		tracker.setState(state);
		for (legacy.expecteddrops.data.BossDefinition boss : tracker.getCatalog().getBosses())
		{
			String kills = backend.get(ExpectedDropsPlugin.killsKey(boss.getName()));
			if (kills == null || kills.isEmpty())
			{
				continue;
			}
			try
			{
				tracker.setKills(boss.getName(), gson.fromJson(kills, KILLS_TYPE));
			}
			catch (Exception e)
			{
				log.warn("Could not read the saved On Rate history of {}", boss.getName(), e);
				backup(ExpectedDropsPlugin.killsKey(boss.getName()), kills);
			}
		}
		for (legacy.expecteddrops.data.BossDefinition boss : tracker.getCatalog().getBosses())
		{
			if (boss.getRaid() == null)
			{
				continue;
			}
			String raids = backend.get(ExpectedDropsPlugin.raidsKey(boss.getName()));
			if (raids == null || raids.isEmpty())
			{
				continue;
			}
			try
			{
				tracker.setRaids(boss.getName(), gson.fromJson(raids, RAIDS_TYPE));
			}
			catch (Exception e)
			{
				log.warn("Could not read the saved On Rate raids of {}", boss.getName(), e);
				backup(ExpectedDropsPlugin.raidsKey(boss.getName()), raids);
			}
		}
		return true;
	}

	/** Writes what changed since the last save. Does nothing before a profile is loaded. */
	synchronized void save(Tracker tracker)
	{
		if (tracker == null || loadedProfile == null)
		{
			return;
		}
		// put together under the tracker's lock: safe from any thread (shutDown runs on Swing's)
		SaveData data = tracker.saveData(gson::toJson);
		// only the History and raids of bosses that changed are written again; they go first,
		// so raids moved out of the main data by an update are stored before it drops them
		for (Map.Entry<String, String> e : data.kills.entrySet())
		{
			write(ExpectedDropsPlugin.killsKey(e.getKey()), e.getValue());
		}
		for (Map.Entry<String, String> e : data.raids.entrySet())
		{
			write(ExpectedDropsPlugin.raidsKey(e.getKey()), e.getValue());
		}
		backend.set(ExpectedDropsPlugin.DATA_KEY, data.progress);
	}

	/** Forgets which profile is loaded (the plugin stopped). */
	void forget()
	{
		loadedProfile = null;
	}

	/** Keeps unreadable data under a ".corrupt" key, so the next save doesn't destroy it. */
	private void backup(String key, String raw)
	{
		backend.set(key + BACKUP_SUFFIX, raw);
	}

	private void write(String key, String json)
	{
		if (json == null)
		{
			backend.unset(key);
		}
		else
		{
			backend.set(key, json);
		}
	}
}

package legacy.expecteddrops;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Who fights a group boss with you: the other players seen hitting it. Only they share the kill,
 * not the players who happen to stand nearby. Seen players expire after a few minutes, and a
 * boss's list is cleared once its kill is counted.
 */
final class TeamSpotter
{
	/** A player seen hitting the boss this long ago (or less) still counts as part of the fight. */
	static final long WINDOW_MILLIS = 5 * 60_000;

	/** The bosses counted this way, by the name their NPC and their kill count both use. */
	private static final String[] FIGHTS = {"nex", "yama", "hueycoatl", "corporeal beast"};

	/** Fight key to the players seen hitting it and when. */
	private final Map<String, Map<String, Long>> seen = new HashMap<>();

	/**
	 * The fight an NPC or boss name belongs to ("Nex", "The Hueycoatl", "Hueycoatl tail"), or null
	 * when it isn't one counted by who hits it.
	 */
	static String fightOf(String name)
	{
		if (name == null)
		{
			return null;
		}
		String n = name.replaceAll("<[^>]*>", "").trim().toLowerCase(Locale.ROOT);
		if (n.startsWith("the "))
		{
			n = n.substring(4);
		}
		for (String fight : FIGHTS)
		{
			if (n.equals(fight) || n.startsWith(fight + " "))
			{
				return fight;
			}
		}
		return null;
	}

	synchronized void onHitting(String fight, String player, long nowMillis)
	{
		seen.computeIfAbsent(fight, f -> new HashMap<>()).put(player, nowMillis);
	}

	/** The other players seen hitting this boss lately (you are not counted). */
	synchronized int others(String fight, long nowMillis)
	{
		Map<String, Long> players = seen.get(fight);
		if (players == null)
		{
			return 0;
		}
		players.values().removeIf(at -> nowMillis - at > WINDOW_MILLIS);
		return players.size();
	}

	/** The kill is counted: the next one starts with nobody seen. */
	synchronized void clear(String fight)
	{
		seen.remove(fight);
	}

	synchronized void clearAll()
	{
		seen.clear();
	}
}

package legacy.expecteddrops.data;

import com.google.gson.Gson;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * All bosses, with lookups by kill-count name, loot name and collection log page.
 */
public class BossCatalog
{
	private final List<BossDefinition> bosses;
	private final Map<String, BossDefinition> byName = new HashMap<>();
	private final Map<String, BossDefinition> byKcName = new HashMap<>();
	private final Map<String, BossDefinition> byLootName = new HashMap<>();
	private final Map<String, List<BossDefinition>> byClogPage = new HashMap<>();
	private final Set<String> clogSharedItems = new HashSet<>();
	/** Items flagged clogShared in the data (dragon 2h sword, thrownaxes...): not tracked anywhere. */
	private final Set<String> untrackedItems = new HashSet<>();
	/** Display names of the shared items that were left out, for the panel. */
	private final Set<String> excludedItems = new java.util.TreeSet<>();
	private final Set<String> allItemNames = new HashSet<>();
	/** Untradeable items worth something through a conversion: normalized name to formula. */
	private final Map<String, ValueFormula> valueFormulas = new HashMap<>();
	private final Set<String> excludedBosses = new java.util.TreeSet<>();
	private final Map<String, List<PoolSource>> pools = new java.util.TreeMap<>();
	private final Set<String> minionLootNames = new HashSet<>();
	/** Bosses marked hidden in the data: prepared for a release, not part of the catalog yet. */
	private final List<BossDefinition> hiddenBosses = new ArrayList<>();

	private static class FileFormat
	{
		List<BossDefinition> bosses;
	}

	public BossCatalog(List<BossDefinition> allBosses)
	{
		List<BossDefinition> bosses = new ArrayList<>();
		for (BossDefinition boss : allBosses)
		{
			(boss.isHidden() ? hiddenBosses : bosses).add(boss);
		}
		// An item that several bosses drop has one collection log total for all of them,
		// so that total can't be credited to any single boss.
		Map<String, Integer> itemBossCount = new HashMap<>();
		for (BossDefinition boss : bosses)
		{
			Set<String> namesForBoss = new HashSet<>();
			for (DropDefinition drop : boss.getDrops())
			{
				if (drop.getValueFrom() != null)
				{
					valueFormulas.put(normalize(drop.getName()), ValueFormula.parse(drop.getValueFrom()));
				}
				for (String item : drop.getAllNames())
				{
					String key = normalize(item);
					namesForBoss.add(key);
					if (drop.isClogSharedFlag())
					{
						clogSharedItems.add(key);
						untrackedItems.add(key);
					}
				}
			}
			for (String key : namesForBoss)
			{
				itemBossCount.merge(key, 1, Integer::sum);
			}
		}
		for (Map.Entry<String, Integer> e : itemBossCount.entrySet())
		{
			if (e.getValue() > 1)
			{
				clogSharedItems.add(e.getKey());
			}
		}

		// Leave those items out of the boss pages: their log total can't be split per boss.
		// Items several bosses drop are pooled for the account instead (all those bosses'
		// expected added up against the one log total); flagged items that also come from
		// outside the bosses (dragon 2h sword) can't be pooled and are left out entirely.
		List<BossDefinition> sorted = new ArrayList<>();
		for (BossDefinition boss : bosses)
		{
			boss.removeDrops(drop ->
			{
				for (String item : drop.getAllNames())
				{
					String key = normalize(item);
					if (clogSharedItems.contains(key))
					{
						excludedItems.add(drop.getDisplayName());
						if (!drop.isClogSharedFlag() && itemBossCount.getOrDefault(key, 0) > 1)
						{
							pools.computeIfAbsent(normalize(drop.getName()), k -> new ArrayList<>())
								.add(new PoolSource(boss, drop));
							// shared items show in the panel too: they need their pictures
							for (String name : drop.getAllNames())
							{
								allItemNames.add(normalize(name));
							}
						}
						return true;
					}
				}
				return false;
			});
			if (boss.getDrops().isEmpty())
			{
				// still tracked for its kill count (shared items need it), but has no page of its own
				excludedBosses.add(boss.getName());
			}
			sorted.add(boss);
		}
		sorted.sort(Comparator.comparing(b -> b.getName().toLowerCase(Locale.ROOT)));
		this.bosses = Collections.unmodifiableList(sorted);

		for (BossDefinition boss : sorted)
		{
			byName.put(normalize(boss.getName()), boss);
			for (String kc : boss.getKcNames())
			{
				byKcName.put(normalize(kc), boss);
			}
			for (String loot : boss.getLootNames())
			{
				byLootName.put(normalize(loot), boss);
			}
			for (String minion : boss.getMinionLoot())
			{
				byLootName.put(normalize(minion), boss);
				minionLootNames.add(normalize(minion));
			}
			for (String page : boss.getClogPages())
			{
				byClogPage.computeIfAbsent(normalize(page), k -> new ArrayList<>()).add(boss);
			}
			for (DropDefinition drop : boss.getDrops())
			{
				for (String item : drop.getAllNames())
				{
					allItemNames.add(normalize(item));
				}
			}
		}
	}

	/** Bosses prepared in the data but still hidden (for tests; nothing else sees them). */
	public List<BossDefinition> getHiddenBosses()
	{
		return Collections.unmodifiableList(hiddenBosses);
	}

	/** One boss that drops a pooled (shared) item, with its drop definition. */
	public static final class PoolSource
	{
		private final BossDefinition boss;
		private final DropDefinition drop;

		PoolSource(BossDefinition boss, DropDefinition drop)
		{
			this.boss = boss;
			this.drop = drop;
		}

		public BossDefinition getBoss()
		{
			return boss;
		}

		public DropDefinition getDrop()
		{
			return drop;
		}
	}

	/** Items several bosses drop, keyed by normalized name, with every boss that drops them. */
	public Map<String, List<PoolSource>> getPools()
	{
		return Collections.unmodifiableMap(pools);
	}

	/** The pooled item (normalized) this boss drops under {@code itemName}, or null. */
	public String poolOf(BossDefinition boss, String itemName)
	{
		String key = normalize(itemName);
		for (Map.Entry<String, List<PoolSource>> e : pools.entrySet())
		{
			for (PoolSource src : e.getValue())
			{
				if (src.boss == boss)
				{
					for (String n : src.drop.getAllNames())
					{
						if (normalize(n).equals(key))
						{
							return e.getKey();
						}
					}
				}
			}
		}
		return null;
	}

	/** The pooled items this boss drops: pool key (normalized item name) to its drop row. */
	public Map<String, DropDefinition> poolsOf(BossDefinition boss)
	{
		Map<String, DropDefinition> result = new java.util.LinkedHashMap<>();
		for (Map.Entry<String, List<PoolSource>> e : pools.entrySet())
		{
			for (PoolSource src : e.getValue())
			{
				if (src.boss == boss)
				{
					result.put(e.getKey(), src.drop);
				}
			}
		}
		return result;
	}

	/** True for a minion's loot tracker name (its loot counts for the boss, not as a kill). */
	public boolean isMinionLoot(String lootName)
	{
		return minionLootNames.contains(normalize(lootName));
	}

	/**
	 * Bosses with nothing left to track once shared items are left out (Chaos Elemental). They
	 * still get a page, with only their shared items on it.
	 */
	public Set<String> getExcludedBosses()
	{
		return Collections.unmodifiableSet(excludedBosses);
	}

	public static BossCatalog load(Gson gson, Reader reader)
	{
		FileFormat file = gson.fromJson(reader, FileFormat.class);
		if (file == null || file.bosses == null)
		{
			throw new IllegalArgumentException("No bosses found in drop data");
		}
		return new BossCatalog(file.bosses);
	}

	public static String normalize(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replace('’', '\'')
			.replace(' ', ' ')
			.trim()
			.toLowerCase(Locale.ROOT);
	}

	public List<BossDefinition> getBosses()
	{
		return bosses;
	}

	public BossDefinition byName(String name)
	{
		return byName.get(normalize(name));
	}

	public BossDefinition byKcName(String kcName)
	{
		return byKcName.get(normalize(kcName));
	}

	public BossDefinition byLootName(String lootName)
	{
		return byLootName.get(normalize(lootName));
	}

	public List<BossDefinition> byClogPage(String pageTitle)
	{
		List<BossDefinition> list = byClogPage.get(normalize(pageTitle));
		return list == null ? Collections.emptyList() : list;
	}

	/** Items several bosses drop, which On Rate leaves out (dragon pickaxe, uncut onyx...). */
	public Set<String> getExcludedItems()
	{
		return Collections.unmodifiableSet(excludedItems);
	}

	public boolean isClogShared(String itemName)
	{
		return clogSharedItems.contains(normalize(itemName));
	}

	/**
	 * True for an item flagged clogShared in the data: it also drops from monsters outside the
	 * bosses, so it isn't tracked at any boss (not pooled either). Items several bosses drop
	 * (pooled, like the dragon axe) aren't untracked.
	 */
	public boolean isUntracked(String itemName)
	{
		return untrackedItems.contains(normalize(itemName));
	}

	/** How to price an untradeable item from tradeable ones, or null when it has no such value. */
	public ValueFormula getValueFormula(String itemName)
	{
		return valueFormulas.get(normalize(itemName));
	}

	/** Every tradeable item some value formula needs a price for (normalized). */
	public Set<String> getFormulaItemNames()
	{
		Set<String> names = new HashSet<>();
		for (ValueFormula f : valueFormulas.values())
		{
			for (String name : f.getItemNames())
			{
				names.add(normalize(name));
			}
		}
		return names;
	}

	public Set<String> getAllItemNames()
	{
		return Collections.unmodifiableSet(allItemNames);
	}
}

package legacy.expecteddrops.data;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A boss (or raid) with its unique drops, as read from bosses.json.
 */
public class BossDefinition
{
	private String name;
	private List<String> kc;
	private List<String> loot;
	private List<String> clog;
	private String raid;
	private String kcMode;
	private Boolean delve;
	/** Team boss whose uniques scale with your damage share (setting key), or null. */
	private String team;
	private String note;
	/** Slayer level needed to fight this boss (a Slayer boss), or null when none is needed. */
	private Integer slayerLevel;
	private List<DropDefinition> drops;
	private List<BossPart> parts;
	/** Minions killed with the boss that roll some of its uniques (God Wars bodyguards). */
	private Integer minions;
	/** Loot tracker names of those minions: their loot counts for the boss, not as kills. */
	private List<String> minionLoot;
	/** True when the rates are an estimate (team, points, assumed setup): shown with a "*". */
	private Boolean estimate;
	/** Group boss where On Rate counts the players around you at each kill (Nex, Corp...). */
	private Boolean detectTeam;
	/**
	 * Loot per reward roll, not per kill (Tempoross): the reward rolls one subdue gives, used
	 * for the subdues from before On Rate could count rolls. Null for every other boss.
	 */
	private Integer rollsPerKill;
	/**
	 * Waves of a run whose loot piles up wave by wave until you claim it (Fortis Colosseum: 12).
	 * Its drops' level rates are per wave; a run claimed at wave W counts every wave up to W.
	 */
	private Integer waves;
	/** True while content is prepared but not released to players: kept out of the catalog entirely. */
	private Boolean hidden;

	public BossDefinition()
	{
	}

	public BossDefinition(String name, List<String> kc, List<String> loot, List<String> clog, List<DropDefinition> drops)
	{
		this.name = name;
		this.kc = kc;
		this.loot = loot;
		this.clog = clog;
		this.drops = drops;
	}

	/** Slayer level needed to fight this boss, 0 when none is. */
	public int getSlayerLevel()
	{
		return slayerLevel == null ? 0 : slayerLevel;
	}

	public String getName()
	{
		return name;
	}

	/** Prepared in bosses.json but not shown yet (no page, no tracking, no collection log sync). */
	public boolean isHidden()
	{
		return Boolean.TRUE.equals(hidden);
	}

	public int getMinions()
	{
		return minions == null ? 0 : minions;
	}

	public List<String> getMinionLoot()
	{
		return minionLoot == null ? Collections.emptyList() : minionLoot;
	}

	/** Waves in a run whose loot is claimed at the end (Fortis Colosseum), or 0. */
	public int getWaves()
	{
		return waves == null ? 0 : waves;
	}

	/** Reward rolls per subdue for content with loot per roll (Tempoross), or 0. */
	public int getRollsPerKill()
	{
		return rollsPerKill == null ? 0 : rollsPerKill;
	}

	/** Group boss: uniques are shared with the players you kill it with, counted at each kill. */
	public boolean isDetectTeam()
	{
		return Boolean.TRUE.equals(detectTeam);
	}

	/** Rates depend on team, points or an assumed setup, so the numbers are an estimate. */
	public boolean isEstimate()
	{
		return Boolean.TRUE.equals(estimate) || raid != null || team != null;
	}

	/** Chat kill-count names, including those of every part. */
	public List<String> getKcNames()
	{
		List<String> names = new ArrayList<>(kc == null ? Collections.emptyList() : kc);
		for (BossPart part : getParts())
		{
			names.addAll(part.getKcNames());
		}
		return names;
	}

	/** Loot tracker names, including those of every part. */
	public List<String> getLootNames()
	{
		List<String> names = new ArrayList<>(loot == null ? Collections.emptyList() : loot);
		for (BossPart part : getParts())
		{
			names.addAll(part.getLootNames());
		}
		return names;
	}

	/** The bosses on a combined page (Dagannoth Kings, Callisto and Artio...), or empty. */
	public List<BossPart> getParts()
	{
		return parts == null ? Collections.emptyList() : parts;
	}

	public String getTeam()
	{
		return team;
	}

	public boolean hasParts()
	{
		return parts != null && !parts.isEmpty();
	}

	public List<String> getClogPages()
	{
		return clog == null ? Collections.emptyList() : clog;
	}

	/** "cox", "tob", "toa" or null for a normal boss. */
	public String getRaid()
	{
		return raid;
	}

	public void setRaid(String raid)
	{
		this.raid = raid;
	}

	/** Delve levels tracked for delve bosses: 1-8, plus 9 for "8+" (deep delves). */
	public static final int DELVE_LEVELS = 9;

	/** True for delve bosses (Doom of Mokhaiotl), whose rates depend on the delve level. */
	public boolean isDelve()
	{
		return delve != null && delve;
	}

	public void setDelve(boolean delve)
	{
		this.delve = delve;
	}

	public static String delveLevelLabel(int level)
	{
		return level >= DELVE_LEVELS ? "8+" : String.valueOf(level);
	}

	/** True when several kill counts should be combined with max instead of being added up. */
	public boolean combineKcWithMax()
	{
		return "max".equalsIgnoreCase(kcMode);
	}

	public String getNote()
	{
		return note;
	}

	/** Drops the uniques that match, e.g. items several bosses share. */
	void removeDrops(java.util.function.Predicate<DropDefinition> remove)
	{
		if (drops == null)
		{
			return;
		}
		List<DropDefinition> kept = new java.util.ArrayList<>();
		for (DropDefinition drop : drops)
		{
			if (!remove.test(drop))
			{
				kept.add(drop);
			}
		}
		drops = kept;
	}

	public List<DropDefinition> getDrops()
	{
		return drops == null ? Collections.emptyList() : drops;
	}

	/** Total unique weight in one raid mode. */
	public double getTotalWeight(String part)
	{
		double total = 0;
		for (DropDefinition drop : getDrops())
		{
			Double w = drop.getWeight(part);
			if (w != null)
			{
				total += w;
			}
		}
		return total;
	}

	public double getTotalWeight()
	{
		double total = 0;
		for (DropDefinition drop : getDrops())
		{
			if (drop.getWeight() != null)
			{
				total += drop.getWeight();
			}
		}
		return total;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

