/**
 * The boss drops on the Ladlor ironman progression chart, in the order of the chart
 * (ladlorchart.json, bundled with the plugin). Each chart item lists the drops it needs.
 */
public final class LadlorChart
{
	private static LadlorChart bundled;

	private final List<Item> items;

	/** A drop a chart item needs, or a number of kills of a boss (a reward that is sure at that kill count). */
	public static final class Need
	{
		private String boss;
		private String drop;
		private Integer kills;
		private Integer count;

		public String getBoss()
		{
			return boss;
		}

		/** The drop's name as the boss page has it, or null for a kill-count need. */
		public String getDrop()
		{
			return drop;
		}

		/** How many of the drop are needed (crystal armour seeds: 3 for the body), at least 1. */
		public int getCount()
		{
			return count == null || count < 1 ? 1 : count;
		}

		/** Kills of the boss needed, or null for a drop. */
		public Integer getKills()
		{
			return kills;
		}
	}

	/** One item of the chart. */
	public static final class Item
	{
		private int step;
		private String name;
		private String icon;
		private List<Need> needs;
		private String note;
		private String route;

		/** Its place in the chart: items of one step share a number. */
		public int getStep()
		{
			return step;
		}

		public String getName()
		{
			return name;
		}

		/** An item name for the picture. */
		public String getIcon()
		{
			return icon;
		}

		public List<Need> getNeeds()
		{
			return needs == null ? Collections.emptyList() : needs;
		}

		/** What the chart item needs besides these drops and isn't counted, or null. */
		public String getNote()
		{
			return note;
		}

		/** A second way to get the item with its own explanation ("oathplate-shards"), or null. */
		public String getRoute()
		{
			return route;
		}
	}

	private static final class FileFormat
	{
		List<Item> items;
	}

	private LadlorChart(FileFormat file)
	{
		this.items = file.items == null ? new ArrayList<>() : file.items;
	}

	public static LadlorChart load(Gson gson, Reader reader)
	{
		FileFormat file = gson.fromJson(reader, FileFormat.class);
		return new LadlorChart(file == null ? new FileFormat() : file);
	}

	/** The file that ships with the plugin; empty if it can't be read. */
	public static synchronized LadlorChart bundled()
	{
		if (bundled == null)
		{
			try (Reader reader = new InputStreamReader(LadlorChart.class.getResourceAsStream("/legacy/expecteddrops/ladlorchart.json"),
				StandardCharsets.UTF_8))
			{
				bundled = load(new Gson(), reader);
			}
			catch (Exception e)
			{
				bundled = new LadlorChart(new FileFormat());
			}
		}
		return bundled;
	}

	/** The chart's items in chart order. */
	public List<Item> getItems()
	{
		return Collections.unmodifiableList(items);
	}
}

package legacy.expecteddrops.data;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.ToLongFunction;
import java.util.regex.Pattern;

/**
 * What an untradeable unique is worth, written in terms of tradeable items:
 * {@code "Amulet of rancour - Amulet of torture"}, {@code "Noxious halberd / 3"}.
 * Operators ({@code + - * /}) have spaces around them; a term is an item name or a number,
 * and {@code *} and {@code /} bind tighter than {@code +} and {@code -}.
 */
public final class ValueFormula
{
	private static final Pattern SUM_SPLIT = Pattern.compile("\\s([+-])\\s");
	private static final Pattern PRODUCT_SPLIT = Pattern.compile("\\s([*/])\\s");

	private final List<Character> signs = new ArrayList<>();
	private final List<List<String>> terms = new ArrayList<>();
	private final List<List<Character>> productOps = new ArrayList<>();
	private final Set<String> itemNames = new LinkedHashSet<>();

	private ValueFormula()
	{
	}

	public static ValueFormula parse(String text)
	{
		ValueFormula f = new ValueFormula();
		java.util.regex.Matcher sums = SUM_SPLIT.matcher(text);
		int start = 0;
		char sign = '+';
		while (true)
		{
			boolean found = sums.find();
			f.addTerm(sign, text.substring(start, found ? sums.start() : text.length()).trim());
			if (!found)
			{
				break;
			}
			sign = sums.group(1).charAt(0);
			start = sums.end();
		}
		return f;
	}

	private void addTerm(char sign, String term)
	{
		List<String> factors = new ArrayList<>();
		List<Character> ops = new ArrayList<>();
		java.util.regex.Matcher m = PRODUCT_SPLIT.matcher(term);
		int start = 0;
		while (m.find())
		{
			factors.add(term.substring(start, m.start()).trim());
			ops.add(m.group(1).charAt(0));
			start = m.end();
		}
		factors.add(term.substring(start).trim());
		for (String factor : factors)
		{
			if (factor.isEmpty())
			{
				throw new IllegalArgumentException("Empty term in value formula: " + term);
			}
			if (!isNumber(factor))
			{
				itemNames.add(factor);
			}
		}
		signs.add(sign);
		terms.add(factors);
		productOps.add(ops);
	}

	private static boolean isNumber(String s)
	{
		return s.matches("\\d+(\\.\\d+)?");
	}

	/** The item names the formula looks up a price for. */
	public Set<String> getItemNames()
	{
		return itemNames;
	}

	/**
	 * The value in GP, never below 0. 0 as well when any item in it has no price, since the
	 * rest of the formula would then be a wrong number rather than a small one.
	 */
	public long evaluate(ToLongFunction<String> price)
	{
		double total = 0;
		for (int t = 0; t < terms.size(); t++)
		{
			List<String> factors = terms.get(t);
			double value = 0;
			for (int f = 0; f < factors.size(); f++)
			{
				double x;
				String factor = factors.get(f);
				if (isNumber(factor))
				{
					x = Double.parseDouble(factor);
				}
				else
				{
					long p = price.applyAsLong(factor);
					if (p <= 0)
					{
						return 0;
					}
					x = p;
				}
				if (f == 0)
				{
					value = x;
				}
				else if (productOps.get(t).get(f - 1) == '*')
				{
					value *= x;
				}
				else
				{
					value /= x;
				}
			}
			total += signs.get(t) == '+' ? value : -value;
		}
		return Math.max(0, (long) total);
	}
}

package legacy.expecteddrops.raids;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;

/**
 * Estimates your contribution in The Fractured Archive from the damage you and your team deal.
 * Jagex's loot post: each room hands out 100 contribution (Ocellus 300) split by damage, minion
 * damage included. The game doesn't show the number, so this adds up the hitsplats On Rate sees:
 * yours, and the other players' (the game shows them on monsters too).
 *
 * <p>NPC IDs are from the OSRS Wiki's boss pages and its Strategies page (November 2026). Not
 * modelled, because Jagex hasn't said how they work: the soft cap on minion damage, and how
 * Ocellus's 300 is split between his phases (here it is one share of all his damage).
 */
public class FracturedContribution
{
	/** The five fights of a run: the Archive Guardian, one of each pair, then Ocellus. */
	enum Room
	{
		ARCHIVE_GUARDIAN(0, 100, 16659, 16660, 16664),
		EZEKIEL(1, 100, 16652, 16653),
		BORK(1, 100, 16640, 16641),
		MOIA(2, 100, 16667, 16670),
		DREADNOTH(2, 100, 16665, 16666),
		DAGONHAI_ELDER(3, 100, 16643, 16644, 16646, 16647, 16648, 16650),
		XARTH(3, 100, 16684, 16687, 16688),
		OCELLUS(4, 300, 16672, 16673, 16674, 16675, 16676, 16677, 16678, 16679, 16680, 16681);

		/** Which of the five fights this is (rooms of a pair share it). */
		final int slot;
		final double contribution;
		final int[] npcIds;

		Room(int slot, double contribution, int... npcIds)
		{
			this.slot = slot;
			this.contribution = contribution;
			this.npcIds = npcIds;
		}
	}

	static final int SLOTS = 5;

	private static final Map<Integer, Room> BY_NPC = new HashMap<>();

	static
	{
		for (Room room : Room.values())
		{
			for (int id : room.npcIds)
			{
				BY_NPC.put(id, room);
			}
		}
	}

	/** What On Rate saw of one raid. */
	public static final class Result
	{
		/** Your contribution out of 700 before deaths, or -1 when a fight was missed. */
		public final double contribution;
		/** Your deaths in the raid. */
		public final int deaths;

		Result(double contribution, int deaths)
		{
			this.contribution = contribution;
			this.deaths = deaths;
		}
	}

	private final Map<Room, long[]> damage = new EnumMap<>(Room.class);
	private int deaths;

	/** True when the NPC belongs to The Fractured Archive. */
	public static boolean isArchiveNpc(int npcId)
	{
		return BY_NPC.containsKey(npcId);
	}

	/**
	 * A hitsplat on a monster. Only player damage counts (yours or another player's), not poison,
	 * venom, burns or healing, which have no owner.
	 */
	public void onHitsplat(int npcId, int amount, boolean mine, boolean others)
	{
		Room room = BY_NPC.get(npcId);
		if (room == null || amount <= 0 || !mine && !others)
		{
			return;
		}
		if (room == Room.ARCHIVE_GUARDIAN && seenPastGuardian())
		{
			// the Archive Guardian is the first fight: this is a new raid (the last one was wiped or missed)
			reset();
		}
		long[] d = damage.computeIfAbsent(room, r -> new long[2]);
		d[0] += mine ? amount : 0;
		d[1] += amount;
	}

	/** You died: counted only during a raid On Rate is following. */
	public void onLocalDeath()
	{
		if (isActive())
		{
			deaths++;
		}
	}

	/** True once a fight of this raid was seen. */
	public boolean isActive()
	{
		return !damage.isEmpty();
	}

	/**
	 * The raid is complete: what it saw, then starts over. Null when it saw nothing of the raid.
	 * The contribution is -1 unless all five fights were seen (On Rate turned on mid-raid, say).
	 */
	public Result finish()
	{
		if (!isActive())
		{
			return null;
		}
		boolean[] seen = new boolean[SLOTS];
		double contribution = 0;
		for (Map.Entry<Room, long[]> e : damage.entrySet())
		{
			long[] d = e.getValue();
			if (d[1] > 0)
			{
				seen[e.getKey().slot] = true;
				contribution += e.getKey().contribution * d[0] / d[1];
			}
		}
		boolean all = true;
		for (boolean s : seen)
		{
			all &= s;
		}
		Result result = new Result(all ? contribution : -1, deaths);
		reset();
		return result;
	}

	public void reset()
	{
		damage.clear();
		deaths = 0;
	}

	private boolean seenPastGuardian()
	{
		for (Room room : damage.keySet())
		{
			if (room != Room.ARCHIVE_GUARDIAN)
			{
				return true;
			}
		}
		return false;
	}
}

package legacy.expecteddrops.raids;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Reads your raid times from the Raid Data Tracker plugin's log files, so raids start on your own
 * times instead of waiting for five timed raids. Read only: it never writes to that plugin's folder.
 *
 * <p>The plugin keeps one file per raid, {@code raid_tracker_data.log}, with one JSON object per
 * line, in {@code .runelite/raid-data tracker/<name>/<raid>/} (the folder name has a space in it; older
 * versions kept the raid folders directly in {@code raid-data tracker/}). Only completed raids of this
 * account (matched by its account hash) with a plausible time are taken, so a second account's raids or
 * a raid you left don't count. Its times are in whole seconds.
 *
 * <p>Which time: the whole raid's time ({@code raidTime}), which the plugin reads from the game's
 * "Duration" (Chambers) or "total completion time" (Tombs) message. For Tombs that is the total, not the
 * challenge time ({@code toaCompTime}): On Rate counts only the total there. Chambers and Tombs only: the
 * plugin does not record whether a Theatre of Blood raid was Normal or Hard Mode, so those times can't be
 * told apart and are left out.
 */
public final class RaidDataImport
{
	/** A raid time shorter than this isn't a finished raid (a record from a failed or abandoned run). */
	static final long MIN_MILLIS = 2 * 60_000L;
	/** A raid time longer than this is a stuck timer, not a raid. */
	static final long MAX_MILLIS = 3 * 60 * 60_000L;
	static final int MILLIS_PER_SECOND = 1000;
	/** The other plugin's folder inside {@code .runelite}: the name has a space, not a hyphen, before "tracker". */
	public static final String FOLDER = "raid-data tracker";
	/** The log file each raid folder holds. */
	static final String LOG_NAME = "raid_tracker_data.log";
	/** Raid folders of the other plugin; "unknown" holds raids it could not place and is skipped. */
	private static final String[] RAIDS = {"cox", "toa"};

	/** The boss name On Rate uses for each folder. */
	private static String boss(String raid)
	{
		switch (raid)
		{
			case "cox":
				return "Chambers of Xeric";
			default:
				return "Tombs of Amascut";
		}
	}

	private RaidDataImport()
	{
	}

	/** One raid time, by boss and raid mode. {@code when} is when the raid ended, in epoch millis. */
	public static final class Times
	{
		/** Boss, then mode, then {when, millis} pairs. */
		private final Map<String, Map<String, List<long[]>>> byBoss = new LinkedHashMap<>();

		void add(String boss, String part, long when, long millis)
		{
			byBoss.computeIfAbsent(boss, k -> new LinkedHashMap<>()).computeIfAbsent(part, k -> new ArrayList<>())
				.add(new long[]{when, millis});
		}

		public Map<String, Map<String, List<long[]>>> byBoss()
		{
			return byBoss;
		}

		public int count()
		{
			int n = 0;
			for (Map<String, List<long[]>> parts : byBoss.values())
			{
				for (List<long[]> list : parts.values())
				{
					n += list.size();
				}
			}
			return n;
		}
	}

	/**
	 * The times of {@code accountHash} found under the other plugin's folder, or none when the
	 * folder isn't there (the plugin isn't installed). Unreadable files and lines are skipped.
	 */
	public static Times read(File root, long accountHash)
	{
		Times times = new Times();
		if (root == null || !root.isDirectory() || accountHash == -1)
		{
			return times;
		}
		List<File> folders = new ArrayList<>();
		folders.add(root);
		File[] users = root.listFiles(File::isDirectory);
		if (users != null)
		{
			for (File u : users)
			{
				folders.add(u);
			}
		}
		for (File folder : folders)
		{
			for (String raid : RAIDS)
			{
				File log = new File(new File(folder, raid), LOG_NAME);
				if (log.isFile())
				{
					readLog(log, raid, accountHash, times);
				}
			}
		}
		return times;
	}

	private static void readLog(File log, String raid, long accountHash, Times times)
	{
		try (BufferedReader reader = Files.newBufferedReader(log.toPath(), StandardCharsets.UTF_8))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				line = line.trim();
				if (!line.isEmpty())
				{
					readLine(line, raid, accountHash, times);
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			// a file being written or in another encoding: take what was read, skip the rest
		}
	}

	private static void readLine(String line, String raid, long accountHash, Times times)
	{
		JsonObject o;
		try
		{
			JsonElement e = new JsonParser().parse(line);
			if (!e.isJsonObject())
			{
				return;
			}
			o = e.getAsJsonObject();
		}
		catch (RuntimeException e)
		{
			return;
		}
		try
		{
			addRecord(o, raid, accountHash, times);
		}
		catch (RuntimeException e)
		{
			// a field with the wrong type: skip this line only
		}
	}

	private static void addRecord(JsonObject o, String raid, long accountHash, Times times)
	{
		if (!has(o, "accountHash") || o.get("accountHash").getAsLong() != accountHash || !bool(o, "raidComplete"))
		{
			return;
		}
		long when = has(o, "date") ? o.get("date").getAsLong() : 0;
		int seconds = seconds(o);
		if (when <= 0 || seconds <= 0)
		{
			return;
		}
		long millis = (long) seconds * MILLIS_PER_SECOND;
		if (millis < MIN_MILLIS || millis > MAX_MILLIS)
		{
			return;
		}
		String part = part(o, raid);
		if (part != null)
		{
			times.add(boss(raid), part, when, millis);
		}
	}

	/** The raid's whole time in seconds (see the class comment): -1 when there is none. */
	private static int seconds(JsonObject o)
	{
		return num(o, "raidTime");
	}

	/**
	 * The raid mode, as On Rate names its parts. Tombs of Amascut modes come from the raid level
	 * (Entry below 150, Normal 150 to 295, Expert from 300), because the other plugin's completion
	 * count mixes the modes.
	 */
	static String part(JsonObject o, String raid)
	{
		switch (raid)
		{
			case "cox":
				return bool(o, "challengeMode") ? "Challenge Mode" : "Normal";
			default:
				int level = num(o, "raidLevel");
				if (level < 0)
				{
					return null;
				}
				return level >= 300 ? "Expert Mode" : level >= 150 ? "Normal" : "Entry Mode";
		}
	}

	private static boolean has(JsonObject o, String key)
	{
		return o.has(key) && o.get(key).isJsonPrimitive();
	}

	private static boolean bool(JsonObject o, String key)
	{
		return has(o, key) && o.get(key).getAsBoolean();
	}

	private static int num(JsonObject o, String key)
	{
		return has(o, key) ? o.get(key).getAsInt() : -1;
	}
}

