package legacy.expecteddrops.stats;

import java.util.Locale;

/**
 * How long it takes, on average, to get one copy of an item at one boss: the time of a kill (or
 * raid, or delve) divided by the chance of the item in it. See {@link ItemTimes}.
 */
public class ItemTime
{
	private final String boss;
	private final String label;
	private final String iconItem;
	private final boolean pet;
	private final boolean have;
	private final double secondsPerDrop;
	private final double secondsPerKill;
	private final double chancePerKill;
	private final boolean estimated;
	private final boolean lowConfidence;
	private final boolean usesOwn;
	private final boolean raid;
	private final String basis;
	private final String unit;
	private String hint;
	private int received;

	ItemTime(String boss, String label, String iconItem, boolean pet, boolean have, double secondsPerDrop,
		double secondsPerKill, double chancePerKill, boolean estimated, boolean usesOwn, boolean lowConfidence, boolean raid, String basis, String unit)
	{
		this.boss = boss;
		this.label = label;
		this.iconItem = iconItem;
		this.pet = pet;
		this.have = have;
		this.secondsPerDrop = secondsPerDrop;
		this.secondsPerKill = secondsPerKill;
		this.chancePerKill = chancePerKill;
		this.estimated = estimated;
		this.usesOwn = usesOwn;
		this.lowConfidence = lowConfidence;
		this.raid = raid;
		this.basis = basis;
		this.unit = unit;
	}

	/** An extra line for the hover about another way to get the item (Oathplate shards), or null. */
	public String getHint()
	{
		return hint;
	}

	ItemTime withHint(String hint)
	{
		this.hint = hint;
		return this;
	}

	/** How many of the item you have (the collection log's count). */
	public int getReceived()
	{
		return received;
	}

	/**
	 * The same boss's time for a unique of any kind: this time per kill over the chance of some unique
	 * in a kill. A copy; this item stays as it is.
	 */
	public ItemTime forAnyUnique(double chancePerKill)
	{
		return new ItemTime(boss, "Any unique", iconItem, false, have, secondsPerKill / chancePerKill, secondsPerKill, chancePerKill,
			estimated, usesOwn, lowConfidence, raid, basis, unit).withHint(hint);
	}

	ItemTime withReceived(int received)
	{
		this.received = received;
		return this;
	}

	public String getBoss()
	{
		return boss;
	}

	public String getLabel()
	{
		return label;
	}

	public String getIconItem()
	{
		return iconItem;
	}

	public boolean isPet()
	{
		return pet;
	}

	/** True when you already have at least one copy of the item. */
	public boolean isHave()
	{
		return have;
	}

	/** Average seconds to get one copy. */
	public double getSecondsPerDrop()
	{
		return secondsPerDrop;
	}

	/** Seconds one kill (raid, delve) takes in this calculation. */
	public double getSecondsPerKill()
	{
		return secondsPerKill;
	}

	/** Your chance of the item in one kill (raid, delve): from your points for raids, your depths for Doom. */
	public double getChancePerKill()
	{
		return chancePerKill;
	}

	/** True when the time per kill is the plugin's estimate, not an average of your own timed kills. */
	public boolean isEstimated()
	{
		return estimated;
	}

	/** True when some of the time per kill is your own timed kills (all of it when {@link #isEstimated()} is false). */
	public boolean usesOwnTimes()
	{
		return usesOwn;
	}

	/** True for a raid item: Chambers, Tombs, Theatre of Blood, the Fractured Archive. */
	public boolean isRaid()
	{
		return raid;
	}

	/** Where the time per kill comes from, short: "your times", "wiki rate" or "wiki + yours". */
	public String getSourceTag()
	{
		return !estimated ? "your times" : usesOwn ? "wiki + yours" : "wiki rate";
	}

	/** True when the estimate rests on a thin source. */
	public boolean isLowConfidence()
	{
		return lowConfidence;
	}

	/** One sentence on where the time per kill comes from. */
	public String getBasis()
	{
		return basis;
	}

	/** "kill", "raid" or "delve". */
	public String getUnit()
	{
		return unit;
	}

	/** "45 min", "3.3 h", "145 h": a long time in the units that read best. */
	public static String formatLong(double seconds)
	{
		if (Double.isNaN(seconds) || Double.isInfinite(seconds) || seconds < 0)
		{
			return "-";
		}
		double minutes = seconds / 60;
		if (minutes < 1)
		{
			return "<1 min";
		}
		if (minutes < 60)
		{
			return String.format(Locale.ROOT, "%.0f min", minutes);
		}
		double hours = minutes / 60;
		if (hours < 10)
		{
			return String.format(Locale.ROOT, "%.1f h", hours);
		}
		if (hours < 10_000)
		{
			return String.format(Locale.ROOT, "%,.0f h", hours);
		}
		return String.format(Locale.ROOT, "%,.0f h", Math.round(hours / 1000) * 1000.0);
	}
}

package legacy.expecteddrops.stats;

import legacy.expecteddrops.data.BossDefinition;
import legacy.expecteddrops.data.BossPart;
import legacy.expecteddrops.data.DropDefinition;
import legacy.expecteddrops.data.KillTimes;
import legacy.expecteddrops.tracking.TimeStats;
import legacy.expecteddrops.tracking.Tracker;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Average time to get each item: the time of one kill divided by the chance of the item in it.
 *
 * <p>The time of a kill is the average of your own timed kills once you have enough of them (5
 * raids, 20 of anything else), otherwise the bundled estimate (see {@link KillTimes}). The chance
 * is your own: for raids it comes from your points (the expected uniques On Rate already counts
 * from them), for Doom from the delve levels you really did.
 *
 * <p>Doom is a run: each delve level you complete rolls once at that level's rates, and the loot
 * of the whole run is claimed at the end (dying forfeits it). So the chance per delve depends on
 * how deep your runs go, and the time per delve on how long each level takes. Both come from your
 * own level counts and level times, level by level.
 */
public final class ItemTimes
{
	/** Timed raids needed before your own average replaces the estimate. */
	public static final int MIN_TIMED_RAIDS = 5;
	/** Timed kills needed before your own average replaces the estimate (any boss that isn't a raid). */
	public static final int MIN_TIMED_KILLS = 20;
	/** Timed delves of one level needed before your own average replaces the estimate for that level. */
	public static final int MIN_TIMED_DELVES = 20;

	private ItemTimes()
	{
	}

	/** The time per kill that goes into a boss, and where it comes from. */
	private static final class PerKill
	{
		double seconds;
		boolean estimated;
		boolean usesOwn;
		boolean lowConfidence;
		String basis;
		/** The part of a combined page the chances are taken from when there are no kills, else null. */
		BossPart assumedPart;
	}

	/** All items with a time, for every boss that has one; items you have are included (see {@link ItemTime#isHave()}). */
	public static List<ItemTime> compute(Tracker tracker, KillTimes web, RaidSettings raids)
	{
		return compute(tracker, web, raids, boss -> true);
	}

	/** {@link #compute(Tracker, KillTimes, RaidSettings)} for the bosses {@code allowed} lets through (the ones you can fight). */
	public static List<ItemTime> compute(Tracker tracker, KillTimes web, RaidSettings raids, java.util.function.Predicate<String> allowed)
	{
		List<ItemTime> result = new ArrayList<>();
		for (BossDefinition boss : tracker.getCatalog().getBosses())
		{
			if (!allowed.test(boss.getName()))
			{
				continue;
			}
			if (boss.getWaves() > 0)
			{
				// a Colosseum run is claimed wave by wave: no time per kill to speak of
				continue;
			}
			BossStats stats = tracker.stats(boss.getName(), raids);
			if (stats == null)
			{
				continue;
			}
			if (boss.isDelve())
			{
				addDoom(result, tracker, web, boss, stats);
			}
			else
			{
				addBoss(result, tracker, web, raids, boss, stats);
			}
		}
		return result;
	}

	/** You have the item: at least one copy (or every copy that counts, for a capped item). */
	private static boolean hasAny(RowStats row)
	{
		return row.getReceived() > 0 || row.isComplete();
	}

	private static String unit(BossDefinition boss)
	{
		return boss.getRaid() != null ? "raid" : "kill";
	}

	private static void addBoss(List<ItemTime> out, Tracker tracker, KillTimes web, RaidSettings raids,
		BossDefinition boss, BossStats stats)
	{
		PerKill time = perKill(tracker, web, boss, stats);
		if (time == null)
		{
			return;
		}
		int kills = stats.getKillCount();
		List<RowStats> rows = stats.getRows();
		List<DropDefinition> drops = stats.getDrops();
		for (int i = 0; i < rows.size(); i++)
		{
			RowStats row = rows.get(i);
			if (row.isAny())
			{
				continue;
			}
			DropDefinition drop = drops != null && drops.size() == rows.size() ? drops.get(i) : null;
			double chance = 0;
			if (kills > 0 && row.getExpected() > 0)
			{
				// what your kills (your raid points) really gave, per kill
				chance = row.getExpected() / kills;
			}
			else if (drop != null)
			{
				chance = staticChance(boss, drop, time.assumedPart, raids);
			}
			else
			{
				chance = row.getRate();
			}
			if (!(chance > 0))
			{
				continue;
			}
			ItemTime item = new ItemTime(boss.getName(), row.getShownLabel(), row.getIconItem(), drop != null && drop.isPet(),
				hasAny(row), time.seconds / chance, time.seconds, chance, time.estimated, time.usesOwn, time.lowConfidence,
				boss.getRaid() != null, time.basis, unit(boss)).withReceived(row.getReceived());
			if ("Yama".equals(boss.getName()) && row.getIconItem() != null && row.getIconItem().startsWith("Oathplate ") && !hasAny(row))
			{
				item.withHint(OathplateShards.describe(new double[]{chance}, time.seconds));
			}
			out.add(item);
		}
	}

	private static double staticChance(BossDefinition boss, DropDefinition drop, BossPart part, RaidSettings raids)
	{
		if (boss.hasParts())
		{
			BossPart p = part != null ? part : boss.getParts().get(0);
			return Tracker.partRate(boss, p, drop, raids);
		}
		return Tracker.effectiveRate(boss, drop, raids);
	}

	/** Time per kill for a boss: kills (or each part, weighted by your kills of it) at your average or the estimate. */
	private static PerKill perKill(Tracker tracker, KillTimes web, BossDefinition boss, BossStats stats)
	{
		boolean raid = boss.getRaid() != null;
		int need = raid ? MIN_TIMED_RAIDS : MIN_TIMED_KILLS;
		String unit = unit(boss);
		if (!boss.hasParts())
		{
			return resolve(tracker, web, boss.getName(), null, need, unit);
		}
		Map<String, Integer> counts = stats.getPartCounts();
		double weighted = 0;
		double weights = 0;
		boolean estimated = false;
		boolean usesOwn = false;
		boolean low = false;
		List<String> bases = new ArrayList<>();
		for (BossPart part : boss.getParts())
		{
			int n = counts == null ? 0 : counts.getOrDefault(part.getName(), 0);
			if (n <= 0)
			{
				continue;
			}
			PerKill p = resolve(tracker, web, boss.getName(), part.getName(), need, unit);
			if (p == null)
			{
				continue;
			}
			weighted += p.seconds * n;
			weights += n;
			estimated |= p.estimated;
			usesOwn |= p.usesOwn;
			low |= p.lowConfidence;
			bases.add(part.getName() + ": " + p.basis);
		}
		if (weights > 0)
		{
			PerKill result = new PerKill();
			result.seconds = weighted / weights;
			result.estimated = estimated;
			result.usesOwn = usesOwn;
			result.lowConfidence = low;
			result.basis = String.join(" ", bases);
			return result;
		}
		// nothing done here yet: the first mode that has a time, with its own chances
		for (BossPart part : boss.getParts())
		{
			PerKill p = resolve(tracker, web, boss.getName(), part.getName(), need, unit);
			if (p != null)
			{
				p.assumedPart = part;
				p.basis = "No " + unit + "s of yours yet, so " + part.getName() + " is assumed. " + p.basis;
				return p;
			}
		}
		return null;
	}

	/** One boss or one part: your average when you have enough timed kills, else the estimate, else null. */
	private static PerKill resolve(Tracker tracker, KillTimes web, String boss, String part, int need, String unit)
	{
		TimeStats own = tracker.killTimes(boss, part);
		int have = own == null ? 0 : own.getCount();
		PerKill result = new PerKill();
		if (own != null && have >= need)
		{
			result.seconds = own.getAverageMillis() / 1000.0;
			result.usesOwn = true;
			result.basis = String.format(Locale.ROOT, "Your times: the average of your %,d timed %ss. It is fight time only, so banking and walking aren't in it.",
				have, unit);
			return result;
		}
		KillTimes.Estimate e = web.forBoss(boss, part);
		if (e == null)
		{
			return null;
		}
		result.seconds = e.getSecondsPerKill();
		result.estimated = true;
		result.lowConfidence = e.isLowConfidence();
		result.basis = String.format(Locale.ROOT, "Wiki rate: %s %ss an hour, from the OSRS Wiki's money-making guide. It includes banking and assumes strong gear and stats, "
				+ "so most players are slower. Your own average takes over at %d timed %ss; you have %d.",
			trim(e.getKillsPerHour()), unit, need, unit, have);
		return result;
	}

	private static String trim(double v)
	{
		return v == Math.rint(v) ? String.format(Locale.ROOT, "%.0f", v) : String.format(Locale.ROOT, "%.1f", v);
	}

	// ---- Doom of Mokhaiotl

	private static void addDoom(List<ItemTime> out, Tracker tracker, KillTimes web, BossDefinition boss, BossStats stats)
	{
		KillTimes.Doom doom = web.doom();
		Map<Integer, Integer> levels = stats.getLevelCounts();
		int levelCount = BossDefinition.DELVE_LEVELS;
		double[] seconds = new double[levelCount + 1];
		boolean[] own = new boolean[levelCount + 1];
		for (int l = 1; l <= levelCount; l++)
		{
			TimeStats t = tracker.levelTimes(boss.getName(), l);
			own[l] = t != null && t.getCount() >= MIN_TIMED_DELVES;
			seconds[l] = own[l] ? t.getAverageMillis() / 1000.0 : doom.isAvailable() ? doom.secondsFor(l) : Double.NaN;
		}
		int total = 0;
		int runs = 0;
		if (levels != null)
		{
			for (Map.Entry<Integer, Integer> e : levels.entrySet())
			{
				total += e.getValue();
			}
			runs = levels.getOrDefault(1, 0);
		}
		List<RowStats> rows = stats.getRows();
		List<DropDefinition> drops = stats.getDrops();
		for (int i = 0; i < rows.size(); i++)
		{
			RowStats row = rows.get(i);
			DropDefinition drop = drops != null && drops.size() == rows.size() ? drops.get(i) : null;
			if (row.isAny() || drop == null)
			{
				continue;
			}
			double perDelve;
			double chance;
			double secondsPerDrop;
			boolean estimated = false;
			boolean usesOwn = false;
			String unit;
			String basis;
			if (total > 0)
			{
				// the depths you really went to: levels 1 to 8 and the deep delves, each with its own time
				double sum = 0;
				for (int l = 1; l <= levelCount; l++)
				{
					int n = levels.getOrDefault(l, 0);
					if (n > 0)
					{
						if (Double.isNaN(seconds[l]))
						{
							sum = Double.NaN;
							break;
						}
						sum += n * seconds[l];
						estimated |= !own[l];
						usesOwn |= own[l];
					}
				}
				if (Double.isNaN(sum))
				{
					continue;
				}
				// banking after each run is in the estimate's times, not in the game's fight times
				perDelve = sum / total + (estimated ? doom.getBankingSecondsPerRun() * runs / total : 0);
				chance = row.getExpected() / total;
				unit = "delve";
				basis = String.format(Locale.ROOT, "Your own depths: %,d delves in %,d runs, about %.1f levels a run, each level at its own time "
						+ "(your times once you have %d timed delves of that level, else the wiki rate). A delve's chance depends on its level, "
						+ "and only a claimed run keeps its loot.", total, Math.max(runs, 1), (double) total / Math.max(runs, 1), MIN_TIMED_DELVES);
				if (!(chance > 0))
				{
					continue;
				}
				secondsPerDrop = perDelve / chance;
			}
			else
			{
				// no delves of yours yet: a run to the depth most people farm
				int depth = Math.min(levelCount, Math.max(1, doom.getAssumedDepthWithoutHistory()));
				double run = 0;
				double chancePerRun = 0;
				for (int l = 1; l <= depth; l++)
				{
					if (Double.isNaN(seconds[l]))
					{
						run = Double.NaN;
						break;
					}
					run += seconds[l];
					chancePerRun += legacy.expecteddrops.stats.DropMath.parseRate(drop.getLevelRate(l));
				}
				if (Double.isNaN(run) || !(chancePerRun > 0))
				{
					continue;
				}
				estimated = true;
				run += doom.getBankingSecondsPerRun();
				perDelve = run;
				chance = chancePerRun;
				unit = "run";
				secondsPerDrop = run / chancePerRun;
				basis = String.format(Locale.ROOT, "Wiki rate: no delves of yours yet, so runs claimed at delve %d are assumed, at the OSRS Wiki guides' pace with banking. "
					+ "Deeper runs take longer and roll better rates.", depth);
			}
			out.add(new ItemTime(boss.getName(), row.getShownLabel(), row.getIconItem(), drop.isPet(), hasAny(row),
				secondsPerDrop, perDelve, chance, estimated, usesOwn, false, false, basis, unit).withReceived(row.getReceived()));
		}
	}
}

package legacy.expecteddrops.stats;

import java.util.Locale;
import java.util.Random;

/**
 * Yama's other way to Oathplate: oathplate shards. Every kill drops some (about 0.81 on average),
 * 450 of them with 2,520 crushed infernal shale make any piece you are missing (83 Smithing), so
 * the pieces come from the drop chance and from the shards together. Figures from the OSRS Wiki's
 * oathplate shards page. The shale grind is not counted in any time here.
 */
public final class OathplateShards
{
	public static final double SHARDS_PER_KILL = 0.8075;
	public static final int SHARDS_PER_PIECE = 450;
	public static final int SHALE_PER_PIECE = 2520;
	public static final int SMITHING_LEVEL = 83;

	private static final int TRIALS = 4000;
	private static final long SEED = 20260607L;

	private OathplateShards()
	{
	}

	/**
	 * Expected kills until every missing piece is had, from drops and shards together, starting
	 * with no shards. Each kill drops piece {@code i} at {@code chances[i]}, and 450 shards turn
	 * into a missing piece whenever you have that many. Shards come at their average rate, so the
	 * count is a fair figure and not a forecast. The same answer every time it is asked.
	 */
	public static double expectedKills(double[] chances)
	{
		int n = chances.length;
		if (n == 0)
		{
			return 0;
		}
		Random random = new Random(SEED);
		boolean[] have = new boolean[n];
		double total = 0;
		for (int trial = 0; trial < TRIALS; trial++)
		{
			java.util.Arrays.fill(have, false);
			int missing = n;
			double shards = 0;
			int kills = 0;
			while (missing > 0)
			{
				kills++;
				for (int i = 0; i < n; i++)
				{
					if (!have[i] && random.nextDouble() < chances[i])
					{
						have[i] = true;
						missing--;
					}
				}
				shards += SHARDS_PER_KILL;
				while (shards >= SHARDS_PER_PIECE && missing > 0)
				{
					shards -= SHARDS_PER_PIECE;
					for (int i = 0; i < n; i++)
					{
						if (!have[i])
						{
							have[i] = true;
							missing--;
							break;
						}
					}
				}
			}
			total += kills;
		}
		return total / TRIALS;
	}

	/**
	 * The hover text for {@code chances.length} missing pieces: what shards are and what they save.
	 *
	 * @param secondsPerKill the time of one Yama kill, NaN when unknown (then only kills are given)
	 */
	public static String describe(double[] chances, double secondsPerKill)
	{
		return describe(chances, secondsPerKill, 0);
	}

	/**
	 * {@link #describe(double[], double)} for someone who already has {@code have} of the pieces: it
	 * says so, and the numbers are for the ones still missing.
	 */
	public static String describe(double[] chances, double secondsPerKill, int have)
	{
		int n = chances.length;
		double withShards = expectedKills(chances);
		double dropsOnly = ChartTimes.expectedKillsForAll(chances);
		boolean timed = !Double.isNaN(secondsPerKill);
		String which = n == 1 ? (have > 0 ? "the piece you are missing" : "this piece") : "all " + n + " missing pieces";
		String had = have > 0 ? String.format(Locale.ROOT, "You have %d of %d pieces. ", have, have + n) : "";
		return had + String.format(Locale.ROOT, "Oathplate shards: Yama also drops about %.2f a kill, and %d of them plus %,d crushed infernal shale "
				+ "(%d Smithing) make a piece you are missing. With drops and shards together %s takes about %,.0f kills%s, "
				+ "against %,.0f kills%s from drops alone. This assumes you start with no shards; the shale is not counted.",
			SHARDS_PER_KILL, SHARDS_PER_PIECE, SHALE_PER_PIECE, SMITHING_LEVEL, which,
			withShards, timed ? " (" + ItemTime.formatLong(withShards * secondsPerKill) + ")" : "",
			dropsOnly, timed ? " (" + ItemTime.formatLong(dropsOnly * secondsPerKill) + ")" : "");
	}
}

package legacy.expecteddrops.stats;

/**
 * Purple chances from raid points, using the formulas on the OSRS Wiki. Each method returns
 * your own expected number of uniques for one raid (for a single roll, that is the chance).
 */
public final class RaidChance
{
	/** Chambers of Xeric: every 8,676 team points is 1% for a unique. */
	public static final double COX_POINTS_PER_PERCENT = 8_676;
	/** One unique roll is capped at 570,000 points (65.7%); points above that roll again. */
	public static final int COX_POINTS_PER_ROLL = 570_000;
	/** At most six uniques per raid. */
	public static final int COX_MAX_ROLLS = 6;

	/** Tombs of Amascut: the chance to see a unique is capped at 55%. */
	public static final double TOA_MAX_CHANCE = 0.55;
	/** Uniques rolled below their minimum raid level are kept 1 time in 50. */
	public static final double TOA_LOW_LEVEL_KEEP = 1 / 50.0;

	/** The Fractured Archive: the team's chance of a unique in a solo or duo raid with no deaths, 1 in 14. */
	public static final double TFA_BASE_CHANCE = 1 / 14.0;
	/** Each player beyond two adds 4% of the base chance (3: x1.04, 5: x1.12, 8: x1.24). */
	public static final double TFA_BONUS_PER_PLAYER = 0.04;
	/** Contribution a whole raid hands out: 100 per room, 300 for Ocellus, split by damage. */
	public static final double TFA_RAID_CONTRIBUTION = 700;
	/** A death takes 10% of your expected contribution (the raid's total over the team size). */
	public static final double TFA_DEATH_PENALTY = 0.10;
	/** The raid takes 1 to 8 players. */
	public static final int TFA_MAX_TEAM = 8;

	private RaidChance()
	{
	}

	/**
	 * The Fractured Archive's team-size multiplier on the base chance: 1 up to two players, then
	 * +4% of the base per extra player. Jagex's examples (x1.12 for five, x1.24 for eight) add the
	 * 4%s rather than compound them.
	 */
	public static double tfaTeamMultiplier(int teamSize)
	{
		int team = Math.max(1, Math.min(TFA_MAX_TEAM, teamSize));
		return 1 + TFA_BONUS_PER_PLAYER * Math.max(0, team - 2);
	}

	/** Contribution an even share of the raid gives you: 700 solo, 350 in a duo, 175 in a four. */
	public static double tfaExpectedContribution(int teamSize)
	{
		return TFA_RAID_CONTRIBUTION / Math.max(1, Math.min(TFA_MAX_TEAM, teamSize));
	}

	/** Your contribution after deaths: each takes 10% of your expected contribution, never below 0. */
	public static double tfaContributionAfterDeaths(double contribution, int teamSize, int deaths)
	{
		double penalty = TFA_DEATH_PENALTY * tfaExpectedContribution(teamSize) * Math.max(0, deaths);
		return Math.max(0, contribution - penalty);
	}

	/**
	 * Your chance of the unique for one Fractured Archive raid. The team rolls the base chance times
	 * the team-size multiplier, scaled by how much of the raid's 700 contribution the team kept (deaths
	 * shrink it), and the unique goes to a player with their share of the team's contribution. Those
	 * two shares cancel, so your chance only depends on your own contribution:
	 * base x multiplier x your contribution / 700.
	 *
	 * @param contribution your contribution after deaths (0 to 700)
	 * @param baseChance   the team's chance for a duo with no deaths (1/14 at release)
	 * @return NaN when the contribution is unknown (negative)
	 */
	public static double tfa(double contribution, int teamSize, double baseChance)
	{
		if (contribution < 0 || Double.isNaN(contribution))
		{
			return Double.NaN;
		}
		double share = Math.min(contribution, TFA_RAID_CONTRIBUTION) / TFA_RAID_CONTRIBUTION;
		return Math.max(0, baseChance) * tfaTeamMultiplier(teamSize) * share;
	}

	/**
	 * Your chance when only the team size (and maybe your deaths) is known: you are assumed to do
	 * an even share of the damage. A duo with no deaths gets 1/28 each.
	 *
	 * @param deaths your deaths, or a negative number when unknown (counted as none)
	 */
	public static double tfaEven(int teamSize, int deaths, double baseChance)
	{
		double contribution = tfaContributionAfterDeaths(tfaExpectedContribution(teamSize), teamSize, deaths);
		return tfa(contribution, teamSize, baseChance);
	}

	/**
	 * Expected uniques for the whole team in one Chambers raid: 1% per 8,676 points, each
	 * roll capped at 570,000 points (65.7%), with further points rolling for another unique.
	 */
	public static double coxTeamUniques(int teamPoints)
	{
		double uniques = 0;
		for (int roll = 0; roll < COX_MAX_ROLLS; roll++)
		{
			int points = Math.min(Math.max(teamPoints - roll * COX_POINTS_PER_ROLL, 0), COX_POINTS_PER_ROLL);
			uniques += points / COX_POINTS_PER_PERCENT / 100;
		}
		return uniques;
	}

	/**
	 * Your expected uniques for one Chambers raid. Each unique goes to a player with a
	 * chance equal to their share of the points. NaN when the points are unknown.
	 */
	public static double cox(int personalPoints, int teamPoints)
	{
		if (personalPoints <= 0)
		{
			return Double.NaN;
		}
		int team = Math.max(teamPoints, personalPoints);
		return coxTeamUniques(team) * personalPoints / team;
	}

	/**
	 * The raid level used for unique rolls: full up to 310, a third from 310 to 430, and a
	 * sixth above that.
	 */
	public static double toaScaledLevel(int raidLevel)
	{
		if (raidLevel <= 310)
		{
			return Math.max(0, raidLevel);
		}
		if (raidLevel <= 430)
		{
			return 310 + (raidLevel - 310) / 3.0;
		}
		return 350 + (raidLevel - 430) / 6.0;
	}

	/** Team points for 1% unique chance at this raid level: 10,500 - 20 x scaled level. */
	public static double toaPointsPerPercent(int raidLevel)
	{
		return 10_500 - 20 * toaScaledLevel(raidLevel);
	}

	/** The team's chance of a unique, capped at 55%. Points without the 5,000 starting points. */
	public static double toaTeamChance(double teamPoints, int raidLevel)
	{
		return Math.min(TOA_MAX_CHANCE, Math.max(0, teamPoints) / toaPointsPerPercent(raidLevel) / 100);
	}

	/**
	 * Your chance of a unique for one Tombs raid. Only one unique per raid; it goes to a
	 * player with a chance equal to their share of the points.
	 *
	 * @param personalPoints your points without the 5,000 starting points
	 * @param partyPoints    points the whole party earns once (puzzles); yours when solo
	 * @param teamPoints     the team total, 0 when unknown
	 * @param teamSize       players in the raid
	 * @return NaN when the points or raid level are unknown
	 */
	public static double toa(int personalPoints, int partyPoints, int teamPoints, int teamSize, int raidLevel)
	{
		if (personalPoints <= 0 || raidLevel < 0)
		{
			return Double.NaN;
		}
		if (teamSize <= 1)
		{
			return toaTeamChance(personalPoints + Math.max(0, partyPoints), raidLevel);
		}
		if (teamPoints > 0)
		{
			int team = Math.max(teamPoints, personalPoints);
			return toaTeamChance(team, raidLevel) * personalPoints / team;
		}
		// Team total unknown: below the 55% cap your share works out to your own points
		// over the points per percent, whatever the others did.
		return Math.min(TOA_MAX_CHANCE, personalPoints / toaPointsPerPercent(raidLevel) / 100);
	}

	/**
	 * Tombs of Amascut pet (Tumeken's guardian): 1% per (350,000 - 700 x level) points, where the
	 * level counts in full up to 400 and a third above that, up to 550. Not capped at 55%.
	 */
	public static double toaPetPointsPerPercent(int raidLevel)
	{
		int level = Math.min(550, Math.max(0, raidLevel));
		double scaled = level <= 400 ? level : 400 + (level - 400) / 3.0;
		return 350_000 - 700 * scaled;
	}

	/** Your chance of the pet in one raid, split over the team like a purple. NaN without points. */
	public static double toaPet(int personalPoints, int partyPoints, int teamPoints, int teamSize, int raidLevel)
	{
		if (personalPoints <= 0 || raidLevel < 0)
		{
			return Double.NaN;
		}
		double perPercent = toaPetPointsPerPercent(raidLevel);
		if (teamSize <= 1)
		{
			return Math.min(1, (personalPoints + Math.max(0, partyPoints)) / perPercent / 100);
		}
		// your share of the team's chance is your own points over the points per percent
		return Math.min(1, personalPoints / perPercent / 100);
	}

	/** How much of an item's normal share survives at this raid level (1, or 1/50 below its minimum). */
	public static double toaLevelFactor(int raidLevel, Integer minRaidLevel)
	{
		if (minRaidLevel == null || raidLevel < 0 || raidLevel >= minRaidLevel)
		{
			return 1;
		}
		return TOA_LOW_LEVEL_KEEP;
	}
}

package legacy.expecteddrops.stats;

/**
 * Player settings the drop maths needs: raid purple chances, and how much of the damage
 * the player does at team bosses.
 */
public interface RaidSettings
{
	/** Chance that a raid mode gives you a unique (a "purple"), as a fraction between 0 and 1. */
	double uniqueChance(String raid);

	/**
	 * The team size {@link #uniqueChance} assumes (ToB splits the team's purples between
	 * the players). Raids with a known team size scale from this.
	 */
	default int teamSize(String raid)
	{
		return 1;
	}

	/**
	 * The Fractured Archive: the team's unique chance for a duo with no deaths (before the bonus
	 * for bigger teams), which raids with a known team size scale from.
	 */
	default double tfaBaseChance()
	{
		return RaidChance.TFA_BASE_CHANCE;
	}

	/**
	 * Your average share of the drops at a team boss over {@code kills} kills: 1 when you
	 * did everything solo, 0.5 for all duos. Pets that don't scale are not affected.
	 */
	default double contribution(String team, int kills)
	{
		return 1.0;
	}

	/** Short text for the panel explaining the split used, e.g. "300 solo and 120 duo kills". */
	default String contributionNote(String team, int kills)
	{
		return null;
	}
}

package legacy.expecteddrops.stats;

/**
 * Numbers for one row in the panel.
 */
public class RowStats
{
	private final String label;
	private final String iconItem;
	private double rate;
	private final double expected;
	private final int received;
	private final boolean any;
	private boolean once;
	private int cap;
	private Integer streak;
	private boolean streakExact;
	/** Fewest and most kills between two drops On Rate saw, or null. */
	private Integer fastest;
	private Integer longest;
	private double driestMultiple = Double.NaN;
	private String driestItem;
	private String mark = "";
	/** How the expected count is made up (see {@link Parts}), or null for a single plain count. */
	private Parts parts;
	/** Set on a copy made for a list ordered by something else (see {@link #withDisplayLuck}). */
	private Double luckOverride;

	/**
	 * What a total (the "Any" row, the account, a drop with a sure copy) is made of: copies that
	 * drop for certain, a part with no limit, and items of which only a few copies count, each
	 * with its uncapped expected. Its luck and chance come from these, not from a Poisson of the
	 * total: a pet's "have it or not" isn't Poisson, nor is a sure copy.
	 */
	public static final class Parts
	{
		private int sure;
		private double plain;
		private final java.util.List<Double> cappedMeans = new java.util.ArrayList<>();
		private final java.util.List<Integer> caps = new java.util.ArrayList<>();
		/** Items sure on one kill for a player with none yet: {kills, rate, kill with the guarantee}. */
		private final java.util.List<double[]> guaranteed = new java.util.ArrayList<>();

		/** {@code count} copies that drop for certain. */
		public Parts addSure(int count)
		{
			sure += count;
			return this;
		}

		/** Expected copies with no limit. */
		public Parts addPlain(double expected)
		{
			plain += expected;
			return this;
		}

		/**
		 * An item rolled at {@code rate} per kill that is sure on kill {@code at} for a player with
		 * none yet (Vorkath's head on the 50th), seen after {@code kills} kills.
		 */
		public Parts addGuaranteed(double kills, double rate, int at)
		{
			guaranteed.add(new double[]{kills, rate, at});
			return this;
		}

		/** An item of which at most {@code cap} copies count, with its uncapped expected. */
		public Parts addCapped(double expected, int cap)
		{
			cappedMeans.add(expected);
			caps.add(cap);
			return this;
		}

		/** Everything a row stands for: its own parts, or else its plain or capped count. */
		public Parts add(RowStats row)
		{
			if (row.parts != null)
			{
				sure += row.parts.sure;
				plain += row.parts.plain;
				cappedMeans.addAll(row.parts.cappedMeans);
				caps.addAll(row.parts.caps);
				guaranteed.addAll(row.parts.guaranteed);
			}
			else if (row.cap > 0)
			{
				addCapped(row.expected, row.cap);
			}
			else
			{
				addPlain(row.expected);
			}
			return this;
		}

		/** Expected copies that count. */
		public double expected()
		{
			double total = sure + plain + guaranteedTotal();
			for (int i = 0; i < caps.size(); i++)
			{
				total += DropMath.expectedCapped(cappedMeans.get(i), caps.get(i));
			}
			return total;
		}

		/** Expected copies if nothing were capped: what the drop rates add up to. */
		double uncapped()
		{
			double total = sure + plain + guaranteedTotal();
			for (double m : cappedMeans)
			{
				total += m;
			}
			return total;
		}

		private double guaranteedTotal()
		{
			double total = 0;
			for (double[] g : guaranteed)
			{
				total += DropMath.guaranteedExpected(g[0], g[1], (int) g[2]);
			}
			return total;
		}

		/** True once a player with none is bound to have one: some guaranteed kill has passed. */
		private boolean certain()
		{
			for (double[] g : guaranteed)
			{
				if (g[0] >= g[2])
				{
					return true;
				}
			}
			return sure > 0;
		}

		double[] shares(int received)
		{
			double[] means = new double[cappedMeans.size()];
			int[] limits = new int[caps.size()];
			for (int i = 0; i < means.length; i++)
			{
				means[i] = cappedMeans.get(i);
				limits[i] = caps.get(i);
			}
			return DropMath.sharesSum(received, sure, plain, means, limits, guaranteed);
		}
	}

	public RowStats(String label, String iconItem, double rate, double expected, int received, boolean any)
	{
		this.label = label;
		this.iconItem = iconItem;
		this.rate = rate;
		this.expected = expected;
		this.received = received;
		this.any = any;
	}

	/**
	 * Marks this row as an item the collection log counts at most once (a pet, a prayer
	 * scroll). The expected number stays as is; luck becomes "have it or not".
	 */
	public RowStats once(int receivedCapped)
	{
		return capped(1, receivedCapped);
	}

	/**
	 * Marks this row as counting at most {@code cap} copies (the two Royal Titans prayer
	 * scrolls in one row). Luck tops out once you have them all.
	 */
	public RowStats capped(int cap, int receivedCapped)
	{
		RowStats copy = new RowStats(label, iconItem, rate, expected, receivedCapped, any);
		copy.once = cap == 1;
		copy.cap = cap;
		copy.streak = streak;
		copy.streakExact = streakExact;
		copy.fastest = fastest;
		copy.longest = longest;
		copy.parts = parts;
		return copy;
	}

	/**
	 * A copy that reports {@code luck} (NaN for none) as its luck, for a list ordered by something
	 * other than uniques (GP value): its word, dot and colour then follow that. The row's numbers
	 * and the shares behind its hover stay its own.
	 */
	public RowStats withDisplayLuck(double luck)
	{
		RowStats copy = new RowStats(label, iconItem, rate, expected, received, any);
		copy.once = once;
		copy.cap = cap;
		copy.streak = streak;
		copy.streakExact = streakExact;
		copy.fastest = fastest;
		copy.longest = longest;
		copy.driestMultiple = driestMultiple;
		copy.driestItem = driestItem;
		copy.mark = mark;
		copy.parts = parts;
		copy.luckOverride = luck;
		return copy;
	}

	/** Sets what this row's expected count is made of; its luck and chance then follow from it. */
	public RowStats withParts(Parts parts)
	{
		this.parts = parts;
		return this;
	}

	public Parts getParts()
	{
		return parts;
	}

	/** Sets the dry streak: kills since the last copy (or since tracking began when not exact). */
	public RowStats withStreak(Integer kills, boolean exact)
	{
		this.streak = kills;
		this.streakExact = exact;
		return this;
	}

	/** Records since On Rate started: fewest and most kills between two drops (null if none). */
	public RowStats withRecords(Integer fastest, Integer longest)
	{
		this.fastest = fastest;
		this.longest = longest;
		return this;
	}

	public Integer getFastest()
	{
		return fastest;
	}

	public Integer getLongest()
	{
		return longest;
	}

	/** For the "Any" row: the summed rate of all its items, so its streak can be expressed in rates. */
	public RowStats withRate(double rate)
	{
		this.rate = rate;
		return this;
	}

	/** For a boss row in the account overview: its driest item right now. */
	public RowStats withDriest(double multiple, String item)
	{
		this.driestMultiple = multiple;
		this.driestItem = item;
		return this;
	}

	/** Adds a mark shown after the label (" *" for estimates); the label itself stays the same. */
	public RowStats withMark(String mark)
	{
		this.mark = mark == null ? "" : mark;
		return this;
	}

	/** The label as shown in the panel, with its mark. */
	public String getShownLabel()
	{
		return label + mark;
	}

	public double getDriestMultiple()
	{
		return driestMultiple;
	}

	public String getDriestItem()
	{
		return driestItem;
	}

	/** Kills since the last copy, or null when unknown (or the item is a pet you already have). */
	public Integer getStreak()
	{
		return streak;
	}

	/** False when the last copy came before On Rate started tracking: the streak is a minimum. */
	public boolean isStreakExact()
	{
		return streakExact;
	}

	/** The streak in multiples of the drop rate: 1.0 means one full drop rate without a copy. */
	public double getStreakMultiple()
	{
		return streak == null ? Double.NaN : streak * rate;
	}

	public boolean isOnce()
	{
		return once;
	}

	/** At most this many copies count, 0 for no limit. */
	public int getCap()
	{
		return cap;
	}

	/** True when you have every copy that counts (a pet you own, both titan scrolls). */
	public boolean isComplete()
	{
		return cap > 0 && received >= cap;
	}

	public String getLabel()
	{
		return label;
	}

	/** Item name to show as the icon, or null for the "Any" row. */
	public String getIconItem()
	{
		return iconItem;
	}

	/** Per-kill rate (0 for the "Any" row). */
	public double getRate()
	{
		return rate;
	}

	public double getExpected()
	{
		return expected;
	}

	public int getReceived()
	{
		return received;
	}

	public boolean isAny()
	{
		return any;
	}

	/**
	 * Expected copies if none were capped: kills times the drop rates. For a pet that's the
	 * pet's expected; for the "Any" row it's what "1x the unique rate" counts.
	 */
	public double getUncappedExpected()
	{
		return parts == null ? expected : parts.uncapped();
	}

	/**
	 * Chance of having had at least one by now. A cap doesn't change the chance of none, so
	 * this goes by the uncapped expected; a sure copy, or a guaranteed kill passed, makes it certain.
	 */
	public double getChanceAtLeastOne()
	{
		if (parts != null && parts.certain())
		{
			return 1;
		}
		return DropMath.chanceAtLeastOne(getUncappedExpected());
	}

	/**
	 * Luck (0..1, 0.5 = average) behind the verdict, tie-aware (see {@link DropMath#tieAware}).
	 * NaN if nothing expected yet.
	 */
	public double getLuck()
	{
		if (luckOverride != null)
		{
			return luckOverride;
		}
		double[] s = getShares();
		return s == null ? Double.NaN : DropMath.tieAware(s[0], s[1]);
	}

	/**
	 * Of players at the same kill count: {share with fewer, share with the same}; the rest have
	 * more. Null if nothing expected yet.
	 */
	public double[] getShares()
	{
		if (parts != null)
		{
			return parts.shares(received);
		}
		return cap > 0 ? DropMath.sharesCapped(received, expected, cap) : DropMath.shares(received, expected);
	}
}

package legacy.expecteddrops.stats;

import java.util.Collections;
import java.util.List;

/**
 * An item several bosses drop (dragon pickaxe, uncut onyx...). The collection log has one
 * total for all of them, so its luck is the bosses' expected added up against that total.
 */
public class SharedPool
{
	private final String label;
	private final String itemName;
	private final double expected;
	private final int received;
	private final List<String> bosses;
	private final List<String> missingPages;
	private boolean logKnown = true;
	private boolean once;
	private String alsoFrom;
	private String key;
	private boolean splittable;
	private int olderCopies;
	private boolean splitNeedsAnswer;

	public SharedPool(String label, String itemName, double expected, int received, List<String> bosses, List<String> missingPages)
	{
		this.label = label;
		this.itemName = itemName;
		this.expected = expected;
		this.received = received;
		this.bosses = Collections.unmodifiableList(bosses);
		this.missingPages = Collections.unmodifiableList(missingPages);
	}

	public String getLabel()
	{
		return label;
	}

	public String getItemName()
	{
		return itemName;
	}

	/** Expected drops from all the bosses together, uncapped (for a pet: its expected, not the chance of one). */
	public double getExpected()
	{
		return expected;
	}

	/** The copies that count: for an item the log counts once (a pet), the chance of having one by now. */
	public double getCountedExpected()
	{
		return once ? DropMath.chanceAtLeastOne(expected) : expected;
	}

	/** True for an item the collection log counts at most once (the Chaos elemental pet). */
	public boolean isOnce()
	{
		return once;
	}

	public SharedPool withOnce(boolean once)
	{
		this.once = once;
		return this;
	}

	/** "dust devils and smoke devils": monsters outside the bosses whose copies the log counts too, or null. */
	public String getAlsoFrom()
	{
		return alsoFrom;
	}

	public SharedPool withAlsoFrom(String alsoFrom)
	{
		this.alsoFrom = alsoFrom;
		return this;
	}

	/** The pool's key (its normalized item name), for choosing to judge it per boss. */
	public String getKey()
	{
		return key;
	}

	public SharedPool withKey(String key)
	{
		this.key = key;
		return this;
	}

	/**
	 * True when it can be judged on each boss separately: only the bosses drop it (nothing like
	 * devils or other dragons the log also counts) and the log total is known.
	 */
	public boolean isSplittable()
	{
		return splittable;
	}

	/** Copies in the log On Rate didn't see drop (from before it, or played elsewhere). */
	public int getOlderCopies()
	{
		return olderCopies;
	}

	/** True when it was judged per boss, but the log has gained copies On Rate didn't see since. */
	public boolean isSplitNeedsAnswer()
	{
		return splitNeedsAnswer;
	}

	public SharedPool withSplit(boolean splittable, int olderCopies, boolean needsAnswer)
	{
		this.splittable = splittable;
		this.olderCopies = olderCopies;
		this.splitNeedsAnswer = needsAnswer;
		return this;
	}

	/** The collection log total. */
	public int getReceived()
	{
		return received;
	}

	/** Every boss that drops it. */
	public List<String> getBosses()
	{
		return bosses;
	}

	/** Collection log pages still to open before this item can be counted; empty when complete. */
	public List<String> getMissingPages()
	{
		return missingPages;
	}

	/** False until a collection log page showing this item has been opened (received unknown). */
	public boolean isLogKnown()
	{
		return logKnown;
	}

	public SharedPool withLogKnown(boolean logKnown)
	{
		this.logKnown = logKnown;
		return this;
	}

	public boolean isComplete()
	{
		return missingPages.isEmpty();
	}

	/** A row for the panel: "have it or not" for an item counted once, like every pet row. */
	public RowStats toRow()
	{
		RowStats row = new RowStats(label, itemName, 0, expected, received, false);
		return once ? row.capped(1, Math.min(1, received)) : row;
	}
}

