package legacy.expecteddrops.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** A speedometer from Dry (left) to Spooned (right) with a needle at your luck. */
class LuckGauge extends JComponent
{
	private double luck = Double.NaN;

	LuckGauge()
	{
		setPreferredSize(new Dimension(160, 104));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 104));
		setAlignmentX(LEFT_ALIGNMENT);
		setOpaque(false);
	}

	void setLuck(double luck)
	{
		this.luck = luck;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int r = Math.min(getWidth() / 2 - 24, getHeight() - 26);
		int cx = getWidth() / 2;
		int cy = r + 6;
		double[] bands = LuckStrip.BANDS;
		g.setStroke(new BasicStroke(14, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
		int inset = 7;
		for (int i = 0; i < bands.length - 1; i++)
		{
			double mid = (bands[i] + bands[i + 1]) / 2;
			g.setColor(Palette.luck(mid));
			int start = 180 - (int) Math.round(bands[i] * 180);
			int extent = -(int) Math.round((bands[i + 1] - bands[i]) * 180);
			g.drawArc(cx - r + inset, cy - r + inset, 2 * (r - inset), 2 * (r - inset), start, extent);
		}
		if (!Double.isNaN(luck))
		{
			double angle = Math.PI * (1 - luck);
			int nx = cx + (int) Math.round(Math.cos(angle) * (r - 10));
			int ny = cy - (int) Math.round(Math.sin(angle) * (r - 10));
			g.setColor(Color.WHITE);
			g.setStroke(new BasicStroke(3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(cx, cy, nx, ny);
			g.fillOval(cx - 5, cy - 5, 10, 10);
		}
		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		g.drawString("Dry", cx - r, cy + 16);
		String sp = "Spooned";
		g.drawString(sp, cx + r - g.getFontMetrics().stringWidth(sp), cy + 16);
		g.dispose();
	}
}

package legacy.expecteddrops.ui;

import legacy.expecteddrops.stats.DropMath;
import legacy.expecteddrops.tracking.HistoryPoint;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.JComponent;
import javax.swing.ToolTipManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Line chart of the account's luck over time: dry at the bottom, spooned at the top, with the
 * "on rate" band around the middle shaded.
 */
class LuckGraph extends JComponent
{
	private static final int HEIGHT = 110;
	private static final int PAD_LEFT = 44;
	private static final int PAD_RIGHT = 6;
	private static final int PAD_TOP = 6;
	private static final int PAD_BOTTOM = 16;
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter LONG_DATE = DateTimeFormatter.ofPattern("d MMM yyyy", Locale.ENGLISH);

	/** The history line: light grey, so it reads on all three bands. */
	private static final Color LINE = new Color(225, 225, 225);

	private List<HistoryPoint> points = new ArrayList<>();
	/** The point the mouse is nearest to, or -1. */
	private int hover = -1;

	LuckGraph()
	{
		setPreferredSize(new Dimension(100, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setAlignmentX(LEFT_ALIGNMENT);
		ToolTipManager.sharedInstance().registerComponent(this);
		addMouseMotionListener(new java.awt.event.MouseMotionAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				setHover(nearest(e.getX()));
			}
		});
		addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseExited(MouseEvent e)
			{
				setHover(-1);
			}
		});
	}

	/** A plain component has no accessible context; this one says what the picture is. */
	@Override
	public javax.accessibility.AccessibleContext getAccessibleContext()
	{
		if (accessibleContext == null)
		{
			accessibleContext = new AccessibleJComponent()
			{
			};
			accessibleContext.setAccessibleName("Your account's luck over time");
		}
		return accessibleContext;
	}

	private void setHover(int index)
	{
		if (index != hover)
		{
			hover = index;
			repaint();
		}
	}

	/** Index of the point whose x is closest to {@code x}, or -1 without points. */
	private int nearest(int x)
	{
		int best = -1;
		for (int i = 0; i < points.size(); i++)
		{
			if (best < 0 || Math.abs(xFor(points.get(i).getDay()) - x) < Math.abs(xFor(points.get(best).getDay()) - x))
			{
				best = i;
			}
		}
		return best;
	}

	void setPoints(List<HistoryPoint> points)
	{
		this.points = points == null ? new ArrayList<>() : points;
		hover = -1;
		repaint();
	}

	private int plotWidth()
	{
		return Math.max(1, getWidth() - PAD_LEFT - PAD_RIGHT);
	}

	private int plotHeight()
	{
		return Math.max(1, getHeight() - PAD_TOP - PAD_BOTTOM);
	}

	private int xFor(long day)
	{
		long first = points.get(0).getDay();
		long last = points.get(points.size() - 1).getDay();
		if (last == first)
		{
			return PAD_LEFT + plotWidth() / 2;
		}
		return PAD_LEFT + (int) Math.round((day - first) * (double) plotWidth() / (last - first));
	}

	private int yFor(double luck)
	{
		return PAD_TOP + (int) Math.round((1 - luck) * plotHeight());
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ColorScheme.DARKER_GRAY_COLOR);
		g.fillRect(0, 0, getWidth(), getHeight());

		// bands: dry below 35%, the middle (a bit dry, on rate, a bit spooned), spooned above;
		// the same lines as the verdict words (DropMath#verdict)
		int w = plotWidth();
		double dry = DropMath.DRY_BELOW;
		double spooned = DropMath.SPOONED_ABOVE;
		g.setColor(withAlpha(ExpectedDropsPanel.luckColor(0.9), 40));
		g.fillRect(PAD_LEFT, yFor(1), w, yFor(spooned) - yFor(1));
		g.setColor(withAlpha(ExpectedDropsPanel.luckColor(0.5), 40));
		g.fillRect(PAD_LEFT, yFor(spooned), w, yFor(dry) - yFor(spooned));
		g.setColor(withAlpha(ExpectedDropsPanel.luckColor(0.1), 40));
		g.fillRect(PAD_LEFT, yFor(dry), w, yFor(0) - yFor(dry));

		g.setFont(FontManager.getRunescapeSmallFont());
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		// words, not percentages: which end is the lucky one is the first thing to read
		g.drawString("Spooned", 2, yFor(1) + 10);
		g.drawString("On rate", 2, yFor(0.5) + 4);
		g.drawString("Dry", 2, yFor(0) - 1);
		g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
		g.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10, new float[]{3, 3}, 0));
		g.drawLine(PAD_LEFT, yFor(0.5), PAD_LEFT + w, yFor(0.5));

		if (points.isEmpty())
		{
			g.dispose();
			return;
		}

		// dates under the plot: the first, the last and, when there is room, the middle one
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		long firstDay = points.get(0).getDay();
		long lastDay = points.get(points.size() - 1).getDay();
		String first = LocalDate.ofEpochDay(firstDay).format(DATE);
		String last = LocalDate.ofEpochDay(lastDay).format(DATE);
		int baseline = getHeight() - 3;
		g.drawString(first, PAD_LEFT, baseline);
		int lastWidth = g.getFontMetrics().stringWidth(last);
		g.drawString(last, PAD_LEFT + w - lastWidth, baseline);
		if (lastDay - firstDay >= 4)
		{
			String middle = LocalDate.ofEpochDay((firstDay + lastDay) / 2).format(DATE);
			int middleWidth = g.getFontMetrics().stringWidth(middle);
			int mx = PAD_LEFT + (w - middleWidth) / 2;
			if (mx > PAD_LEFT + g.getFontMetrics().stringWidth(first) + 6 && mx + middleWidth < PAD_LEFT + w - lastWidth - 6)
			{
				g.drawString(middle, mx, baseline);
			}
		}

		// the hovered day: a faint guide line, so the tooltip is clearly about this point
		if (hover >= 0 && hover < points.size())
		{
			int hx = xFor(points.get(hover).getDay());
			g.setColor(new Color(255, 255, 255, 70));
			g.setStroke(new BasicStroke(1f));
			g.drawLine(hx, PAD_TOP, hx, PAD_TOP + plotHeight());
		}

		HistoryPoint latest = points.get(points.size() - 1);
		// a neutral line: the coloured bands carry the verdict, so the history isn't painted in today's colour
		g.setColor(LINE);
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int i = 1; i < points.size(); i++)
		{
			HistoryPoint a = points.get(i - 1);
			HistoryPoint b = points.get(i);
			// luck only moves on days you play: across days without a point it stays flat, then
			// changes on the next day you played (a slope over the gap would suggest it drifted)
			long dayBefore = b.getDay() - 1;
			if (dayBefore > a.getDay())
			{
				g.drawLine(xFor(a.getDay()), yFor(a.getLuck()), xFor(dayBefore), yFor(a.getLuck()));
				g.drawLine(xFor(dayBefore), yFor(a.getLuck()), xFor(b.getDay()), yFor(b.getLuck()));
			}
			else
			{
				g.drawLine(xFor(a.getDay()), yFor(a.getLuck()), xFor(b.getDay()), yFor(b.getLuck()));
			}
		}
		if (hover >= 0 && hover < points.size())
		{
			HistoryPoint p = points.get(hover);
			int hx = xFor(p.getDay());
			int hy = yFor(p.getLuck());
			g.setColor(Color.WHITE);
			g.fillOval(hx - 4, hy - 4, 9, 9);
			g.setColor(ExpectedDropsPanel.luckColor(p.getLuck()).brighter());
			g.setStroke(new BasicStroke(2f));
			g.drawOval(hx - 4, hy - 4, 9, 9);
		}
		// the latest point, with its verdict beside it
		int x = xFor(latest.getDay());
		int y = yFor(latest.getLuck());
		Color latestColor = ExpectedDropsPanel.luckColor(latest.getLuck()).brighter();
		g.setColor(LINE);
		g.fillOval(x - 3, y - 3, 7, 7);
		String verdict = DropMath.verdict(latest.getLuck());
		if (!verdict.isEmpty())
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			int tw = g.getFontMetrics().stringWidth(verdict);
			int tx = Math.max(PAD_LEFT, Math.min(x - tw / 2, PAD_LEFT + w - tw));
			// above the dot, or below it when the dot is near the top
			int ty = y - 7 > PAD_TOP + 8 ? y - 7 : y + 15;
			g.setColor(latestColor);
			g.drawString(verdict, tx, ty);
		}
		g.dispose();
	}

	@Override
	public String getToolTipText(MouseEvent event)
	{
		if (points.isEmpty())
		{
			return null;
		}
		HistoryPoint nearest = points.get(nearest(event.getX()));
		return String.format(java.util.Locale.ROOT, "<html><b>%s</b><br>%s: %s<br>%d got, %.1f expected</html>",
			LocalDate.ofEpochDay(nearest.getDay()).format(LONG_DATE), DropMath.verdict(nearest.getLuck()),
			Texts.html(Texts.luckPercent(nearest.getLuck())), nearest.getReceived(), nearest.getExpected());
	}

	private static Color withAlpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package legacy.expecteddrops.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JLabel;
import javax.swing.SwingConstants;

/** A ring that fills up (clockwise from the top) around an item picture or a short text. */
class LuckRing extends JLabel
{
	private static final Color TRACK = Theme.TRACK;
	private double fraction;
	private Color color = Color.GRAY;

	LuckRing()
	{
		setPreferredSize(new Dimension(56, 56));
		setMinimumSize(new Dimension(56, 56));
		setHorizontalAlignment(SwingConstants.CENTER);
		setVerticalAlignment(SwingConstants.CENTER);
	}

	void set(double fraction, Color color)
	{
		this.fraction = Math.max(0, Math.min(1, fraction));
		this.color = color;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int size = Math.min(getWidth(), getHeight()) - 6;
		int x = (getWidth() - size) / 2;
		int y = (getHeight() - size) / 2;
		g.setStroke(new BasicStroke(5, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
		g.setColor(TRACK);
		g.drawOval(x, y, size, size);
		g.setColor(color);
		g.drawArc(x, y, size, size, 90, -(int) Math.round(360 * fraction));
		g.dispose();
		super.paintComponent(graphics);
	}
}

package legacy.expecteddrops.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;

/**
 * The dry-to-spooned scale with a dot where you are: five coloured bands in the Luck gauge view, or
 * (in lists, where the scale repeats on every row) one neutral track with a tick at the middle.
 * The dot's place and the verdict word carry the meaning, the colours only echo it.
 */
class LuckStrip extends JComponent
{
	static final double[] BANDS = {0, 0.1, 0.35, 0.65, 0.9, 1};
	private static final Color TRACK = new Color(72, 72, 72);
	private static final Color MIDDLE = new Color(120, 120, 120);
	private double luck = Double.NaN;
	private boolean bands = true;

	LuckStrip()
	{
		setPreferredSize(new Dimension(80, 14));
		setOpaque(false);
	}

	/** False for the neutral track used in lists. */
	void setBands(boolean bands)
	{
		this.bands = bands;
		repaint();
	}

	void setLuck(double luck)
	{
		this.luck = luck;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth() - 8;
		int y = getHeight() / 2;
		if (!bands)
		{
			g.setColor(TRACK);
			g.fillRect(4, y - 1, w, 2);
			g.setColor(MIDDLE);
			g.fillRect(4 + w / 2, y - 4, 1, 8);
		}
		for (int i = 0; bands && i < BANDS.length - 1; i++)
		{
			double mid = (BANDS[i] + BANDS[i + 1]) / 2;
			g.setColor(Palette.blend(Palette.luck(mid), ColorScheme.DARKER_GRAY_COLOR, 0.35));
			int x0 = 4 + (int) Math.round(BANDS[i] * w);
			int x1 = 4 + (int) Math.round(BANDS[i + 1] * w);
			g.fillRect(x0, y - 2, x1 - x0, 4);
		}
		if (!Double.isNaN(luck))
		{
			int x = 4 + (int) Math.round(luck * w);
			g.setColor(Palette.luck(luck).brighter());
			g.fillOval(x - 4, y - 4, 9, 9);
			g.setColor(Color.WHITE);
			g.drawOval(x - 4, y - 4, 9, 9);
		}
		g.dispose();
	}
}

package legacy.expecteddrops.ui;

import java.awt.Color;
import net.runelite.client.ui.ColorScheme;

/**
 * Luck colours: red (dry) to yellow to green (spooned), or orange to grey to blue for
 * colour-blind players.
 */
public final class Palette
{
	static final Color BAD = new Color(170, 40, 30);
	static final Color MID = new Color(170, 150, 20);
	static final Color GOOD = new Color(46, 160, 67);

	static final Color CB_BAD = new Color(220, 120, 20);
	static final Color CB_MID = new Color(140, 140, 140);
	static final Color CB_GOOD = new Color(40, 110, 200);

	private static volatile boolean colourBlind;

	private Palette()
	{
	}

	public static void setColourBlind(boolean on)
	{
		colourBlind = on;
	}

	/** Colour for a luck percentile 0..1 (grey when unknown). */
	public static Color luck(double luck)
	{
		if (Double.isNaN(luck))
		{
			return ColorScheme.MEDIUM_GRAY_COLOR;
		}
		Color bad = colourBlind ? CB_BAD : BAD;
		Color mid = colourBlind ? CB_MID : MID;
		Color good = colourBlind ? CB_GOOD : GOOD;
		if (luck < 0.5)
		{
			return blend(bad, mid, luck / 0.5);
		}
		return blend(mid, good, (luck - 0.5) / 0.5);
	}

	/**
	 * The verdict colour on a boss page: the dry and spooned bands (a third of players each) are
	 * toned down, so only very dry and very spooned get the full colour.
	 */
	static Color verdict(double luck)
	{
		Color c = luck(luck);
		boolean mild = !Double.isNaN(luck) && (luck >= 0.10 && luck < 0.35 || luck > 0.65 && luck <= 0.90);
		return mild ? blend(c, new Color(170, 170, 170), 0.3) : c;
	}

	/** The "you have it" colour. */
	public static Color good()
	{
		return colourBlind ? CB_GOOD : GOOD;
	}

	static Color blend(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	/** A quiet background in the hue of a luck colour (the pill under a verdict). */
	static Color tint(Color c)
	{
		return blend(Theme.SURFACE, c, 0.2);
	}

	/** Text on a {@link #tint}: the luck colour, lifted a little so it stays readable. */
	static Color onTint(Color c)
	{
		return blend(c, Color.WHITE, 0.22);
	}

	static Color withAlpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package legacy.expecteddrops.ui;

import legacy.expecteddrops.stats.AccountStats;
import legacy.expecteddrops.stats.DropMath;
import legacy.expecteddrops.stats.ItemHighlight;
import legacy.expecteddrops.stats.RowStats;
import java.util.Locale;

/**
 * The plain text behind "Copy my luck": your account's verdicts in a few lines you can paste into
 * Discord or Reddit. It uses the same words and numbers as the panel and nothing else, and is never
 * sent anywhere: the player pastes it themselves.
 */
final class ShareText
{
	/** An item counts as a brag when it is past "Spooned" (more than 65% of players have fewer). */
	private static final double BRAG_ABOVE = 0.65;

	private ShareText()
	{
	}

	/**
	 * The account's verdicts as text, or null when there is nothing to share yet (no boss loaded,
	 * or no verdict).
	 *
	 * @param showValue whether the GP value setting is on, as for the tiles in the panel
	 */
	static String account(AccountStats account, boolean showValue)
	{
		if (account == null || account.getRows().isEmpty())
		{
			return null;
		}
		RowStats total = account.getTotal();
		String verdict = DropMath.verdict(total.getLuck());
		if (verdict.isEmpty())
		{
			return null;
		}

		StringBuilder out = new StringBuilder();
		out.append(String.format(Locale.ROOT, "On Rate: %s · %,d unique%s, %s expected", verdict, total.getReceived(),
			total.getReceived() == 1 ? "" : "s", Texts.formatExpected(total.getExpected())));
		String how = Texts.luckShort(total.getShares(), total.getReceived());
		if (how != null && !how.isEmpty())
		{
			out.append(" (").append(how).append(')');
		}

		// the GP value verdict, under the same rule as the GP value tile
		if (showValue && account.getExpectedValue() > 0 && !Double.isNaN(account.getValueLuck()))
		{
			String valueVerdict = DropMath.verdict(account.getValueLuck());
			if (!valueVerdict.isEmpty())
			{
				out.append(String.format(Locale.ROOT, "%nGP value: %s · %s got, %s expected", valueVerdict,
					DropMath.formatGp(account.getReceivedValue()), DropMath.formatGp(account.getExpectedValue())));
			}
		}

		int bosses = account.getRows().size();
		out.append(String.format(Locale.ROOT, "%n%,d boss%s", bosses, bosses == 1 ? "" : "es"));
		ItemHighlight best = luckiest(account);
		if (best != null)
		{
			out.append(" · Luckiest: ").append(best.getRow().getLabel()).append(" (").append(best.getBoss()).append("), ")
				.append(DropMath.verdict(best.getRow().getLuck()));
		}
		return out.toString();
	}

	/** The item you got that is furthest on the lucky side, if any is past "Spooned". */
	private static ItemHighlight luckiest(AccountStats account)
	{
		ItemHighlight best = null;
		for (ItemHighlight h : account.getItems())
		{
			RowStats row = h.getRow();
			double luck = row.getLuck();
			if (row.getReceived() <= 0 || Double.isNaN(luck) || luck <= BRAG_ABOVE)
			{
				continue;
			}
			if (best == null || luck > best.getRow().getLuck())
			{
				best = h;
			}
		}
		return best;
	}
}

package legacy.expecteddrops.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.BasicStroke;
import javax.swing.JComponent;

/**
 * A thin bar: the fill is what you received, the white line is what you should have by now.
 */
class TargetBar extends JComponent
{
	private static final Color TRACK = Theme.TRACK;
	private double fill;
	private double marker = -1;
	private Color color = Color.GRAY;
	private boolean quiet;

	TargetBar()
	{
		setPreferredSize(new Dimension(100, 10));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 10));
		setOpaque(false);
	}

	/** A quiet bar (nothing expected yet) has a slimmer track and a grey tick instead of a white one. */
	void setQuiet(boolean quiet)
	{
		this.quiet = quiet;
		int height = quiet ? 8 : 10;
		setPreferredSize(new Dimension(100, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		repaint();
	}

	/** Fractions of the bar width; marker below 0 hides the line. */
	void set(double fill, double marker, Color color)
	{
		this.fill = Math.max(0, Math.min(1, fill));
		this.marker = marker;
		this.color = color;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		int w = getWidth();
		int h = getHeight();
		g.setColor(TRACK);
		g.fillRect(0, 2, w, h - 4);
		g.setColor(color);
		g.fillRect(0, 2, (int) Math.round(w * fill), h - 4);
		if (marker >= 0)
		{
			int x = (int) Math.round(Math.min(1, marker) * (w - 2));
			g.setColor(quiet ? Theme.QUIET_MARK : Color.WHITE);
			g.setStroke(new BasicStroke(2));
			g.drawLine(x + 1, 0, x + 1, h);
		}
		g.dispose();
	}
}

package legacy.expecteddrops.ui;

import legacy.expecteddrops.data.BossDefinition;
import legacy.expecteddrops.stats.RowStats;
import java.util.ArrayList;
import java.util.List;

/**
 * The panel's words and numbers: small functions that turn stats into short text. Kept apart
 * from the Swing code so they are easy to read and test.
 */
final class Texts
{
	private Texts()
	{
	}

	/** Boss page: a log page of this boss was opened but could not be read. */
	static final String LOG_PAGE_UNREADABLE = "Log page opened but not readable. The game may have changed; please report it.";

	static final String LOG_PAGE_UNREADABLE_TIP = "On Rate could not read this page, so your numbers are unchanged. "
		+ "A missing read does not mean zero drops. To clear this boss on purpose, use \"Reset this boss\u2026\". "
		+ "You can report it on On Rate's GitHub page.";

	static final String SETUP_UNREADABLE_TIP = "On Rate could not read it, so your numbers are unchanged. "
		+ "A missing read does not mean zero drops. You can report it on On Rate's GitHub page.";

	/**
	 * The one line in the setup area when log pages were opened but could not be read, or null when
	 * there is nothing to say (the normal case).
	 */
	static String setupProblem(List<String> pages, boolean headerUnreadable)
	{
		if (!headerUnreadable && pages.isEmpty())
		{
			return null;
		}
		String which = !headerUnreadable && pages.size() == 1 ? "The \"" + pages.get(0) + "\" log page"
			: "A collection log page";
		return which + " was opened but could not be read. The game may have changed; please report it.";
	}

	/** "today", "yesterday", "3 days ago" for a time in milliseconds. */
	static String daysAgo(long time, long now)
	{
		if (time <= 0)
		{
			// added by hand from memory: the kill count is known, the date isn't
			return "date unknown";
		}
		long days = java.time.temporal.ChronoUnit.DAYS.between(
			java.time.Instant.ofEpochMilli(time).atZone(java.time.ZoneId.systemDefault()).toLocalDate(),
			java.time.Instant.ofEpochMilli(now).atZone(java.time.ZoneId.systemDefault()).toLocalDate());
		return days <= 0 ? "today" : days == 1 ? "yesterday" : String.format(java.util.Locale.ROOT, "%,d days ago", days);
	}

	/**
	 * How lucky one drop was: "quicker than 99.9% of players (1 in 1,000)" when it came before the
	 * drop rate says, "slower than 94% of players" when after, "" when the wait isn't known exactly.
	 * The "1 in N" is how many players are as quick (or as slow) as you; it is left out when it is
	 * under 1 in 10.
	 */
	static String dropLuck(legacy.expecteddrops.tracking.KillEntry.DropEntry d)
	{
		if (d.getMultiple() == null || d.isAtLeast())
		{
			return "";
		}
		// older versions saved a multiple rounded to two decimals: 0.00 is only known to be under 0.005
		return waitLuck(d.getMultiple());
	}

	/** {@link #dropLuck} for a wait of {@code multiple} times the drop rate (also a wait still going on). */
	static String waitLuck(double multiple)
	{
		boolean floor = multiple == 0;
		double m = floor ? 0.005 : multiple;
		if (m == 1)
		{
			return "right on the drop rate";
		}
		boolean quick = m < 1;
		// players slower than you (quick) or as slow as you (slow), and as quick as you or quicker
		double behind = Math.exp(-m);
		double oneIn = quick ? 1 / (1 - behind) : 1 / behind;
		String text = (quick ? "quicker than " : "slower than ") + shareText(quick ? behind : 1 - behind) + " of players";
		if (oneIn >= 10)
		{
			text += " (1 in " + (floor ? "200+" : oneInText(oneIn)) + ")";
		}
		return text;
	}

	/** {@link #dropLuck} for a list row: "1 in 34 players this quick", "1 in 30 players wait this long". */
	static String dropLuckShort(legacy.expecteddrops.tracking.KillEntry.DropEntry d)
	{
		return d.getMultiple() == null || d.isAtLeast() ? "" : waitLuckShort(d.getMultiple(), false);
	}

	/**
	 * Short luck wording for a list row. {@code ongoing}: the wait isn't over yet ("1 in 16 still
	 * waiting"). Under 1 in 10 it falls back to "quicker/slower than 74%".
	 */
	static String waitLuckShort(double multiple, boolean ongoing)
	{
		boolean floor = multiple == 0;
		double m = floor ? 0.005 : multiple;
		if (m == 1)
		{
			return "right on the drop rate";
		}
		boolean quick = m < 1;
		double behind = Math.exp(-m);
		double oneIn = quick ? 1 / (1 - behind) : 1 / behind;
		if (oneIn >= 10)
		{
			String n = floor ? "200+" : oneInText(oneIn);
			return quick ? "1 in " + n + " players this quick"
				: ongoing ? "1 in " + n + " still waiting" : "1 in " + n + " players wait this long";
		}
		return (quick ? "quicker than " : "slower than ") + shareText(quick ? behind : 1 - behind);
	}

	private static String shareText(double share)
	{
		return share >= 0.9995 ? ">99.9%" : share >= 0.995 ? String.format(java.util.Locale.ROOT, "%.1f%%", share * 100)
			: share < 0.005 ? "<1%" : String.format(java.util.Locale.ROOT, "%.0f%%", share * 100);
	}

	/** 3 significant digits: 25, 1,030, 41,200. */
	private static String oneInText(double n)
	{
		double scale = Math.pow(10, Math.max(0, Math.floor(Math.log10(n)) - 2));
		return String.format(java.util.Locale.ROOT, "%,.0f", Math.round(n / scale) * scale);
	}

	/** "after 7 kills (0.1x)", "your first one", or "" when the gap is unknown. */
	static String afterText(legacy.expecteddrops.tracking.KillEntry.DropEntry d, String unit)
	{
		if (d.isFirst())
		{
			return "your first one";
		}
		if (d.getSince() == null)
		{
			return d.isEntered() ? "added by you" : "";
		}
		if (d.isAtLeast())
		{
			return String.format(java.util.Locale.ROOT, "after %,d+ %ss", d.getSince(), unit);
		}
		return String.format(java.util.Locale.ROOT, "after %,d %s%s", d.getSince(), unit, d.getSince() == 1 ? "" : "s")
			+ (d.getMultiple() == null ? "" : " (" + formatMultiple(d.getMultiple()) + ")");
	}

	/**
	 * "Vorkath 437", or for a page with several bosses the one that dropped it with its own
	 * kill count ("Callisto 96"); raid modes other than Normal get a short tag ("CoX CM 12").
	 */
	static String whereText(BossDefinition boss, String bossName, legacy.expecteddrops.tracking.KillEntry kill)
	{
		if (boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null)
		{
			if (boss.getRaid() == null)
			{
				return String.format(java.util.Locale.ROOT, "%s %,d", kill.getPart(), kill.getPartKc());
			}
			if (!"Normal".equals(kill.getPart()))
			{
				return String.format(java.util.Locale.ROOT, "%s %s %,d", bossName, shortMode(kill.getPart()), kill.getPartKc());
			}
			return String.format(java.util.Locale.ROOT, "%s %,d", bossName, kill.getPartKc());
		}
		return String.format(java.util.Locale.ROOT, "%s %,d", bossName, kill.getKc());
	}

	/**
	 * Where a saved kill happened, for hover rows: the page's boss, or for a page with several
	 * bosses the one it was ("Corrupted Gauntlet", "Artio"), or a raid with its mode ("Tombs of Amascut, Expert Mode").
	 */
	static String whereName(BossDefinition boss, String bossName, legacy.expecteddrops.tracking.KillEntry kill)
	{
		if (boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null)
		{
			if (boss.getRaid() == null)
			{
				return kill.getPart();
			}
			// a raid with one mode needs no "Normal"
			return boss.getParts().size() == 1 ? bossName : bossName + ", " + kill.getPart();
		}
		return bossName;
	}

	/** The kill count of a saved kill as a number: the mode's or boss's own on a page with several, else the page's. */
	static String killCount(BossDefinition boss, legacy.expecteddrops.tracking.KillEntry kill)
	{
		boolean own = boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null;
		return String.format(java.util.Locale.ROOT, "%,d", own ? kill.getPartKc() : kill.getKc());
	}

	/**
	 * The kill count of a saved kill without the boss, for hover rows: "437", or with the mode or
	 * boss of a combined page and its own count ("Challenge Mode 12", "Artio 40").
	 */
	static String killValue(BossDefinition boss, legacy.expecteddrops.tracking.KillEntry kill)
	{
		if (boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null)
		{
			return String.format(java.util.Locale.ROOT, "%s %,d", kill.getPart(), kill.getPartKc());
		}
		return String.format(java.util.Locale.ROOT, "%,d", kill.getKc());
	}

	/** {@link #killValue} with what is counted in front when there is no mode: "Raid 115", "Kill 437". */
	static String killText(BossDefinition boss, legacy.expecteddrops.tracking.KillEntry kill)
	{
		boolean mode = boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null;
		return mode ? killValue(boss, kill)
			: capital(boss == null ? "kill" : legacy.expecteddrops.tracking.Tracker.unitOne(boss)) + " " + killValue(boss, kill);
	}

	static String shortMode(String part)
	{
		switch (part)
		{
			case "Challenge Mode":
				return "CM";
			case "Hard Mode":
				return "HM";
			case "Entry Mode":
				return "Entry";
			case "Expert Mode":
				return "Expert";
			default:
				return part;
		}
	}

	static String formatPoints(int points)
	{
		return points >= 10_000 ? String.format(java.util.Locale.ROOT, "%.1fk", points / 1000.0) : String.format(java.util.Locale.ROOT, "%,d", points);
	}

	/** "Vorkath", "Vorkath and Zulrah", "Vorkath, Zulrah and Cerberus". */
	public static String joinAnd(List<String> names)
	{
		if (names.size() <= 1)
		{
			return String.join("", names);
		}
		return String.join(", ", names.subList(0, names.size() - 1)) + " and " + names.get(names.size() - 1);
	}

	static String lowerFirst(String text)
	{
		return text.isEmpty() ? text : Character.toLowerCase(text.charAt(0)) + text.substring(1);
	}

	/** "2.6×" since the last unique, "1.2×+" when the last one came before On Rate, "-" when unknown. */
	static String streakText(RowStats row)
	{
		double m = row.getStreakMultiple();
		if (Double.isNaN(m) || !row.isStreakExact() && row.getStreak() != null && row.getStreak() == 0)
		{
			// unknown, or the last one came before On Rate and nothing was killed since
			return "-";
		}
		return formatMultiple(m) + (row.isStreakExact() ? "" : "+");
	}

	/**
	 * Luck in plain words: "About 1 in 6 players is this dry (or drier)". Around the middle it
	 * just says you're about average.
	 */
	public static String plainLuck(double luck)
	{
		if (Double.isNaN(luck))
		{
			return null;
		}
		if (luck >= 0.4 && luck <= 0.6)
		{
			return "About average for your kill count";
		}
		if (luck < 0.5)
		{
			long n = Math.max(2, Math.round(1 / Math.max(luck, 0.0001)));
			return String.format(java.util.Locale.ROOT, "About 1 in %,d players is this dry (or drier)", n);
		}
		long n = Math.max(2, Math.round(1 / Math.max(1 - luck, 0.0001)));
		return String.format(java.util.Locale.ROOT, "About 1 in %,d players is this lucky (or luckier)", n);
	}

	/** Chance of at least one more in the next {@code kills}, at {@code rate} per kill. */
	public static double nextChance(double rate, int kills)
	{
		return rate <= 0 ? 0 : -Math.expm1(-rate * kills);
	}

	/**
	 * For something you don't have yet, how far past the drop rate you are, the way players
	 * count it: "2.1\u00d7 the drop rate without one" (1\u00d7 is on rate, 2\u00d7 dry, 3\u00d7 very dry).
	 * Null when you have one, or nothing is expected.
	 */
	static String rateMultipleLine(RowStats row)
	{
		String multiple = rateMultiple(row);
		return multiple == null ? null : multiple + (row.isAny() ? " without a unique" : " without one");
	}

	/** {@link #rateMultipleLine} without its ending, for a hover row: "2.1× the drop rate". */
	static String rateMultiple(RowStats row)
	{
		// the drop rates times the kills: a capped pet still counts in full here
		double multiple = row.getUncappedExpected();
		if (row.getReceived() > 0 || row.isComplete() || !(multiple > 0))
		{
			return null;
		}
		return String.format(java.util.Locale.ROOT, "%s the %s rate", formatMultiple(multiple), row.isAny() ? "unique" : "drop");
	}

	/** The dry streak as a footnote line, or null when unknown. */
	static String streakNote(RowStats row, String unit)
	{
		// with none yet, rateMultipleLine already says how far past the rate you are
		if (row.getStreak() == null || row.getReceived() == 0 && row.isStreakExact())
		{
			return null;
		}
		if (!row.isStreakExact() && row.getStreak() == 0)
		{
			return "Dry streak: your last one came before On Rate, so it counts from your next " + unit + ".";
		}
		String kills = String.format(java.util.Locale.ROOT, "%,d %s%s", row.getStreak(), unit, row.getStreak() == 1 ? "" : "s");
		double m = row.getStreakMultiple();
		boolean multiple = !Double.isNaN(m) && row.getRate() > 0;
		if (!row.isStreakExact())
		{
			// only a minimum is known: the last one came before On Rate
			return "Dry streak: at least " + kills + (multiple ? String.format(java.util.Locale.ROOT, " (%s the drop rate or more)", formatMultiple(m)) : "")
				+ ". Your last one came before On Rate started tracking.";
		}
		return String.format(java.util.Locale.ROOT, "Dry streak: %s %s", kills, row.isAny() ? "since your last unique" : "since your last one")
			+ (multiple ? String.format(java.util.Locale.ROOT, " (%s the drop rate)", formatMultiple(m)) : "") + ".";
	}

	/** Two-column table of completions per delve level, like the Doom plugin's header. */
	static String levelTable(java.util.Map<Integer, Integer> levels)
	{
		StringBuilder sb = new StringBuilder("<html><table cellpadding=0 cellspacing=0>");
		int half = (BossDefinition.DELVE_LEVELS + 1) / 2;
		for (int i = 1; i <= half; i++)
		{
			sb.append("<tr>").append(levelCell(i, levels.get(i)));
			int j = i + half;
			if (j <= BossDefinition.DELVE_LEVELS)
			{
				sb.append("<td width=12></td>").append(levelCell(j, levels.get(j)));
			}
			sb.append("</tr>");
		}
		return sb.append("</table></html>").toString();
	}

	/** "184 raids · 182 Normal · 2 CM" or "Callisto 96 · Artio 624", short enough for the header. */
	static String partLine(java.util.Map<String, Integer> parts, boolean raid, int total)
	{
		List<String> shown = new ArrayList<>();
		for (java.util.Map.Entry<String, Integer> e : parts.entrySet())
		{
			if (e.getValue() > 0)
			{
				String name = raid ? shortMode(e.getKey()) : e.getKey().replace("Dagannoth ", "");
				shown.add(raid ? String.format(java.util.Locale.ROOT, "%,d %s", e.getValue(), name) : String.format(java.util.Locale.ROOT, "%s %,d", name, e.getValue()));
			}
		}
		if (raid)
		{
			shown.add(0, String.format(java.util.Locale.ROOT, "%,d raids", total));
		}
		return String.join(" \u00b7 ", shown);
	}

	/** "Callisto 96 · Artio 624" or "182 Normal · 2 Challenge Mode"; parts with 0 are left out. */
	static String partTable(java.util.Map<String, Integer> parts, boolean raid)
	{
		List<String> shown = new ArrayList<>();
		for (java.util.Map.Entry<String, Integer> e : parts.entrySet())
		{
			if (e.getValue() > 0)
			{
				shown.add(raid ? String.format(java.util.Locale.ROOT, "%,d %s", e.getValue(), e.getKey()) : String.format(java.util.Locale.ROOT, "%s %,d", e.getKey(), e.getValue()));
			}
		}
		return "<html><body style='width: 165px'>" + String.join(" \u00b7 ", shown) + "</body></html>";
	}

	/** Kill count per boss on a combined page, e.g. "Dagannoth Rex: 436". */
	static String levelCell(int level, Integer count)
	{
		return String.format(java.util.Locale.ROOT, "<td><font color='#ffffff'>Level %s:</font></td><td align=right>&nbsp;%,d</td>",
			BossDefinition.delveLevelLabel(level), count == null ? 0 : count);
	}

	static String formatExpected(double expected)
	{
		if (expected >= 100)
		{
			return String.format(java.util.Locale.ROOT, "%.0f", expected);
		}
		if (expected >= 10)
		{
			return String.format(java.util.Locale.ROOT, "%.1f", expected);
		}
		return String.format(java.util.Locale.ROOT, "%.2f", expected);
	}

	static String formatMultiple(double m)
	{
		if (m < 0.1)
		{
			return String.format(java.util.Locale.ROOT, "%.2f\u00d7", m);
		}
		return m < 10 ? String.format(java.util.Locale.ROOT, "%.1f\u00d7", m) : String.format(java.util.Locale.ROOT, "%.0f\u00d7", m);
	}

	static String formatPercent(double p)
	{
		if (p > 0.999)
		{
			return ">99.9%";
		}
		return String.format(java.util.Locale.ROOT, "%.1f%%", p * 100);
	}

	static String initials(String name)
	{
		StringBuilder sb = new StringBuilder();
		for (String part : name.split("[\\s(]+"))
		{
			if (!part.isEmpty() && Character.isLetterOrDigit(part.charAt(0)) && sb.length() < 3)
			{
				sb.append(Character.toUpperCase(part.charAt(0)));
			}
		}
		return sb.toString();
	}

	/**
	 * A luck percentile as a whole percentage for "luckier than ...": "<1%" and ">99%" at the
	 * ends, so a very dry 0.3% doesn't read as "luckier than 0%" (nobody is drier).
	 */
	static String pct(double luck)
	{
		double p = luck * 100;
		if (p < 0.5)
		{
			return "<1%";
		}
		if (p >= 99.5)
		{
			return ">99%";
		}
		return String.format(java.util.Locale.ROOT, "%.0f%%", p);
	}

	/**
	 * Short line under a verdict: how common your result is among players at your kill count.
	 * "74% have none" when you have none, else "1 in 3 as dry" or "1 in 6 as lucky" (also for a
	 * bit dry and a bit spooned), or "about average" when the verdict is "On rate". Matches the tie-aware verdict (see DropMath#tieAware).
	 */
	static String luckShort(double[] shares, int received)
	{
		if (shares == null)
		{
			return "";
		}
		double fewer = shares[0];
		double same = shares[1];
		if (received <= 0 || fewer <= 1e-12)
		{
			if (same >= 0.995)
			{
				return ">99% have none";
			}
			if (same >= 0.5)
			{
				return String.format(java.util.Locale.ROOT, "%.0f%% have none", same * 100);
			}
			return String.format(java.util.Locale.ROOT, "only 1 in %,d has none", Math.max(2, Math.round(1 / Math.max(same, 0.0001))));
		}
		return luckShort(legacy.expecteddrops.stats.DropMath.tieAware(fewer, same));
	}

	/** The same from the luck value alone (GP value, the luck graph). */
	static String luckShort(double luck)
	{
		if (Double.isNaN(luck))
		{
			return "";
		}
		if (legacy.expecteddrops.stats.DropMath.isOnRate(luck))
		{
			// "On rate": the same band as the verdict (a bit dry and a bit spooned get their 1 in N)
			return "about average";
		}
		if (luck < 0.5)
		{
			return luck < 0.0001 ? "<1 in 10,000 as dry"
				: String.format(java.util.Locale.ROOT, "1 in %,d as dry", Math.max(2, Math.round(1 / luck)));
		}
		return 1 - luck < 0.0001 ? "<1 in 10,000 as lucky"
			: String.format(java.util.Locale.ROOT, "1 in %,d as lucky", Math.max(2, Math.round(1 / (1 - luck))));
	}

	/**
	 * Below this many expected uniques a boss page says "Too early" instead of a verdict: a
	 * handful of kills can't tell dry from lucky.
	 */
	static final double TOO_EARLY_BELOW = legacy.expecteddrops.stats.DropMath.TOO_EARLY_BELOW;

	/**
	 * A row with nothing to read yet: none got and under {@link #TOO_EARLY_BELOW} expected. Its verdict is
	 * always "On rate" (see {@code DropMath.luck}), so lists draw it quietly without hiding anything
	 * dry. Never "Any unique".
	 */
	static boolean isQuiet(legacy.expecteddrops.stats.RowStats r)
	{
		return r != null && !r.isAny() && r.getReceived() == 0 && r.getExpected() < TOO_EARLY_BELOW;
	}

	/**
	 * "got / expected" for a row, as boss pages show it: "0 / 2.60", "3 / 1.20". Expected is the average a
	 * player would have by now at the drop rates, not a number owed. A cap (a pet is 1, Warm gloves 3) only
	 * limits what counts as got; the expected number is the row's own, as in every other view.
	 */
	static String gotOfExpected(legacy.expecteddrops.stats.RowStats r)
	{
		return String.format(java.util.Locale.ROOT, "%,d / %s", r.getReceived(), formatExpected(r.getExpected()));
	}

	/** What a row says once you have every copy that counts: "have it", "have both", "have all 3". */
	static String haveText(legacy.expecteddrops.stats.RowStats r)
	{
		switch (r.getCap())
		{
			case 0:
			case 1:
				return "have it";
			case 2:
				return "have both";
			default:
				return "have all " + r.getCap();
		}
	}

	/** How far out a dry or lucky item must be to be worth a sentence: 8 in 10 players. */
	static final double NOTABLE_SHARE = 0.80;
	/** An item you don't have yet is worth a sentence once this many players would have it. */
	static final double NOTABLE_CHANCE = 0.60;

	/**
	 * One true sentence for under an "On rate" verdict: the item furthest from average, or null
	 * when nothing stands out. The driest item ("drier than 88% of players"), an item most
	 * players would have by now while you don't ("6 in 10 players would have a Tumeken's shadow
	 * by now"), or the luckiest item ("luckier than 97% of players"), whichever is furthest out.
	 */
	static String notableLine(java.util.List<legacy.expecteddrops.stats.RowStats> items)
	{
		legacy.expecteddrops.stats.RowStats best = null;
		double bestShare = 0;
		boolean bestLucky = false;
		for (legacy.expecteddrops.stats.RowStats r : items)
		{
			double[] shares = r == null || r.isAny() ? null : r.getShares();
			if (shares == null)
			{
				continue;
			}
			double fewer = r.getReceived() <= 0 ? 0 : shares[0];
			double more = Math.max(0, 1 - fewer - shares[1]);
			// none yet: a sentence once most players would have one; else 8 in 10 out
			double dryNeeded = r.getReceived() <= 0 ? NOTABLE_CHANCE : NOTABLE_SHARE;
			if (more >= dryNeeded && more > bestShare)
			{
				best = r;
				bestShare = more;
				bestLucky = false;
			}
			if (fewer >= NOTABLE_SHARE && fewer > bestShare)
			{
				best = r;
				bestShare = fewer;
				bestLucky = true;
			}
		}
		if (best == null)
		{
			return null;
		}
		String name = best.getLabel();
		if (bestLucky)
		{
			return String.format(java.util.Locale.ROOT, "Luckiest: %s, luckier than %s of players.", name, sharePct(bestShare));
		}
		if (best.getReceived() <= 0)
		{
			// with none, the players who have more are the ones who'd have one by now
			String players = bestShare < 0.95
				? String.format(java.util.Locale.ROOT, "%d in 10 players", (int) Math.floor(bestShare * 10))
				: sharePct(bestShare) + " of players";
			return String.format(java.util.Locale.ROOT, "%s would have %s by now.", players, withArticle(name));
		}
		return String.format(java.util.Locale.ROOT, "Driest: %s, drier than %s of players.", name, sharePct(bestShare));
	}

	/**
	 * For the "Unique value" hover: the item most of the value comes from, when one item is at
	 * least half of it ("Most of it is the Crystal tool seed (95%)."), else null.
	 */
	static String mainValueSource(java.util.List<String> names, java.util.List<Double> values)
	{
		double total = 0;
		int best = -1;
		for (int i = 0; i < values.size(); i++)
		{
			double v = Math.max(0, values.get(i));
			total += v;
			if (best < 0 || v > values.get(best))
			{
				best = i;
			}
		}
		if (best < 0 || total <= 0 || values.get(best) / total < 0.5)
		{
			return null;
		}
		return String.format(java.util.Locale.ROOT, "Most of it is the %s (%.0f%%).", names.get(best), Math.floor(values.get(best) / total * 100));
	}

	/** "a Tumeken's shadow", "an Elder maul", "Bandos boots" (a pair or a set takes none). */
	static String withArticle(String name)
	{
		if (name.isEmpty())
		{
			return name;
		}
		if (name.endsWith("s") && !name.endsWith("'s"))
		{
			return name;
		}
		return ("AEIOUaeiou".indexOf(name.charAt(0)) >= 0 ? "an " : "a ") + name;
	}

	/**
	 * For hovers: how your result compares with players at your kill count, as a percentage.
	 * Always told from the side that holds most players, so the number is over 50%: "drier than
	 * 67%" (67% have more), "luckier than 83%" (83% have fewer), and "74% have none" when you
	 * and most players have none. Players with exactly your count are on neither side. "About
	 * average" when neither side is a majority. Past 95% the "1 in N" is added: "drier than
	 * 99.91% (1 in 1,205)".
	 */
	static String luckPercent(double[] shares, int received)
	{
		if (shares == null)
		{
			return "";
		}
		double fewer = received <= 0 ? 0 : shares[0];
		double same = shares[1];
		double more = Math.max(0, 1 - fewer - same);
		if (more > 0.5)
		{
			return side("drier", more);
		}
		if (fewer > 0.5)
		{
			return side("luckier", fewer);
		}
		if (received <= 0)
		{
			return same >= 0.995 ? ">99% have none" : String.format(java.util.Locale.ROOT, "%.0f%% have none", same * 100);
		}
		return "about average";
	}

	/** The same from the luck value alone (GP value, the luck graph). */
	static String luckPercent(double luck)
	{
		if (Double.isNaN(luck))
		{
			return "";
		}
		if (luck < 0.495)
		{
			return side("drier", 1 - luck);
		}
		if (luck > 0.505)
		{
			return side("luckier", luck);
		}
		return "about average";
	}

	/** "drier than 67%", with "(1 in 33)" added past 95%: how rare a result this far out is. */
	private static String side(String word, double share)
	{
		String text = word + " than " + sharePct(share);
		if (share < 0.95)
		{
			return text;
		}
		double rest = 1 - share;
		return text + (rest < 0.0001 ? " (<1 in 10,000 players)"
			: String.format(java.util.Locale.ROOT, " (1 in %,d players)", Math.max(2, Math.round(1 / rest))));
	}

	/**
	 * A majority share as a percentage: whole numbers like the hover's split ("67%", "97%"), then
	 * decimals rounded down so it never reaches 100% ("99.4%", "99.91%").
	 */
	static String sharePct(double share)
	{
		double p = share * 100;
		if (share < 0.99)
		{
			return String.format(java.util.Locale.ROOT, "%d%%", Math.round(p));
		}
		if (share < 0.999)
		{
			return String.format(java.util.Locale.ROOT, "%.1f%%", Math.floor(p * 10) / 10);
		}
		return String.format(java.util.Locale.ROOT, "%.2f%%", Math.min(99.99, Math.floor(p * 100) / 100));
	}

	/**
	 * The full split for a hover: "74% of players have none by now, 26% have one or more", or
	 * "18% of players have fewer, 15% as many, 67% more". Null when nothing is expected.
	 */
	static String sharesLine(double[] shares, int received)
	{
		if (shares == null)
		{
			return null;
		}
		double fewer = shares[0];
		double same = shares[1];
		double more = Math.max(0, 1 - fewer - same);
		if (received <= 0 || fewer <= 1e-12)
		{
			return String.format(java.util.Locale.ROOT, "%s of players have none by now, %s have one or more", pct(same), pct(more));
		}
		return String.format(java.util.Locale.ROOT, "%s of players have fewer, %s as many%s", pct(fewer), pct(same),
			more < 0.0005 ? "" : ", " + pct(more) + " more");
	}

	/** First letter upper case, for a short line used on its own. */
	static String capital(String text)
	{
		return text == null || text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	/**
	 * Makes "<1%" or "<1 in 10,000" safe inside Swing HTML, which drops a "<" before a digit
	 * (it reads it as the start of a tag). Real tags like {@code <br>} are left alone.
	 */
	static String html(String text)
	{
		return text == null ? null : text.replaceAll("<(?=[0-9])", "&lt;");
	}
}

package legacy.expecteddrops.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.Icon;
import net.runelite.client.ui.ColorScheme;

/**
 * Every interface colour, spacing step and text width in one place. Luck colours are not here:
 * they live in {@link Palette} and are used for luck and nothing else.
 *
 * <ul>
 * <li>{@link #TEXT}: names, labels and headings</li>
 * <li>{@link #TEXT_MUTED}: secondary text, and the lowest grey any text may use</li>
 * <li>{@link #ACCENT}: selection, focus and hover (tab underlines, the focus ring, link hovers). Never
 * for notices or decoration: orange is also the "dry" end of the luck colours</li>
 * </ul>
 */
public final class Theme
{
	public static final Color TEXT = Color.WHITE;
	public static final Color TEXT_MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	public static final Color ACCENT = ColorScheme.BRAND_ORANGE;

	public static final Color PANEL = ColorScheme.DARK_GRAY_COLOR;
	public static final Color SURFACE = ColorScheme.DARKER_GRAY_COLOR;
	public static final Color SURFACE_RAISED = new Color(45, 45, 45);
	public static final Color SURFACE_SELECTED = new Color(61, 61, 61);
	public static final Color TRACK = new Color(55, 55, 55);
	public static final Color TRACK_DARK = new Color(26, 26, 26);
	public static final Color OUTLINE = new Color(70, 70, 70);
	/** The thin line between label / value rows in a tooltip. */
	public static final Color DIVIDER = new Color(60, 60, 60);
	/** The expected-by-now tick on a quiet item row (nothing expected yet): visible, but not white. */
	public static final Color QUIET_MARK = new Color(150, 150, 150);
	/** Bars that show progress, not luck: no verdict colours on them. */
	public static final Color PROGRESS = new Color(90, 106, 122);
	/** Raid "purples": the game's own colour for raid uniques. */
	public static final Color RAID_PURPLE = new Color(192, 112, 255);

	/** Spacing: a hairline gap between rows, a small and a medium step. */
	public static final int HAIR = 2;
	public static final int S = 4;
	public static final int M = 8;

	/** Wrapped text inside the panel, and the two tooltip widths. */
	public static final int TEXT_WIDTH = 165;
	public static final int TIP_SHORT = 180;
	public static final int TIP_WIDE = 240;

	private Theme()
	{
	}

	/** HTML that wraps at {@code width} pixels. */
	public static String wrap(String html, int width)
	{
		return "<html><body style='width: " + width + "px'>" + html + "</body></html>";
	}

	/** {@code #rrggbb} for a colour, for use inside HTML text. */
	public static String hex(Color c)
	{
		return String.format(java.util.Locale.ROOT, "#%06x", c.getRGB() & 0xFFFFFF);
	}

	/** A small "i" in a circle, in front of information lines (not warnings, not luck). */
	public static Icon infoIcon()
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics graphics, int x, int y)
			{
				Graphics2D g = (Graphics2D) graphics.create();
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g.setColor(TEXT_MUTED);
				g.setStroke(new BasicStroke(1f));
				g.drawOval(x, y + 1, 10, 10);
				g.fillRect(x + 5, y + 5, 1, 4);
				g.fillRect(x + 5, y + 3, 1, 1);
				g.dispose();
			}

			@Override
			public int getIconWidth()
			{
				return 11;
			}

			@Override
			public int getIconHeight()
			{
				return 12;
			}
		};
	}

	/** A step number in a thin circle, for the welcome guide. */
	public static Icon stepIcon(int number)
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics graphics, int x, int y)
			{
				Graphics2D g = (Graphics2D) graphics.create();
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g.setColor(OUTLINE);
				g.setStroke(new BasicStroke(1f));
				g.drawOval(x, y, 14, 14);
				g.setFont(net.runelite.client.ui.FontManager.getRunescapeSmallFont());
				g.setColor(TEXT_MUTED);
				String text = String.valueOf(number);
				java.awt.FontMetrics fm = g.getFontMetrics();
				g.drawString(text, x + (15 - fm.stringWidth(text)) / 2, y + (15 - fm.getHeight()) / 2 + fm.getAscent());
				g.dispose();
			}

			@Override
			public int getIconWidth()
			{
				return 15;
			}

			@Override
			public int getIconHeight()
			{
				return 15;
			}
		};
	}

	/** Item and secondary numbers in lists: the regular weight, so names stay the bold ones. */
	static java.awt.Font numberFont()
	{
		return net.runelite.client.ui.FontManager.getRunescapeFont();
	}

	/** The font of the verdicts at the top ("On rate") and of the names and numbers in the lists. */
	static java.awt.Font rowFont()
	{
		return net.runelite.client.ui.FontManager.getRunescapeBoldFont().deriveFont(java.awt.Font.PLAIN, 16f);
	}

	/** The verdict in the tiles at the top ("Very spooned"): bold and a little bigger than the lists. */
	static java.awt.Font verdictFont()
	{
		return net.runelite.client.ui.FontManager.getRunescapeBoldFont().deriveFont(18f);
	}
}

package legacy.expecteddrops.ui;

import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

/**
 * One layout for every tooltip: a bold title, a few facts, and an optional grey footnote.
 * Facts are lines of text, or label / value rows with a thin line between them:
 * <pre>new Tip("Vorkath's head").row("Drop rate", "1/50 per kill").note("Counted from ...").wide()</pre>
 * Lines and rows show in the order they were added; rows next to each other form one table.
 */
final class Tip
{
	private final String title;
	/** Lines (a String) and rows (a String[] of label and value), in order. */
	private final List<Object> parts = new ArrayList<>();
	private final List<String> notes = new ArrayList<>();

	Tip(String title)
	{
		this.title = title;
	}

	Tip line(String html)
	{
		if (html != null && !html.isEmpty())
		{
			parts.add(Texts.html(html));
		}
		return this;
	}

	/** A line in a colour (a verdict, or grey for a subtitle). */
	Tip line(String text, Color color)
	{
		if (text == null || text.isEmpty())
		{
			return this;
		}
		return line("<font color='" + Theme.hex(color) + "'>" + text + "</font>");
	}

	/** A grey label on the left, its value on the right. Skipped when the value is empty. */
	Tip row(String label, String value)
	{
		if (value != null && !value.isEmpty())
		{
			parts.add(new String[]{Texts.html(label), Texts.html(value)});
		}
		return this;
	}

	/** A row whose value is in a colour (a verdict). */
	Tip row(String label, String value, Color color)
	{
		if (value == null || value.isEmpty())
		{
			return this;
		}
		return row(label, "<font color='" + Theme.hex(color) + "'>" + value + "</font>");
	}

	/**
	 * A thin bar split into the players with fewer, as many as you (in {@code you}, the verdict colour)
	 * and more. Skipped when the split is unknown.
	 */
	Tip split(double[] shares, int received, Color you)
	{
		if (shares == null)
		{
			return this;
		}
		double fewer = received <= 0 ? 0 : shares[0];
		double same = shares[1];
		double more = Math.max(0, 1 - fewer - same);
		StringBuilder sb = new StringBuilder("<table width='100%' cellpadding='0' cellspacing='0' style='margin-top: 3px'><tr>");
		cell(sb, fewer, Theme.DIVIDER.brighter());
		cell(sb, same, you);
		cell(sb, more, Palette.blend(you, Color.WHITE, 0.5));
		parts.add(sb.append("</tr></table>").toString());
		return this;
	}

	/** One part of {@link #split}: at least 1% wide when there is any of it, so a sliver still shows. */
	private static void cell(StringBuilder sb, double share, Color color)
	{
		if (share < 0.0005)
		{
			return;
		}
		int pct = Math.max(1, (int) Math.round(share * 100));
		sb.append("<td width='").append(pct).append("%' bgcolor='").append(Theme.hex(color))
			.append("' style='font-size: 4px'>&nbsp;</td>");
	}

	/** Grey text at the bottom: where a number comes from, or a caveat. */
	Tip note(String html)
	{
		if (html != null && !html.isEmpty())
		{
			notes.add(Texts.html(html));
		}
		return this;
	}

	/** For details (item and value tooltips). */
	String wide()
	{
		return build(Theme.TIP_WIDE);
	}

	/** For short hints. */
	String small()
	{
		return build(Theme.TIP_SHORT);
	}

	private String build(int width)
	{
		String muted = Theme.hex(Theme.TEXT_MUTED);
		// a line above every row: it parts the rows from each other and from the text above
		String cell = "style='border-top: 1px solid " + Theme.hex(Theme.DIVIDER) + "'";
		StringBuilder sb = new StringBuilder();
		if (title != null)
		{
			sb.append("<b>").append(title).append("</b>");
		}
		boolean inTable = false;
		for (Object part : parts)
		{
			if (part instanceof String[])
			{
				if (!inTable)
				{
					sb.append("<table width='100%' cellpadding='2' cellspacing='0' style='margin-top: 3px; margin-bottom: 3px'>");
					inTable = true;
				}
				String[] row = (String[]) part;
				sb.append("<tr><td nowrap ").append(cell).append("><font color='").append(muted).append("'>")
					.append(row[0]).append("</font></td><td align='right' ").append(cell).append(">")
					.append(row[1]).append("</td></tr>");
				continue;
			}
			if (inTable)
			{
				sb.append("</table>");
				inTable = false;
			}
			else if (sb.length() > 0 && !endsWithTable(sb))
			{
				sb.append("<br>");
			}
			sb.append(part);
		}
		if (inTable)
		{
			sb.append("</table>");
		}
		if (!notes.isEmpty())
		{
			// a table ends its own line
			sb.append(sb.length() == 0 || endsWithTable(sb) ? "" : "<br>").append("<font color='").append(muted).append("'>");
			sb.append(String.join("<br>", notes)).append("</font>");
		}
		return Theme.wrap(sb.toString(), width);
	}

	private static boolean endsWithTable(StringBuilder sb)
	{
		return sb.length() >= 8 && sb.substring(sb.length() - 8).equals("</table>");
	}
}

package legacy.expecteddrops.ui;

import java.awt.Color;
import java.awt.Component;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;

/** One verdict tile: a small title, the verdict word, and the numbers behind it. */
class VerdictTile extends JPanel
{
	private final JLabel key = new FullWidthLabel();
	private final JLabel word = new FullWidthLabel();
	private final JLabel numbers = new FullWidthLabel();
	private final LuckPill luck = new LuckPill();
	/** The colour of the top edge: the verdict's colour. */
	private Color accent = Theme.TEXT_MUTED;
	/** The verdict word and the two small lines as set, before any wrapping (see {@link #doLayout}). */
	private String wordText = "";
	private String numbersText = "";
	private String luckText = "";

	VerdictTile(String title)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setBorder(new EmptyBorder(Theme.M, Theme.M, Theme.M - 1, Theme.S + 1));
		key.setText(title);
		key.setFont(FontManager.getRunescapeSmallFont());
		key.setForeground(Theme.TEXT_MUTED);
		// the verdict is what On Rate is about: a size up from the lists
		word.setFont(Theme.verdictFont());
		numbers.setFont(FontManager.getRunescapeSmallFont());
		numbers.setForeground(Theme.TEXT_MUTED);
		numbers.setBorder(new EmptyBorder(0, 0, Theme.S, 0));
		for (JLabel l : new JLabel[]{key, word, numbers})
		{
			l.setAlignmentX(LEFT_ALIGNMENT);
		}
		luck.setAlignmentX(LEFT_ALIGNMENT);
		add(key);
		add(word);
		add(numbers);
		add(luck);
	}

	/** The card: a quiet gradient, a hairline outline and a coloured top edge. */
	@Override
	protected void paintComponent(java.awt.Graphics graphics)
	{
		java.awt.Graphics2D g = (java.awt.Graphics2D) graphics.create();
		g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new java.awt.GradientPaint(0, 0, Theme.SURFACE_RAISED, w, h, Theme.SURFACE));
		g.fillRoundRect(0, 0, w - 1, h - 1, 8, 8);
		g.setColor(Theme.OUTLINE);
		g.drawRoundRect(0, 0, w - 1, h - 1, 8, 8);
		// the coloured edge, clipped to the card's rounded corners
		g.setClip(new java.awt.geom.RoundRectangle2D.Float(0, 0, w - 1, h - 1, 8, 8));
		g.setColor(accent);
		g.fillRect(0, 0, w, 2);
		g.dispose();
	}

	/**
	 * A label that takes the whole width of the tile. A plain label is never wider than its text was when it
	 * was last measured, which is too narrow once the verdict word grows or the line wraps in {@link #doLayout}.
	 */
	private static final class FullWidthLabel extends JLabel
	{
		@Override
		public java.awt.Dimension getMaximumSize()
		{
			return new java.awt.Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}
	}

	/** The luck line as a pill that grows with its text. */
	private static final class LuckPill extends JLabel
	{
		private Color hue = Theme.TEXT_MUTED;

		LuckPill()
		{
			setFont(FontManager.getRunescapeSmallFont());
			setBorder(new EmptyBorder(2, 11, 2, 6));
		}

		void setHue(Color hue)
		{
			this.hue = hue;
			setForeground(Palette.onTint(hue));
		}

		@Override
		public java.awt.Dimension getMaximumSize()
		{
			// as wide as its text, never stretched across the tile
			return getPreferredSize();
		}

		@Override
		protected void paintComponent(java.awt.Graphics graphics)
		{
			if (getText() == null || getText().isEmpty())
			{
				return;
			}
			java.awt.Graphics2D g = (java.awt.Graphics2D) graphics.create();
			g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(Palette.tint(hue));
			int arc = getHeight() > 20 ? 12 : getHeight();
			g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
			g.setColor(hue);
			g.fillOval(4, getInsets().top + getFontMetrics(getFont()).getHeight() / 2 - 1, 4, 4);
			g.dispose();
			super.paintComponent(graphics);
		}
	}

	/**
	 * Verdict size by default; smaller only when a long word ("Very spooned") doesn't fit the tile.
	 * A word too wide even at the smallest size ("Extremely spooned") goes back to full size on two lines.
	 */
	private static final float WORD_SIZE = 18f;
	private static final float WORD_MIN_SIZE = 14f;

	/**
	 * The tile is about 98px wide for text when the panel has its scrollbar. Two things in it can be
	 * wider: "Very spooned" in the full size needs 102 ("Extremely spooned" 141, still 113 at the
	 * smallest size, so it takes two lines), and "only 1 in 10,000 has none" needs 127. The
	 * verdict word steps down a point at a time until it fits (and back up when it does); the small
	 * lines wrap onto a second line instead of ending in "...".
	 */
	@Override
	public void doLayout()
	{
		super.doLayout();
		int room = getWidth() - getInsets().left - getInsets().right;
		if (room <= 0)
		{
			return;
		}
		boolean changed = false;
		String text = wordText;
		if (text != null && !text.isEmpty())
		{
			float size = WORD_SIZE;
			java.awt.Font base = Theme.verdictFont();
			while (size > WORD_MIN_SIZE && word.getFontMetrics(base.deriveFont(size)).stringWidth(text) > room)
			{
				size -= 1f;
			}
			boolean twoLines = word.getFontMetrics(base.deriveFont(size)).stringWidth(text) > room;
			if (twoLines)
			{
				size = WORD_SIZE;
			}
			if (word.getFont().getSize2D() != size)
			{
				word.setFont(base.deriveFont(size));
				changed = true;
			}
			if (twoLines)
			{
				changed |= wrapIfLong(word, text, room);
			}
			else if (!text.equals(word.getText()))
			{
				word.setText(text);
				changed = true;
			}
		}
		changed |= wrapIfLong(numbers, numbersText, room);
		changed |= wrapIfLong(luck, luckText, room - 17);
		if (changed)
		{
			// a label that wrapped (or shrank) needs a different height: lay the tile and its row out again,
			// or the second line is cut off. Later, not now: a revalidate made while the tile is being laid
			// out is wiped when that layout pass ends (Swing marks the tile valid again afterwards)
			javax.swing.SwingUtilities.invokeLater(this::revalidate);
		}
	}

	/**
	 * Shows {@code plain} as it is, or broken into lines of at most {@code room} pixels when it would be cut off.
	 * The breaks are made here, from the label's own font: a CSS width in an HTML label is not in pixels
	 * (it comes out about a third wider and varies with the screen).
	 */
	private static boolean wrapIfLong(JLabel label, String plain, int room)
	{
		if (plain == null || plain.isEmpty())
		{
			return false;
		}
		java.awt.FontMetrics fm = label.getFontMetrics(label.getFont());
		StringBuilder shown = new StringBuilder();
		StringBuilder line = new StringBuilder();
		for (String word : plain.split(" "))
		{
			String longer = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && fm.stringWidth(longer) > room)
			{
				shown.append(Texts.html(line.toString())).append("<br>");
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(longer);
			}
		}
		shown.append(Texts.html(line.toString()));
		String text = shown.indexOf("<br>") < 0 ? plain : "<html>" + shown + "</html>";
		if (!text.equals(label.getText()))
		{
			label.setText(text);
			return true;
		}
		return false;
	}

	void set(String verdict, Color color, String numbersText, String luckText, String tip)
	{
		word.setText(verdict);
		this.wordText = verdict;
		word.setForeground(color);
		this.accent = color;
		luck.setHue(color);
		this.numbersText = numbersText;
		this.luckText = luckText;
		numbers.setText(numbersText);
		luck.setText(luckText);
		setToolTipText(tip);
		for (Component c : getComponents())
		{
			((JLabel) c).setToolTipText(tip);
		}
		// the tile was taken out of its row while its text changed: drop the size it remembers
		invalidate();
		repaint();
	}
}

