			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				shareLink.setForeground(Color.WHITE);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				shareLink.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
