package com.onrate.engine.data;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.ToLongFunction;
import java.util.regex.Pattern;

/**
 * What an untradeable unique is worth, written in terms of tradeable items:
 * {@code "Amulet of rancour - Amulet of torture"}, {@code "Noxious halberd / 3"}.
 * Operators ({@code + - * /}) have spaces around them; a term is an item name or a number,
 * and {@code *} and {@code /} bind tighter than {@code +} and {@code -}.
 */
public final class ValueFormula
{
	private static final Pattern SUM_SPLIT = Pattern.compile("\\s([+-])\\s");
	private static final Pattern PRODUCT_SPLIT = Pattern.compile("\\s([*/])\\s");

	private final List<Character> signs = new ArrayList<>();
	private final List<List<String>> terms = new ArrayList<>();
	private final List<List<Character>> productOps = new ArrayList<>();
	private final Set<String> itemNames = new LinkedHashSet<>();

	private ValueFormula()
	{
	}

	public static ValueFormula parse(String text)
	{
		ValueFormula f = new ValueFormula();
		java.util.regex.Matcher sums = SUM_SPLIT.matcher(text);
		int start = 0;
		char sign = '+';
		while (true)
		{
			boolean found = sums.find();
			f.addTerm(sign, text.substring(start, found ? sums.start() : text.length()).trim());
			if (!found)
			{
				break;
			}
			sign = sums.group(1).charAt(0);
			start = sums.end();
		}
		return f;
	}

	private void addTerm(char sign, String term)
	{
		List<String> factors = new ArrayList<>();
		List<Character> ops = new ArrayList<>();
		java.util.regex.Matcher m = PRODUCT_SPLIT.matcher(term);
		int start = 0;
		while (m.find())
		{
			factors.add(term.substring(start, m.start()).trim());
			ops.add(m.group(1).charAt(0));
			start = m.end();
		}
		factors.add(term.substring(start).trim());
		for (String factor : factors)
		{
			if (factor.isEmpty())
			{
				throw new IllegalArgumentException("Empty term in value formula: " + term);
			}
			if (!isNumber(factor))
			{
				itemNames.add(factor);
			}
		}
		signs.add(sign);
		terms.add(factors);
		productOps.add(ops);
	}

	private static boolean isNumber(String s)
	{
		return s.matches("\\d+(\\.\\d+)?");
	}

	/** The item names the formula looks up a price for. */
	public Set<String> getItemNames()
	{
		return itemNames;
	}

	/**
	 * The value in GP, never below 0. 0 as well when any item in it has no price, since the
	 * rest of the formula would then be a wrong number rather than a small one.
	 */
	public long evaluate(ToLongFunction<String> price)
	{
		double total = 0;
		for (int t = 0; t < terms.size(); t++)
		{
			List<String> factors = terms.get(t);
			double value = 0;
			for (int f = 0; f < factors.size(); f++)
			{
				double x;
				String factor = factors.get(f);
				if (isNumber(factor))
				{
					x = Double.parseDouble(factor);
				}
				else
				{
					long p = price.applyAsLong(factor);
					if (p <= 0)
					{
						return 0;
					}
					x = p;
				}
				if (f == 0)
				{
					value = x;
				}
				else if (productOps.get(t).get(f - 1) == '*')
				{
					value *= x;
				}
				else
				{
					value /= x;
				}
			}
			total += signs.get(t) == '+' ? value : -value;
		}
		return Math.max(0, (long) total);
	}
}

package com.onrate.engine.math;

/**
 * Luck as a percentile in 0..1 (0.5 = average). Built from the {@link Poisson} shares, and
 * deliberately tie-aware: the most common result is never called dry.
 */
public final class Luck
{
	private Luck()
	{
	}

	/**
	 * Of the range from "share with fewer" to "share with this many or fewer", the point closest to
	 * the middle. So you only count as dry when few players have this many or fewer, and as spooned
	 * when few have this many or more. With big counts ties are rare and this is the usual percentile.
	 */
	public static double tieAware(double fewer, double same)
	{
		return Math.max(0, Math.min(1, Math.min(Math.max(0.5, fewer), fewer + same)));
	}

	/** Tie-aware luck behind every verdict. NaN when nothing is expected. */
	public static double of(int received, double expected)
	{
		double[] s = Poisson.shares(received, expected);
		return s == null ? Double.NaN : tieAware(s[0], s[1]);
	}

	/** Tie-aware luck when at most {@code cap} copies count. NaN when nothing is expected. */
	public static double ofCapped(int received, double expected, int cap)
	{
		double[] s = Poisson.sharesCapped(received, expected, cap);
		return s == null ? Double.NaN : tieAware(s[0], s[1]);
	}

	/**
	 * The mid-p percentile: players with fewer than you, plus half of those with exactly as many.
	 * NaN when nothing is expected yet.
	 */
	public static double midP(int received, double expected)
	{
		if (expected <= 0 || Double.isNaN(expected))
		{
			return Double.NaN;
		}
		double[] raw = Poisson.rawShares(Math.max(received, 0), expected);
		double p = raw[0] + 0.5 * raw[1];
		return Math.max(0, Math.min(1, p));
	}
}

package com.onrate.engine.math;

import java.util.List;

/**
 * Probability of drop counts. Every kill is an independent roll, so the number of drops after
 * n kills is binomial; with the small rates bosses use a Poisson with the same mean is an
 * excellent approximation, and it lets several items be added into one "any unique" row.
 *
 * <p>A "shares" result is {share of players with fewer than you, share with exactly as many};
 * the rest have more.
 */
public final class Poisson
{
	private Poisson()
	{
	}

	/** Chance of at least one drop in {@code kc} kills at {@code rate} per kill (binomial). */
	public static double chanceAtLeastOne(double rate, long kc)
	{
		if (kc <= 0 || rate <= 0)
		{
			return 0;
		}
		if (rate >= 1)
		{
			return 1;
		}
		return -Math.expm1(kc * Math.log1p(-rate));
	}

	/** Chance of at least one event when {@code expected} events are expected (Poisson). */
	public static double chanceAtLeastOne(double expected)
	{
		if (expected <= 0)
		{
			return 0;
		}
		return -Math.expm1(-expected);
	}

	/** Kills needed to reach {@code probability} chance of at least one drop. -1 if never. */
	public static long killsForChance(double rate, double probability)
	{
		if (rate <= 0 || probability <= 0)
		{
			return -1;
		}
		if (rate >= 1)
		{
			return 1;
		}
		return (long) Math.ceil(Math.log1p(-probability) / Math.log1p(-rate));
	}

	/** Expected number of copies that count when at most {@code cap} can: E[min(X, cap)], X Poisson. */
	public static double expectedCapped(double expected, int cap)
	{
		if (expected <= 0 || cap <= 0)
		{
			return 0;
		}
		double sum = 0;
		double p = Math.exp(-expected);
		double cdf = 0;
		for (int k = 0; k < cap; k++)
		{
			cdf += p;
			sum += 1 - cdf;
			p *= expected / (k + 1);
		}
		return sum;
	}

	/** Expected copies that count: the plain expected, or E[min(X, cap)] when at most {@code cap} count. */
	public static double expectedCounted(double expected, int cap)
	{
		return cap > 0 ? expectedCapped(expected, cap) : expected;
	}

	/** Shares for a plain (uncapped) count; null when nothing is expected. */
	public static double[] shares(int received, double expected)
	{
		if (expected <= 0 || Double.isNaN(expected))
		{
			return null;
		}
		double[] raw = rawShares(Math.max(received, 0), expected);
		return new double[]{Math.min(1, raw[0]), Math.min(1, raw[1])};
	}

	/**
	 * Unclamped {fewer, same} for {@code received} drops when {@code expected} are expected.
	 * Shared by {@link #shares} and {@link Luck#midP} so both use the very same arithmetic.
	 */
	static double[] rawShares(int received, double expected)
	{
		double logLambda = Math.log(expected);
		double logFactorial = 0;
		double below = 0;
		for (int j = 0; j < received; j++)
		{
			if (j > 0)
			{
				logFactorial += Math.log(j);
			}
			below += Math.exp(-expected + j * logLambda - logFactorial);
		}
		if (received > 0)
		{
			logFactorial += Math.log(received);
		}
		double equal = Math.exp(-expected + received * logLambda - logFactorial);
		return new double[]{below, equal};
	}

	/**
	 * Shares when at most {@code cap} copies count: everyone with {@code cap} or more is level with
	 * you. Null when nothing is expected.
	 */
	public static double[] sharesCapped(int received, double expected, int cap)
	{
		if (expected <= 0 || Double.isNaN(expected))
		{
			return null;
		}
		int r = Math.min(Math.max(received, 0), cap);
		double p = Math.exp(-expected);
		double below = 0;
		for (int k = 0; k < r; k++)
		{
			below += p;
			p *= expected / (k + 1);
		}
		double same = r < cap ? p : 1 - below;
		return new double[]{below, Math.max(0, same)};
	}

	/** {@link #sharesSum(int, int, double, double[], int[], List)} without guaranteed items. */
	public static double[] sharesSum(int received, int sure, double plain, double[] cappedMeans, int[] caps)
	{
		return sharesSum(received, sure, plain, cappedMeans, caps, null);
	}

	/**
	 * Shares for a total made of several items: {@code sure} copies that drop for certain, a part
	 * with no limit ({@code plain} expected), items of which at most {@code caps[i]} count (each
	 * with its uncapped mean {@code cappedMeans[i]}), and items that are sure on one kill only for a
	 * player with none yet ({@code guaranteed}: {kills, rate per kill, kill with the guarantee}).
	 * A capped item's count isn't Poisson, so the total isn't either: this adds the exact
	 * distributions. Null when nothing is expected.
	 */
	public static double[] sharesSum(int received, int sure, double plain, double[] cappedMeans, int[] caps,
		List<double[]> guaranteed)
	{
		int n = cappedMeans == null ? 0 : cappedMeans.length;
		int g = guaranteed == null ? 0 : guaranteed.size();
		if (n == 0 && g == 0 && sure <= 0)
		{
			return shares(received, plain);
		}
		double total = Math.max(0, sure) + (Double.isNaN(plain) ? 0 : Math.max(0, plain));
		for (int i = 0; i < n; i++)
		{
			total += expectedCapped(cappedMeans[i], caps[i]);
		}
		for (int i = 0; i < g; i++)
		{
			double[] item = guaranteed.get(i);
			total += guaranteedExpected(item[0], item[1], (int) item[2]);
		}
		if (!(total > 0))
		{
			return null;
		}
		int r = Math.max(received, 0) - Math.max(0, sure);
		if (r < 0)
		{
			// fewer than the sure copies: nobody has as few
			return new double[]{0, 0};
		}
		// only counts up to r matter for "fewer" and "the same"
		double[] pmf = poissonPmf(Double.isNaN(plain) ? 0 : plain, r);
		for (int i = 0; i < n; i++)
		{
			if (!(cappedMeans[i] > 0) || caps[i] <= 0)
			{
				continue;
			}
			double[] item = poissonPmf(cappedMeans[i], caps[i]);
			double rest = 1;
			for (int k = 0; k < caps[i]; k++)
			{
				rest -= item[k];
			}
			item[caps[i]] = Math.max(0, rest);
			pmf = convolve(pmf, item, caps[i], r, true);
		}
		for (int i = 0; i < g; i++)
		{
			double[] item = guaranteed.get(i);
			double[] own = guaranteedPmf(item[0], item[1], (int) item[2], r);
			pmf = convolve(pmf, own, r, r, false);
		}
		double below = 0;
		for (int k = 0; k < r; k++)
		{
			below += pmf[k];
		}
		return new double[]{Math.min(1, below), Math.min(1, pmf[r])};
	}

	/** Adds two independent counts, keeping totals up to {@code r}. */
	private static double[] convolve(double[] left, double[] right, int rightMax, int r, boolean skipEmptyLeft)
	{
		double[] next = new double[r + 1];
		for (int a = 0; a <= r; a++)
		{
			if (skipEmptyLeft && left[a] == 0)
			{
				continue;
			}
			for (int b = 0; b <= rightMax && a + b <= r; b++)
			{
				next[a + b] += left[a] * right[b];
			}
		}
		return next;
	}

	/**
	 * Expected copies of an item rolled at {@code rate} per kill that is also sure on kill
	 * {@code at} for a player who has none yet (Vorkath's head on the 50th): kills * rate, plus the
	 * extra copy that kill gives, (1 - rate)^at, from then on.
	 */
	public static double guaranteedExpected(double kills, double rate, int at)
	{
		double expected = kills * rate;
		return kills >= at ? expected + Math.pow(1 - rate, at) : expected;
	}

	/**
	 * Exact probabilities of 0..{@code max} copies after {@code kills} kills at {@code rate}, when
	 * kill {@code at} is a sure drop for a player with none from kills 1 to at - 1 and a plain roll
	 * otherwise. Nobody who has been through kill {@code at} has none.
	 */
	public static double[] guaranteedPmf(double kills, double rate, int at, int max)
	{
		int total = (int) Math.round(kills);
		if (total < at)
		{
			return binomialPmf(total, rate, max);
		}
		double miss = 1 - rate;
		double[] before = binomialPmf(at - 1, rate, max);
		// kills 1 to at - 1, then kill at: sure with none so far, a plain roll with one or more
		double[] upTo = new double[max + 1];
		for (int k = 0; k <= max; k++)
		{
			if (k == 0)
			{
				if (max >= 1)
				{
					upTo[1] += before[0];
				}
				continue;
			}
			upTo[k] += before[k] * miss;
			if (k + 1 <= max)
			{
				upTo[k + 1] += before[k] * rate;
			}
		}
		double[] after = binomialPmf(total - at, rate, max);
		return convolve(upTo, after, max, max, false);
	}

	private static double[] binomialPmf(int n, double p, int max)
	{
		double[] pmf = new double[max + 1];
		if (p <= 0)
		{
			pmf[0] = 1;
			return pmf;
		}
		if (p >= 1)
		{
			if (n <= max)
			{
				pmf[n] = 1;
			}
			return pmf;
		}
		double logChoose = 0;
		for (int k = 0; k <= Math.min(n, max); k++)
		{
			if (k > 0)
			{
				logChoose += Math.log((double) (n - k + 1) / k);
			}
			pmf[k] = Math.exp(logChoose + k * Math.log(p) + (n - k) * Math.log1p(-p));
		}
		return pmf;
	}

	private static double[] poissonPmf(double mean, int max)
	{
		double[] pmf = new double[max + 1];
		if (!(mean > 0))
		{
			pmf[0] = 1;
			return pmf;
		}
		double logMean = Math.log(mean);
		double logFactorial = 0;
		for (int k = 0; k <= max; k++)
		{
			if (k > 0)
			{
				logFactorial += Math.log(k);
			}
			pmf[k] = Math.exp(-mean + k * logMean - logFactorial);
		}
		return pmf;
	}
}

package com.onrate.engine.math;

import java.util.Locale;

/** Reading and writing drop rates ("1/50", "3/512", "0.02") and GP amounts. */
public final class Rates
{
	private Rates()
	{
	}

	/** Parses "1/50", "3/512" or a plain decimal like "0.02". Returns 0 for null or blank. */
	public static double parse(String rate)
	{
		if (rate == null || rate.trim().isEmpty())
		{
			return 0;
		}
		String s = rate.replace(",", "").trim();
		int slash = s.indexOf('/');
		if (slash < 0)
		{
			return Double.parseDouble(s);
		}
		double num = Double.parseDouble(s.substring(0, slash).trim());
		double den = Double.parseDouble(s.substring(slash + 1).trim());
		if (den <= 0)
		{
			throw new IllegalArgumentException("Bad rate: " + rate);
		}
		return num / den;
	}

	/** "1/181" style text for a per-kill rate. */
	public static String format(double rate)
	{
		if (rate <= 0)
		{
			return "unknown";
		}
		double inverse = 1.0 / rate;
		if (inverse < 10)
		{
			return String.format(Locale.ROOT, "1/%.2f", inverse);
		}
		if (Math.abs(inverse - Math.rint(inverse)) < 0.05 || inverse >= 1000)
		{
			return String.format(Locale.ROOT, "1/%,d", Math.round(inverse));
		}
		return String.format(Locale.ROOT, "1/%,.1f", inverse);
	}

	/** "1.24b", "345.6m", "12.3k" or "950" coins. */
	public static String gp(double gp)
	{
		double abs = Math.abs(gp);
		if (abs >= 1_000_000_000)
		{
			return String.format(Locale.ROOT, "%.2fb", gp / 1_000_000_000);
		}
		if (abs >= 1_000_000)
		{
			return String.format(Locale.ROOT, "%.1fm", gp / 1_000_000);
		}
		if (abs >= 1_000)
		{
			return String.format(Locale.ROOT, "%.1fk", gp / 1_000);
		}
		return String.format(Locale.ROOT, "%.0f", gp);
	}
}

package com.onrate.engine.math;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/** Araxxor's halberd pieces: untradeable, and no duplicates drop until a full set is made. */
public final class Untradeables
{
	private static final Set<String> HALBERD_PIECES = Collections.unmodifiableSet(new HashSet<>(
		Arrays.asList("noxious point", "noxious blade", "noxious pommel")));

	private Untradeables()
	{
	}

	public static boolean isHalberdPiece(String itemName)
	{
		return itemName != null && HALBERD_PIECES.contains(itemName.toLowerCase(Locale.ROOT));
	}

	public static int halberdPieceCount()
	{
		return HALBERD_PIECES.size();
	}

	/**
	 * GP the halberd pieces you have are worth: only full sets, since a piece alone can't be sold
	 * and duplicates don't drop before the set is done. {@code piecePrice} is a third of a halberd.
	 */
	public static long setValue(int pieces, long piecePrice)
	{
		return (pieces / HALBERD_PIECES.size()) * HALBERD_PIECES.size() * piecePrice;
	}
}

package com.onrate.engine.math;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Random;

/**
 * Luck by GP value. Rare, expensive items dominate value, so there is no formula: the kills are
 * simulated many times with a fixed seed (the number doesn't jump around between refreshes) and
 * your value is placed among the simulated players, ties counted like the counts do.
 */
public final class ValueLuck
{
	/** Players simulated for the account and boss GP verdicts. */
	public static final int SAMPLES = 5000;
	/** The fixed seed the account GP verdict has always used. */
	public static final long SEED = 1234567L;

	private ValueLuck()
	{
	}

	/**
	 * @param expected expected number of drops per item
	 * @param prices   price per item (0 for untradeables, which are skipped)
	 * @param caps     at most {@code caps[i]} copies of an item count (0 for no limit); may be null
	 * @param received total value actually received
	 * @return luck between 0 and 1, or NaN when nothing of value is expected yet
	 */
	public static double of(double[] expected, long[] prices, int[] caps, long received, int samples, long seed)
	{
		// Only items with a price and a chance take part; keeping them in the same order means
		// the random numbers, and so the result, are the same as drawing for every item.
		int n = 0;
		double total = 0;
		for (int i = 0; i < expected.length; i++)
		{
			if (prices[i] > 0)
			{
				total += Poisson.expectedCounted(expected[i], caps == null ? 0 : caps[i]) * prices[i];
				if (expected[i] > 0)
				{
					n++;
				}
			}
		}
		if (total <= 0)
		{
			return Double.NaN;
		}
		double[] means = new double[n];
		double[] limits = new double[n];
		long[] values = new long[n];
		int[] itemCaps = new int[n];
		int j = 0;
		for (int i = 0; i < expected.length; i++)
		{
			if (prices[i] > 0 && expected[i] > 0)
			{
				means[j] = expected[i];
				limits[j] = Math.exp(-expected[i]);
				values[j] = prices[i];
				itemCaps[j] = caps == null ? 0 : Math.max(0, caps[i]);
				j++;
			}
		}
		Key key = new Key(means, values, itemCaps, received, samples, seed);
		synchronized (CACHE)
		{
			Double cached = CACHE.get(key);
			if (cached != null)
			{
				return cached;
			}
		}
		Random random = new Random(seed);
		double below = 0;
		double equal = 0;
		for (int s = 0; s < samples; s++)
		{
			long value = 0;
			for (int i = 0; i < n; i++)
			{
				long copies = poisson(random, means[i], limits[i]);
				if (itemCaps[i] > 0)
				{
					copies = Math.min(copies, itemCaps[i]);
				}
				value += copies * values[i];
			}
			if (value < received)
			{
				below += 1;
			}
			else if (value == received)
			{
				equal += 1;
			}
		}
		// ties (often: nothing tradeable yet, like most players) handled like the counts
		double luck = Luck.tieAware(below / samples, equal / samples);
		synchronized (CACHE)
		{
			CACHE.put(key, luck);
		}
		return luck;
	}

	/** Without caps. */
	public static double of(double[] expected, long[] prices, long received, int samples, long seed)
	{
		return of(expected, prices, null, received, samples, seed);
	}

	/** A random number of drops when {@code mean} are expected. */
	public static long poisson(Random random, double mean)
	{
		return poisson(random, mean, Math.exp(-mean));
	}

	/** The last few results: switching tabs or re-opening a boss asks for the same numbers. */
	private static final Map<Key, Double> CACHE = new LinkedHashMap<Key, Double>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Key, Double> eldest)
		{
			return size() > 32;
		}
	};

	private static long poisson(Random random, double mean, double limit)
	{
		if (mean > 30)
		{
			// normal approximation is accurate here and much faster
			return Math.max(0, Math.round(mean + Math.sqrt(mean) * random.nextGaussian()));
		}
		double product = random.nextDouble();
		long count = 0;
		while (product > limit)
		{
			product *= random.nextDouble();
			count++;
		}
		return count;
	}

	private static final class Key
	{
		private final double[] means;
		private final long[] values;
		private final int[] caps;
		private final long received;
		private final int samples;
		private final long seed;
		private final int hash;

		Key(double[] means, long[] values, int[] caps, long received, int samples, long seed)
		{
			this.means = means;
			this.values = values;
			this.caps = caps;
			this.received = received;
			this.samples = samples;
			this.seed = seed;
			this.hash = Objects.hash(Arrays.hashCode(means), Arrays.hashCode(values), Arrays.hashCode(caps),
				received, samples, seed);
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Key))
			{
				return false;
			}
			Key k = (Key) o;
			return hash == k.hash && received == k.received && samples == k.samples && seed == k.seed
				&& Arrays.equals(means, k.means) && Arrays.equals(values, k.values) && Arrays.equals(caps, k.caps);
		}

		@Override
		public int hashCode()
		{
			return hash;
		}
	}
}

package com.onrate.engine.math;

/**
 * The nine words a luck value can earn, driest first. One definition shared by every list,
 * tile, overlay, trip card and graph.
 *
 * <p>Luck is a percentile in 0..1 (0.5 = average). A value exactly on a line goes to the side
 * nearer the middle: 1% is Very dry, 35% is A bit dry, 45% and 55% are On rate, 65% is A bit
 * spooned, 99% is Very spooned.
 */
public enum Verdict
{
	EXTREMELY_DRY("Extremely dry"),
	VERY_DRY("Very dry"),
	DRY("Dry"),
	A_BIT_DRY("A bit dry"),
	ON_RATE("On rate"),
	A_BIT_SPOONED("A bit spooned"),
	SPOONED("Spooned"),
	VERY_SPOONED("Very spooned"),
	EXTREMELY_SPOONED("Extremely spooned");

	/** Below this luck it is dry; at or above it the middle band starts. */
	public static final double DRY_BELOW = 0.35;
	/** Above this luck it is spooned. */
	public static final double SPOONED_ABOVE = 0.65;
	/** Under this many expected uniques there is nothing to read yet ("Too early"). */
	public static final double TOO_EARLY_BELOW = 0.5;

	private final String label;

	Verdict(String label)
	{
		this.label = label;
	}

	public String label()
	{
		return label;
	}

	/** 0 (extremely dry) to 8 (extremely spooned). */
	public int band()
	{
		return ordinal();
	}

	public boolean isDry()
	{
		return ordinal() < ON_RATE.ordinal();
	}

	public boolean isSpooned()
	{
		return ordinal() > ON_RATE.ordinal();
	}

	/** Every word, driest first. */
	public static java.util.List<String> labels()
	{
		java.util.List<String> labels = new java.util.ArrayList<>();
		for (Verdict v : values())
		{
			labels.add(v.label);
		}
		return java.util.Collections.unmodifiableList(labels);
	}

	/** The verdict for a luck percentile, or null when there is nothing to judge (NaN). */
	public static Verdict of(double luck)
	{
		if (Double.isNaN(luck))
		{
			return null;
		}
		int band;
		if (luck < 0.01)
		{
			band = 0;
		}
		else if (luck < 0.10)
		{
			band = 1;
		}
		else if (luck < DRY_BELOW)
		{
			band = 2;
		}
		else if (luck < 0.45)
		{
			band = 3;
		}
		else if (luck <= 0.55)
		{
			band = 4;
		}
		else if (luck <= SPOONED_ABOVE)
		{
			band = 5;
		}
		else if (luck <= 0.90)
		{
			band = 6;
		}
		else if (luck <= 0.99)
		{
			band = 7;
		}
		else
		{
			band = 8;
		}
		return values()[band];
	}

	/** The word for a luck percentile, or "" when there is nothing to judge. */
	public static String labelOf(double luck)
	{
		Verdict v = of(luck);
		return v == null ? "" : v.label;
	}

	/** True when {@code luck} reads "On rate" (false for NaN). */
	public static boolean isOnRate(double luck)
	{
		return of(luck) == ON_RATE;
	}

	/**
	 * Where a luck value sits on the nine-step Rate Line, 0 (far left, driest) to 1 (far right).
	 * Every verdict gets an equal ninth, and the value moves along inside its own band, so the
	 * 1% and 99% bands stay readable. Null luck (NaN) gives NaN.
	 */
	public static double position(double luck)
	{
		Verdict v = of(luck);
		if (v == null)
		{
			return Double.NaN;
		}
		double lo = LOWER[v.ordinal()];
		double hi = LOWER[v.ordinal() + 1];
		double within = hi > lo ? Math.max(0, Math.min(1, (luck - lo) / (hi - lo))) : 0.5;
		return (v.ordinal() + within) / 9.0;
	}

	/** Lower edge of each band, plus 1 at the end. */
	private static final double[] LOWER = {0, 0.01, 0.10, 0.35, 0.45, 0.55, 0.65, 0.90, 0.99, 1};
}

package com.onrate.engine.raids;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;

/**
 * Estimates your contribution in The Fractured Archive from the damage you and your team deal.
 * Jagex's loot post: each room hands out 100 contribution (Ocellus 300) split by damage, minion
 * damage included. The game doesn't show the number, so this adds up the hitsplats On Rate sees:
 * yours, and the other players' (the game shows them on monsters too).
 *
 * <p>NPC IDs are from the OSRS Wiki's boss pages and its Strategies page (November 2026). Not
 * modelled, because Jagex hasn't said how they work: the soft cap on minion damage, and how
 * Ocellus's 300 is split between his phases (here it is one share of all his damage).
 */
public class FracturedContribution
{
	/** The five fights of a run: the Archive Guardian, one of each pair, then Ocellus. */
	enum Room
	{
		ARCHIVE_GUARDIAN(0, 100, 16659, 16660, 16664),
		EZEKIEL(1, 100, 16652, 16653),
		BORK(1, 100, 16640, 16641),
		MOIA(2, 100, 16667, 16670),
		DREADNOTH(2, 100, 16665, 16666),
		DAGONHAI_ELDER(3, 100, 16643, 16644, 16646, 16647, 16648, 16650),
		XARTH(3, 100, 16684, 16687, 16688),
		OCELLUS(4, 300, 16672, 16673, 16674, 16675, 16676, 16677, 16678, 16679, 16680, 16681);

		/** Which of the five fights this is (rooms of a pair share it). */
		final int slot;
		final double contribution;
		final int[] npcIds;

		Room(int slot, double contribution, int... npcIds)
		{
			this.slot = slot;
			this.contribution = contribution;
			this.npcIds = npcIds;
		}
	}

	static final int SLOTS = 5;

	private static final Map<Integer, Room> BY_NPC = new HashMap<>();

	static
	{
		for (Room room : Room.values())
		{
			for (int id : room.npcIds)
			{
				BY_NPC.put(id, room);
			}
		}
	}

	/** What On Rate saw of one raid. */
	public static final class Result
	{
		/** Your contribution out of 700 before deaths, or -1 when a fight was missed. */
		public final double contribution;
		/** Your deaths in the raid. */
		public final int deaths;

		Result(double contribution, int deaths)
		{
			this.contribution = contribution;
			this.deaths = deaths;
		}
	}

	private final Map<Room, long[]> damage = new EnumMap<>(Room.class);
	private int deaths;

	/** True when the NPC belongs to The Fractured Archive. */
	public static boolean isArchiveNpc(int npcId)
	{
		return BY_NPC.containsKey(npcId);
	}

	/**
	 * A hitsplat on a monster. Only player damage counts (yours or another player's), not poison,
	 * venom, burns or healing, which have no owner.
	 */
	public void onHitsplat(int npcId, int amount, boolean mine, boolean others)
	{
		Room room = BY_NPC.get(npcId);
		if (room == null || amount <= 0 || !mine && !others)
		{
			return;
		}
		if (room == Room.ARCHIVE_GUARDIAN && seenPastGuardian())
		{
			// the Archive Guardian is the first fight: this is a new raid (the last one was wiped or missed)
			reset();
		}
		long[] d = damage.computeIfAbsent(room, r -> new long[2]);
		d[0] += mine ? amount : 0;
		d[1] += amount;
	}

	/** You died: counted only during a raid On Rate is following. */
	public void onLocalDeath()
	{
		if (isActive())
		{
			deaths++;
		}
	}

	/** True once a fight of this raid was seen. */
	public boolean isActive()
	{
		return !damage.isEmpty();
	}

	/**
	 * The raid is complete: what it saw, then starts over. Null when it saw nothing of the raid.
	 * The contribution is -1 unless all five fights were seen (On Rate turned on mid-raid, say).
	 */
	public Result finish()
	{
		if (!isActive())
		{
			return null;
		}
		boolean[] seen = new boolean[SLOTS];
		double contribution = 0;
		for (Map.Entry<Room, long[]> e : damage.entrySet())
		{
			long[] d = e.getValue();
			if (d[1] > 0)
			{
				seen[e.getKey().slot] = true;
				contribution += e.getKey().contribution * d[0] / d[1];
			}
		}
		boolean all = true;
		for (boolean s : seen)
		{
			all &= s;
		}
		Result result = new Result(all ? contribution : -1, deaths);
		reset();
		return result;
	}

	public void reset()
	{
		damage.clear();
		deaths = 0;
	}

	private boolean seenPastGuardian()
	{
		for (Room room : damage.keySet())
		{
			if (room != Room.ARCHIVE_GUARDIAN)
			{
				return true;
			}
		}
		return false;
	}
}

