	public synchronized void reset(String bossName)
	{
		clogSync.forget(bossName);
		if (ctx.state().bosses != null && ctx.state().bosses.remove(bossName) != null)
		{
			ctx.killsChanged.add(bossName);
			ctx.raidsChanged.add(bossName);
		}
		// Recent's day counts, the trip and the last-kill pointers must not outlive the reset
		for (Map<String, DayCount> forDay : ctx.state().days().values())
		{
			forDay.remove(bossName);
		}
		dayCounts.forget(bossName);
		trips.forget(bossName);
		if (bossName.equals(lastBoss))
		{
			lastBoss = null;
		}
	}

	/** True for content where one completion takes long: a raid, the Inferno or the Fight Caves. */
	public static boolean isLongRun(BossDefinition boss)
	{
		return Trips.isLongRun(boss);
	}

	/** How long without a kill ends the current trip (0 when there is none). */
	public synchronized long tripIdleLimitMillis()
	{
		return trips.tripIdleLimitMillis();
	}

	/** Forget the current trip; the next kill starts a new one. */
	public synchronized void resetTrip()
	{
		trips.resetTrip();
	}

	/** The last unique On Rate saw in History (any boss), or null; with when History starts. */
	public synchronized LastUnique lastUnique()
	{
		return historyBook.lastUnique();
	}

	/** See {@link #lastUnique()}: the item (null when none in History), its boss and time, and History's start. */
	public static final class LastUnique
	{
		public final String item;
		public final String boss;
		public final long time;
		public final long historyStart;

		LastUnique(String item, String boss, long time, long historyStart)
		{
			this.item = item;
			this.boss = boss;
			this.time = time;
			this.historyStart = historyStart;
		}
	}

	/** The current trip's numbers, or null when there is no trip. */
	public synchronized TripStats tripStats()
	{
		return trips.tripStats();
	}

	private void markKill(BossDefinition boss, long nowMillis)
	{
		lastBoss = boss.getName();
		lastKillMillis = nowMillis;
	}

	public synchronized BossStats stats(String bossName, RaidSettings raids)
	{
		return statistics.stats(bossName, raids);
	}

	/**
	 * Every boss with kills or drops, added up: how dry or spooned the account is overall.
	 */
	public synchronized AccountStats accountStats(RaidSettings raids)
	{
		return statistics.accountStats(raids);
	}

	/**
	 * Same as {@link #accountStats(RaidSettings)}, plus GE value when {@code prices} is given.
	 * Prices are per item name; untradeable items have price 0, so they count for the number
	 * of uniques but not for value.
	 */
	public synchronized AccountStats accountStats(RaidSettings raids, ToLongFunction<String> prices)
	{
		return statistics.accountStats(raids, prices);
	}

	/**
	 * Every item several bosses drop. Complete when the log total is known and every boss
	 * that drops it has a known kill count; otherwise lists the pages still to open.
	 */
	public synchronized List<SharedPool> sharedPools(RaidSettings raids)
	{
		return statistics.sharedPools(raids);
	}

	/** The shared items this boss drops (with every boss that drops them), for its page. */
	public synchronized List<SharedPool> sharedPoolsFor(String bossName, RaidSettings raids)
	{
		return statistics.sharedPoolsFor(bossName, raids);
	}

}

package com.onrate.engine.tracking;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.stats.RaidSettings;
import java.util.HashSet;
import java.util.Set;
import java.util.function.ToIntFunction;

/**
 * What the parts of the tracker share: the catalogue, the account loaded now, the player's settings,
 * how to count the team at a kill, and which bosses' History and raids changed since the last save.
 *
 * <p>The account's state is swapped when another account logs in ({@link Tracker#setState}). Parts of
 * the tracker must therefore never keep the state object itself: they ask for {@link #state()} each
 * time, so they always see the account that is loaded now. Only used under the tracker's lock.
 */
final class TrackerContext
{
	final BossCatalog catalog;
	private TrackerState state = new TrackerState();
	private RaidSettings settings = raid -> 0;
	/** Your team at a boss kill (you included), by boss name; 0 when unknown or turned off. */
	private ToIntFunction<String> teamSize = boss -> 0;
	/** Bosses whose History changed since the last save (it is saved per boss). */
	final Set<String> killsChanged = new HashSet<>();
	/** Raids whose saved raids changed since the last save (saved per raid). */
	final Set<String> raidsChanged = new HashSet<>();

	TrackerContext(BossCatalog catalog)
	{
		this.catalog = catalog;
	}

	/** The account loaded now. Ask each time; never keep it. */
	TrackerState state()
	{
		return state;
	}

	void setState(TrackerState state)
	{
		this.state = state;
	}

	RaidSettings settings()
	{
		return settings;
	}

	void setSettings(RaidSettings settings)
	{
		this.settings = settings;
	}

	ToIntFunction<String> teamSize()
	{
		return teamSize;
	}

	void setTeamSize(ToIntFunction<String> teamSize)
	{
		this.teamSize = teamSize;
	}
}

package com.onrate.engine.tracking;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * All saved progress for one account, keyed by boss name.
 */
public class TrackerState
{
	Map<String, BossProgress> bosses = new HashMap<>();
	/**
	 * Collection log totals of items that several bosses drop (godsword shards, Virtus...).
	 * The log only shows one total, so it can't be split per boss, but it is exact for the
	 * account as a whole.
	 */
	Map<String, Integer> sharedClog = new HashMap<>();

	/** Kills, uniques and expected per day (epoch day as text) per boss, for the last two weeks. */
	Map<String, Map<String, DayCount>> days = new HashMap<>();

	Map<String, Map<String, DayCount>> days()
	{
		if (days == null)
		{
			days = new HashMap<>();
		}
		return days;
	}

	/** Luck graph: the account's luck at the end of each day On Rate was used. */
	List<HistoryPoint> history = new ArrayList<>();

	List<HistoryPoint> history()
	{
		if (history == null)
		{
			history = new ArrayList<>();
		}
		return history;
	}

	/** Shared items (pool key) the player chose to judge on each boss separately. Null in older saves. */
	Map<String, PoolSplit> poolSplits = new HashMap<>();

	/** Copies of shared items (pool key) On Rate saw drop from monsters other than their bosses. Null in older saves. */
	Map<String, Integer> poolElsewhereSeen = new HashMap<>();

	Map<String, Integer> poolElsewhereSeen()
	{
		if (poolElsewhereSeen == null)
		{
			poolElsewhereSeen = new HashMap<>();
		}
		return poolElsewhereSeen;
	}

	Map<String, PoolSplit> poolSplits()
	{
		if (poolSplits == null)
		{
			poolSplits = new HashMap<>();
		}
		return poolSplits;
	}

	Map<String, Integer> sharedClog()
	{
		if (sharedClog == null)
		{
			sharedClog = new HashMap<>();
		}
		return sharedClog;
	}

	BossProgress get(String boss)
	{
		if (bosses == null)
		{
			bosses = new HashMap<>();
		}
		BossProgress progress = bosses.computeIfAbsent(boss, k -> new BossProgress());
		progress.ensureMaps();
		return progress;
	}

	BossProgress peek(String boss)
	{
		if (bosses == null)
		{
			return null;
		}
		BossProgress progress = bosses.get(boss);
		if (progress != null)
		{
			progress.ensureMaps();
		}
		return progress;
	}
}

package com.onrate.engine.tracking;

import java.util.Map;

/** Where a trip started: the numbers of its boss just before its first kill. Not saved. */
class Trip
{
	final String boss;
	final long startMillis;
	long lastMillis;
	final int startKc;
	final double startExpected;
	final int startReceived;
	final Map<String, Integer> receivedPerRow;
	/** Shared items (godsword shards...) this boss had dropped when the trip started, by pool key. */
	Map<String, Integer> poolSeenStart = new java.util.HashMap<>();

	Trip(String boss, long startMillis, int startKc, double startExpected, int startReceived,
		Map<String, Integer> receivedPerRow)
	{
		this.boss = boss;
		this.startMillis = startMillis;
		this.lastMillis = startMillis;
		this.startKc = startKc;
		this.startExpected = startExpected;
		this.startReceived = startReceived;
		this.receivedPerRow = receivedPerRow;
	}
}

package com.onrate.engine.tracking;

import com.onrate.engine.math.Luck;
import com.onrate.engine.math.Poisson;

import java.util.Collections;
import java.util.List;

/** The current trip: kills, uniques and what was expected since it started. */
public class TripStats
{
	private final String boss;
	private final long startMillis;
	private final long lastMillis;
	private final int kills;
	private final int received;
	private final double expected;
	private final List<String> drops;
	private final double sharedExpected;
	private final int sharedReceived;
	private final List<String> sharedNames;

	TripStats(String boss, long startMillis, long lastMillis, int kills, int received, double expected, List<String> drops,
		double sharedExpected, int sharedReceived, List<String> sharedNames)
	{
		this.sharedExpected = sharedExpected;
		this.sharedReceived = sharedReceived;
		this.sharedNames = Collections.unmodifiableList(sharedNames);
		this.boss = boss;
		this.startMillis = startMillis;
		this.lastMillis = lastMillis;
		this.kills = kills;
		this.received = received;
		this.expected = expected;
		this.drops = Collections.unmodifiableList(drops);
	}

	public String getBoss()
	{
		return boss;
	}

	public long getStartMillis()
	{
		return startMillis;
	}

	public long getLastMillis()
	{
		return lastMillis;
	}

	public int getKills()
	{
		return kills;
	}

	public int getReceived()
	{
		return received;
	}

	public double getExpected()
	{
		return expected;
	}

	/** Items received this trip, one entry per drop. */
	public List<String> getDrops()
	{
		return drops;
	}

	/** Expected from shared items (godsword shards...) the boss drops, part of {@link #getExpected()}. */
	public double getSharedExpected()
	{
		return sharedExpected;
	}

	/** Shared items received this trip, part of {@link #getReceived()}. */
	public int getSharedReceived()
	{
		return sharedReceived;
	}

	/** Names of the shared items counted in the shared figures. */
	public List<String> getSharedNames()
	{
		return sharedNames;
	}

	/** Luck for this trip alone, from the first kill on (NaN only when nothing is expected). */
	public double getLuck()
	{
		return Luck.of(received, expected);
	}

	/** Of players doing the same kills: {share with fewer uniques, share with as many}; null when nothing was expected. */
	public double[] getShares()
	{
		return Poisson.shares(received, expected);
	}

	/** Kills per hour, or NaN for trips shorter than a minute. */
	public double getKillsPerHour()
	{
		long millis = lastMillis - startMillis;
		return millis < 60_000 || kills < 2 ? Double.NaN : (kills - 1) * 3_600_000.0 / millis;
	}
}

package com.onrate.engine.tracking;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.DropDefinition;
import com.onrate.engine.stats.BossStats;
import com.onrate.engine.stats.RowStats;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The current trip: the kills of one boss without a long break (longer for raids and other long
 * runs), the numbers just before the latest kill and what the trip has given so far.
 * <p>
 * Package-private and unsynchronized: reached only through {@link Tracker}, under its lock.
 */
final class Trips
{
	private final TrackerContext ctx;
	private final BossCatalog catalog;
	private final Statistics statistics;
	private final SharedItems sharedItems;
	private final List<Note> outbox;

	/** A trip ends after this long without a kill, or when you kill another boss. */
	static final long TRIP_IDLE_MILLIS = 30 * 60_000;
	/**
	 * The same for content where one completion takes long: a raid, the Inferno or the Fight
	 * Caves often takes more than 30 minutes, which would start a new trip every time. Two hours
	 * leaves room for a slow raid plus a break; another boss or the button still end it sooner.
	 */
	static final long LONG_TRIP_IDLE_MILLIS = 120 * 60_000;
	private Trip trip;
	/** This boss's numbers just before the kill being counted (for the trip card and Recent). */
	private Trip beforeThisKill;

	Trips(TrackerContext ctx, Statistics statistics, SharedItems sharedItems, List<Note> outbox)
	{
		this.ctx = ctx;
		this.catalog = ctx.catalog;
		this.statistics = statistics;
		this.sharedItems = sharedItems;
		this.outbox = outbox;
	}

	/** The numbers just before the kill being counted now, or null outside a kill. */
	Trip beforeThisKill()
	{
		return beforeThisKill;
	}

	/** Another account was loaded: no trip carries over. */
	void clear()
	{
		trip = null;
		beforeThisKill = null;
	}

	/** This boss was reset: its trip ends. */
	void forget(String bossName)
	{
		if (trip != null && trip.boss.equals(bossName))
		{
			trip = null;
			beforeThisKill = null;
		}
	}

	/**
	 * GE value the current trip's own kills should give (their delve level, raid points, team),
	 * or NaN without a trip or when History lacks one of its kills.
	 */
	double tripValue(java.util.function.ToLongFunction<String> prices)
	{
		if (trip == null)
		{
			return Double.NaN;
		}
		BossDefinition boss = catalog.byName(trip.boss);
		BossProgress p = boss == null ? null : ctx.state().peek(boss.getName());
		BossStats s = boss == null ? null : statistics.stats(boss.getName(), ctx.settings());
		if (p == null || s == null)
		{
			return Double.NaN;
		}
		int kills = Math.max(0, s.getKillCount() - trip.startKc);
		double sum = 0;
		int found = 0;
		for (int i = p.kills.size() - 1; i >= 0 && found < kills; i--)
		{
			KillEntry k = p.kills.get(i);
			if (!k.isDateKnown())
			{
				// a drop added by hand, not a kill of this trip
				continue;
			}
			if (k.time < trip.startMillis)
			{
				break;
			}
			sum += statistics.perKill(boss, k, drop -> Math.max(0, prices.applyAsLong(drop.getName())));
			found++;
		}
		return found == kills && kills > 0 ? sum : Double.NaN;
	}

	/** True for content where one completion takes long: a raid, the Inferno or the Fight Caves. */
	static boolean isLongRun(BossDefinition boss)
	{
		String name = boss.getName();
		return boss.getRaid() != null || "TzKal-Zuk".equals(name) || "TzTok-Jad".equals(name);
	}

	static long tripIdleMillis(BossDefinition boss)
	{
		return isLongRun(boss) ? LONG_TRIP_IDLE_MILLIS : TRIP_IDLE_MILLIS;
	}

	boolean continuesTrip(BossDefinition boss, long nowMillis)
	{
		return trip != null && trip.boss.equals(boss.getName()) && nowMillis - trip.lastMillis <= tripIdleMillis(boss);
	}

	/**
	 * Called just before a kill is counted: remembers the numbers as they are now, so the trip
	 * card and Recent get exactly what this kill added (also for raids, whose points come in a
	 * moment after the kill).
	 */
	void beforeKill(BossDefinition boss, long nowMillis)
	{
		beforeThisKill = null;
		BossStats s = statistics.stats(boss.getName(), ctx.settings());
		if (s == null)
		{
			return;
		}
		Map<String, Integer> received = new HashMap<>();
		for (RowStats row : s.getRows())
		{
			received.put(row.getLabel(), row.getReceived());
		}
		RowStats any = s.getAnyRow();
		beforeThisKill = new Trip(boss.getName(), nowMillis, s.getKillCount(), any.getExpected(), any.getReceived(), received);
		beforeThisKill.poolSeenStart = sharedItems.poolSeenSnapshot(boss);
	}

	/**
	 * Called after each kill: continues the current trip, or starts a new one when this is
	 * another boss or the last kill was a while ago. The new trip includes this kill.
	 */
	void afterKill(BossDefinition boss, long nowMillis)
	{
		Trip before = beforeThisKill;
		beforeThisKill = null;
		if (continuesTrip(boss, nowMillis))
		{
			trip.lastMillis = nowMillis;
			return;
		}
		BossStats s = statistics.stats(boss.getName(), ctx.settings());
		if (s == null)
		{
			return;
		}
		if (before != null && before.boss.equals(boss.getName()) && s.getKillCount() == before.startKc + 1)
		{
			trip = before;
			return;
		}
		// no snapshot of exactly one kill ago (e.g. the first kill count after a long break
		// jumped by more than one): start from this kill at the average rate
		Map<String, Integer> received = new HashMap<>();
		for (RowStats row : s.getRows())
		{
			received.put(row.getLabel(), row.getReceived());
		}
		RowStats any = s.getAnyRow();
		trip = new Trip(boss.getName(), nowMillis, s.getKillCount() - 1,
			any.getExpected() - any.getRate(), any.getReceived(), received);
		trip.poolSeenStart = sharedItems.poolSeenSnapshot(boss);
	}

	/** How long without a kill ends the current trip (0 when there is none). */
	long tripIdleLimitMillis()
	{
		BossDefinition boss = trip == null ? null : catalog.byName(trip.boss);
		return boss == null ? 0 : tripIdleMillis(boss);
	}

	/** Forget the current trip; the next kill starts a new one. */
	void resetTrip()
	{
		trip = null;
	}

	/** The current trip's numbers, or null when there is no trip. */
	TripStats tripStats()
	{
		if (trip == null)
		{
			return null;
		}
		BossStats s = statistics.stats(trip.boss, ctx.settings());
		if (s == null)
		{
			return null;
		}
		List<String> drops = new ArrayList<>();
		for (RowStats row : s.getRows())
		{
			Integer before = trip.receivedPerRow.get(row.getLabel());
			int got = row.getReceived() - (before == null ? 0 : before);
			for (int i = 0; i < got; i++)
			{
				drops.add(row.getLabel());
			}
		}
		RowStats any = s.getAnyRow();
		int kills = Math.max(0, s.getKillCount() - trip.startKc);
		int received = Math.max(0, any.getReceived() - trip.startReceived);
		double expected = Math.max(0, any.getExpected() - trip.startExpected);
		// Shared items (godsword shards...) can drop here too, whether or not the player assigned
		// them to this boss: the trip counts them as this boss's drops, expected and received.
		BossDefinition tripBoss = catalog.byName(trip.boss);
		BossProgress progress = ctx.state().peek(trip.boss);
		double sharedExpected = 0;
		int sharedReceived = 0;
		List<String> sharedNames = new ArrayList<>();
		if (tripBoss != null)
		{
			// shared items the player assigned to this boss are rows after the boss's own
			List<DropDefinition> shown = s.getDrops();
			for (int i = tripBoss.getDrops().size(); i < s.getRows().size() && i < shown.size(); i++)
			{
				RowStats row = s.getRows().get(i);
				if (!statistics.counts(tripBoss, shown.get(i), progress))
				{
					continue;
				}
				Integer before = trip.receivedPerRow.get(row.getLabel());
				sharedExpected += row.getRate() * kills;
				sharedReceived += Math.max(0, row.getReceived() - (before == null ? 0 : before));
				sharedNames.add(row.getLabel());
			}
			for (Map.Entry<String, DropDefinition> e : catalog.poolsOf(tripBoss).entrySet())
			{
				DropDefinition drop = e.getValue();
				if (sharedItems.activeSplit(e.getKey()) != null || !statistics.counts(tripBoss, drop, progress))
				{
					continue; // already one of the boss's rows above, or left out of the total
				}
				double poolExpected = RateModel.effectiveRate(tripBoss, drop, ctx.settings()) * kills;
				expected += poolExpected;
				sharedExpected += poolExpected;
				sharedNames.add(drop.getDisplayName());
				Integer start = trip.poolSeenStart.get(e.getKey());
				int got = Math.max(0, sharedItems.poolSeenAt(trip.boss, e.getKey()) - (start == null ? 0 : start));
				received += got;
				sharedReceived += got;
				for (int i = 0; i < got; i++)
				{
					drops.add(drop.getDisplayName());
				}
			}
		}
		return new TripStats(trip.boss, trip.startMillis, trip.lastMillis, kills, received, expected, drops,
			sharedExpected, sharedReceived, sharedNames);
	}
}

package com.onrate.game;

import com.onrate.engine.tracking.ClogPage;
import com.onrate.engine.tracking.Tracker;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Reads a collection log page from the game's widgets when the player opens it, and hands it to
 * the tracker. A page that can't be read changes nothing: a missing read is never "zero drops".
 */
public final class ClogReader
{
	private static final Logger log = LoggerFactory.getLogger(ClogReader.class);

	private final Client client;
	private final ItemManager itemManager;
	private final Tracker tracker;
	private final PriceBook prices;
	private final Consumer<String> synced;
	private final Runnable unreadable;
	/** Problems already warned about this session (a page title, or "header"), so each shows once. */
	private final Set<String> reported = new HashSet<>();
	/** Titles of pages we don't cover already noted at debug level. */
	private final Set<String> uncovered = new HashSet<>();

	/**
	 * @param synced     told the first boss a page changed
	 * @param unreadable told when a page we cover could not be read
	 */
	public ClogReader(Client client, ItemManager itemManager, Tracker tracker, PriceBook prices, Consumer<String> synced,
		Runnable unreadable)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.tracker = tracker;
		this.prices = prices;
		this.synced = synced;
		this.unreadable = unreadable;
	}

	/** Reads the page that is open now. Client thread only. */
	public void read()
	{
		Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		Widget itemsWidget = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (header == null || itemsWidget == null)
		{
			// most likely the log was closed before the next tick; not worth telling the player
			log.debug("Collection log page drawn but its widgets are gone (header {}, items {})", header != null, itemsWidget != null);
			return;
		}
		Widget[] headerLines = header.getDynamicChildren();
		String rawTitle = headerLines == null || headerLines.length == 0 ? null : headerLines[0].getText();
		List<String> rawCounters = new ArrayList<>();
		for (int i = 1; headerLines != null && i < headerLines.length; i++)
		{
			rawCounters.add(headerLines[i].getText());
		}

		List<ClogPage.Item> rawItems = new ArrayList<>();
		Widget[] itemWidgets = itemsWidget.getDynamicChildren();
		if (itemWidgets != null)
		{
			for (Widget w : itemWidgets)
			{
				int id = w.getItemId();
				if (id <= 0)
				{
					continue;
				}
				String name = itemManager.getItemComposition(id).getName();
				rawItems.add(new ClogPage.Item(name, w.getItemQuantity(), w.getOpacity()));
				prices.learn(name, id);
			}
		}

		ClogPage.Result page = ClogPage.parse(rawTitle, rawCounters, rawItems);
		String title = page.getTitle();
		ClogPage.Problem problem = page.getProblem();
		if (problem == ClogPage.Problem.NO_TITLE || problem == ClogPage.Problem.TITLE_IS_A_COUNTER)
		{
			// not even the page is known: the header may have changed
			fail(null, problem.toString());
			return;
		}
		if (!tracker.coversPage(title))
		{
			// a page On Rate doesn't read (Clues, Minigames, ...): normal, nothing to say
			if (uncovered.add(title))
			{
				log.debug("Collection log page \"{}\" is not one On Rate covers", title);
			}
			return;
		}
		if (problem != null)
		{
			fail(title, problem.toString());
			return;
		}
		if (page.isAllFaded() && tracker.wouldZeroSaved(title, page.getItems()))
		{
			// the log never loses items, so this page was misread: keep what we have
			fail(title, "every item read as not obtained, but drops are saved");
			return;
		}
		Set<String> changed = tracker.onClogPage(title, page.getCounters(), page.getItems());
		if (!changed.isEmpty())
		{
			synced.accept(changed.iterator().next());
		}
	}

	private void fail(String title, String reason)
	{
		if (tracker.onClogPageUnreadable(title) && reported.add(title == null ? "header" : title))
		{
			if (title == null)
			{
				log.warn("Collection log opened but its header could not be read: {}", reason);
			}
			else
			{
				log.warn("Collection log page \"{}\" opened but not read: {}", title, reason);
			}
		}
		unreadable.run();
	}
}

package com.onrate.game;

import com.expecteddrops.ExpectedDropsConfig;
import com.expecteddrops.DuoMode;
import com.onrate.engine.stats.RaidChance;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.RaidHabits;
import java.util.Locale;
import java.util.function.Supplier;

/** The player's settings, as the numbers the drop maths needs. */
public final class ConfigRaidSettings implements RaidSettings
{
	private final ExpectedDropsConfig config;
	/** How you usually raid, from your recorded raids; used where a setting is still at its default. */
	private final Supplier<RaidHabits> habits;

	public ConfigRaidSettings(ExpectedDropsConfig config)
	{
		this(config, RaidHabits::none);
	}

	public ConfigRaidSettings(ExpectedDropsConfig config, Supplier<RaidHabits> habits)
	{
		this.config = config;
		this.habits = habits == null ? RaidHabits::none : habits;
	}

	/** The settings as they come: a setting still at one of these was never changed by the player. */
	private static final ExpectedDropsConfig DEFAULTS = new ExpectedDropsConfig()
	{
	};

	@Override
	public double uniqueChance(String raid)
	{
		double percent;
		switch (raid)
		{
			case "cox":
				percent = config.coxUniqueChance();
				break;
			case "coxCm":
				percent = config.coxCmUniqueChance();
				break;
			case "tob":
				percent = config.tobTeamChance() / teamSize(raid);
				break;
			case "tobHm":
				percent = config.tobHmTeamChance() / teamSize(raid);
				break;
			case "toaEntry":
				percent = config.toaEntryUniqueChance();
				break;
			case "toa":
				percent = config.toaUniqueChance();
				break;
			case "toaExpert":
				percent = config.toaExpertUniqueChance();
				break;
			case "fractured":
				// an even share of the damage, no deaths, at the usual team size
				return RaidChance.tfaEven(teamSize(raid), 0, tfaBaseChance());
			default:
				percent = 0;
		}
		if (learnedRaids(raid) > 0 && !RaidHabits.usesTeamSize(family(raid)))
		{
			return habits.get().chance(raid);
		}
		return Math.max(0, Math.min(100, percent)) / 100.0;
	}

	@Override
	public int teamSize(String raid)
	{
		if (raid.startsWith("tob") || "fractured".equals(raid))
		{
			if (learnedRaids(raid) > 0)
			{
				return habits.get().teamSize(raid);
			}
			return raid.startsWith("tob") ? tobTeamSize() : tfaTeamSize();
		}
		return 1;
	}

	/**
	 * How many of your recorded raids a raid mode's chance (or team size) comes from instead of the
	 * setting, 0 when it uses the setting: the setting was changed, or there aren't enough raids yet.
	 */
	@Override
	public int learnedRaids(String raid)
	{
		if (raid == null || !atDefault(raid))
		{
			return 0;
		}
		RaidHabits h = habits.get();
		boolean known = RaidHabits.usesTeamSize(family(raid)) ? h.teamSize(raid) > 0 : !Double.isNaN(h.chance(raid));
		return known ? h.raids(raid) : 0;
	}

	/** "tobHm" is a Theatre of Blood mode, "coxCm" a Chambers one... */
	private static String family(String raid)
	{
		return raid.startsWith("tob") ? "tob" : raid.startsWith("toa") ? "toa" : raid.startsWith("cox") ? "cox" : raid;
	}

	/** True when the setting a raid mode would use was left as it came. */
	private boolean atDefault(String raid)
	{
		switch (raid)
		{
			case "cox":
				return config.coxUniqueChance() == DEFAULTS.coxUniqueChance();
			case "coxCm":
				return config.coxCmUniqueChance() == DEFAULTS.coxCmUniqueChance();
			case "tob":
			case "tobHm":
				// the team chance is the game's; what you choose is the team size
				return config.tobTeamSize() == DEFAULTS.tobTeamSize();
			case "toaEntry":
				return config.toaEntryUniqueChance() == DEFAULTS.toaEntryUniqueChance();
			case "toa":
				return config.toaUniqueChance() == DEFAULTS.toaUniqueChance();
			case "toaExpert":
				return config.toaExpertUniqueChance() == DEFAULTS.toaExpertUniqueChance();
			case "fractured":
				return config.tfaTeamSize() == DEFAULTS.tfaTeamSize();
			default:
				return false;
		}
	}

	@Override
	public double tfaBaseChance()
	{
		return Math.max(0, Math.min(100, config.tfaTeamChance())) / 100.0;
	}

	@Override
	public double contribution(String team, int kills)
	{
		if (!isDuoTeam(team) || kills <= 0)
		{
			return 1.0;
		}
		int duo = duoKills(team, kills);
		return (kills - duo + 0.5 * duo) / kills;
	}

	@Override
	public String contributionNote(String team, int kills)
	{
		if (!isDuoTeam(team))
		{
			return null;
		}
		int duo = duoKills(team, kills);
		if (duo == 0)
		{
			return "Counted as solo kills. If you duo, change it under Team bosses in the settings.";
		}
		if (duo >= kills)
		{
			return "Counted as duo kills: about half the uniques of a solo kill (the pet chance stays the same). "
				+ "If you solo, change it under Team bosses in the settings.";
		}
		return String.format(Locale.ROOT, "Counted as %,d solo and %,d duo kills (a duo gives about half the uniques).",
			kills - duo, duo);
	}

	private int tobTeamSize()
	{
		return Math.max(1, Math.min(5, config.tobTeamSize()));
	}

	private int tfaTeamSize()
	{
		return Math.max(1, Math.min(RaidChance.TFA_MAX_TEAM, config.tfaTeamSize()));
	}

	private static boolean isDuoTeam(String team)
	{
		return "royalTitans".equals(team) || "yama".equals(team);
	}

	/** How many of these kills count as duo kills, from the boss's solo/duo setting. */
	private int duoKills(String team, int kills)
	{
		boolean yama = "yama".equals(team);
		DuoMode mode = yama ? config.yamaMode() : config.royalTitansMode();
		int solo = yama ? config.yamaSoloKills() : config.royalTitansSoloKills();
		switch (mode)
		{
			case DUO:
				return kills;
			case SOLO:
				return 0;
			case MIXED:
				return kills - Math.max(0, Math.min(kills, solo));
			default:
				return kills;
		}
	}
}

package com.onrate.game;

import java.util.Collection;
import java.util.function.Predicate;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.loottracker.LootTrackerPlugin;

/**
 * Whether RuneLite's Loot Tracker plugin is turned on. On Rate sees new drops through the
 * {@code LootReceived} event, and only the Loot Tracker posts it, so with it off no new drop arrives.
 * <p>
 * Read through {@link PluginManager#isPluginEnabled}, the same check RuneLite's own plugin list uses
 * (the "runelite" setting named after the plugin, or its default when never set), so no setting key is
 * guessed here. When it can't be told for sure (no plugin manager, the Loot Tracker isn't loaded, or
 * the check fails) the answer is {@link State#UNKNOWN} and nothing should be shown.
 */
public final class LootTrackerStatus
{
	public enum State
	{
		ENABLED,
		DISABLED,
		UNKNOWN,
	}

	private LootTrackerStatus()
	{
	}

	/** The Loot Tracker's state from RuneLite's plugin manager; UNKNOWN when it can't be told. */
	public static State of(PluginManager plugins)
	{
		if (plugins == null)
		{
			return State.UNKNOWN;
		}
		try
		{
			return of(plugins.getPlugins(), plugins::isPluginEnabled);
		}
		catch (RuntimeException e)
		{
			return State.UNKNOWN;
		}
	}

	/** As {@link #of(PluginManager)}, for the loaded plugins and a way to ask whether one is turned on. */
	static State of(Collection<Plugin> loaded, Predicate<Plugin> enabled)
	{
		if (loaded == null)
		{
			return State.UNKNOWN;
		}
		for (Plugin p : loaded)
		{
			if (isLootTracker(p))
			{
				try
				{
					return enabled.test(p) ? State.ENABLED : State.DISABLED;
				}
				catch (RuntimeException e)
				{
					return State.UNKNOWN;
				}
			}
		}
		// not loaded (yet): don't claim it is off
		return State.UNKNOWN;
	}

	/** True for RuneLite's Loot Tracker plugin. */
	public static boolean isLootTracker(Plugin plugin)
	{
		return plugin instanceof LootTrackerPlugin;
	}
}

package com.onrate.game;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.ValueFormula;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Item ids and prices for the items On Rate tracks, from RuneLite's own price list (no web
 * requests). Untradeable items are worth what they make, where {@code bosses.json} says so.
 */
public final class PriceBook
{
	private static final Logger log = LoggerFactory.getLogger(PriceBook.class);
	private static final long REFRESH_MILLIS = 10 * 60_000;

	private final BossCatalog catalog;
	private final ItemManager itemManager;
	private final Map<String, Integer> itemIds = new ConcurrentHashMap<>();
	/** GE price per normalized item name. Untradeables are 0. */
	private final Map<String, Long> prices = new ConcurrentHashMap<>();
	private volatile boolean resolved;
	private long refreshedAt;

	public PriceBook(BossCatalog catalog, ItemManager itemManager)
	{
		this.catalog = catalog;
		this.itemManager = itemManager;
	}

	/** Remembers an id seen on the collection log page. */
	public void learn(String itemName, int id)
	{
		itemIds.putIfAbsent(BossCatalog.normalize(itemName), id);
	}

	/** Looks up an id for every item in the drop data, once. Client thread only. */
	public boolean resolve(Client client)
	{
		if (resolved)
		{
			return false;
		}
		Set<String> wanted = new HashSet<>(catalog.getAllItemNames());
		wanted.addAll(catalog.getFormulaItemNames());
		int count = client.getItemCount();
		for (int id = 0; id < count; id++)
		{
			ItemComposition comp = client.getItemDefinition(id);
			if (comp == null || comp.getNote() != -1 || comp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			String key = BossCatalog.normalize(comp.getName());
			if (wanted.contains(key))
			{
				itemIds.putIfAbsent(key, id);
			}
		}
		resolved = true;
		refresh(true);
		return true;
	}

	/** Copies the prices of all tracked items from RuneLite's list. Client thread only. */
	public void refresh(boolean force)
	{
		long now = System.currentTimeMillis();
		if (!force && now - refreshedAt < REFRESH_MILLIS)
		{
			return;
		}
		refreshedAt = now;
		for (Map.Entry<String, Integer> e : itemIds.entrySet())
		{
			try
			{
				prices.put(e.getKey(), (long) Math.max(0, itemManager.getItemPrice(e.getValue())));
			}
			catch (RuntimeException ex)
			{
				log.debug("No price for {}", e.getKey(), ex);
			}
		}
	}

	/** GP value of an item: its price, or what it makes when it can't be traded. */
	public long priceOf(String itemName)
	{
		Long price = prices.get(BossCatalog.normalize(itemName));
		if (price != null && price > 0)
		{
			return price;
		}
		ValueFormula formula = catalog.getValueFormula(itemName);
		return formula == null ? 0 : formula.evaluate(this::tradedPrice);
	}

	private long tradedPrice(String itemName)
	{
		Long price = prices.get(BossCatalog.normalize(itemName));
		return price == null ? 0 : price;
	}

	/** The id for an item picture, or -1 while it is not known. */
	public int idOf(String itemName)
	{
		Integer id = itemIds.get(BossCatalog.normalize(itemName));
		return id == null ? -1 : id;
	}

	public boolean isResolved()
	{
		return resolved;
	}

	public void clear()
	{
		itemIds.clear();
		prices.clear();
		resolved = false;
		refreshedAt = 0;
	}
}

