			Arrays.asList(item("Vorkath", 5.0, 1), item("Zulrah", 2.0, 2)), 0.2, 0.8, "uniques");
		for (String f : facts)
		{
			String lower = f.toLowerCase(java.util.Locale.ROOT);
			for (String word : new String[]{"due", "soon", "next", "keep going", "overdue"})
			{
