	@Test
	public void theFactMovesOnWhenThePageOpensOrAKillComesInNotOnARedraw() throws Exception
	{
		int[] turns = new int[6];
		SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				RaidSettings raids = raid -> 0.03;
				ExpectedDropsPanel p = new ExpectedDropsPanel(new Tracker(Bundled.catalog(new Gson())), null, () -> raids,
					s -> -1, () -> { }, () -> false, () -> { }, name -> 0L,
					() -> new ViewOptions(ItemView.TARGET_BARS, false, false, false, false, true));
				Field select = ExpectedDropsPanel.class.getDeclaredField("bossSelect");
				select.setAccessible(true);
				@SuppressWarnings("unchecked")
				JComboBox<String> bosses = (JComboBox<String>) select.get(p);
				Method turn = ExpectedDropsPanel.class.getDeclaredMethod("factTurn", double.class);
				turn.setAccessible(true);
				bosses.setSelectedItem("Vorkath");
				turns[0] = (int) turn.invoke(p, 1.0);
				// a plain redraw: the same fact
				turns[1] = (int) turn.invoke(p, 1.0);
				// a kill changed the expected count: the next fact
				turns[2] = (int) turn.invoke(p, 1.01);
				bosses.setSelectedItem("Zulrah");
				turns[3] = (int) turn.invoke(p, 2.0);
				// back to Vorkath: opening the page again moves it on
				bosses.setSelectedItem("Vorkath");
				turns[4] = (int) turn.invoke(p, 1.01);
				turns[5] = (int) turn.invoke(p, 1.01);
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		assertEquals(0, turns[0]);
		assertEquals(0, turns[1]);
		assertEquals(1, turns[2]);
		assertEquals(0, turns[3]);
		assertEquals(2, turns[4]);
		assertEquals(2, turns[5]);
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import org.junit.After;
import org.junit.Test;

/** The luck colour sets: Classic is unchanged, spooned stays green, and dry, on rate and spooned stay apart. */
public class PaletteSchemeTest
{
	private static final Color GREEN = new Color(46, 160, 67);
	private static final Color BLUE = new Color(40, 110, 200);

	@After
	public void back()
	{
		Palette.setScheme(LuckColours.CLASSIC, null, null);
	}

	private static double apart(Color a, Color b)
	{
		int r = a.getRed() - b.getRed();
		int g = a.getGreen() - b.getGreen();
		int bl = a.getBlue() - b.getBlue();
		return Math.sqrt(r * r + g * g + bl * bl);
	}

	@Test
	public void classicIsTheUsualRedYellowGreen()
	{
		Palette.setScheme(LuckColours.CLASSIC, new Color(1, 2, 3), new Color(4, 5, 6));
		assertEquals(new Color(170, 40, 30), Palette.luck(0));
		assertEquals(new Color(170, 150, 20), Palette.luck(0.5));
		assertEquals(GREEN, Palette.luck(1));
	}

	@Test
	public void colourBlindIsTheUsualOrangeGreyBlue()
	{
		Palette.setScheme(LuckColours.COLOUR_BLIND, null, null);
		assertEquals(new Color(220, 120, 20), Palette.luck(0));
		assertEquals(BLUE, Palette.luck(1));
		assertEquals(BLUE, Palette.good());
	}

	@Test
	public void everyReadySetKeepsDryOnRateAndSpoonedApart()
	{
		for (LuckColours s : LuckColours.values())
		{
			if (s == LuckColours.CUSTOM)
			{
				continue;
			}
			Palette.setScheme(s, null, null);
			Color dry = Palette.luck(0);
			Color mid = Palette.luck(0.5);
			Color spooned = Palette.luck(1);
			assertTrue(s + " dry vs on rate", apart(dry, mid) > 40);
			assertTrue(s + " on rate vs spooned", apart(mid, spooned) > 40);
			assertTrue(s + " dry vs spooned", apart(dry, spooned) > 40);
		}
	}

	@Test
	public void spoonedStaysGreenInEverySetExceptColourBlind()
	{
		for (LuckColours s : LuckColours.values())
		{
			Palette.setScheme(s, new Color(10, 10, 10), new Color(100, 100, 100));
			assertEquals(s.name(), s == LuckColours.COLOUR_BLIND ? BLUE : GREEN, Palette.luck(1));
		}
	}

	@Test
	public void customTakesYourDryAndOnRateColours()
	{
		Color dry = new Color(200, 0, 200);
		Color mid = new Color(0, 200, 200);
		Palette.setScheme(LuckColours.CUSTOM, dry, mid);
		assertEquals(dry, Palette.luck(0));
		assertEquals(mid, Palette.luck(0.5));
		assertEquals(GREEN, Palette.luck(1));
	}

	@Test
	public void unknownLuckIsStillGrey()
	{
		Palette.setScheme(LuckColours.MONO, null, null);
		assertNotEquals(GREEN, Palette.luck(Double.NaN));
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import java.awt.event.HierarchyEvent;
import javax.swing.SwingUtilities;
import org.junit.Test;

/** The panel's on-screen flag, which the plugin reads to decide on background work (audit F1). */
public class PanelOnScreenTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static final RaidSettings RAIDS = raid -> 0.03;

	private static ExpectedDropsPanel panel()
	{
		return new ExpectedDropsPanel(new Tracker(Bundled.catalog(new Gson())), null, () -> RAIDS, s -> -1, () -> { },
			() -> false, () -> { }, name -> 0L, () -> new ViewOptions(ItemView.TARGET_BARS, false, false, false, false, true));
	}

	private static void onSwing(Runnable r) throws Exception
	{
		SwingUtilities.invokeAndWait(r);
	}

	@Test
	public void followsOpeningAndClosingInTheSidebar() throws Exception
	{
		boolean[] seen = new boolean[3];
		onSwing(() ->
		{
			ExpectedDropsPanel p = panel();
			seen[0] = p.isOnScreen();
			p.onActivate();
			seen[1] = p.isOnScreen();
			p.onDeactivate();
			seen[2] = p.isOnScreen();
		});
		assertFalse("not on screen before it is ever opened", seen[0]);
		assertTrue(seen[1]);
		assertFalse(seen[2]);
	}

	@Test
	public void leavingTheScreenWithoutBeingDeactivatedClearsTheFlag() throws Exception
	{
		boolean[] seen = new boolean[2];
		onSwing(() ->
		{
			ExpectedDropsPanel p = panel();
			p.onActivate();
			seen[0] = p.isOnScreen();
			// taken off screen some other way (the sidebar closed, the window hidden): Swing says so
			p.dispatchEvent(new HierarchyEvent(p, HierarchyEvent.HIERARCHY_CHANGED, p, null, HierarchyEvent.SHOWING_CHANGED));
			seen[1] = p.isOnScreen();
		});
		assertTrue(seen[0]);
		assertFalse("the flag follows what Swing reports", seen[1]);
	}

	@Test
	public void readableFromAnotherThread() throws Exception
	{
		ExpectedDropsPanel[] p = new ExpectedDropsPanel[1];
		onSwing(() ->
		{
			p[0] = panel();
			p[0].onActivate();
		});
		// the client thread reads it while the Swing thread owns the panel
		boolean[] seen = new boolean[1];
		Thread t = new Thread(() -> seen[0] = p[0].isOnScreen());
		t.start();
		t.join();
		assertTrue(seen[0]);
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import com.onrate.service.AccountPrecompute;
import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseListener;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import org.junit.Test;

/** A click that changes the data drops numbers worked out before it; a plain redraw doesn't (audit F2). */
public class PanelSupersedeTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static final RaidSettings RAIDS = raid -> 0.03;

	private static final class Tasks
	{
		final List<Runnable> list = new ArrayList<>();

		synchronized void add(Runnable r)
		{
			list.add(r);
		}

		void runAll()
		{
			List<Runnable> now;
			synchronized (this)
			{
				now = new ArrayList<>(list);
				list.clear();
			}
			now.forEach(Runnable::run);
		}
	}

	private static JPopupMenu menuOf(Component c) throws Exception
	{
		for (MouseListener l : c.getMouseListeners())
		{
			if (!l.getClass().getName().startsWith("com.expecteddrops"))
			{
				continue;
			}
			for (java.lang.reflect.Field f : l.getClass().getDeclaredFields())
			{
				if (JPopupMenu.class.isAssignableFrom(f.getType()))
				{
					f.setAccessible(true);
					return (JPopupMenu) f.get(l);
				}
			}
		}
		return null;
	}

	private static JMenuItem entry(Component c, String text) throws Exception
	{
		JPopupMenu menu = menuOf(c);
		if (menu != null)
		{
			for (Component e : menu.getComponents())
			{
				if (e instanceof JMenuItem && text.equals(((JMenuItem) e).getText()))
				{
					return (JMenuItem) e;
				}
			}
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				JMenuItem found = entry(child, text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	private Tracker tracker;
	private Tasks worker;
	private Tasks swing;
	private AccountPrecompute pre;
	private ExpectedDropsPanel panel;

	private void setUpPanel()
	{
		tracker = new Tracker(Bundled.catalog(new Gson()));
		tracker.setSettings(RAIDS);
		tracker.onClogPage("Vorkath", Collections.singletonList("Vorkath kills: 500"), Collections.singletonMap("Vorkath's head", 9));
		worker = new Tasks();
		swing = new Tasks();
		pre = new AccountPrecompute(tracker, worker::add, swing::add, () -> true);
		panel = new ExpectedDropsPanel(tracker, null, () -> RAIDS, s -> -1, () -> { }, () -> false, () -> { },
			s -> 1_000_000L, () -> new ViewOptions(ItemView.TARGET_BARS, true, false, false, false, true));
		panel.setSize(225, 4000);
		panel.setPrecomputed(pre);
		panel.showBoss("Vorkath");
		panel.refresh();
	}

	@Test
	public void leavingAnItemOutDropsNumbersWorkedOutBefore() throws Exception
	{
		setUpPanel();
		List<String> drawn = new ArrayList<>();
		// a kill asked for the account; it is worked out and on its way to the Swing thread
		pre.request(RAIDS, null, () -> drawn.add("background"));
		worker.runAll();
		JMenuItem leaveOut = entry(panel, "Leave out of the calculations");
		assertNotNull(leaveOut);
		leaveOut.doClick();
		boolean anyLeftOut = false;
		for (com.onrate.engine.data.DropDefinition d : tracker.getCatalog().byName("Vorkath").getDrops())
		{
			anyLeftOut |= tracker.isLeftOut("Vorkath", d.getName());
		}
		assertTrue("the click changed the data", anyLeftOut);
		swing.runAll();
		assertTrue("numbers from before the click are never drawn", drawn.isEmpty());
	}

	@Test
	public void aPlainRedrawKeepsThePendingResult() throws Exception
	{
		setUpPanel();
		List<String> drawn = new ArrayList<>();
		pre.request(RAIDS, null, () -> drawn.add("background"));
		worker.runAll();
		// a redraw that changes no data (a tab, a setting the panel keeps): the kill's draw still comes
		panel.refresh();
		panel.showBoss(ExpectedDropsPanel.ACCOUNT);
		swing.runAll();
		assertEquals(Collections.singletonList("background"), drawn);
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.expecteddrops.ui.ExpectedDropsPanel.ProfileState;
import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import javax.swing.SwingUtilities;
import org.junit.Test;

/**
 * Until an account is loaded the panel says why (not logged in, loading, or loading failed) instead
 * of a new player's setup steps (audit H1 and its follow-up).
 */
public class PreLoginTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static final RaidSettings RAIDS = raid -> 0.03;

	/** The account page's note, its big word, and whether setup steps show, in this state. */
	private static Object[] shown(ProfileState... states) throws Exception
	{
		Object[] out = new Object[3];
		SwingUtilities.invokeAndWait(() ->
		{
			// the welcome guide is on, as for a new player
			ExpectedDropsPanel p = new ExpectedDropsPanel(new Tracker(Bundled.catalog(new Gson())), null, () -> RAIDS, s -> -1,
				() -> { }, () -> true, () -> { }, name -> 0L,
				() -> new ViewOptions(ItemView.TARGET_BARS, false, false, false, false, true));
			p.onActivate();
			for (ProfileState state : states)
			{
				p.setProfileState(state);
			}
			p.showBoss(ExpectedDropsPanel.ACCOUNT);
			out[0] = p.noteText();
			out[1] = p.verdictText();
			out[2] = p.isSetupShown();
		});
		return out;
	}

	@Test
	public void notLoggedInSaysToLogIn() throws Exception
	{
		Object[] s = shown(ProfileState.NOT_LOGGED_IN);
		assertTrue((String) s[0], ((String) s[0]).contains("Log in to see your account."));
		assertFalse("no setup steps before login", ((String) s[0]).contains("collection log"));
		assertEquals("Not logged in", s[1]);
		assertFalse("no welcome guide or checklist before login", (Boolean) s[2]);
	}

	@Test
	public void loadingSaysSo() throws Exception
	{
		Object[] s = shown(ProfileState.NOT_LOGGED_IN, ProfileState.LOADING);
		assertTrue((String) s[0], ((String) s[0]).contains("Loading your account"));
		assertFalse(((String) s[0]).contains("Log in"));
		assertEquals("Loading", s[1]);
		assertFalse((Boolean) s[2]);
	}

	@Test
	public void aFailedLoadNeverSaysLogIn() throws Exception
	{
		Object[] s = shown(ProfileState.LOADING, ProfileState.FAILED);
		assertTrue((String) s[0], ((String) s[0]).contains("couldn't load this account's saved data"));
		assertFalse((String) s[0], ((String) s[0]).contains("Log in to see"));
		assertEquals("Couldn't load", s[1]);
		assertFalse("no setup steps over data that didn't load", (Boolean) s[2]);
	}

	@Test
	public void afterLoadingTheSetupStepsAreBack() throws Exception
	{
		Object[] s = shown(ProfileState.NOT_LOGGED_IN, ProfileState.LOADING, ProfileState.LOADED);
		// a new account after login: the real setup instructions
		assertTrue((String) s[0], ((String) s[0]).contains("Open your collection log"));
		assertFalse(((String) s[0]).contains("Log in"));
		assertEquals("No kills yet", s[1]);
		assertTrue("welcome guide and checklist after login", (Boolean) s[2]);
	}

	@Test
	public void aPanelNobodyTellsShowsTheAccount() throws Exception
	{
		Object[] s = shown();
		assertEquals("No kills yet", s[1]);
	}
}

package com.expecteddrops.ui;

import com.expecteddrops.ExpectedDropsPlugin;
import com.onrate.engine.data.BossCatalog;
