		RaidInsights.Setup s = tracker.raidInsights("Tombs of Amascut", null).getSetups().get(0);
		assertEquals("Duo · level 300–349", ExpectedDropsPanel.setupName(
			tracker.stats("Tombs of Amascut", raid -> 0.03).getBoss(), s));
