import com.expecteddrops.ExpectedDropsPlugin;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.DropDefinition;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.JLabel;
import org.junit.Test;

/** "Copy my luck" in the footer: only on an account overview with a loaded boss. */
public class ShareLinkTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static final RaidSettings RAIDS = raid -> 0.03;

	private static BossCatalog catalog() throws Exception
	{
		try (Reader reader = com.onrate.engine.data.Bundled.reader("bosses.json"))
		{
			return BossCatalog.load(new Gson(), reader);
		}
	}

	/** A tracker with one boss loaded from its collection log page, or none loaded. */
	private static Tracker tracker(BossCatalog catalog, BossDefinition loaded)
	{
		Tracker tracker = new Tracker(catalog);
		tracker.setSettings(RAIDS);
		if (loaded != null)
		{
			List<String> counters = new ArrayList<>();
			for (String name : loaded.getKcNames())
			{
				counters.add(name + " kills: 200");
			}
			Map<String, Integer> items = new LinkedHashMap<>();
			for (DropDefinition drop : loaded.getDrops())
			{
				for (String name : drop.getAllNames())
				{
					items.put(name, 0);
				}
			}
			tracker.onClogPage(loaded.getClogPages().get(0), counters, items);
		}
		return tracker;
	}

	private static BossDefinition aBoss(BossCatalog catalog)
	{
		for (BossDefinition boss : catalog.getBosses())
		{
			if (!boss.getKcNames().isEmpty() && !boss.getClogPages().isEmpty() && !boss.getDrops().isEmpty())
			{
				return boss;
			}
		}
		throw new AssertionError("no boss to load");
	}

	private static ExpectedDropsPanel panel(Tracker tracker, String page) throws Exception
	{
		ExpectedDropsPanel panel = new ExpectedDropsPanel(tracker, null, () -> RAIDS, s -> -1, () -> { }, () -> false, () -> { },
			name -> 1_000_000L, () -> new ViewOptions(ItemView.TARGET_BARS, true, false, false, false, true));
		panel.showBoss(page);
		panel.refresh();
		return panel;
	}

	private static Object field(ExpectedDropsPanel panel, String name) throws Exception
	{
		Field f = ExpectedDropsPanel.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(panel);
	}

	@Test
	public void shownOnTheAccountOverviewOnceABossIsLoaded() throws Exception
	{
		BossCatalog catalog = catalog();
		ExpectedDropsPanel panel = panel(tracker(catalog, aBoss(catalog)), ExpectedDropsPanel.ACCOUNT);
		assertTrue(((JLabel) field(panel, "shareLink")).isVisible());
		assertTrue(((JLabel) field(panel, "shareSep")).isVisible());
		String text = (String) field(panel, "shareText");
		assertNotNull(text);
		assertTrue(text, text.startsWith("On Rate: "));
	}

	@Test
	public void hiddenWhenNothingIsLoadedYet() throws Exception
	{
		BossCatalog catalog = catalog();
		ExpectedDropsPanel panel = panel(tracker(catalog, null), ExpectedDropsPanel.ACCOUNT);
		assertFalse(((JLabel) field(panel, "shareLink")).isVisible());
		assertFalse(((JLabel) field(panel, "shareSep")).isVisible());
		assertNull(field(panel, "shareText"));
	}

	@Test
	public void hiddenOnABossPage() throws Exception
	{
		BossCatalog catalog = catalog();
		BossDefinition boss = aBoss(catalog);
		ExpectedDropsPanel panel = panel(tracker(catalog, boss), ExpectedDropsPanel.ACCOUNT);
		panel.showBoss(boss.getName());
		panel.refresh();
		assertFalse(((JLabel) field(panel, "shareLink")).isVisible());
		assertNull(field(panel, "shareText"));
	}
}

package com.expecteddrops.ui;

import com.onrate.engine.math.Verdict;

import com.onrate.engine.stats.AccountStats;
import com.onrate.engine.stats.ItemHighlight;
import com.onrate.engine.stats.RowStats;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The text "Copy my luck" puts on the clipboard. */
public class ShareTextTest
{
	private static RowStats row(String label, double expected, int received)
	{
		return new RowStats(label, null, 0.01, expected, received, false);
	}

	private static AccountStats account(RowStats total, RowStats... bossRows)
	{
		return new AccountStats(total, Arrays.asList(bossRows), new HashMap<>());
	}

	@Test
	public void nothingToShareBeforeABossIsLoaded()
	{
		assertNull(ShareText.account(null, true));
		assertNull(ShareText.account(account(row("Any", 0, 0)), true));
	}

	@Test
	public void firstLineUsesThePanelsWordsAndNumbers()
	{
		RowStats total = row("Any", 87.8, 80);
		String text = ShareText.account(account(total, row("Zulrah", 2, 1)), false);
		String first = text.split("\\R")[0];
		assertTrue(first, first.startsWith("On Rate: " + Verdict.labelOf(total.getLuck()) + " · 80 uniques, 87.8 expected"));
		assertTrue(first, first.contains(Texts.luckShort(total.getShares(), 80)));
	}

	@Test
	public void singularForOneUniqueAndOneBoss()
	{
		String text = ShareText.account(account(row("Any", 1.5, 1), row("Zulrah", 1.5, 1)), false);
		assertTrue(text, text.contains("1 unique, 1.50 expected"));
		assertTrue(text, text.endsWith("1 boss"));
	}

	@Test
	public void gpValueLineOnlyWhenTheSettingIsOnAndThereIsAValue()
	{
		AccountStats a = account(row("Any", 10, 12), row("Zulrah", 10, 12));
		a.setValue(1_230_000_000d, 4_000_000_000L, 0.995);
		String on = ShareText.account(a, true);
		assertTrue(on, on.contains("GP value: Extremely spooned · 4.00b got, 1.23b expected"));
		assertFalse(ShareText.account(a, false).contains("GP value"));

		AccountStats none = account(row("Any", 10, 12), row("Zulrah", 10, 12));
		assertFalse(ShareText.account(none, true).contains("GP value"));
	}

	@Test
	public void countsBosses()
	{
		String text = ShareText.account(account(row("Any", 5, 5), row("A", 1, 1), row("B", 1, 1), row("C", 1, 1)), false);
		assertTrue(text, text.endsWith("3 bosses"));
	}

	@Test
	public void luckiestItemOnlyWhenItIsPastSpooned()
	{
		RowStats bow = row("Twisted bow", 0.21, 2);
		RowStats dry = row("Dexterous prayer scroll", 1.49, 0);
		assertTrue(bow.getLuck() > 0.9);

		AccountStats a = account(row("Any", 10, 10), row("Chambers of Xeric", 10, 10));
		a.setItems(Arrays.asList(new ItemHighlight("Chambers of Xeric", dry), new ItemHighlight("Chambers of Xeric", bow)));
		String text = ShareText.account(a, false);
		assertTrue(text, text.contains("Luckiest: Twisted bow (Chambers of Xeric), " + Verdict.labelOf(bow.getLuck())));
		assertFalse(text, text.contains("Dexterous"));

		// only dry items, or items you don't have: no brag
		AccountStats b = account(row("Any", 10, 10), row("Chambers of Xeric", 10, 10));
		b.setItems(Collections.singletonList(new ItemHighlight("Chambers of Xeric", dry)));
		assertFalse(ShareText.account(b, false).contains("Luckiest"));
	}

	@Test
	public void threeLinesAtMostForTheMostCommonCase()
	{
		AccountStats a = account(row("Any", 10, 12), row("Zulrah", 10, 12));
		a.setValue(1_000_000d, 2_000_000L, 0.9);
		assertEquals(3, ShareText.account(a, true).split("\\R").length);
	}
}

package com.expecteddrops.ui;

import com.expecteddrops.ExpectedDropsPlugin;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import com.google.gson.Gson;
import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseListener;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.JMenu;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import org.junit.Test;

/** The right-click menu that judges a shared item on each boss separately, and back. */
public class SplitSharedMenuTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static Tracker tracker() throws Exception
	{
		try (Reader reader = com.onrate.engine.data.Bundled.reader("bosses.json"))
		{
			Tracker tracker = new Tracker(BossCatalog.load(new Gson(), reader));
			tracker.setSettings(raid -> 0.03);
			return tracker;
		}
	}

	private static ExpectedDropsPanel panel(Tracker tracker)
	{
		RaidSettings raids = raid -> 0.03;
		ExpectedDropsPanel panel = new ExpectedDropsPanel(tracker, null, () -> raids, s -> -1, () -> { }, () -> false, () -> { },
			s -> 1_000_000L, () -> new ViewOptions(ItemView.TARGET_BARS, true, false, false, false, true));
		panel.setSize(225, 4000);
		return panel;
	}

	private static JPopupMenu menuOf(Component c) throws Exception
	{
		for (MouseListener l : c.getMouseListeners())
		{
			if (!l.getClass().getName().startsWith("com.expecteddrops"))
			{
				continue;
			}
			for (java.lang.reflect.Field f : l.getClass().getDeclaredFields())
			{
				if (JPopupMenu.class.isAssignableFrom(f.getType()))
				{
					f.setAccessible(true);
					return (JPopupMenu) f.get(l);
				}
			}
		}
		return null;
	}

	/** The first menu entry (an item or a submenu) anywhere on the page with this text. */
	private static JMenuItem entry(Component c, String text) throws Exception
	{
		JPopupMenu menu = menuOf(c);
		if (menu != null)
		{
			for (Component e : menu.getComponents())
			{
				if (e instanceof JMenuItem && text.equals(((JMenuItem) e).getText()))
				{
					return (JMenuItem) e;
				}
			}
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				JMenuItem found = entry(child, text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	@Test
	public void olderCopiesGoToTheBossPickedAndCanComeBack() throws Exception
	{
		Tracker tracker = tracker();
		Map<String, Integer> items = new LinkedHashMap<>();
		items.put("Berserker ring", 2);
		items.put("Dragon axe", 3);
		tracker.onClogPage("Dagannoth Kings", Arrays.asList(
			"Dagannoth Rex kills: 436", "Dagannoth Prime kills: 10", "Dagannoth Supreme kills: 9"), items);
		tracker.onRollBaseline("Wintertodt", 200, 0);
		ExpectedDropsPanel panel = panel(tracker);
		panel.showBoss("Dagannoth Kings");
		panel.refresh();

		JMenu from = (JMenu) entry(panel, "Move all 3 older ones to");
		assertNotNull(from);
		List<String> bosses = new ArrayList<>();
		for (int i = 0; i < from.getItemCount(); i++)
		{
			bosses.add(from.getItem(i).getText());
		}
		assertEquals(Arrays.asList("Dagannoth Kings", "Wintertodt"), bosses);
		assertNotNull(entry(panel, "Split my 3 older ones between bosses..."));
		from.getItem(0).doClick();
		assertEquals("dragon axe", tracker.splitPoolOf("Dagannoth Kings", "Dragon axe"));

		// now a row of the Kings' own, with the way back on it
		panel.refresh();
		assertNull(entry(panel, "Move all 3 older ones to"));
		JMenuItem back = entry(panel, "Move it back to Shared with other bosses");
		assertNotNull(back);
		back.doClick();
		assertNull(tracker.splitPoolOf("Dagannoth Kings", "Dragon axe"));
	}

	@Test
	public void aVisageCanBeNotFromABoss() throws Exception
	{
		Tracker tracker = tracker();
		tracker.onClogPage("Vorkath", java.util.Collections.singletonList("Vorkath kills: 500"),
			java.util.Collections.singletonMap("Draconic visage", 1));
		ExpectedDropsPanel panel = panel(tracker);
		panel.showBoss("Vorkath");
		panel.refresh();
		JMenu from = (JMenu) entry(panel, "Move my older one to");
		assertNotNull(from);
		// King Black Dragon has no kills here, so only Vorkath and "not from a boss"
		assertEquals(2, from.getItemCount());
		assertEquals("Vorkath", from.getItem(0).getText());
		assertEquals("Not from a boss (other dragons and skeletal wyverns)", from.getItem(1).getText());
		from.getItem(1).doClick();
		assertEquals("draconic visage", tracker.splitPoolOf("Vorkath", "Draconic visage"));
		// split, but the one copy is no boss's: Vorkath has the row with none
		panel.refresh();
		assertNotNull(entry(panel, "Move it back to Shared with other bosses"));
	}
}

package com.expecteddrops.ui;

import com.onrate.engine.math.Poisson;

import java.util.Arrays;
import java.util.Collections;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The words under and behind each verdict. */
public class TextsTest
{
	@Test
	public void noneSaysHowManyHaveNone()
	{
		assertEquals("74% have none", Texts.luckShort(Poisson.shares(0, 0.30), 0));
		assertEquals("only 1 in 5 has none", Texts.luckShort(Poisson.shares(0, 1.65), 0));
		assertEquals(">99% have none", Texts.luckShort(Poisson.shares(0, 0.001), 0));
		assertEquals("74% of players have none by now, 26% have one or more", Texts.sharesLine(Poisson.shares(0, 0.30), 0));
	}

	@Test
	public void countsSayHowCommon()
	{
		// 4 of 5.67: 33% have this many or fewer
		assertEquals("1 in 3 as dry", Texts.luckShort(Poisson.shares(4, 5.67), 4));
		// 1 of 0.16: 15% have one or more
		assertEquals("1 in 7 as lucky", Texts.luckShort(Poisson.shares(1, 0.16), 1));
		// 2 of 1.65: the middle of the range
		assertEquals("about average", Texts.luckShort(Poisson.shares(2, 1.65), 2));
		assertEquals("18% of players have fewer, 15% as many, 67% more", Texts.sharesLine(Poisson.shares(4, 5.67), 4));
	}

	@Test
	public void valueLuckInWords()
	{
		assertEquals("1 in 6 as lucky", Texts.luckShort(0.83));
		assertEquals("1 in 3 as dry", Texts.luckShort(0.30));
		assertEquals("about average", Texts.luckShort(0.5));
		assertEquals("<1 in 10,000 as dry", Texts.luckShort(0.00001));
	}

	@Test
	public void shortLineFollowsTheVerdictBands()
	{
		// "On rate" (45% to 55%) is about average
		assertEquals("about average", Texts.luckShort(0.45));
		assertEquals("about average", Texts.luckShort(0.50));
		assertEquals("about average", Texts.luckShort(0.55));
		// a bit dry and a bit spooned say how common they are
		assertEquals("1 in 3 as dry", Texts.luckShort(0.35));
		assertEquals("1 in 3 as dry", Texts.luckShort(0.40));
		assertEquals("1 in 2 as dry", Texts.luckShort(0.44));
		assertEquals("1 in 2 as lucky", Texts.luckShort(0.56));
		assertEquals("1 in 3 as lucky", Texts.luckShort(0.60));
		assertEquals("1 in 3 as lucky", Texts.luckShort(0.65));
	}

	private static com.onrate.engine.stats.RowStats item(String name, double expected, int received)
	{
		return new com.onrate.engine.stats.RowStats(name, name, expected / 100, expected, received, false);
	}

	@Test
	public void onRateGetsOneNotableSentence()
	{
		// 1 of 4.0: 91% of players have more
		assertEquals("Driest: Magic fang, drier than 91% of players.",
