		for (ChartTime t : ChartTimes.compute(tracker, web, RAIDS, LadlorChart.bundled(new com.google.gson.Gson()), boss -> canFight(boss, 93)))
		{
			names.add(t.getName());
		}
		assertTrue(names.contains("Eternal boots"));
		assertTrue(names.contains("Occult necklace"));
	}

	@Test
	public void theFullChartHasItsSlayerAndCompletionItems()
	{
		List<String> names = new ArrayList<>();
		for (ChartTime t : chart())
		{
			names.add(t.getName());
		}
		for (String expected : new String[]{"Primordial boots", "Eternal boots", "Amulet of rancour", "Occult necklace", "Ferocious gloves",
			"Toxic blowpipe", "Necklace of rupture", "Masori body", "Masori mask", "Masori chaps", "Ancient icon",
			"Crystal body", "Crystal helm", "Crystal legs", "Bow of Faerdhinen"})
		{
			assertTrue(expected + " is on the chart", names.contains(expected));
		}
		// the chart's order: the boots before the rancour amulet, the amulet before the Doom items
		assertTrue(names.indexOf("Primordial boots") < names.indexOf("Amulet of rancour"));
		assertTrue(names.indexOf("Voidwaker") < names.indexOf("Necklace of rupture"));
		assertTrue(names.indexOf("Necklace of rupture") < names.indexOf("Toxic blowpipe"));
		assertTrue(names.indexOf("Ferocious gloves") < names.indexOf("Oathplate armour"));
		assertFalse(names.contains("Dizana's quiver"));
		assertFalse(names.contains("Infernal cape"));
		assertFalse(names.contains("Masori body (f)"));
		// crystal armour in the chart's order: body, helm, legs, then the bow
		assertTrue(names.indexOf("Crystal body") < names.indexOf("Crystal helm"));
		assertTrue(names.indexOf("Crystal helm") < names.indexOf("Crystal legs"));
		assertTrue(names.indexOf("Crystal legs") < names.indexOf("Bow of Faerdhinen"));
	}

	@Test
	public void theBlowpipeNeedsZulrahsFang()
	{
		ChartTime blowpipe = find("Toxic blowpipe");
		assertNotNull(blowpipe);
		assertEquals(drop("Zulrah", "Tanzanite fang").getSecondsPerDrop(), blowpipe.getSeconds(), 1e-6);
		sync("Zulrah", 300, "Tanzanite fang");
		assertNull(find("Toxic blowpipe"));
	}

	@Test
	public void theSlayerGatedChartItemsFollowTheirBossesLevels()
	{
		java.util.Map<String, Integer> level = new java.util.HashMap<>();
		level.put("Primordial boots", 91);
		level.put("Eternal boots", 91);
		level.put("Amulet of rancour", 92);
		level.put("Occult necklace", 93);
		level.put("Ferocious gloves", 95);
		for (java.util.Map.Entry<String, Integer> e : level.entrySet())
		{
			List<String> at = new ArrayList<>();
			for (ChartTime t : ChartTimes.compute(tracker, web, RAIDS, LadlorChart.bundled(new com.google.gson.Gson()), boss -> canFight(boss, e.getValue() - 1)))
			{
				at.add(t.getName());
			}
			assertFalse(e.getKey() + " is hidden one level short", at.contains(e.getKey()));
			at.clear();
			for (ChartTime t : ChartTimes.compute(tracker, web, RAIDS, LadlorChart.bundled(new com.google.gson.Gson()), boss -> canFight(boss, e.getValue())))
			{
				at.add(t.getName());
			}
			assertTrue(e.getKey() + " shows at its level", at.contains(e.getKey()));
		}
	}

	@Test
	public void crystalArmourIsCountedInSeeds()
	{
		// the body takes 3 crystal armour seeds, the legs 2, the helm 1
		ItemTime seed = drop("The Gauntlet", "Crystal armour seed");
		assertEquals(3 * seed.getSecondsPerDrop(), find("Crystal body").getSeconds(), 1e-6);
		assertEquals(2 * seed.getSecondsPerDrop(), find("Crystal legs").getSeconds(), 1e-6);
		assertEquals(seed.getSecondsPerDrop(), find("Crystal helm").getSeconds(), 1e-6);
		assertEquals("3 x Crystal armour seed", find("Crystal body").getParts().get(0).getLabel());
		assertEquals("wiki rate", find("Crystal body").getSourceTag());
	}

	@Test
	public void theSeedsYouHaveGoToTheChartItemsInOrder()
	{
		// 4 seeds obtained: the body (3) and the helm (1) are covered, the legs (2) are not
		sync("The Gauntlet", 214, new String[]{}, 4);
		assertNull(find("Crystal body"));
		assertNull(find("Crystal helm"));
		assertNotNull(find("Crystal legs"));
		assertEquals(2, find("Crystal legs").getParts().get(0).getMissing());
		// 5 seeds: one seed short on the legs
		sync("The Gauntlet", 214, new String[]{}, 5);
		assertEquals(1, find("Crystal legs").getParts().get(0).getMissing());
		ItemTime seed = drop("The Gauntlet", "Crystal armour seed");
		assertEquals(seed.getSecondsPerDrop(), find("Crystal legs").getSeconds(), 1e-6);
		// 2 seeds: not even the body
		sync("The Gauntlet", 214, new String[]{}, 2);
		assertEquals(1, find("Crystal body").getParts().get(0).getMissing());
		assertEquals(1, find("Crystal helm").getParts().get(0).getMissing());
		assertEquals(2, find("Crystal legs").getParts().get(0).getMissing());
		// 6: all of it
		sync("The Gauntlet", 214, new String[]{}, 6);
		assertNull(find("Crystal body"));
		assertNull(find("Crystal helm"));
		assertNull(find("Crystal legs"));
	}

	@Test
	public void theSameDropInSeveralChartItemsIsOneGrindInTheTotal()
	{
		List<ChartTime> items = new ArrayList<>();
		for (ChartTime t : chart())
		{
			if (t.getName().startsWith("Crystal"))
			{
				items.add(t);
			}
		}
		assertEquals(3, items.size());
		ItemTime seed = drop("The Gauntlet", "Crystal armour seed");
		ChartTimes.Total total = ChartTimes.total(items);
		// six copies of one drop: 6 / p kills, not three separate waits that happen to add to the same
		assertEquals(6 * seed.getSecondsPerDrop(), total.getSeconds(), 1.0);
	}

	@Test
	public void expectedKillsForSeveralCopies()
	{
		double p = 1 / 120.0;
		assertEquals(3 / p, ChartTimes.expectedKillsForAll(new double[]{p}, new int[]{3}), 1e-3);
		assertEquals(1 / p, ChartTimes.expectedKillsForAll(new double[]{p}, new int[]{1}), 1e-9);
		// two drops, one needed twice: checked against a simulation
		double p1 = 1 / 100.0;
		double p2 = 1 / 250.0;
		double exact = ChartTimes.expectedKillsForAll(new double[]{p1, p2}, new int[]{2, 1});
		java.util.Random random = new java.util.Random(99);
		double sum = 0;
		int runs = 200_000;
		for (int r = 0; r < runs; r++)
		{
			int a = 0;
			boolean b = false;
			int kills = 0;
			while (a < 2 || !b)
			{
				kills++;
				if (random.nextDouble() < p1)
				{
					a++;
				}
				if (random.nextDouble() < p2)
				{
					b = true;
				}
			}
			sum += kills;
		}
		assertEquals(sum / runs, exact, exact * 0.01);
		// more copies of anything takes longer
		assertTrue(exact > ChartTimes.expectedKillsForAll(new double[]{p1, p2}, new int[]{1, 1}));
	}
}

package com.onrate.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.onrate.engine.tracking.ChatTimes;
import org.junit.Test;

public class ChatTimesTest
{
	private static int millis(String message)
	{
		ChatTimes.Reading r = ChatTimes.read(message);
		assertNotNull(message, r);
		return r.getMillis();
	}

	@Test
	public void parsesTimes()
	{
		assertEquals(26 * 60_000 + 10_200, ChatTimes.parseMillis("26:10.20"));
		assertEquals(61_200, ChatTimes.parseMillis("1:01.2"));
		assertEquals(52_000, ChatTimes.parseMillis("0:52"));
		assertEquals(3_723_000, ChatTimes.parseMillis("1:02:03"));
		assertEquals(0, ChatTimes.parseMillis("abc"));
		assertEquals(0, ChatTimes.parseMillis("0:00"));
		assertEquals(0, ChatTimes.parseMillis(null));
	}

	@Test
	public void formatsTimes()
	{
		assertEquals("1:01.2", ChatTimes.format(61_200));
		assertEquals("26:10", ChatTimes.format(26 * 60_000 + 10_200));
		assertEquals("1:02:03", ChatTimes.format(3_723_000));
		assertEquals("0:52.0", ChatTimes.format(52_000));
		assertEquals("", ChatTimes.format(0));
	}

	@Test
	public void bossFightDuration()
	{
		assertEquals(61_200, millis("Fight duration: <col=ff0000>1:01.20</col>. Personal best: 0:55.80"));
		assertEquals(61_200, millis("Fight duration: <col=ff0000>1:01.20</col> (new personal best)"));
		assertEquals(ChatTimes.RANK_KILL, ChatTimes.read("Fight duration: 1:01.20").getRank());
	}

	@Test
	public void gauntletAndTempoross()
	{
		assertEquals(5 * 60_000 + 3_400, millis("Challenge duration: <col=ff0000>5:03.40</col>. Personal best: 4:50.00"));
		assertEquals(7 * 60_000 + 2_000, millis("Corrupted challenge duration: <col=ff0000>7:02.00</col> (new personal best)"));
		assertEquals(5 * 60_000 + 12_600, millis("Subdued in <col=ff0000>5:12.60</col>. Personal best: 4:40.20"));
	}

	@Test
	public void chambersRaid()
	{
		String message = "<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>3 players</col> Duration:</col> <col=ff0000>26:10.20</col> Personal best: </col><col=ff0000>25:00.00</col>";
		assertEquals(26 * 60_000 + 10_200, millis(message));
		assertEquals(ChatTimes.RANK_TOTAL, ChatTimes.read(message).getRank());
		assertEquals(18 * 60_000 + 59_000, millis("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>Solo</col> Duration:</col> <col=ff0000>18:59.00</col> (new personal best)</col>"));
	}

	@Test
	public void tombsCountsOnlyTheTotalTime()
	{
		// the challenge time leaves out the rooms around the fight: not a time we keep
		assertNull(ChatTimes.read("Tombs of Amascut: Expert Mode challenge completion time: <col=ff0000>31:35.40</col>. Personal best: 24:19.80"));
		ChatTimes.Reading total = ChatTimes.read("Tombs of Amascut: Expert Mode total completion time: <col=ff0000>36:00.00</col>");
		assertEquals(36 * 60_000, total.getMillis());
		assertEquals(ChatTimes.RANK_TOTAL, total.getRank());
	}

	@Test
	public void theatreAndArchiveTotals()
	{
		ChatTimes.Reading tob = ChatTimes.read("Theatre of Blood total completion time: <col=ff0000>23:50.40</col>. Personal best: 22:12.00");
		assertEquals(23 * 60_000 + 50_400, tob.getMillis());
		assertEquals(ChatTimes.RANK_TOTAL, tob.getRank());
		ChatTimes.Reading archive = ChatTimes.read("The Fractured Archive: Total completion time: <col=ff0000>12:00.00</col>. Personal best: 11:00.00");
		assertEquals(12 * 60_000, archive.getMillis());
		assertEquals(ChatTimes.RANK_TOTAL, archive.getRank());
	}

	@Test
	public void timesOfRoomsAndWavesAreNotTheKill()
	{
		assertNull(ChatTimes.read("Wave 'The Maiden of Sugadinti' (Normal Mode) complete!<br>Duration: <col=ff0000>1:41.40</col>"));
		assertNull(ChatTimes.read("Challenge complete: Apmeken. Duration: <col=ff0000>3:04.20</col>"));
		assertNull(ChatTimes.read("Your Zulrah kill count is: <col=ff0000>309</col>."));
		assertNull(ChatTimes.read("Nothing to see here"));
		assertNull(ChatTimes.read(null));
	}
}

package com.onrate.engine;

import com.onrate.engine.tracking.ClogPage;
import com.onrate.engine.tracking.ClogPage.Item;
import com.onrate.engine.tracking.ClogPage.Problem;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Reading a collection log page from plain values, no client needed. */
public class ClogPageTest
{
	private static final int OWNED = ClogPage.OBTAINED_OPACITY;
	private static final int FADED = 175;

	private static List<Item> vorkath()
	{
		return Arrays.asList(new Item("Vorkath's head", 7, OWNED), new Item("Draconic visage", 1, OWNED),
			new Item("Skeletal visage", 0, FADED), new Item("Vorki", 1, OWNED));
	}

	@Test
	public void normalPageStripsTagsAndReadsOwnedItems()
	{
		ClogPage.Result r = ClogPage.parse("<col=ff9040>Vorkath</col>",
			Arrays.asList("<col=ffffff>Vorkath kills: <col=ff9040>350</col>"), vorkath());
		assertNull(r.getProblem());
		assertEquals("Vorkath", r.getTitle());
		assertEquals(Collections.singletonList("Vorkath kills: 350"), r.getCounters());
		assertEquals(7, (int) r.getItems().get("Vorkath's head"));
		assertEquals(1, (int) r.getItems().get("Vorki"));
		assertFalse(r.isAllFaded());
	}

	@Test
	public void fadedItemsAreNotObtained()
	{
		ClogPage.Result r = ClogPage.parse("Vorkath", Collections.emptyList(), vorkath());
		assertEquals(0, (int) r.getItems().get("Skeletal visage"));
		// the quantity of a faded item is not trusted
		ClogPage.Result faded = ClogPage.parse("Vorkath", Collections.emptyList(),
			Collections.singletonList(new Item("Vorki", 5, FADED)));
		assertEquals(0, (int) faded.getItems().get("Vorki"));
	}

	@Test
	public void stacksKeepTheirQuantityAndOwnedItemsCountAtLeastOne()
	{
		ClogPage.Result r = ClogPage.parse("Zulrah", Collections.emptyList(), Arrays.asList(
			new Item("Zulrah's scales", 250, OWNED), new Item("Tanzanite fang", 0, OWNED)));
		assertEquals(250, (int) r.getItems().get("Zulrah's scales"));
		assertEquals(1, (int) r.getItems().get("Tanzanite fang"));
	}

	@Test
	public void emptyPageHasNoItems()
	{
		assertEquals(Problem.NO_ITEMS, ClogPage.parse("Vorkath", Collections.emptyList(), new ArrayList<>()).getProblem());
		assertEquals(Problem.NO_ITEMS, ClogPage.parse("Vorkath", Collections.emptyList(), null).getProblem());
		// items without a name can't be matched either
		assertEquals(Problem.NO_ITEMS, ClogPage.parse("Vorkath", Collections.emptyList(),
			Collections.singletonList(new Item("", 1, OWNED))).getProblem());
	}

	@Test
	public void missingOrEmptyHeaderHasNoTitle()
	{
		assertEquals(Problem.NO_TITLE, ClogPage.parse(null, Collections.emptyList(), vorkath()).getProblem());
		assertEquals(Problem.NO_TITLE, ClogPage.parse("", Collections.emptyList(), vorkath()).getProblem());
		assertEquals(Problem.NO_TITLE, ClogPage.parse("<col=ff9040></col>", Collections.emptyList(), vorkath()).getProblem());
	}

	@Test
	public void aTitleThatIsACounterMeansTheHeaderChanged()
	{
		assertEquals(Problem.TITLE_IS_A_COUNTER,
			ClogPage.parse("Vorkath kills: 1,234", Collections.emptyList(), vorkath()).getProblem());
		assertEquals(Problem.TITLE_IS_A_COUNTER,
			ClogPage.parse("<col=ffffff>Vorkath kills: <col=ff9040>350</col>", Collections.emptyList(), vorkath()).getProblem());
		// a real title with no number after a colon is fine
		assertNull(ClogPage.parse("Tombs of Amascut", Collections.emptyList(), vorkath()).getProblem());
	}

	@Test
	public void combinedPageKeepsEveryCounterInOrder()
	{
		ClogPage.Result r = ClogPage.parse("Dagannoth Kings", Arrays.asList(
			"Dagannoth Rex kills: 436", "", null, "Dagannoth Prime kills: 10", "Dagannoth Supreme kills: 9"),
			Arrays.asList(new Item("Berserker ring", 2, OWNED), new Item("Seers ring", 1, FADED)));
		assertNull(r.getProblem());
		assertEquals(Arrays.asList("Dagannoth Rex kills: 436", "Dagannoth Prime kills: 10", "Dagannoth Supreme kills: 9"),
			r.getCounters());
		assertEquals(Arrays.asList("Berserker ring", "Seers ring"), new ArrayList<>(r.getItems().keySet()));
	}

	@Test
	public void allFadedOnlyWhenEveryItemIsMissing()
	{
		assertTrue(ClogPage.parse("Vorkath", Collections.emptyList(), Arrays.asList(
			new Item("Vorkath's head", 0, FADED), new Item("Vorki", 0, FADED))).isAllFaded());
		assertFalse(ClogPage.parse("Vorkath", Collections.emptyList(), vorkath()).isAllFaded());
		assertFalse(ClogPage.parse("Vorkath", Collections.emptyList(), new ArrayList<>()).isAllFaded());
	}
}

package com.onrate.engine;

import com.onrate.engine.data.Bundled;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.KillTimes;
import com.onrate.engine.stats.ItemTime;
import com.onrate.engine.stats.ItemTimes;
import com.onrate.engine.stats.RaidChance;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.Tracker;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/** Average time to get each item: your own timed kills once there are enough, the estimate until then. */
public class ItemTimesTest
{
	private static final RaidSettings RAIDS = raid -> 0.03;
	private BossCatalog catalog;
	private Tracker tracker;
	private KillTimes web;
	private long now = 1_000_000;

	@Before
	public void setUp() throws Exception
	{
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			catalog = BossCatalog.load(new Gson(), reader);
		}
		web = KillTimes.bundled(new com.google.gson.Gson());
		tracker = new Tracker(catalog);
	}

	private ItemTime find(String boss, String label)
	{
		for (ItemTime t : ItemTimes.compute(tracker, web, RAIDS))
		{
			if (t.getBoss().equals(boss) && t.getLabel().equals(label))
			{
				return t;
			}
		}
		return null;
	}

	/** {@code n} Zulrah kills, each 100 seconds, an hour apart. */
	private void zulrahKills(int n, int from)
	{
		for (int i = 0; i < n; i++)
		{
			long at = now + (from + i) * 3_600_000L;
			tracker.onChatMessage("Your Zulrah kill count is: <col=ff0000>" + (from + i + 1) + "</col>.", at);
			tracker.onChatMessage("Fight duration: <col=ff0000>1:40.00</col>. Personal best: 0:55.80", at + 500);
		}
	}

	@Test
	public void theBundledFileHasTheBossesItPromises()
	{
		assertNotNull(web.forBoss("Zulrah", null));
		assertEquals(180.0, web.forBoss("Zulrah", null).getSecondsPerKill(), 1e-9);
		assertNotNull(web.forBoss("Chambers of Xeric", "Normal"));
		assertNull(web.forBoss("Chambers of Xeric", null));
		assertNull(web.forBoss("Brutus", null));
		assertTrue(web.doom().isAvailable());
		// every boss and part in the file is one the catalog has
		for (com.onrate.engine.data.BossDefinition boss : catalog.getBosses())
		{
			if (boss.hasParts())
			{
				for (String part : web.partsWithEstimate(boss.getName()))
				{
					assertTrue(boss.getName() + " / " + part, boss.getParts().stream().anyMatch(p -> p.getName().equals(part)));
				}
			}
		}
	}

	@Test
	public void noKillsYetUsesTheEstimateAndTheDropRate()
	{
		ItemTime fang = find("Zulrah", "Tanzanite fang");
		assertNotNull(fang);
		assertTrue(fang.isEstimated());
		// 20 an hour is 180 s a kill; 1 in 512 a kill
		assertEquals(180.0, fang.getSecondsPerKill(), 1e-9);
		assertEquals(512 * 180.0, fang.getSecondsPerDrop(), 1.0);
		assertEquals("kill", fang.getUnit());
		assertFalse(fang.isHave());
	}

	@Test
	public void ownAverageTakesOverAtTwentyTimedKills()
	{
		zulrahKills(19, 0);
		assertTrue(find("Zulrah", "Tanzanite fang").isEstimated());
		zulrahKills(1, 19);
		ItemTime fang = find("Zulrah", "Tanzanite fang");
		assertFalse(fang.isEstimated());
		assertEquals(100.0, fang.getSecondsPerKill(), 1e-6);
		assertEquals(512 * 100.0, fang.getSecondsPerDrop(), 1.0);
	}

	@Test
	public void raidsNeedOnlyFiveTimedRaids()
	{
		for (int i = 0; i < 4; i++)
		{
			coxRaid(i + 1);
		}
		assertTrue(find("Chambers of Xeric", "Twisted bow").isEstimated());
		coxRaid(5);
		ItemTime tbow = find("Chambers of Xeric", "Twisted bow");
		assertFalse(tbow.isEstimated());
		assertEquals("raid", tbow.getUnit());
		assertEquals(1500.0, tbow.getSecondsPerKill(), 1e-6);
		// the chance comes from your points: 25,000 of 25,000, 2 of 60 of the unique chance
		double unique = RaidChance.cox(25_000, 25_000);
		assertEquals(unique * 2 / 60, tbow.getChancePerKill(), 1e-9);
		assertEquals(1500.0 / (unique * 2 / 60), tbow.getSecondsPerDrop(), 1.0);
	}

	private void coxRaid(int kc)
	{
		long at = now + kc * 3_600_000L;
		tracker.onChatMessage("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>Solo</col> Duration:</col> <col=ff0000>25:00.00</col>", at);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>" + kc + "</col>.", at + 500);
		tracker.onRaidRecord(RaidRecord.cox(25_000, 25_000, 1), at + 1_000);
	}

	@Test
	public void aCombinedPageWeighsItsPartsByYourKills()
	{
		// Callisto is 25 an hour (144 s), Artio 52 an hour: only Callisto kills here
		for (int i = 1; i <= 3; i++)
		{
			tracker.onChatMessage("Your Callisto kill count is: <col=ff0000>" + i + "</col>.", now + i * 600_000L);
		}
		ItemTime hilt = find("Callisto and Artio", "Voidwaker hilt");
		assertNotNull(hilt);
		assertEquals(144.0, hilt.getSecondsPerKill(), 1e-6);
		assertTrue(hilt.isEstimated());
	}

	@Test
	public void aCombinedPageWithNoKillsAssumesItsFirstModeWithATime()
	{
		// the Tombs have a time only for expert mode
		ItemTime t = find("Tombs of Amascut", "Tumeken's shadow (uncharged)");
		assertNotNull(t);
		assertEquals(3600 / 1.75, t.getSecondsPerKill(), 1e-6);
		assertTrue(t.getBasis().contains("Expert Mode"));
	}

	@Test
	public void aBossWithNoFigureHasNoTimeUntilYouHaveYourOwn()
	{
		assertNull(find("Brutus", "Mooleta"));
		assertNull(find("Wintertodt", "Phoenix"));
	}

	@Test
	public void doomWithNoDelvesAssumesARunToDelveEight()
	{
		ItemTime treads = find("Doom of Mokhaiotl", "Avernic treads");
		assertNotNull(treads);
		assertEquals("run", treads.getUnit());
		assertTrue(treads.isEstimated());
		// 8 levels at 67.5 s plus a minute of banking; treads from level 4 at 1/1350, 1/810, 1/765, 1/720, 1/630
		double run = 8 * 67.5 + 60;
		double chance = 1 / 1350.0 + 1 / 810.0 + 1 / 765.0 + 1 / 720.0 + 1 / 630.0;
		assertEquals(run, treads.getSecondsPerKill(), 1e-6);
		assertEquals(run / chance, treads.getSecondsPerDrop(), 1.0);
		// cloth can drop from level 2, so it comes sooner than the treads
		assertTrue(find("Doom of Mokhaiotl", "Mokhaiotl cloth").getSecondsPerDrop() > 0);
	}

	@Test
	public void doomUsesTheDepthsYouReallyWent()
	{
		// 10 runs: all got to level 4, none deeper
		java.util.Map<Integer, Integer> levels = new java.util.LinkedHashMap<>();
		for (int l = 1; l <= 4; l++)
		{
			levels.put(l, 10);
		}
		tracker.onDelveScoreboard(levels);
		ItemTime treads = find("Doom of Mokhaiotl", "Avernic treads");
		assertNotNull(treads);
		assertEquals("delve", treads.getUnit());
		assertTrue(treads.isEstimated());
		// 40 delves at 67.5 s, plus a minute of banking for each of the 10 runs, over the 40 delves
		assertEquals(67.5 + 60.0 * 10 / 40, treads.getSecondsPerKill(), 1e-6);
		// only level 4 can drop treads: 10 rolls at 1/1350 over 40 delves
		assertEquals((10 / 1350.0) / 40, treads.getChancePerKill(), 1e-9);
		// a player who always goes deeper waits less per drop than one who stops at level 4
		java.util.Map<Integer, Integer> deeper = new java.util.LinkedHashMap<>();
		for (int l = 1; l <= 8; l++)
		{
			deeper.put(l, 10);
		}
		Tracker other = new Tracker(catalog);
		other.onDelveScoreboard(deeper);
		double shallow = treads.getSecondsPerDrop();
		for (ItemTime t : ItemTimes.compute(other, web, RAIDS))
		{
			if (t.getBoss().equals("Doom of Mokhaiotl") && t.getLabel().equals("Avernic treads"))
			{
				assertTrue(t.getSecondsPerDrop() < shallow);
			}
		}
	}

	@Test
	public void doomLevelTimesAreYoursOnceYouHaveTwentyOfThatLevel()
	{
		for (int i = 0; i < 20; i++)
		{
			tracker.onChatMessage("Delve level: 2 duration: <col=ff0000>1:00.00</col>", now + i * 600_000L);
		}
		ItemTime cloth = find("Doom of Mokhaiotl", "Mokhaiotl cloth");
		assertNotNull(cloth);
		assertFalse(cloth.isEstimated());
		assertEquals(60.0, cloth.getSecondsPerKill(), 1e-6);
		// 20 delves at level 2, 1 in 2500 each
		assertEquals(60.0 * 2500, cloth.getSecondsPerDrop(), 1.0);
	}

	@Test
	public void longTimesRead()
	{
		assertEquals("<1 min", ItemTime.formatLong(20));
		assertEquals("45 min", ItemTime.formatLong(45 * 60));
		assertEquals("3.3 h", ItemTime.formatLong(3.3 * 3600));
		assertEquals("145 h", ItemTime.formatLong(145 * 3600));
		assertEquals("-", ItemTime.formatLong(Double.NaN));
	}
}

package com.onrate.engine;

import com.onrate.engine.data.Bundled;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.tracking.HistoryRow;
import com.onrate.engine.tracking.KillEntry;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.TimeStats;
import com.onrate.engine.tracking.Tracker;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/** How long kills and raids took, read from the game's time messages. */
public class KillTimesTest
{
	private Tracker tracker;
	private long now = 1_000_000;

	@Before
	public void setUp() throws Exception
	{
		BossCatalog catalog;
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			catalog = BossCatalog.load(new Gson(), reader);
		}
		tracker = new Tracker(catalog);
	}

	private static String zulrahTime(String time)
	{
		return "Fight duration: <col=ff0000>" + time + "</col>. Personal best: 0:55.80";
	}

	private static String zulrahKc(int kc)
	{
		return "Your Zulrah kill count is: <col=ff0000>" + kc + "</col>.";
	}

	private KillEntry kill(String boss, int kc)
	{
		for (HistoryRow row : tracker.history(boss))
		{
			KillEntry k = row.getKill();
			if ((k.getPartKc() != null ? k.getPartKc() : k.getKc()) == kc)
			{
				return k;
			}
		}
		throw new AssertionError("no kill " + kc + " at " + boss);
	}

	@Test
	public void timeAfterTheKillCount()
	{
		tracker.onChatMessage(zulrahKc(10), now);
		assertEquals("Zulrah", tracker.onChatMessage(zulrahTime("1:01.20"), now + 600));
		assertEquals(61_200, (int) kill("Zulrah", 10).getDurationMillis());
	}

	@Test
	public void timeBeforeTheKillCount()
	{
		assertNull(tracker.onChatMessage(zulrahTime("1:01.20"), now));
		tracker.onChatMessage(zulrahKc(10), now + 600);
		assertEquals(61_200, (int) kill("Zulrah", 10).getDurationMillis());
	}

	@Test
	public void fastKillsKeepTheirOwnTimeWhicheverOrderTheMessagesCome()
	{
		// time first: each time waits for the kill after it, and must not land on the kill before
		tracker.onChatMessage(zulrahTime("0:40.20"), now);
		tracker.onChatMessage(zulrahKc(10), now + 600);
		tracker.onChatMessage(zulrahTime("0:45.60"), now + 10_000);
		tracker.onChatMessage(zulrahKc(11), now + 10_600);
		assertEquals(40_200, (int) kill("Zulrah", 10).getDurationMillis());
		assertEquals(45_600, (int) kill("Zulrah", 11).getDurationMillis());
		// time second
		tracker.onChatMessage(zulrahKc(12), now + 20_000);
		tracker.onChatMessage(zulrahTime("0:50.00"), now + 20_600);
		tracker.onChatMessage(zulrahKc(13), now + 30_000);
		tracker.onChatMessage(zulrahTime("0:52.80"), now + 30_600);
		assertEquals(50_000, (int) kill("Zulrah", 12).getDurationMillis());
		assertEquals(52_800, (int) kill("Zulrah", 13).getDurationMillis());
	}

	@Test
	public void aTimeWithNoKillNearItIsNotKept()
	{
		tracker.onChatMessage(zulrahTime("1:01.20"), now);
		// the next kill is minutes later: that time belonged to something else
		tracker.onChatMessage(zulrahKc(10), now + 5 * 60_000);
		assertNull(kill("Zulrah", 10).getDurationMillis());
	}

	@Test
	public void aBossWithoutTimeMessagesHasNoTime()
	{
		tracker.onChatMessage(zulrahKc(10), now);
		assertNull(kill("Zulrah", 10).getDurationMillis());
		assertNull(tracker.killTimes("Zulrah", null));
	}

	@Test
	public void timesOfRoomsAreNotTheKill()
	{
		tracker.onChatMessage("Wave 'The Maiden of Sugadinti' (Normal Mode) complete!<br>Duration: <col=ff0000>1:41.40</col>", now);
		tracker.onChatMessage(zulrahKc(10), now + 600);
		assertNull(kill("Zulrah", 10).getDurationMillis());
	}

	@Test
	public void chambersRaidTimeBeforeTheCompletionCountAndThePoints()
	{
		tracker.onChatMessage("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>3 players</col> Duration:</col> <col=ff0000>26:10.20</col> Personal best: </col><col=ff0000>25:00.00</col>", now);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>100</col>.", now + 600);
		tracker.onRaidRecord(RaidRecord.cox(24_000, 70_000, 3), now + 1_200);
		List<RaidRecord> raids = tracker.raidRecords("Chambers of Xeric");
		assertEquals(1, raids.size());
		assertEquals(26 * 60_000 + 10_200, raids.get(0).getDurationMillis());
		assertEquals(26 * 60_000 + 10_200, (int) kill("Chambers of Xeric", 100).getDurationMillis());
	}

	@Test
	public void timeMessagesFromFriendsChatNeverCountKills()
	{
		// the Chambers time arrives as a friends chat notification: only the time is read from it
		assertNull(tracker.onTimeMessage("Your Zulrah kill count is: <col=ff0000>10</col>.", now));
		assertTrue(tracker.history("Zulrah").isEmpty());
		tracker.onTimeMessage("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>3 players</col> Duration:</col> <col=ff0000>26:10.20</col>", now);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>100</col>.", now + 600);
		assertEquals(26 * 60_000 + 10_200, (int) kill("Chambers of Xeric", 100).getDurationMillis());
		// and after the count, as the message may come either side
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>101</col>.", now + 3_600_000);
		assertEquals("Chambers of Xeric", tracker.onTimeMessage("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>2 players</col> Duration:</col> <col=ff0000>25:00.00</col>", now + 3_600_500));
		assertEquals(25 * 60_000, (int) kill("Chambers of Xeric", 101).getDurationMillis());
	}

	@Test
	public void chambersRaidTimeAfterThePoints()
	{
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>100</col>.", now);
		tracker.onRaidRecord(RaidRecord.cox(24_000, 70_000, 3), now + 600);
		assertEquals(-1, tracker.raidRecords("Chambers of Xeric").get(0).getDurationMillis());
		tracker.onChatMessage("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>3 players</col> Duration:</col> <col=ff0000>26:10.20</col> (new personal best)</col>", now + 1_200);
		assertEquals(26 * 60_000 + 10_200, tracker.raidRecords("Chambers of Xeric").get(0).getDurationMillis());
		assertEquals(26 * 60_000 + 10_200, (int) kill("Chambers of Xeric", 100).getDurationMillis());
	}

	private static long[] sample(long when, int minutes)
	{
		return new long[]{when, minutes * 60_000L};
	}

	@Test
	public void importedRaidTimesCountAndAreNotAddedTwice()
	{
		java.util.List<long[]> samples = java.util.Arrays.asList(sample(10_000_000, 15), sample(20_000_000, 17), sample(30_000_000, 16));
		assertEquals(3, tracker.importRaidTimes("Chambers of Xeric", "Normal", samples));
		assertEquals(3, tracker.importedRaidTimes("Chambers of Xeric", null));
		TimeStats stats = tracker.killTimes("Chambers of Xeric", "Normal");
		assertEquals(3, stats.getCount());
		assertEquals(16 * 60_000, stats.getAverageMillis());
		assertEquals(16 * 60_000, stats.getLastMillis());
		// the same list again (every login): nothing is added
		assertEquals(0, tracker.importRaidTimes("Chambers of Xeric", "Normal", samples));
		assertEquals(3, tracker.killTimes("Chambers of Xeric", "Normal").getCount());
		// each raid mode on its own, and a boss that isn't a raid takes nothing
		assertNull(tracker.killTimes("Chambers of Xeric", "Challenge Mode"));
		assertEquals(3, tracker.killTimes("Chambers of Xeric", null).getCount());
		assertEquals(0, tracker.importRaidTimes("Zulrah", "Normal", samples));
		assertEquals(0, tracker.importRaidTimes("Chambers of Xeric", "Normal", null));
		assertEquals(0, tracker.importRaidTimes("Chambers of Xeric", "Normal", java.util.Collections.singletonList(new long[]{0, 5})));
	}

	@Test
	public void importedRaidIsNotCountedAgainWhenOnRateTimedItItself()
	{
		long done = System.currentTimeMillis();
		tracker.onChatMessage("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>Solo</col> Duration:</col> <col=ff0000>18:00.00</col>", done);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>100</col>.", done + 600);
		assertEquals(1, tracker.killTimes("Chambers of Xeric", "Normal").getCount());
		// the other plugin saw the same raid a few seconds apart, and an earlier one On Rate never saw
		assertEquals(2, tracker.importRaidTimes("Chambers of Xeric", "Normal",
			java.util.Arrays.asList(new long[]{done + 15_000, 18 * 60_000L + 5_000}, sample(done - 86_400_000, 20))));
		TimeStats stats = tracker.killTimes("Chambers of Xeric", "Normal");
		assertEquals(2, stats.getCount());
		// On Rate's own time is used for the raid it saw, the other plugin's for the older one
		assertEquals(19 * 60_000, stats.getAverageMillis());
		assertEquals(18 * 60_000, stats.getLastMillis());
	}

	@Test
	public void importedTimeFillsARaidOnRateSawWithoutATime()
	{
		long done = System.currentTimeMillis();
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>100</col>.", done);
		tracker.onRaidRecord(RaidRecord.cox(24_000, 70_000, 3), done + 600);
		assertNull(tracker.killTimes("Chambers of Xeric", "Normal"));
		tracker.importRaidTimes("Chambers of Xeric", "Normal", java.util.Collections.singletonList(new long[]{done + 30_000, 21 * 60_000L}));
		assertEquals(21 * 60_000, (int) kill("Chambers of Xeric", 100).getDurationMillis());
		assertEquals(21 * 60_000, tracker.raidRecords("Chambers of Xeric").get(0).getDurationMillis());
		assertEquals(1, tracker.killTimes("Chambers of Xeric", "Normal").getCount());
	}

	@Test
	public void importedTimesSurviveSavingAndLoading()
	{
		tracker.importRaidTimes("Chambers of Xeric", "Normal", java.util.Collections.singletonList(sample(10_000_000, 15)));
		Gson gson = new Gson();
		com.onrate.engine.tracking.SaveData data = tracker.saveData(gson::toJson);
		Tracker restored = new Tracker(tracker.getCatalog());
		restored.setState(gson.fromJson(data.progress, com.onrate.engine.tracking.TrackerState.class));
		assertEquals(1, restored.killTimes("Chambers of Xeric", "Normal").getCount());
		assertEquals(1, restored.importedRaidTimes("Chambers of Xeric", "Normal"));
	}

	@Test
	public void raidModesKeepTheirOwnTimes()
	{
		tracker.onChatMessage("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>Solo</col> Duration:</col> <col=ff0000>40:00.00</col>", now);
		tracker.onChatMessage("Your completed Chambers of Xeric Challenge Mode count is: <col=ff0000>20</col>.", now + 600);
		tracker.onChatMessage("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>3 players</col> Duration:</col> <col=ff0000>26:00.00</col>", now + 3_600_000);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>100</col>.", now + 3_600_600);
		assertEquals(40 * 60_000, (int) kill("Chambers of Xeric", 20).getDurationMillis());
		assertEquals(26 * 60_000, (int) kill("Chambers of Xeric", 100).getDurationMillis());
		assertEquals(26 * 60_000, tracker.killTimes("Chambers of Xeric", "Normal").getBestMillis());
		assertEquals(40 * 60_000, tracker.killTimes("Chambers of Xeric", "Challenge Mode").getBestMillis());
	}

	@Test
	public void tombsKeepsOnlyTheTotalTimeWhicheverComesFirst()
	{
		tracker.onChatMessage("Tombs of Amascut: Expert Mode challenge completion time: <col=ff0000>31:35.40</col>.", now);
		tracker.onChatMessage("Tombs of Amascut: Expert Mode total completion time: <col=ff0000>36:00.00</col>.", now + 100);
		tracker.onChatMessage("Your completed Tombs of Amascut: Expert Mode count is: <col=ff0000>50</col>.", now + 600);
		assertEquals(36 * 60_000, (int) kill("Tombs of Amascut", 50).getDurationMillis());
		// the other way round
		tracker.onChatMessage("Tombs of Amascut: Expert Mode total completion time: <col=ff0000>37:00.00</col>.", now + 3_600_000);
		tracker.onChatMessage("Tombs of Amascut: Expert Mode challenge completion time: <col=ff0000>30:00.00</col>.", now + 3_600_100);
		tracker.onChatMessage("Your completed Tombs of Amascut: Expert Mode count is: <col=ff0000>51</col>.", now + 3_600_600);
		assertEquals(37 * 60_000, (int) kill("Tombs of Amascut", 51).getDurationMillis());
		// a raid with only the challenge time has no time at all
		tracker.onChatMessage("Tombs of Amascut: Expert Mode challenge completion time: <col=ff0000>30:00.00</col>.", now + 7_200_000);
		tracker.onChatMessage("Your completed Tombs of Amascut: Expert Mode count is: <col=ff0000>52</col>.", now + 7_200_600);
		assertNull(kill("Tombs of Amascut", 52).getDurationMillis());
	}

	@Test
	public void doomDelvesCarryTheirOwnTime()
	{
		tracker.onChatMessage("Delve level: 3 duration: <col=ff0000>1:52.20</col>", now);
		tracker.onChatMessage("Delve level: 8+ (12) duration: <col=ff0000>2:05.00</col>", now + 600_000);
		List<HistoryRow> history = tracker.history("Doom of Mokhaiotl");
		assertEquals(2, history.size());
		assertEquals(125_000, (int) history.get(0).getKill().getDurationMillis());
		assertEquals(112_200, (int) history.get(1).getKill().getDurationMillis());
	}

	@Test
	public void timeStatsFromTheKillsThatHaveATime()
	{
		int[] seconds = {70, 50, 60, 100};
		for (int i = 0; i < seconds.length; i++)
		{
			long at = now + i * 600_000L;
			tracker.onChatMessage(zulrahKc(10 + i), at);
			tracker.onChatMessage(zulrahTime(String.format("%d:%02d.00", seconds[i] / 60, seconds[i] % 60)), at + 500);
		}
		// one kill with no time must not count
		tracker.onChatMessage(zulrahKc(14), now + 10 * 600_000L);
		TimeStats stats = tracker.killTimes("Zulrah", null);
		assertNotNull(stats);
		assertEquals(4, stats.getCount());
		assertEquals(50_000, stats.getBestMillis());
		assertEquals(70_000, stats.getAverageMillis());
		assertEquals(65_000, stats.getMedianMillis());
		assertEquals(100_000, stats.getLastMillis());
	}

	@Test
	public void olderSavesWithoutATimeStillLoad()
	{
		List<KillEntry> kills = new Gson().fromJson("[{\"k\":5,\"t\":1000},{\"k\":6,\"t\":2000,\"du\":61200}]",
			new com.google.gson.reflect.TypeToken<List<KillEntry>>()
			{
			}.getType());
		assertNull(kills.get(0).getDurationMillis());
		assertEquals(61_200, (int) kills.get(1).getDurationMillis());
		RaidRecord record = new Gson().fromJson("{\"family\":\"cox\",\"personalPoints\":1000,\"teamSize\":2}", RaidRecord.class);
		assertEquals(-1, record.getDurationMillis());
		// and the time survives a round trip
		RaidRecord timed = new Gson().fromJson(new Gson().toJson(RaidRecord.cox(1, 2, 3)), RaidRecord.class);
		assertEquals(-1, timed.getDurationMillis());
		assertTrue(new Gson().toJson(kills.get(1)).contains("\"du\":61200"));
	}
}

package com.onrate.engine;

import com.onrate.engine.data.Bundled;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.KillTimes;
import com.onrate.engine.data.LadlorChart;
import com.onrate.engine.stats.ChartTime;
import com.onrate.engine.stats.ChartTimes;
import com.onrate.engine.stats.ItemTime;
import com.onrate.engine.stats.ItemTimes;
import com.onrate.engine.stats.OathplateShards;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/** Yama's oathplate shards: another way to the pieces, shown in the hovers. */
public class OathplateShardsTest
{
	private static final RaidSettings RAIDS = raid -> 0.03;
	private BossCatalog catalog;
	private Tracker tracker;

	@Before
	public void setUp() throws Exception
	{
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			catalog = BossCatalog.load(new Gson(), reader);
		}
		tracker = new Tracker(catalog);
		tracker.setSettings(RAIDS);
	}

	@Test
	public void onePieceWithShardsAgreesWithTheMathsDoneByHand()
	{
		// 450 shards are in hand after ceil(450 / 0.8075) = 558 kills: until then only the drop can give the piece,
		// so the expected kills are (1 - (1 - p)^558) / p
		double p = 1 / 600.0;
		double byHand = (1 - Math.pow(1 - p, 558)) / p;
		assertEquals(byHand, OathplateShards.expectedKills(new double[]{p}), 8);
		assertTrue(byHand > 350 && byHand < 380);
	}

	@Test
	public void shardsSaveKillsAndTheAnswerDoesNotChange()
	{
		double[] three = {1 / 600.0, 1 / 600.0, 1 / 600.0};
		double with = OathplateShards.expectedKills(three);
		double without = ChartTimes.expectedKillsForAll(three);
		assertTrue(with < without);
		assertTrue(with > 200);
		assertEquals(with, OathplateShards.expectedKills(three), 0);
		assertEquals(0, OathplateShards.expectedKills(new double[0]), 0);
		// a piece alone saves more than a piece in a set of three, in kills per piece
		assertTrue(OathplateShards.expectedKills(new double[]{1 / 600.0}) < 600);
	}

	@Test
	public void theHoverSaysWhatShardsAre()
	{
		String text = OathplateShards.describe(new double[]{1 / 600.0, 1 / 600.0}, 360);
		assertTrue(text, text.contains("Oathplate shards"));
		assertTrue(text, text.contains("450"));
		assertTrue(text, text.contains("2,520 crushed infernal shale"));
		assertTrue(text, text.contains("83 Smithing"));
		assertTrue(text, text.contains("all 2 missing pieces"));
		assertTrue(text, text.contains(" h)") || text.contains(" min)"));
		assertTrue(OathplateShards.describe(new double[]{1 / 600.0}, 360).contains("this piece"));
		// without a time per kill only kills are given
		assertFalse(OathplateShards.describe(new double[]{1 / 600.0}, Double.NaN).contains(" h)"));
	}

	@Test
	public void theChartItemShowsTheShardRoute()
	{
		ChartTime oathplate = null;
		for (ChartTime t : ChartTimes.compute(tracker, KillTimes.bundled(new com.google.gson.Gson()), RAIDS, LadlorChart.bundled(new com.google.gson.Gson())))
		{
			if (t.getName().equals("Oathplate armour"))
			{
				oathplate = t;
			}
			else
			{
				assertNull(t.getName() + " has no second route", t.getRoute());
			}
		}
		assertNotNull(oathplate);
		assertNotNull(oathplate.getRoute());
		assertTrue(oathplate.getRoute().contains("all 3 missing pieces"));
		// the headline time is still from drops alone
		assertEquals(600 * (1 + 1 / 2.0 + 1 / 3.0) * 360, oathplate.getSeconds(), 1.0);
	}

	@Test
	public void withTwoPiecesHadItTalksOfThePieceLeft()
	{
		BossDefinition yama = catalog.byName("Yama");
		List<String> counters = new ArrayList<>();
		for (String name : yama.getKcNames())
		{
			counters.add(name + " kills: 40");
		}
		java.util.Map<String, Integer> have = new java.util.HashMap<>();
		have.put("Oathplate helm", 1);
		have.put("Oathplate chest", 1);
		tracker.onClogPage(yama.getClogPages().get(0), counters, have);
		for (ChartTime t : ChartTimes.compute(tracker, KillTimes.bundled(new com.google.gson.Gson()), RAIDS, LadlorChart.bundled(new com.google.gson.Gson())))
		{
			if (t.getName().equals("Oathplate armour"))
			{
				// it recounts for the piece left and says how many you have
				assertTrue(t.getRoute(), t.getRoute().startsWith("You have 2 of 3 pieces."));
				assertTrue(t.getRoute(), t.getRoute().contains("the piece you are missing"));
				return;
			}
		}
		throw new AssertionError("Oathplate armour should still be on the chart");
	}

	@Test
	public void yamasPiecesCarryTheHintAndNothingElseDoes()
	{
		for (ItemTime t : ItemTimes.compute(tracker, KillTimes.bundled(new com.google.gson.Gson()), RAIDS))
		{
			boolean oathplate = t.getBoss().equals("Yama") && t.getIconItem().startsWith("Oathplate ");
			if (oathplate)
			{
				assertNotNull(t.getIconItem(), t.getHint());
				assertTrue(t.getHint().contains("Oathplate shards"));
			}
			else
			{
				assertNull(t.getBoss() + " / " + t.getIconItem(), t.getHint());
			}
		}
	}

	@Test
	public void theRouteIsRecountedAsYouGetPieces()
	{
		BossDefinition yama = catalog.byName("Yama");
		List<String> counters = new ArrayList<>();
		for (String name : yama.getKcNames())
		{
			counters.add(name + " kills: 40");
		}
		double[] kills = new double[3];
		String[][] had = {{}, {"Oathplate helm"}, {"Oathplate helm", "Oathplate chest"}};
		for (int i = 0; i < had.length; i++)
		{
			Tracker t = new Tracker(catalog);
			t.setSettings(RAIDS);
			java.util.Map<String, Integer> have = new java.util.HashMap<>();
			for (String piece : had[i])
			{
				have.put(piece, 1);
			}
			t.onClogPage(yama.getClogPages().get(0), counters, have);
			for (ChartTime c : ChartTimes.compute(t, KillTimes.bundled(new com.google.gson.Gson()), RAIDS, LadlorChart.bundled(new com.google.gson.Gson())))
			{
				if (c.getName().equals("Oathplate armour"))
				{
					String route = c.getRoute();
					assertTrue(route, i == 0 ? !route.startsWith("You have") : route.startsWith("You have " + i + " of 3 pieces."));
					java.util.regex.Matcher m = java.util.regex.Pattern.compile("takes about ([\\d,]+) kills").matcher(route);
					assertTrue(route, m.find());
					kills[i] = Double.parseDouble(m.group(1).replace(",", ""));
				}
			}
		}
		// fewer pieces missing: fewer kills
		assertTrue(kills[0] > kills[1] && kills[1] > kills[2]);
	}
}

package com.onrate.engine;

import com.onrate.engine.stats.RaidChance;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Raid formulas from the OSRS Wiki (Ancient chest; Chest (Tombs of Amascut)). */
public class RaidChanceTest
{
	@Test
	public void toaPetHasItsOwnLevelScaling()
	{
		// wiki: 1% per (350,000 - 700 x level); full up to 400, a third above, at most 550
		assertEquals(140_000, RaidChance.toaPetPointsPerPercent(300), 1e-9);
		assertEquals(70_000, RaidChance.toaPetPointsPerPercent(400), 1e-9);
		assertEquals(350_000 - 700 * (400 + 100 / 3.0), RaidChance.toaPetPointsPerPercent(500), 1e-6);
		assertEquals(RaidChance.toaPetPointsPerPercent(550), RaidChance.toaPetPointsPerPercent(600), 1e-9);
		// at level 400 the pet is about 1/19 of the purple chance, not 1/30
		double ratio = RaidChance.toaPet(30_000, 0, 0, 1, 400) / RaidChance.toa(30_000, 0, 0, 1, 400);
		assertEquals(3_700 / 70_000.0, ratio, 1e-9);
	}

	@Test
	public void coxIsOnePercentPer8676Points()
	{
		assertEquals(0.01, RaidChance.cox(8_676, 8_676), 1e-12);
		assertEquals(30_000 / 867_600.0, RaidChance.cox(30_000, 30_000), 1e-12);
	}

	@Test
	public void coxRollIsCappedAt570kAndRollsAgain()
	{
		assertEquals(0.657, RaidChance.coxTeamUniques(570_000), 0.0005);
		// 130,000 more points roll for a second unique
		assertEquals((570_000 + 130_000) / 867_600.0, RaidChance.coxTeamUniques(700_000), 1e-12);
		// at most six rolls
		assertEquals(RaidChance.coxTeamUniques(6 * 570_000), RaidChance.coxTeamUniques(9_000_000), 1e-12);
	}

	@Test
	public void coxShareIsYourShareOfThePoints()
	{
		assertEquals(RaidChance.coxTeamUniques(100_000) / 4, RaidChance.cox(25_000, 100_000), 1e-12);
		assertTrue(Double.isNaN(RaidChance.cox(0, 100_000)));
	}

	@Test
	public void toaScaledRaidLevel()
	{
		assertEquals(300, RaidChance.toaScaledLevel(300), 1e-12);
		assertEquals(340, RaidChance.toaScaledLevel(400), 1e-12);
		assertEquals(350, RaidChance.toaScaledLevel(430), 1e-12);
		assertEquals(360, RaidChance.toaScaledLevel(490), 1e-12);
	}

	@Test
	public void toaWikiExampleLevel400()
	{
		// "at raid level 400, the chance is 1% per 3,700 points"
		assertEquals(3_700, RaidChance.toaPointsPerPercent(400), 1e-9);
		assertEquals(0.05, RaidChance.toa(18_500, 0, 0, 1, 400), 1e-12);
	}

	@Test
	public void toaIsCappedAt55Percent()
	{
		// a solo raid can't reach the cap (64,000 points at most), a big team can
		assertTrue(RaidChance.toa(59_000, 1_500, 0, 1, 600) < 0.55);
		assertEquals(0.55, RaidChance.toaTeamChance(200_000, 600), 1e-12);
		assertEquals(0.55 / 5, RaidChance.toa(40_000, 0, 200_000, 5, 600), 1e-12);
		assertEquals(0.55, RaidChance.toa(170_000, 0, 0, 8, 600), 1e-12);
	}

	@Test
	public void toaSoloIncludesPuzzlePoints()
	{
		assertEquals(10_500 / (10_500 - 20 * 150.0) / 100, RaidChance.toa(9_000, 1_500, 0, 1, 150), 1e-12);
	}

	@Test
	public void toaTeamWithoutTotalUsesYourOwnPoints()
	{
		// below the cap, your share of the team chance is your points over the points per percent
		assertEquals(20_000 / 3_700.0 / 100, RaidChance.toa(20_000, 1_500, 0, 4, 400), 1e-12);
		assertEquals(RaidChance.toa(20_000, 0, 60_000, 4, 400), RaidChance.toa(20_000, 1_500, 0, 4, 400), 1e-12);
	}

	@Test
	public void toaUnknownPointsFallBack()
	{
		assertTrue(Double.isNaN(RaidChance.toa(0, 0, 0, 1, 300)));
		assertTrue(Double.isNaN(RaidChance.toa(10_000, 0, 0, 1, -1)));
	}

	@Test
	public void toaLowLevelItems()
	{
		assertEquals(1.0, RaidChance.toaLevelFactor(149, 50), 0);
		assertEquals(1 / 50.0, RaidChance.toaLevelFactor(149, 150), 1e-12);
		assertEquals(1.0, RaidChance.toaLevelFactor(150, 150), 0);
		assertEquals(1.0, RaidChance.toaLevelFactor(0, null), 0);
	}

	@Test
	public void fracturedArchiveTeamBonusAddsFourPercentPerPlayerBeyondTwo()
	{
		// Jagex's loot post: 3-man x1.04, 5-man x1.12, 8-man x1.24 (added, not compounded)
		assertEquals(1.0, RaidChance.tfaTeamMultiplier(1), 1e-12);
		assertEquals(1.0, RaidChance.tfaTeamMultiplier(2), 1e-12);
		assertEquals(1.04, RaidChance.tfaTeamMultiplier(3), 1e-12);
		assertEquals(1.12, RaidChance.tfaTeamMultiplier(5), 1e-12);
		assertEquals(1.24, RaidChance.tfaTeamMultiplier(8), 1e-12);
		assertEquals(1.24, RaidChance.tfaTeamMultiplier(12), 1e-12);
		// the wiki's 8-man team chance: 8.86%
		assertEquals(0.0886, RaidChance.tfa(700, 8, RaidChance.TFA_BASE_CHANCE), 0.00005);
	}

	@Test
	public void fracturedArchiveSplitsTheUniqueByContribution()
	{
		double base = RaidChance.TFA_BASE_CHANCE;
		// a duo with even damage: 1 in 14 for the team, half each
		assertEquals(1 / 28.0, RaidChance.tfaEven(2, 0, base), 1e-12);
		assertEquals(1 / 14.0, RaidChance.tfaEven(1, 0, base), 1e-12);
		// 30% of the contribution is 30% of the team's purples
		assertEquals(0.3 / 14, RaidChance.tfa(0.3 * 700, 2, base), 1e-12);
		// a four with even damage: 1.08 / 14 for the team, a quarter each
		assertEquals(1.08 / 14 / 4, RaidChance.tfaEven(4, 0, base), 1e-12);
		assertTrue(Double.isNaN(RaidChance.tfa(-1, 2, base)));
		assertEquals(base, RaidChance.tfa(900, 2, base), 1e-12);
	}

	@Test
	public void fracturedArchiveDeathTakesTenPercentOfExpectedContribution()
	{
		// "In a duo, your expected contribution is 350 out of 700, so a death would subtract 35"
		assertEquals(350, RaidChance.tfaExpectedContribution(2), 1e-12);
		assertEquals(315, RaidChance.tfaContributionAfterDeaths(350, 2, 1), 1e-12);
		// the same 35 whoever carried more damage
		assertEquals(565, RaidChance.tfaContributionAfterDeaths(600, 2, 1), 1e-12);
		assertEquals(0, RaidChance.tfaContributionAfterDeaths(20, 2, 1), 1e-12);
		// unknown deaths count as none
		assertEquals(350, RaidChance.tfaContributionAfterDeaths(350, 2, -1), 1e-12);
		assertEquals(315 / 700.0 / 14, RaidChance.tfaEven(2, 1, RaidChance.TFA_BASE_CHANCE), 1e-12);
	}
}

