			assertTrue(catalog.isUntracked(item));
		}
		Map<String, Integer> hydra = new LinkedHashMap<>();
		hydra.put("Dragon thrownaxe", 1500);
		hydra.put("Dragon knife", 1500);
		hydra.put("Hydra's claw", 1);
