	@Test
	public void cappedLuckMatchesOnceItems()
	{
		// a cap of 1 is the same as "have it or not"
		assertEquals(Poisson.chanceAtLeastOne(2.0), Poisson.expectedCapped(2.0, 1), 1e-12);
		double chance = Poisson.chanceAtLeastOne(2.0);
		// having it when 86% of players do is average, not lucky (tie-aware)
		assertEquals(0.5, Luck.ofCapped(1, 2.0, 1), 1e-12);
		// not having it: only the 14% without one are this dry or drier
		assertEquals(1 - chance, Luck.ofCapped(0, 2.0, 1), 1e-12);
		// E[min(X, 2)] = P(X >= 1) + P(X >= 2)
		double p0 = Math.exp(-2.0);
		double p1 = 2.0 * p0;
		assertEquals((1 - p0) + (1 - p0 - p1), Poisson.expectedCapped(2.0, 2), 1e-12);
	}

