	}

	@Test
	public void bigTeamsShareOneRow()
	{
		assertEquals(0, RaidInsights.teamRow(0));
		assertEquals(5, RaidInsights.teamRow(5));
		assertEquals(RaidInsights.TEAM_CAP, RaidInsights.teamRow(RaidInsights.TEAM_CAP));
