	private static ImportedRaid imported(String part, int kc, long when, int minutes, int team, int points, int total, String unique)
	{
		return new ImportedRaid(part, kc, when, minutes < 0 ? -1 : minutes * 60_000L, team, points, total, -1, unique);
	}

	@Test
	public void importedRaidsAreSavedWithTheirPointsAndShowInTheSections()
	{
		List<ImportedRaid> raids = new java.util.ArrayList<>();
		for (int kc = 1; kc <= 5; kc++)
		{
			raids.add(imported("Normal", kc, kc * 3_600_000L, 30, 1, 43_380, 43_380, kc == 3 ? "Twisted bow" : null));
		}
		assertEquals(5, tracker.importRaids(COX, raids));

		List<RaidRecord> saved = tracker.raidRecords(COX);
		assertEquals(5, saved.size());
		assertEquals(3, saved.get(2).getKc());
		assertEquals("Normal", saved.get(2).getPart());
		assertEquals(30 * 60_000, saved.get(2).getDurationMillis());
		// their purple chance comes from their points, like a raid On Rate saw
		assertEquals(5, tracker.measuredRaids(COX, "Normal"));
		RaidInsights insights = tracker.raidInsights(COX, null);
		assertEquals(0.10, insights.getSetups().get(0).getChancePerHour(), 1e-9);
		List<RaidInsights.Point> points = insights.getPoints("Normal");
		assertTrue(points.get(2).isPurple());
		assertEquals(Collections.singletonList("Twisted bow"), points.get(2).getUniques());
		assertFalse(points.get(1).isPurple());
	}

	@Test
	public void aRaidOnRateSawItselfIsNotImportedAgain()
	{
		RaidRecord own = cox(52_100, 52_100, 1, 31);
		List<ImportedRaid> raids = new java.util.ArrayList<>();
		raids.add(imported("Normal", 1, now - 1000, 40, 2, 10_000, 20_000, "Dragon claws"));
		raids.add(imported("Normal", 2, now + 3_600_000, 30, 1, 30_000, 30_000, null));
		assertEquals(1, tracker.importRaids(COX, raids));
		// importing the same list again adds nothing
		assertEquals(0, tracker.importRaids(COX, raids));

		List<RaidRecord> saved = tracker.raidRecords(COX);
		assertEquals(2, saved.size());
		assertSame(own, saved.get(0));
		assertEquals(52_100, saved.get(0).getPersonalPoints());
		// the unique Raid Data Tracker saw still names the purple of On Rate's own record
		assertEquals(Collections.singletonList("Dragon claws"), tracker.raidInsights(COX, null).getPoints("Normal").get(0).getUniques());
	}

	@Test
	public void aCompletionCountThatRunsBackwardsIsSkipped()
	{
		List<ImportedRaid> raids = new java.util.ArrayList<>();
		raids.add(imported("Normal", 10, 1_000, 30, 1, 30_000, 30_000, null));
		raids.add(imported("Normal", 9, 2_000, 30, 1, 30_000, 30_000, null));
		raids.add(imported("Normal", 11, 3_000, 30, 1, 30_000, 30_000, null));
		// another mode has its own count
		raids.add(imported("Challenge Mode", 2, 2_500, 50, 1, 40_000, 40_000, null));
		// a mode this raid doesn't have, and a raid without points
		raids.add(imported("Hard Mode", 3, 2_600, 50, 1, 40_000, 40_000, null));
		raids.add(imported("Normal", 12, 4_000, 30, 1, 0, 0, null));
		assertEquals(3, tracker.importRaids(COX, raids));
		List<RaidRecord> saved = tracker.raidRecords(COX);
		assertEquals(10, saved.get(0).getKc());
		assertEquals("Challenge Mode", saved.get(1).getPart());
		assertEquals(11, saved.get(2).getKc());
	}

	@Test
	public void importedRaidsGoInTheirPlaceByDate()
	{
		RaidRecord own = cox(30_000, 30_000, 1, 30);
		List<ImportedRaid> raids = new java.util.ArrayList<>();
		raids.add(imported("Normal", 5, now + 7_200_000, 30, 1, 30_000, 30_000, null));
		raids.add(imported("Normal", 0 + 2, 1_000, 30, 1, 30_000, 30_000, null));
		tracker.importRaids(COX, raids);
		List<RaidRecord> saved = tracker.raidRecords(COX);
		assertEquals(3, saved.size());
		assertEquals(2, saved.get(0).getKc());
		assertSame(own, saved.get(1));
		assertEquals(5, saved.get(2).getKc());
	}

	@Test
	public void tombsRaidsOnlyShowInTheSectionsAndDontChangeTheSavedRaids()
	{
		// one raid On Rate saw itself; Raid Data Tracker has the same raid a few seconds later
		RaidRecord own = toa(26_595, 3, 225, 40);
		List<ImportedRaid> raids = new java.util.ArrayList<>();
		raids.add(new ImportedRaid("Normal", 40, now + 5_000, 2_410_000L, 3, 26_595, 26_596, 225, null));
		raids.add(new ImportedRaid("Expert Mode", 11, now - 86_400_000L, 2_200_000L, 1, 30_000, 30_000, 300, "Osmumten's fang"));
		raids.add(new ImportedRaid("Normal", 12, now - 3 * 86_400_000L, -1, 2, 20_000, 40_000, 240, null));
		// nothing is saved: Tombs counts in those files can't be placed among your raids
		assertEquals(0, tracker.importRaids(TOA, raids));
		assertEquals(1, tracker.raidRecords(TOA).size());
		assertSame(own, tracker.raidRecords(TOA).get(0));

		RaidInsights insights = tracker.raidInsights(TOA, null);
		int raidsInSetups = 0;
		for (RaidInsights.Setup s : insights.getSetups())
		{
			raidsInSetups += s.getRaids();
		}
		// your own raid once (not again from the other plugin), plus the two other raids
		assertEquals(3, raidsInSetups);
		RaidInsights.Point expert = insights.getPoints("Expert Mode").get(0);
		assertEquals(0, expert.getRaid().getKc());
		assertEquals(Collections.singletonList("Osmumten's fang"), expert.getUniques());
		// the older raid comes first on the graph
		assertEquals(240, insights.getPoints("Normal").get(0).getRaid().getRaidLevel());

		// importing again replaces the list instead of adding it twice
		tracker.importRaids(TOA, raids);
		int again = 0;
		for (RaidInsights.Setup s : tracker.raidInsights(TOA, null).getSetups())
		{
			again += s.getRaids();
		}
		assertEquals(3, again);
	}

	private RaidRecord coxScaled(int points, int scale, int players, int minutes)
	{
		RaidRecord r = RaidRecord.cox(points, points * scale, scale, players);
		r.durationMillis = minutes * 60_000;
		now += 3_600_000;
		tracker.onRaidRecord(r, now);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>" + (++coxKc) + "</col>.", now + 1000);
		return r;
	}

	@Test
	public void aScaledRaidARealTeamAndAnUnknownOneAreSeparateSetups()
	{
		coxScaled(30_000, 3, 1, 40);
		coxScaled(20_000, 3, 3, 25);
		// saved before the players were counted: was it a trio or a scaled raid?
		cox(20_000, 60_000, 3, 25);

		List<RaidInsights.Setup> setups = tracker.raidInsights(COX, null).getSetups();
		assertEquals(3, setups.size());
		java.util.Set<Integer> players = new java.util.HashSet<>();
		for (RaidInsights.Setup s : setups)
		{
			assertEquals(3, s.getTeam());
			players.add(s.getPlayers());
		}
		assertEquals(new java.util.HashSet<>(java.util.Arrays.asList(1, 3, -1)), players);
		// and three lines of personal bests
		assertEquals(3, tracker.raidInsights(COX, null).getBests().size());
		// grouped by team, they stay apart; grouped by mode alone, together
		assertEquals(3, tracker.raidInsights(COX, null).getSetups(RaidInsights.BY_TEAM).size());
		assertEquals(1, tracker.raidInsights(COX, null).getSetups(RaidInsights.BY_CHOICE).size());
	}

	@Test
	public void soloRaidsAndOtherRaidsAreNeverScaled()
	{
		cox(30_000, 30_000, 1, 30);
		toa(10_000, 3, 300, 40);
		assertEquals(1, tracker.raidInsights(COX, null).getSetups().get(0).getPlayers());
		assertEquals(3, tracker.raidInsights(TOA, null).getSetups().get(0).getPlayers());
	}

	@Test
	public void playersAreOnlySavedWhenKnownSoOldSavesStayTheSame()
	{
		Gson gson = new Gson();
		// a raid without the count is written exactly as before
		assertFalse(gson.toJson(RaidRecord.cox(30_000, 90_000, 3)).contains("players"));
		RaidRecord scaled = RaidRecord.cox(30_000, 90_000, 3, 1);
		String json = gson.toJson(scaled);
		assertTrue(json.contains("\"players\":1"));
		assertEquals(Integer.valueOf(1), gson.fromJson(json, RaidRecord.class).players);
		// an old save has no players field: it loads as unknown
		RaidRecord old = gson.fromJson("{\"family\":\"cox\",\"part\":\"Normal\",\"kc\":241,\"personalPoints\":10102,"
			+ "\"teamPoints\":37189,\"teamSize\":2,\"raidLevel\":-1,\"durationMillis\":1301400}", RaidRecord.class);
		assertNull(old.players);
		assertEquals(2, old.teamSize);
		// 0 players counted is no count
		assertNull(RaidRecord.cox(30_000, 90_000, 3, 0).players);
	}
}

package com.onrate.game;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.expecteddrops.ExpectedDropsConfig;
import com.expecteddrops.DuoMode;
import org.junit.Test;

public class ConfigRaidSettingsTest
{
	private static ExpectedDropsConfig config(DuoMode titans, int soloKills, int tobTeam)
	{
		return new ExpectedDropsConfig()
		{
			@Override
			public DuoMode royalTitansMode()
			{
				return titans;
			}

			@Override
			public int royalTitansSoloKills()
			{
				return soloKills;
			}

			@Override
			public int tobTeamSize()
			{
				return tobTeam;
			}
		};
	}

	@Test
	public void defaultsAreTheOnesPlayersAlwaysHad()
	{
		ConfigRaidSettings s = new ConfigRaidSettings(new ExpectedDropsConfig()
		{
		});
		assertEquals(0.035, s.uniqueChance("cox"), 1e-12);
		assertEquals(0.066, s.uniqueChance("coxCm"), 1e-12);
		assertEquals(0.11 / 4, s.uniqueChance("tob"), 1e-12);
		assertEquals(0.13 / 4, s.uniqueChance("tobHm"), 1e-12);
		assertEquals(0.0075, s.uniqueChance("toaEntry"), 1e-12);
		assertEquals(0.025, s.uniqueChance("toa"), 1e-12);
		assertEquals(0.05, s.uniqueChance("toaExpert"), 1e-12);
		assertEquals(0, s.uniqueChance("nothing"), 0);
		// a duo with no deaths: 1 in 14 for the team, an even half each
		assertEquals(1 / 28.0, s.uniqueChance("fractured"), 1e-12);
	}

	@Test
	public void teamSizesAreClamped()
	{
		assertEquals(5, new ConfigRaidSettings(config(DuoMode.DUO, 0, 99)).teamSize("tob"));
		assertEquals(1, new ConfigRaidSettings(config(DuoMode.DUO, 0, -3)).teamSize("tobHm"));
		assertEquals(1, new ConfigRaidSettings(config(DuoMode.DUO, 0, 4)).teamSize("cox"));
	}

	@Test
	public void duoKillsHalveTheShareAndSoloKillsKeepIt()
	{
		assertEquals(0.5, new ConfigRaidSettings(config(DuoMode.DUO, 0, 4)).contribution("royalTitans", 100), 1e-12);
		assertEquals(1.0, new ConfigRaidSettings(config(DuoMode.SOLO, 0, 4)).contribution("royalTitans", 100), 1e-12);
		// 30 solo, 70 duo: (30 + 35) / 100
		assertEquals(0.65, new ConfigRaidSettings(config(DuoMode.MIXED, 30, 4)).contribution("royalTitans", 100), 1e-12);
		assertEquals(1.0, new ConfigRaidSettings(config(DuoMode.DUO, 0, 4)).contribution("nex", 100), 1e-12);
		assertEquals(1.0, new ConfigRaidSettings(config(DuoMode.DUO, 0, 4)).contribution("royalTitans", 0), 1e-12);
	}

	@Test
	public void notesSayWhatIsAssumedAndWhereToChangeIt()
	{
		assertNull(new ConfigRaidSettings(config(DuoMode.DUO, 0, 4)).contributionNote("nex", 10));
		assertNotNull(new ConfigRaidSettings(config(DuoMode.DUO, 0, 4)).contributionNote("royalTitans", 10));
	}

	/** A tracker that saw {@code n} Chambers raids at these points and {@code n} Theatre raids of three. */
	private static com.onrate.engine.tracking.Tracker raided(int n) throws Exception
	{
		com.onrate.engine.tracking.Tracker t;
		try (java.io.Reader reader = com.onrate.engine.data.Bundled.reader("bosses.json"))
		{
			t = new com.onrate.engine.tracking.Tracker(com.onrate.engine.data.BossCatalog.load(new com.google.gson.Gson(), reader));
		}
		long now = 10_000_000;
		for (int i = 1; i <= n; i++)
		{
			now += 3_600_000;
			t.onRaidRecord(com.onrate.engine.tracking.RaidRecord.cox(43_380, 100_000, 3), now);
			t.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>" + i + "</col>.", now + 1000);
			now += 3_600_000;
			t.onRaidRecord(com.onrate.engine.tracking.RaidRecord.tob(3, 0, 0, false), now);
			t.onChatMessage("Your completed Theatre of Blood count is: <col=ff0000>" + i + "</col>.", now + 1000);
		}
		return t;
	}

	@Test
	public void settingsLeftAsTheyCameUseYourRecordedRaids() throws Exception
	{
		com.onrate.engine.tracking.Tracker t = raided(10);
		ConfigRaidSettings s = new ConfigRaidSettings(new ExpectedDropsConfig()
		{
		}, t::raidHabits);
		// 43,380 points is 5%
		assertEquals(0.05, s.uniqueChance("cox"), 1e-9);
		assertEquals(10, s.learnedRaids("cox"));
		// Theatre of Blood: the team chance stays, split over your usual team of three
		assertEquals(3, s.teamSize("tob"));
		assertEquals(0.11 / 3, s.uniqueChance("tob"), 1e-12);
		// modes without enough raids keep the setting
		assertEquals(0.066, s.uniqueChance("coxCm"), 1e-12);
		assertEquals(0, s.learnedRaids("coxCm"));
	}

	@Test
	public void aChangedSettingWins() throws Exception
	{
		com.onrate.engine.tracking.Tracker t = raided(10);
		ConfigRaidSettings s = new ConfigRaidSettings(new ExpectedDropsConfig()
		{
			@Override
			public double coxUniqueChance()
			{
				return 2.0;
			}

			@Override
			public int tobTeamSize()
			{
				return 5;
			}
		}, t::raidHabits);
		assertEquals(0.02, s.uniqueChance("cox"), 1e-12);
		assertEquals(0, s.learnedRaids("cox"));
		assertEquals(5, s.teamSize("tob"));
	}

	@Test
	public void fewerThanTenRaidsUseTheDefaults() throws Exception
	{
		com.onrate.engine.tracking.Tracker t = raided(9);
		ConfigRaidSettings s = new ConfigRaidSettings(new ExpectedDropsConfig()
		{
		}, t::raidHabits);
		assertEquals(0.035, s.uniqueChance("cox"), 1e-12);
		assertEquals(4, s.teamSize("tob"));
	}
}

package com.onrate.game;

import static org.junit.Assert.assertEquals;

import com.onrate.game.LootTrackerStatus.State;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.loottracker.LootTrackerPlugin;
import org.junit.Test;

/** Whether RuneLite's Loot Tracker is on, as the panel's note needs it (audit C3). */
public class LootTrackerStatusTest
{
	private final Plugin lootTracker = new LootTrackerPlugin();
	private final Plugin other = new Plugin()
	{
	};

	@Test
	public void enabledWhenThePluginManagerSaysSo()
	{
		assertEquals(State.ENABLED, LootTrackerStatus.of(Arrays.asList(other, lootTracker), p -> true));
	}

	@Test
	public void disabledWhenThePluginManagerSaysSo()
	{
		// only the Loot Tracker's own answer counts, not another plugin's
		assertEquals(State.DISABLED, LootTrackerStatus.of(Arrays.asList(other, lootTracker), p -> p != lootTracker));
	}

	@Test
	public void unknownWhenItCantBeTold()
	{
		// no plugin manager (yet)
		assertEquals(State.UNKNOWN, LootTrackerStatus.of(null));
		// the plugins aren't loaded, or the Loot Tracker isn't among them (startup, or removed)
		assertEquals(State.UNKNOWN, LootTrackerStatus.of(null, p -> false));
		assertEquals(State.UNKNOWN, LootTrackerStatus.of(Collections.emptyList(), p -> false));
		List<Plugin> withoutIt = Collections.singletonList(other);
		assertEquals(State.UNKNOWN, LootTrackerStatus.of(withoutIt, p -> false));
		// the check itself fails
		assertEquals(State.UNKNOWN, LootTrackerStatus.of(Collections.singletonList(lootTracker), p ->
		{
			throw new IllegalStateException("no config yet");
		}));
	}

	@Test
	public void recognisesOnlyTheLootTracker()
	{
		assertEquals(true, LootTrackerStatus.isLootTracker(lootTracker));
		assertEquals(false, LootTrackerStatus.isLootTracker(other));
		assertEquals(false, LootTrackerStatus.isLootTracker(null));
	}
}

package com.onrate.game;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.raids.RaidDataImport;
import com.onrate.engine.tracking.Tracker;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.config.RuneScapeProfileType;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** Raid Data Tracker times are only ever added to the profile they were read for (audit F4). */
public class RaidTimesImportTest
{
	private static final long ME = 123456789L;

	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	/** Runs handed-over tasks only when the test says so: the worker, or the client thread. */
	private static final class Tasks
	{
		final List<Runnable> list = new ArrayList<>();

		synchronized void add(Runnable r)
		{
			list.add(r);
		}

		void runAll()
		{
			List<Runnable> now;
			synchronized (this)
			{
				now = new ArrayList<>(list);
				list.clear();
			}
			now.forEach(Runnable::run);
		}
	}

	private Tasks worker;
	private Tasks clientThread;
	private AtomicReference<String> loaded;
	private RaidTimesImport importer;
	private Tracker tracker;
	private List<String> changed;
	private Supplier<RaidDataImport.Times> read;

	@Before
	public void setUp() throws IOException
	{
		worker = new Tasks();
		clientThread = new Tasks();
		loaded = new AtomicReference<>("A");
		importer = new RaidTimesImport(worker::add, clientThread::add, loaded::get);
		tracker = new Tracker(Bundled.catalog(new Gson()));
		changed = new ArrayList<>();
		// two Chambers raids of this account in Raid Data Tracker's log
		File root = tmp.newFolder("raid-data tracker");
		File dir = new File(root, "cox");
		assertTrue(dir.mkdirs());
		Files.write(new File(dir, "raid_tracker_data.log").toPath(), String.join("\n",
			"{\"accountHash\":" + ME + ",\"raidComplete\":true,\"date\":1000000,\"challengeMode\":false,\"raidTime\":1500}",
			"{\"accountHash\":" + ME + ",\"raidComplete\":true,\"date\":2000000,\"challengeMode\":false,\"raidTime\":1800}")
			.getBytes(StandardCharsets.UTF_8));
		read = () -> RaidDataImport.read(net.runelite.client.util.Filepath.Unchecked.getRooted(root.toPath()), ME);
	}

	private int imported()
	{
		return tracker.importedRaidTimes("Chambers of Xeric", null);
	}

	@Test
	public void addedWhenTheSameProfileIsStillLoaded()
	{
		importer.start("A", read, tracker, changed::add);
		assertEquals("nothing happens on the client thread before the files are read", 0, imported());
		worker.runAll();
		assertEquals("nothing is added on the worker thread", 0, imported());
		clientThread.runAll();
		assertEquals(2, imported());
		assertEquals(Collections.singletonList("Chambers of Xeric"), changed);
	}

	@Test
	public void droppedWhenAnotherAccountWasLoadedMeanwhile()
	{
		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		// A logs out and B logs in before the times reach the client thread; the tracker now holds B
		loaded.set("B");
		clientThread.runAll();
		assertEquals(0, imported());
		assertTrue(changed.isEmpty());
	}

	@Test
	public void droppedWhenTheSameAccountMovedToALeaguesProfile()
	{
		importer.start("main", read, tracker, changed::add);
		loaded.set("leagues");
		worker.runAll();
		clientThread.runAll();
		assertEquals(0, imported());
		assertTrue(changed.isEmpty());
	}

	@Test
	public void onlyAStandardProfileTakesImports()
	{
		List<RuneScapeProfile> profiles = Arrays.asList(
			new RuneScapeProfile("Me", RuneScapeProfileType.STANDARD, ME, "main"),
			new RuneScapeProfile("Me", RuneScapeProfileType.RAGING_ECHOES_LEAGUE, ME, "leagues"),
			new RuneScapeProfile("Me", RuneScapeProfileType.DEADMAN, ME, "dmm"));
		assertTrue(RaidTimesImport.importsInto("main", profiles));
		assertFalse("the log can't tell Leagues raids from the main game's", RaidTimesImport.importsInto("leagues", profiles));
		assertFalse(RaidTimesImport.importsInto("dmm", profiles));
		assertFalse("an unknown profile takes nothing", RaidTimesImport.importsInto("other", profiles));
		assertFalse(RaidTimesImport.importsInto(null, profiles));
	}

	@Test
	public void nothingIsAddedOnceThePluginHasStopped()
	{
		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		importer.stop();
		clientThread.runAll();
		assertEquals(0, imported());
		assertTrue(changed.isEmpty());

		// and a read still in progress at shutdown never reaches the client thread
		RaidTimesImport other = new RaidTimesImport(worker::add, clientThread::add, loaded::get);
		other.start("A", read, tracker, changed::add);
		other.stop();
		worker.runAll();
		assertTrue(clientThread.list.isEmpty());
		assertEquals(0, imported());
	}

	@Test
	public void timesAlreadyThereAreNotAddedAgain()
	{
		// one of the two raids was imported before
		tracker.importRaidTimes("Chambers of Xeric", "Normal", Collections.singletonList(new long[]{1000000, 1500_000}));
		assertEquals(1, imported());
		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		clientThread.runAll();
		assertEquals(2, imported());
	}

	@Test
	public void importingTwiceAddsEachTimeOnce()
	{
		// RuneLite loads on login and again when the profile is announced: two imports may overlap
		importer.start("A", read, tracker, changed::add);
		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		clientThread.runAll();
		assertEquals(2, imported());
		assertEquals("only the import that added times reports a change", 1, changed.size());

		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		clientThread.runAll();
		assertEquals(2, imported());
		assertEquals(1, changed.size());
	}
}

package com.onrate.game;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class TeamSpotterTest
{
	@Test
	public void knowsWhichNpcsAreGroupBosses()
	{
		assertEquals("nex", TeamSpotter.fightOf("Nex"));
		assertEquals("yama", TeamSpotter.fightOf("Yama"));
		assertEquals("hueycoatl", TeamSpotter.fightOf("The Hueycoatl"));
		assertEquals("hueycoatl", TeamSpotter.fightOf("Hueycoatl"));
		assertEquals("hueycoatl", TeamSpotter.fightOf("Hueycoatl tail"));
		assertEquals("corporeal beast", TeamSpotter.fightOf("Corporeal Beast"));
		// names that only contain one
		assertNull(TeamSpotter.fightOf("Nexling"));
		assertNull(TeamSpotter.fightOf("Zalcano"));
		assertNull(TeamSpotter.fightOf("Vorkath"));
		assertNull(TeamSpotter.fightOf(null));
	}

	@Test
	public void onlyPlayersWhoHitTheBossCount()
	{
		TeamSpotter spotter = new TeamSpotter();
		assertEquals(0, spotter.others("nex", 1_000));
		spotter.onHitting("nex", "Alice", 1_000);
		spotter.onHitting("nex", "Bob", 2_000);
		// the same player hitting again is still one player
		spotter.onHitting("nex", "Alice", 3_000);
		assertEquals(2, spotter.others("nex", 4_000));
		// another boss's fight is separate
		assertEquals(0, spotter.others("yama", 4_000));
	}

	@Test
	public void aPlayerSeenLongAgoNoLongerCounts()
	{
		TeamSpotter spotter = new TeamSpotter();
		spotter.onHitting("corporeal beast", "Alice", 0);
		spotter.onHitting("corporeal beast", "Bob", TeamSpotter.WINDOW_MILLIS);
		assertEquals(2, spotter.others("corporeal beast", TeamSpotter.WINDOW_MILLIS));
		assertEquals(1, spotter.others("corporeal beast", TeamSpotter.WINDOW_MILLIS + 1));
	}

	@Test
	public void theNextKillStartsFresh()
	{
		TeamSpotter spotter = new TeamSpotter();
		spotter.onHitting("nex", "Alice", 1_000);
		spotter.clear("nex");
		assertEquals(0, spotter.others("nex", 2_000));
	}
}

package com.onrate.game.toa;

import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import static org.junit.Assert.assertEquals;
import org.junit.Before;
import org.junit.Test;

/**
 * Checks the Tombs of Amascut points estimate (ported from Raid Data Tracker / the Tombs of
 * Amascut plugin) follows its rules.
 */
public class ToaPointsEstimatorTest
{
	/** Any monster without its own factor counts 1 point per damage. */
	private static final int PLAIN_NPC = 1;

	private ToaPointsEstimator points;

	@Before
	public void setUp()
	{
		points = new ToaPointsEstimator();
		points.onGameMessage(ToaPointsEstimator.START_MESSAGE + ".");
		points.setTeamSize(1);
	}

	@Test
	public void startsAtZeroWithoutTheBasePoints()
	{
		assertEquals(0, points.getPersonalTotalPoints());
	}

	@Test
	public void onlyYourOwnHitsCount()
	{
