package com.onrate.parity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.io.InputStream;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;

/**
 * The drop-rate data is the source of truth and must not drift. The three data files are compared
 * byte for byte with the originals, and the catalogue built from them is compared structurally:
 * every boss, part, drop, rate, weight, level rate, pool, shared and untracked item, value formula.
 */
public class DataParityTest
{
	private static String sha256(String resource) throws Exception
	{
		try (InputStream in = DataParityTest.class.getResourceAsStream(resource))
		{
			assertTrue("missing " + resource, in != null);
			MessageDigest md = MessageDigest.getInstance("SHA-256");
			byte[] buffer = new byte[8192];
			for (int n; (n = in.read(buffer)) > 0; )
			{
				md.update(buffer, 0, n);
			}
			StringBuilder hex = new StringBuilder();
			for (byte b : md.digest())
			{
				hex.append(String.format("%02x", b));
			}
			return hex.toString();
		}
	}

	@Test
	public void dataFilesAreByteIdenticalToTheOriginals() throws Exception
	{
		for (String file : new String[]{"bosses.json", "killtimes.json", "ladlorchart.json"})
		{
			assertEquals(file, sha256("/legacy/expecteddrops/" + file), sha256("/com/onrate/" + file));
		}
	}

	private String describe(Side s) throws Exception
	{
		s.newTracker();
		Object catalog = s.catalog;
		StringBuilder out = new StringBuilder();
		@SuppressWarnings("unchecked") List<Object> bosses = (List<Object>) s.callOn(catalog, "getBosses");
		Object defClass = null;
		for (Object boss : bosses)
		{
			out.append("BOSS ").append(Dumper.dump(boss)).append('\n');
			@SuppressWarnings("unchecked") List<Object> drops = (List<Object>) s.callOn(boss, "getDrops");
			@SuppressWarnings("unchecked") List<Object> parts = (List<Object>) s.callOn(boss, "getParts");
			for (Object drop : drops)
			{
				StringBuilder d = new StringBuilder();
				for (int level = 0; level <= 9; level++)
				{
					d.append(s.callOn(drop, "getLevelRate", level)).append('|');
				}
				for (Object part : parts)
				{
					String partName = (String) s.callOn(part, "getName");
					d.append(partName).append('=').append(s.callOn(drop, "getPartRate", partName)).append('/')
						.append(s.callOn(drop, "getWeight", partName)).append('/').append(s.callOn(boss, "getTotalWeight", partName)).append('|');
				}
				for (int raidLevel : new int[]{0, 50, 100, 150, 200, 300, 350, 400, 450, 500, 600})
				{
					d.append(s.callOn(drop, "getWeightAtLevel", raidLevel)).append(',');
				}
				for (int quantity : new int[]{0, 1, 2, 10, 750, 1500})
				{
					d.append(s.callOn(drop, "dropsFromQuantity", quantity)).append(';');
				}
				out.append("  DROP ").append(Dumper.dump(drop)).append(" extra ").append(d).append('\n');
			}
		}
		Map<String, Object> pools = new TreeMap<>();
		@SuppressWarnings("unchecked") Map<String, List<Object>> p = (Map<String, List<Object>>) s.callOn(catalog, "getPools");
		for (Map.Entry<String, List<Object>> e : p.entrySet())
		{
			List<String> sources = new ArrayList<>();
			for (Object src : e.getValue())
			{
				sources.add(Dumper.dump(s.callOn(src, "getBoss")).length() + ":" + s.callOn(s.callOn(src, "getBoss"), "getName") + "/"
					+ s.callOn(s.callOn(src, "getDrop"), "getName"));
			}
			pools.put(e.getKey(), sources);
		}
		out.append("POOLS ").append(pools).append('\n');
		out.append("EXCLUDED ITEMS ").append(Dumper.dump(s.callOn(catalog, "getExcludedItems"))).append('\n');
		out.append("EXCLUDED BOSSES ").append(Dumper.dump(s.callOn(catalog, "getExcludedBosses"))).append('\n');
		out.append("FORMULA ITEMS ").append(Dumper.dump(s.callOn(catalog, "getFormulaItemNames"))).append('\n');
		@SuppressWarnings("unchecked") java.util.Set<String> names = new java.util.TreeSet<>((java.util.Set<String>) s.callOn(catalog, "getAllItemNames"));
		for (String name : names)
		{
			Object formula = s.callOn(catalog, "getValueFormula", name);
			out.append("ITEM ").append(name).append(" shared=").append(s.callOn(catalog, "isClogShared", name))
				.append(" untracked=").append(s.callOn(catalog, "isUntracked", name))
				.append(" formula=").append(formula == null ? "none" : evaluate(s, formula)).append('\n');
		}
		out.append("HIDDEN ").append(Dumper.dump(s.callOn(catalog, "getHiddenBosses"))).append('\n');
		return out.toString();
	}

	/** A formula evaluated against a fixed price list, so equal results mean equal formulas. */
	private String evaluate(Side s, Object formula)
	{
		java.util.function.ToLongFunction<String> prices = name -> 100_000L + Math.abs(name.toLowerCase().hashCode()) % 9_000_000;
		return String.valueOf(s.callOn(formula, "evaluate", prices)) + "/" + Dumper.dump(s.callOn(formula, "getItemNames"));
	}

	@Test
	public void catalogueIsIdentical() throws Exception
	{
		String original = describe(Side.ORIGINAL);
		String rebuilt = describe(Side.REBUILT);
		assertTrue(original.length() > 50_000);
		assertEquals(Collections.emptyList(), diffLines(original, rebuilt));
		System.out.println("data parity: " + original.split("\n").length + " catalogue lines identical");
	}

	private static List<String> diffLines(String a, String b)
	{
		String[] x = a.split("\n");
		String[] y = b.split("\n");
		List<String> diffs = new ArrayList<>();
		for (int i = 0; i < Math.max(x.length, y.length) && diffs.size() < 5; i++)
		{
			String l = i < x.length ? x[i] : "<missing>";
			String r = i < y.length ? y[i] : "<missing>";
			if (!l.equals(r))
			{
				diffs.add("line " + i + "\n  original: " + l + "\n  rebuilt : " + r);
			}
		}
		return diffs;
	}
}

package com.onrate.parity;

import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Turns any result object into canonical text by walking its public no-argument getters
 * ({@code getX}, {@code isX}, {@code hasX}). Class names are not part of the text, so the original
 * and the rebuilt classes give the same text when they hold the same values. Doubles print with
 * their exact shortest representation, so equal text means bit-equal numbers.
 */
final class Dumper
{
	private static final int MAX_DEPTH = 7;

	private Dumper()
	{
	}

	static String dump(Object o)
	{
		StringBuilder out = new StringBuilder();
		walk(o, out, 0, new IdentityHashMap<>());
		return out.toString();
	}

	private static boolean ours(Class<?> c)
	{
		String n = c.getName();
		return n.startsWith("com.expecteddrops.") || n.startsWith("legacy.expecteddrops.") || n.startsWith("com.onrate.");
	}

	private static void walk(Object o, StringBuilder out, int depth, IdentityHashMap<Object, Boolean> seen)
	{
		if (o == null)
		{
			out.append("null");
		}
		else if (o instanceof Double || o instanceof Float)
		{
			double d = ((Number) o).doubleValue();
			out.append(Double.isNaN(d) ? "NaN" : Double.toString(d));
		}
		else if (o instanceof Number || o instanceof Boolean || o instanceof CharSequence || o instanceof Character
			|| o instanceof Enum)
		{
			out.append(o instanceof Enum ? ((Enum<?>) o).name() : String.valueOf(o));
		}
		else if (o.getClass().isArray())
		{
			out.append('[');
			int n = java.lang.reflect.Array.getLength(o);
			for (int i = 0; i < n; i++)
			{
				if (i > 0)
				{
					out.append(',');
				}
				walk(java.lang.reflect.Array.get(o, i), out, depth + 1, seen);
			}
			out.append(']');
		}
		else if (o instanceof Map)
		{
			out.append('{');
			Map<String, Object> sorted = new TreeMap<>();
			for (Map.Entry<?, ?> e : ((Map<?, ?>) o).entrySet())
			{
				sorted.put(String.valueOf(e.getKey()), e.getValue());
			}
			boolean first = true;
			for (Map.Entry<String, Object> e : sorted.entrySet())
			{
				if (!first)
				{
					out.append(',');
				}
				first = false;
				out.append(e.getKey()).append('=');
				walk(e.getValue(), out, depth + 1, seen);
			}
			out.append('}');
		}
		else if (o instanceof Collection)
		{
			out.append('[');
			boolean first = true;
			List<Object> items = new ArrayList<>((Collection<?>) o);
			if (o instanceof java.util.Set)
			{
				items.sort((a, b) -> String.valueOf(a).compareTo(String.valueOf(b)));
			}
			for (Object item : items)
			{
				if (!first)
				{
					out.append(',');
				}
				first = false;
				walk(item, out, depth + 1, seen);
			}
			out.append(']');
		}
		else if (ours(o.getClass()) && depth < MAX_DEPTH && seen.put(o, true) == null)
		{
			out.append('(');
			List<Method> getters = new ArrayList<>();
			for (Method m : o.getClass().getMethods())
			{
				String n = m.getName();
				if (m.getParameterCount() == 0 && !Modifier.isStatic(m.getModifiers()) && m.getDeclaringClass() != Object.class
					&& m.getReturnType() != void.class && (n.startsWith("get") || n.startsWith("is") || n.startsWith("has"))
					&& !n.equals("getClass") && !n.equals("getCatalog") && !n.equals("getBoss") && !n.equals("getState"))
				{
					getters.add(m);
				}
			}
			getters.sort((a, b) -> a.getName().compareTo(b.getName()));
			boolean first = true;
			// public fields too (SaveData)
			List<java.lang.reflect.Field> fields = new ArrayList<>();
			for (java.lang.reflect.Field f : o.getClass().getFields())
			{
				if (!Modifier.isStatic(f.getModifiers()))
				{
					fields.add(f);
				}
			}
			fields.sort((a, b) -> a.getName().compareTo(b.getName()));
			for (java.lang.reflect.Field f : fields)
			{
				if (!first)
				{
					out.append(';');
				}
				first = false;
				out.append('.').append(f.getName()).append(':');
				try
				{
					walk(f.get(o), out, depth + 1, seen);
				}
				catch (IllegalAccessException e)
				{
					out.append("!access");
				}
			}
			for (Method m : getters)
			{
				if (!first)
				{
					out.append(';');
				}
				first = false;
				out.append(m.getName()).append(':');
				try
				{
					m.setAccessible(true);
					walk(m.invoke(o), out, depth + 1, seen);
				}
				catch (Exception e)
				{
					Throwable t = e.getCause() == null ? e : e.getCause();
					out.append("!").append(t.getClass().getSimpleName());
				}
			}
			out.append(')');
			seen.remove(o);
		}
		else
		{
			out.append(ours(o.getClass()) ? o.getClass().getSimpleName() : String.valueOf(o));
		}
	}

	/** The first line (one observation) that differs, in full, so a failure can be read. */
	static String firstDifference(String a, String b)
	{
		String[] x = a.split("\n", -1);
		String[] y = b.split("\n", -1);
		for (int i = 0; i < Math.min(x.length, y.length); i++)
		{
			if (!x[i].equals(y[i]))
			{
				int at = 0;
				while (at < Math.min(x[i].length(), y[i].length()) && x[i].charAt(at) == y[i].charAt(at))
				{
					at++;
				}
				int from = Math.max(0, at - 200);
				String key = x[i].contains(" = ") ? x[i].substring(0, x[i].indexOf(" = ")) : x[i];
				return "observation [" + key + "] differs at char " + at + "\n  original: ..." + x[i].substring(from, Math.min(x[i].length(), at + 300))
					+ "\n  rebuilt : ..." + y[i].substring(from, Math.min(y[i].length(), at + 300));
			}
		}
		return "different number of observations: " + x.length + " vs " + y.length;
	}

	static String dumpAll(Object... values)
	{
		return Arrays.stream(values).map(Dumper::dump).reduce("", (x, y) -> x + y + "\n");
	}
}

package com.onrate.parity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.Bundled;
import com.onrate.parity.Side.Settings;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;
import java.util.function.ToIntFunction;
import java.util.function.ToLongFunction;
import org.junit.Test;

/**
 * The same player, played into the original tracker and the rebuilt tracker. After every few
 * steps everything either of them can tell you (every row of every boss, the account totals with
 * prices, shared pools, trips, day counts, history, kill times, the Time page, the saved JSON) is
 * turned into text and compared. One differing digit fails the test.
 */
public class EngineParityTest
{
	private static final Gson GSON = new Gson();
	private static long observations;
	private static long ops;

	private static final ToLongFunction<String> PRICES = name ->
	{
		int h = Math.abs(name.toLowerCase().hashCode());
		return h % 7 == 0 ? 0 : (h % 5000) * 1000L + 100;
	};

	private static BossCatalog catalog()
	{
		return Bundled.catalog(GSON);
	}

	/** Plays a script on both sides, comparing results step by step and everything at each OBSERVE. */
	private void replay(String label, List<Sim.Op> script, Settings initial, List<String> touched) throws Exception
	{
		Side[] sides = {Side.ORIGINAL, Side.REBUILT};
		AtomicInteger team = new AtomicInteger(0);
		Settings[] settings = {initial};
		for (Side s : sides)
		{
			s.newTracker();
			s.call("setTeamSizeDetectorFor", (ToIntFunction<String>) boss -> team.get());
			s.call("setSettings", initial);
		}
		long now = Sim.BASE;
		for (int i = 0; i < script.size(); i++)
		{
			Sim.Op op = script.get(i);
			ops++;
			if (op.method.equals("SET_TEAM"))
			{
				team.set((Integer) op.args[0]);
				continue;
			}
			if (op.method.equals("SET_SETTINGS"))
			{
				settings[0] = (Settings) op.args[0];
				for (Side s : sides)
				{
					s.call("setSettings", settings[0]);
				}
				continue;
			}
			if (op.method.equals("OBSERVE"))
			{
				String a = observe(sides[0], settings[0], touched, now);
				String b = observe(sides[1], settings[0], touched, now);
				observations++;
				if (!a.equals(b))
				{
					fail(label + " after step " + i + " (" + (i > 0 ? script.get(i - 1) : "start") + "): " + Dumper.firstDifference(a, b));
				}
				continue;
			}
			now = Math.max(now, lastTime(op));
			String[] results = new String[2];
			for (int k = 0; k < 2; k++)
			{
				try
				{
					results[k] = Dumper.dump(sides[k].apply(op));
				}
				catch (RuntimeException e)
				{
					results[k] = "threw " + e.getClass().getSimpleName();
				}
			}
			assertEquals(label + " step " + i + " " + op + " returned differently", results[0], results[1]);
		}
		// the final state, saved: bytes must match
		String a = observe(sides[0], settings[0], touched, now);
		String b = observe(sides[1], settings[0], touched, now);
		if (!a.equals(b))
		{
			fail(label + " at the end: " + Dumper.firstDifference(a, b));
		}
	}

	private static Object[] withSettings(Object[] args, Settings s)
	{
		return args;
	}

	private static long lastTime(Sim.Op op)
	{
		for (int i = op.args.length - 1; i >= 0; i--)
		{
			if (op.args[i] instanceof Long && (Long) op.args[i] > Sim.BASE / 2)
			{
				return (Long) op.args[i];
			}
		}
		return 0;
	}

	/** Everything either implementation can say about its current state, as one string. */
	private String observe(Side s, Settings st, List<String> touched, long now)
	{
		StringBuilder out = new StringBuilder();
		TreeMap<String, Object> map = new TreeMap<>();
		for (String boss : touched)
		{
			map.put("stats " + boss, s.call("stats", boss, st));
			map.put("history " + boss, s.call("history", boss));
			map.put("killTimes " + boss, s.call("killTimes", boss, null));
			map.put("killsSeen " + boss, s.call("killsSeen", boss));
			map.put("teamKills " + boss, s.call("teamKills", boss));
			map.put("olderShare " + boss, s.call("olderShare", boss));
			map.put("raidRecords " + boss, s.call("raidRecords", boss));
			map.put("syncReminder " + boss, s.call("syncReminder", boss));
			map.put("sharedPoolsFor " + boss, s.call("sharedPoolsFor", boss, st));
			map.put("measured " + boss, s.call("measuredRaids", boss, null));
			map.put("levelTimes " + boss, s.call("levelTimes", boss, 3));
		}
		map.put("account", s.call("accountStats", st));
		map.put("accountWithPrices", s.call("accountStats", st, PRICES));
		map.put("sharedPools", s.call("sharedPools", st));
		map.put("today", s.call("recentDays", 1, now));
		map.put("week", s.call("recentDays", 7, now));
		map.put("trip", s.call("tripStats"));
		map.put("tripValue", s.call("tripValue", PRICES));
		map.put("lastUnique", s.call("lastUnique"));
		map.put("checklist", s.call("syncChecklist"));
		map.put("mostKills", s.call("bossWithMostKills"));
		map.put("luckyDrops", s.call("dropsByLuck", true, 25));
		map.put("dryDrops", s.call("dropsByLuck", false, 25));
		map.put("recentDrops", s.call("recentDrops", 25));
		map.put("lastBoss", s.call("getLastBoss"));
		map.put("tripIdle", s.call("tripIdleLimitMillis"));
		Object killTimes = s.callStatic("data", "KillTimes", "bundled");
		Object chart = s.callStatic("data", "LadlorChart", "bundled");
		map.put("itemTimes", s.callStatic("stats", "ItemTimes", "compute", s.tracker, killTimes, st));
		map.put("chartTimes", s.callStatic("stats", "ChartTimes", "compute", s.tracker, killTimes, st, chart));
		map.put("notes", withoutTripNotes(s.call("drainNotes")));
		map.put("save", s.call("saveData", (Function<Object, String>) GSON::toJson));
		for (Map.Entry<String, Object> e : map.entrySet())
		{
			out.append(e.getKey()).append(" = ").append(Dumper.dump(e.getValue())).append('\n');
		}
		return out.toString();
	}

	/**
	 * The trip summary chat line was removed on purpose (the original still sends it), so TRIP
	 * notes are left out on both sides; every other note must still match.
	 */
	private static Object withoutTripNotes(Object notes)
	{
		List<Object> kept = new ArrayList<>();
		for (Object n : (Iterable<?>) notes)
		{
			Object kind;
			try
			{
				kind = n.getClass().getMethod("getKind").invoke(n);
			}
			catch (ReflectiveOperationException e)
			{
				throw new IllegalStateException(e);
			}
			if (!"TRIP".equals(String.valueOf(kind)))
			{
				kept.add(n);
			}
		}
		return kept;
	}

	private List<BossDefinition> allBosses(BossCatalog catalog)
	{
		return new ArrayList<>(catalog.getBosses());
	}

	@Test
	public void everyBossPlayedOnBothImplementations() throws Exception
	{
		BossCatalog catalog = catalog();
		List<BossDefinition> bosses = allBosses(catalog);
		int seeds = 0;
		// each scenario plays a handful of bosses; the offsets walk the whole catalogue
		for (int seed = 0; seed < 28; seed++)
		{
			Sim sim = new Sim(1000 + seed, catalog);
			for (int i = 0; i < 6; i++)
			{
				sim.playBoss(bosses.get((seed * 5 + i * 11) % bosses.size()));
			}
			sim.sprinkle();
			replay("seed " + seed, sim.ops, sim.settings, sim.touched);
			seeds++;
		}
		System.out.println("engine parity: " + seeds + " scenarios, " + ops + " steps, " + observations + " full-state comparisons");
	}

