	@Test
	public void accountSwitchingKeepsAccountsApart() throws Exception
	{
		BossCatalog catalog = catalog();
		List<BossDefinition> bosses = allBosses(catalog);
		for (int seed = 0; seed < 6; seed++)
		{
			Sim sim = new Sim(12000 + seed, catalog);
			for (int i = 0; i < 4; i++)
			{
				sim.playBoss(bosses.get((seed * 11 + i * 13) % bosses.size()));
			}
			sim.switchAway();
			sim.playBoss(bosses.get((seed * 5 + 3) % bosses.size()));
			sim.switchAway();
			// on both implementations, step by step
			replay("switching seed " + seed, sim.ops, sim.settings, sim.touched);

			// and on the new one: a fresh account shows nothing of the old one, and coming back restores it exactly
			Side side = Side.REBUILT;
			replayInto(side, sim);
			String before = persistedOnly(observe(side, sim.settings, sim.touched, Sim.BASE + 9_000_000_000L));
			side.apply(new Sim.Op("SWITCH", "fresh"));
			Object account = side.call("accountStats", sim.settings);
			assertEquals("a new account starts empty", 0, ((List<?>) account.getClass().getMethod("getRows").invoke(account)).size());
			assertEquals(null, side.call("tripStats"));
			assertEquals(0, ((List<?>) side.call("recentDrops", 50)).size());
			side.apply(new Sim.Op("SWITCH", "main"));
			String after = persistedOnly(observe(side, sim.settings, sim.touched, Sim.BASE + 9_000_000_000L));
			if (!before.equals(after))
			{
				fail("switching back changed the account: " + Dumper.firstDifference(before, after));
			}
		}
	}

	@Test
	public void savedDataLoadsAcrossVersionsBothWays() throws Exception
	{
		BossCatalog catalog = catalog();
		List<BossDefinition> bosses = allBosses(catalog);
		for (int seed = 0; seed < 6; seed++)
		{
			Sim sim = new Sim(9000 + seed, catalog);
			for (int i = 0; i < 7; i++)
			{
				sim.playBoss(bosses.get((seed * 9 + i * 7) % bosses.size()));
			}
			sim.sprinkle();
			for (Side from : new Side[]{Side.ORIGINAL, Side.REBUILT})
			{
				Side to = from == Side.ORIGINAL ? Side.REBUILT : Side.ORIGINAL;
				replayInto(from, sim);
				// everything `from` has saved for this account (switches mid-session saved part of it already)
				java.util.Map<String, String> store = new java.util.HashMap<>(from.saveAccount());
				String before = observe(from, sim.settings, sim.touched, Sim.BASE + 10_000_000_000L);
				String progress = store.get("progress");

				// the other version loads it, as ProfileStore does
				to.newTracker();
				to.call("setSettings", sim.settings);
				to.loadAccount(store);
				String after = observe(to, sim.settings, sim.touched, Sim.BASE + 10_000_000_000L);
				// the first save re-sends everything that changed; compare what the loaded tracker reports
				before = persistedOnly(before);
				after = persistedOnly(after);
				if (!before.equals(after))
				{
					fail("seed " + seed + " " + from.name + " -> " + to.name + ": " + Dumper.firstDifference(before, after));
				}
				assertTrue(progress.length() > 100);
			}
		}
	}

	/** Observations that depend only on what is saved: the trip, the last boss and chat notes live in memory only. */
	private static String persistedOnly(String observations)
	{
		return observations.replaceAll("(?m)^(save|lastBoss|trip|tripValue|tripIdle|lastUnique|notes) = .*$", "");
	}

	private void replayInto(Side side, Sim sim) throws Exception
	{
		side.newTracker();
		side.call("setSettings", sim.settings);
		AtomicInteger team = new AtomicInteger(0);
		side.call("setTeamSizeDetectorFor", (ToIntFunction<String>) boss -> team.get());
		Settings current = sim.settings;
		for (Sim.Op op : sim.ops)
		{
			if (op.method.equals("SET_TEAM"))
			{
				team.set((Integer) op.args[0]);
			}
			else if (op.method.equals("SET_SETTINGS"))
			{
				current = (Settings) op.args[0];
				side.call("setSettings", current);
			}
			else if (!op.method.equals("OBSERVE"))
			{
				try
				{
					side.apply(op);
				}
				catch (RuntimeException e)
				{
					// same on both sides, checked in the replay test
				}
			}
		}
	}
}

package com.onrate.parity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.tracking.KillEntry;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.SaveData;
import com.onrate.engine.tracking.Tracker;
import com.onrate.engine.tracking.TrackerState;
import com.onrate.store.Keys;
import com.onrate.store.ProfileStore;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.ToIntFunction;
import org.junit.Test;

/**
 * Valid saved data loads exactly as before the damage-tolerant load (audit F5): simulated players'
 * saved data, read the old way (Gson straight from the text) and through ProfileStore, gives the
 * same tracker, and nothing is reported as damaged.
 */
public class LenientLoadParityTest
{
	private static final Type KILLS = new TypeToken<List<KillEntry>>() { }.getType();
	private static final Type RAIDS = new TypeToken<List<RaidRecord>>() { }.getType();

	private static final class Profile implements ProfileStore.Backend
	{
		final Map<String, String> values = new HashMap<>();

		@Override
		public String get(String profile, String key)
		{
			return values.get(key);
		}

		@Override
		public void set(String profile, String key, String value)
		{
			values.put(key, value);
		}

		@Override
		public void unset(String profile, String key)
		{
			values.remove(key);
		}
	}

	/** Everything a loaded tracker would save: the main data and every boss's History and raids. */
	private static String everything(Tracker t, BossCatalog catalog, Gson gson)
	{
		List<String> all = new ArrayList<>();
		for (BossDefinition b : catalog.getBosses())
		{
			all.add(b.getName());
		}
		t.markUnsaved(all, all);
		SaveData d = t.saveData(gson::toJson);
		return d.progress + "\n" + new java.util.TreeMap<>(d.kills) + "\n" + new java.util.TreeMap<>(d.raids);
	}

	@Test
	public void simulatedPlayersLoadTheSameThroughTheTolerantLoad() throws Exception
	{
		Gson gson = new Gson();
		int players = 0;
		int keys = 0;
		for (int seed = 0; seed < 10; seed++)
		{
			Side side = Side.REBUILT;
			side.newTracker();
			BossCatalog catalog = (BossCatalog) side.catalog;
			Tracker played = (Tracker) side.tracker;
			AtomicInteger team = new AtomicInteger();
			played.setTeamSizeDetectorFor((ToIntFunction<String>) boss -> team.get());
			Profile profile = new Profile();
			ProfileStore store = new ProfileStore(profile, gson);
			store.load("p", played);

			Sim sim = new Sim(31000 + seed, catalog);
			List<BossDefinition> bosses = new ArrayList<>(catalog.getBosses());
			for (int i = 0; i < 6; i++)
			{
				sim.playBoss(bosses.get((seed * 7 + i * 13) % bosses.size()));
			}
			sim.sprinkle();
			side.call("setSettings", sim.settings);
			for (Sim.Op op : sim.ops)
			{
				switch (op.method)
				{
					case "SET_TEAM":
						team.set((Integer) op.args[0]);
						break;
					case "SET_SETTINGS":
						side.call("setSettings", op.args[0]);
						break;
					case "OBSERVE":
					case "SWITCH":
						// account switching has its own store mimic in the parity harness
						break;
					default:
						try
						{
							side.apply(op);
						}
						catch (RuntimeException e)
						{
							// a step both implementations refuse; nothing to save
						}
						store.save(played);
				}
			}
			store.save(played);
			keys += profile.values.size();

			// the old way: Gson straight from the saved text
			Tracker before = new Tracker(catalog);
			before.setState(gson.fromJson(profile.values.get(Keys.DATA), TrackerState.class));
			for (BossDefinition b : catalog.getBosses())
			{
				String k = profile.values.get(Keys.killsKey(b.getName()));
				if (k != null)
				{
					before.setKills(b.getName(), gson.fromJson(k, KILLS));
				}
				String r = b.getRaid() == null ? null : profile.values.get(Keys.raidsKey(b.getName()));
				if (r != null)
				{
					before.setRaids(b.getName(), gson.fromJson(r, RAIDS));
				}
			}
			// now: through the store
			Tracker after = new Tracker(catalog);
			Map<String, String> savedBefore = new HashMap<>(profile.values);
			assertTrue(new ProfileStore(profile, gson).load("p", after));

			assertEquals("seed " + seed, everything(before, catalog, gson), everything(after, catalog, gson));
			assertEquals("loading valid data writes nothing", savedBefore, profile.values);
			for (String key : profile.values.keySet())
			{
				assertFalse("valid data was reported as damaged: " + key, key.endsWith(Keys.CORRUPT_SUFFIX));
			}
			players++;
		}
		System.out.println("lenient load parity: " + players + " simulated players, " + keys + " saved keys identical");
	}
}

package com.onrate.parity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;

import legacy.expecteddrops.stats.DropMath;
import com.onrate.engine.math.Luck;
import com.onrate.engine.math.Poisson;
import com.onrate.engine.math.Rates;
import com.onrate.engine.math.Untradeables;
import com.onrate.engine.math.ValueLuck;
import com.onrate.engine.math.Verdict;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Random;
import org.junit.Test;

/**
 * The statistics, old against new. {@code DropMath} (the original) is the reference; every
 * function of the rebuilt math layer must return the very same double, bit for bit, for the same
 * input. Grids are dense and cover the extremes (a drop rate of 1 in 20 million up to 400
 * expected, 0 to 120 received).
 */
public class MathParityTest
{
	private static long checks;

	private static void same(String what, double original, double rebuilt)
	{
		checks++;
		if (Double.compare(original, rebuilt) != 0)
		{
			fail(what + ": original " + original + " but rebuilt " + rebuilt);
		}
	}

	private static void sameArray(String what, double[] original, double[] rebuilt)
	{
		checks++;
		if (original == null || rebuilt == null)
		{
			assertEquals(what, original == null, rebuilt == null);
			return;
		}
		assertEquals(what + " length", original.length, rebuilt.length);
		for (int i = 0; i < original.length; i++)
		{
			same(what + "[" + i + "]", original[i], rebuilt[i]);
		}
	}

	/** Expected counts from 1e-6 to 400, log-spaced, plus awkward values. */
	private static List<Double> expectedValues()
	{
		List<Double> list = new ArrayList<>();
		for (double e = 1e-6; e < 450; e *= 1.37)
		{
			list.add(e);
		}
		list.addAll(Arrays.asList(0.0, -1.0, Double.NaN, 0.5, 1.0, 2.0, 30.0, 30.0000001, 100.0));
		return list;
	}

	@Test
	public void rateParsingAndFormatting()
	{
		String[] rates = {null, "", "  ", "1/50", "3/512", "7/2448", " 1 / 1,024 ", "0.02", "0", "1/3", "2.5/100", "1/1"};
		for (String r : rates)
		{
			same("parse " + r, DropMath.parseRate(r), Rates.parse(r));
		}
		for (String bad : new String[]{"1/0", "1/-5", "abc", "1/x"})
		{
			String a = null;
			String b = null;
			try
			{
				DropMath.parseRate(bad);
			}
			catch (RuntimeException e)
			{
				a = e.getClass().getName();
			}
			try
			{
				Rates.parse(bad);
			}
			catch (RuntimeException e)
			{
				b = e.getClass().getName();
			}
			assertEquals("exception for " + bad, a, b);
		}
		for (double d = 1e-7; d < 1e4; d *= 1.21)
		{
			assertEquals(DropMath.formatRate(d), Rates.format(d));
		}
		assertEquals(DropMath.formatRate(0), Rates.format(0));
		assertEquals(DropMath.formatRate(-3), Rates.format(-3));
		for (double gp = -5e9; gp < 5e9; gp += 7_654_321.5)
		{
			assertEquals(DropMath.formatGp(gp), Rates.gp(gp));
		}
		for (double gp : new double[]{0, 1, 999, 999.5, 1000, 1_000_000, 999_999_999, 1_000_000_000, 2.5e12})
		{
			assertEquals(DropMath.formatGp(gp), Rates.gp(gp));
		}
	}

	@Test
	public void sharesLuckPercentileAndCaps()
	{
		for (double expected : expectedValues())
		{
			for (int received = -2; received <= 120; received++)
			{
				sameArray("shares " + received + "/" + expected, DropMath.shares(received, expected), Poisson.shares(received, expected));
				same("luck " + received + "/" + expected, DropMath.luck(received, expected), Luck.of(received, expected));
				same("midP " + received + "/" + expected, DropMath.luckPercentile(received, expected), Luck.midP(received, expected));
				for (int cap = 1; cap <= 3; cap++)
				{
					sameArray("sharesCapped " + received + "/" + expected + "/" + cap,
						DropMath.sharesCapped(received, expected, cap), Poisson.sharesCapped(received, expected, cap));
					same("luckCapped " + received + "/" + expected + "/" + cap,
						DropMath.luckCapped(received, expected, cap), Luck.ofCapped(received, expected, cap));
				}
			}
			for (int cap = 0; cap <= 4; cap++)
			{
				same("expectedCapped " + expected + "/" + cap, DropMath.expectedCapped(expected, cap), Poisson.expectedCapped(expected, cap));
				same("expectedValue " + expected + "/" + cap, DropMath.expectedValue(expected, cap), Poisson.expectedCounted(expected, cap));
			}
			same("chance " + expected, DropMath.chanceAtLeastOne(expected), Poisson.chanceAtLeastOne(expected));
		}
		for (double fewer = 0; fewer <= 1; fewer += 0.013)
		{
			for (double same = 0; same <= 1; same += 0.017)
			{
				same("tieAware", DropMath.tieAware(fewer, same), Luck.tieAware(fewer, same));
			}
		}
	}

	@Test
	public void chancesAndKillsNeeded()
	{
		for (double rate : new double[]{0, -1, 1e-7, 1 / 5000.0, 1 / 181.0, 1 / 50.0, 0.3, 0.999, 1, 2})
		{
			for (long kc : new long[]{-5, 0, 1, 2, 50, 1000, 100_000, 5_000_000})
			{
				same("chance " + rate + "/" + kc, DropMath.chanceAtLeastOne(rate, kc), Poisson.chanceAtLeastOne(rate, kc));
			}
			for (double p : new double[]{0, -0.1, 0.5, 0.9, 0.99, 0.999999})
			{
				assertEquals(DropMath.killsForChance(rate, p), Poisson.killsForChance(rate, p));
			}
		}
	}

	@Test
	public void verdictBandsAndEveryBoundary()
	{
		List<Double> lucks = new ArrayList<>();
		for (double l = -0.01; l <= 1.01; l += 0.0005)
		{
			lucks.add(l);
		}
		for (double edge : new double[]{0.01, 0.1, 0.35, 0.45, 0.55, 0.65, 0.9, 0.99, 0, 1, 0.5})
		{
			lucks.add(edge);
			lucks.add(Math.nextUp(edge));
			lucks.add(Math.nextDown(edge));
		}
		lucks.add(Double.NaN);
		for (double luck : lucks)
		{
			assertEquals("verdict " + luck, DropMath.verdict(luck), Verdict.labelOf(luck));
			assertEquals("onRate " + luck, DropMath.isOnRate(luck), Verdict.isOnRate(luck));
		}
		assertEquals(DropMath.TOO_EARLY_BELOW, Verdict.TOO_EARLY_BELOW, 0);
		assertEquals(DropMath.DRY_BELOW, Verdict.DRY_BELOW, 0);
		assertEquals(DropMath.SPOONED_ABOVE, Verdict.SPOONED_ABOVE, 0);
		assertEquals(DropMath.VERDICTS, Verdict.labels());
		assertEquals(DropMath.ON_RATE, Verdict.ON_RATE.label());
	}

	@Test
	public void sumsOfCappedAndGuaranteedItems()
	{
		Random random = new Random(20261107);
		for (int trial = 0; trial < 4000; trial++)
		{
			int sure = random.nextInt(3) == 0 ? random.nextInt(3) : 0;
			double plain = random.nextInt(4) == 0 ? 0 : random.nextDouble() * (random.nextBoolean() ? 3 : 40);
			int n = random.nextInt(4);
			double[] means = new double[n];
			int[] caps = new int[n];
			for (int i = 0; i < n; i++)
			{
				means[i] = random.nextInt(5) == 0 ? 0 : Math.exp(random.nextDouble() * 8 - 6);
				caps[i] = random.nextInt(3) + 1;
			}
			int g = random.nextInt(3) == 0 ? 1 + random.nextInt(2) : 0;
			List<double[]> guaranteed = new ArrayList<>();
			for (int i = 0; i < g; i++)
			{
				guaranteed.add(new double[]{random.nextInt(300), 1 / (20.0 + random.nextInt(200)), 50});
			}
			int received = random.nextInt(25) - 1;
			String tag = "trial " + trial;
			sameArray(tag + " sharesSum", DropMath.sharesSum(received, sure, plain, means, caps, guaranteed),
				Poisson.sharesSum(received, sure, plain, means, caps, guaranteed));
			sameArray(tag + " sharesSum5", DropMath.sharesSum(received, sure, plain, means, caps),
				Poisson.sharesSum(received, sure, plain, means, caps));
		}
		assertNull(Poisson.sharesSum(0, 0, 0, new double[]{0}, new int[]{1}));
		sameArray("nulls", DropMath.sharesSum(1, 1, 0.98, null, null), Poisson.sharesSum(1, 1, 0.98, null, null));
	}

	@Test
