package com.onrate.parity;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.Bundled;
import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import java.util.function.ToIntFunction;
import java.util.function.ToLongFunction;
import javax.imageio.ImageIO;
import net.runelite.client.game.ItemManager;
import org.junit.Test;

/**
 * UI regression guard. The original panel (running on the original engine) and the integrated
 * panel (the same UI classes, running on the new engine) are built from the same simulated player
 * and drawn off screen, page by page, in every item view. The pictures must be identical, pixel for
 * pixel. A difference saves both pictures and a diff to build/pixel-diff.
 */
public class PanelPixelParityTest
{
	private static final int WIDTH = 225;
	private static final String[] VIEWS = {"TARGET_BARS", "DELVE_BARS", "COMPACT", "RINGS", "GAUGE"};
	private static int pages;
	private static long pixels;

	/** One way of drawing the panel: an item view and the display switches. */
	private static final class Look
	{
		final String view;
		final boolean gp;
		final boolean graph;
		final boolean trip;
		final boolean colourBlind;

		Look(String view, boolean gp, boolean graph, boolean trip, boolean colourBlind)
		{
			this.view = view;
			this.gp = gp;
			this.graph = graph;
			this.trip = trip;
			this.colourBlind = colourBlind;
		}

		@Override
		public String toString()
		{
			return view + (gp ? "" : "-noGP") + (graph ? "-graph" : "") + (colourBlind ? "-cb" : "");
		}
	}

	private static String ui(Side side)
	{
		return side == Side.ORIGINAL ? "legacy.expecteddrops.ui." : "com.expecteddrops.ui.";
	}

	@SuppressWarnings({"unchecked", "rawtypes"})
	private static Object panel(Side side, Side.Settings settings, Look look) throws Exception
	{
		Class<?> panelClass = Class.forName(ui(side) + "ExpectedDropsPanel");
		Class<?> itemView = Class.forName(ui(side) + "ItemView");
		Class<?> options = Class.forName(ui(side) + "ViewOptions");
		Object view = Enum.valueOf((Class<Enum>) itemView, look.view);
		Object opts = options.getConstructor(itemView, boolean.class, boolean.class, boolean.class, boolean.class, boolean.class)
			.newInstance(view, look.gp, look.graph, look.trip, look.colourBlind, true);
		Object raids = side.raidSettings(settings);
		Constructor<?> c = panelClass.getConstructor(side.cls("tracking", "Tracker"), ItemManager.class, Supplier.class, ToIntFunction.class,
			Runnable.class, BooleanSupplier.class, Runnable.class, ToLongFunction.class, Supplier.class);
		Object p = c.newInstance(side.tracker, null, (Supplier<Object>) () -> raids, (ToIntFunction<String>) s -> -1, (Runnable) () ->
		{
		}, (BooleanSupplier) () -> false, (Runnable) () ->
		{
		}, PRICES, (Supplier<Object>) () -> opts);
		if (side == Side.REBUILT)
		{
			// the raid sections and PB tags are new: the original panel has none, so they are
			// left out of the comparison (RaidSectionsTest covers them)
			set(p, "raidExtras", false);
			// the card look (lists in outlined cards, one pill and tab style) is new too: the comparison draws
			// the old look, so it still checks every number and row pixel for pixel (CardLookTest covers the cards)
			set(p, "boxes", false);
			// the line under the verdict taking turns with other facts is new: the original shows one line
			set(p, "moreFacts", false);
			// the View buttons (boss pages' ITEMS line, account Sort row) are new: the comparison draws the old layout
			// (ViewChipTest covers the button)
			set(p, "viewButtons", false);
		}
		panelClass.getMethod("onActivate").invoke(p);
		return p;
	}

	private static final ToLongFunction<String> PRICES = name ->
	{
		int h = Math.abs(name.toLowerCase().hashCode());
		return h % 7 == 0 ? 0 : (h % 5000) * 1000L + 100;
	};

	private static void set(Object target, String field, Object value) throws Exception
	{
		Field f = target.getClass().getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	@SuppressWarnings({"unchecked", "rawtypes"})
	private static void setEnum(Object target, String field, String nested, String value) throws Exception
	{
		Class<?> type = Class.forName(target.getClass().getName() + "$" + nested);
		set(target, field, Enum.valueOf((Class<Enum>) type, value));
	}

	private static void layoutAll(Component c)
	{
		if (c instanceof Container)
		{
			((Container) c).doLayout();
			for (Component child : ((Container) c).getComponents())
			{
				layoutAll(child);
			}
		}
	}

	private static BufferedImage render(Object panelObject)
	{
		Container panel = (Container) panelObject;
		panel.setSize(WIDTH, 6000);
		layoutAll(panel);
		int height = Math.max(200, Math.min(6000, panel.getPreferredSize().height));
		panel.setSize(WIDTH, height);
		layoutAll(panel);
		layoutAll(panel);
		BufferedImage image = new BufferedImage(WIDTH, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		panel.printAll(g);
		g.dispose();
		return image;
	}

	/** Draws the same page on both panels, one after the other: the original's picture, then the integrated one's. */
	private static BufferedImage[] draw(Object[] panels, PageSetter page) throws Exception
	{
		BufferedImage[] shots = new BufferedImage[2];
		for (int k = 0; k < 2; k++)
		{
			Object panel = panels[k];
			int index = k;
			// drawn on the Swing thread, as in the client, and only once the deferred re-layouts the
			// original UI queues (a tile whose text wrapped lays itself out again "later") have run
			onSwing(() ->
			{
				page.show(panel);
				panel.getClass().getMethod("refresh").invoke(panel);
				render(panel);
			});
			settle();
			onSwing(() -> render(panel));
			settle();
			onSwing(() -> shots[index] = render(panel));
		}
		return shots;
	}

	/** Pixels that differ between two pictures: {count, first x, first y}; count -1 when the sizes differ. */
	private static int[] difference(BufferedImage a, BufferedImage b)
	{
		if (a.getWidth() != b.getWidth() || a.getHeight() != b.getHeight())
		{
			return new int[]{-1, -1, -1};
		}
		int differing = 0;
		int firstX = -1;
		int firstY = -1;
		for (int y = 0; y < a.getHeight(); y++)
		{
			for (int x = 0; x < a.getWidth(); x++)
			{
				if (a.getRGB(x, y) != b.getRGB(x, y) && differing++ == 0)
				{
					firstX = x;
					firstY = y;
				}
			}
		}
		return new int[]{differing, firstX, firstY};
	}

	/** Shows the same page on both panels and compares the pictures. */
	private static void compare(String name, Object[] panels, PageSetter page) throws Exception
	{
		long minuteBefore = System.currentTimeMillis() / 60_000;
		BufferedImage[] shots = draw(panels, page);
		int[] diff = difference(shots[0], shots[1]);
		// The trip card reads the clock ("Idle 12 min"): when the minute turns between the two pictures, the
		// same page says 12 on one and 13 on the other. Only then, draw both once more, well inside a minute:
		// a real difference shows again, a clock tick doesn't.
		if (diff[0] != 0 && System.currentTimeMillis() / 60_000 != minuteBefore)
		{
			shots = draw(panels, page);
			diff = difference(shots[0], shots[1]);
		}
		pages++;
		BufferedImage a = shots[0];
		BufferedImage b = shots[1];
		if (diff[0] >= 0)
		{
			pixels += (long) a.getWidth() * a.getHeight();
		}
		int differing = diff[0];
		int firstX = diff[1];
		int firstY = diff[2];
		if (differing == 0 && name.startsWith("seed0-TARGET_BARS-"))
		{
			// a sample of pages side by side (original | integrated) for people to look at
			File dir = new File(System.getProperty("onrate.pairs", "build/pixel-parity"));
			dir.mkdirs();
			BufferedImage pair = new BufferedImage(a.getWidth() * 2 + 6, a.getHeight(), BufferedImage.TYPE_INT_RGB);
			Graphics2D g = pair.createGraphics();
			g.setColor(new java.awt.Color(220, 138, 0));
			g.fillRect(0, 0, pair.getWidth(), pair.getHeight());
			g.drawImage(a, 0, 0, null);
			g.drawImage(b, a.getWidth() + 6, 0, null);
			g.dispose();
			ImageIO.write(pair, "png", new File(dir, name.substring("seed0-TARGET_BARS-".length()).replaceAll("[^A-Za-z0-9.-]", "_") + ".png"));
		}
		if (differing != 0)
		{
			File dir = new File("build/pixel-diff");
			dir.mkdirs();
			String file = name.replaceAll("[^A-Za-z0-9.-]", "_");
			ImageIO.write(a, "png", new File(dir, file + "-original.png"));
			ImageIO.write(b, "png", new File(dir, file + "-integrated.png"));
			fail(name + ": " + (differing < 0 ? "sizes differ " + a.getWidth() + "x" + a.getHeight() + " vs " + b.getWidth() + "x" + b.getHeight()
				: differing + " pixels differ, first at " + firstX + "," + firstY) + " (pictures in build/pixel-diff)");
		}
	}

	private interface SwingTask
	{
		void run() throws Exception;
	}

	private static void onSwing(SwingTask task) throws Exception
	{
		Exception[] failed = new Exception[1];
		javax.swing.SwingUtilities.invokeAndWait(() ->
		{
			try
			{
				task.run();
			}
			catch (Exception e)
			{
				failed[0] = e;
			}
		});
		if (failed[0] != null)
		{
			throw failed[0];
		}
	}

	/** Lets everything already queued on the Swing thread run (twice: a run can queue another). */
	private static void settle() throws Exception
	{
		for (int i = 0; i < 3; i++)
		{
			javax.swing.SwingUtilities.invokeAndWait(() ->
			{
			});
		}
	}

	private interface PageSetter
	{
		void show(Object panel) throws Exception;
	}

	private static void account(Object p, int tab, int topMode) throws Exception
	{
		set(p, "accountTab", tab);
		set(p, "topMode", topMode);
		p.getClass().getMethod("showBoss", String.class).invoke(p, "Account overview");
	}

	private static void boss(Object p, String name) throws Exception
	{
		set(p, "historyOpen", true);
		p.getClass().getMethod("showBoss", String.class).invoke(p, name);
	}

	/** Plays one simulated player into both trackers. */
	private static Sim play(long seed, BossCatalog catalog, List<BossDefinition> bosses, int offset) throws Exception
	{
		Sim sim = new Sim(seed, catalog);
		for (int i = 0; i < 6; i++)
		{
			sim.playBoss(bosses.get((offset + i * 9) % bosses.size()));
		}
		sim.sprinkle();
		for (Side side : new Side[]{Side.ORIGINAL, Side.REBUILT})
		{
			side.newTracker();
			side.call("setSettings", sim.settings);
			AtomicInteger team = new AtomicInteger();
			side.call("setTeamSizeDetectorFor", (ToIntFunction<String>) b -> team.get());
			for (Sim.Op op : sim.ops)
			{
				if (op.method.equals("SET_TEAM"))
				{
					team.set((Integer) op.args[0]);
				}
				else if (op.method.equals("SET_SETTINGS"))
				{
					side.call("setSettings", op.args[0]);
				}
				else if (!op.method.equals("OBSERVE"))
				{
					try
					{
						side.apply(op);
					}
					catch (RuntimeException e)
					{
						// identical on both, checked by the replay test
					}
				}
			}
		}
		return sim;
	}

	@Test
	public void everyPageLooksTheSameInEveryView() throws Exception
	{
		BossCatalog catalog = Bundled.catalog(new com.google.gson.Gson());
		List<BossDefinition> bosses = new ArrayList<>(catalog.getBosses());
		List<Look> looks = new ArrayList<>();
		for (String v : VIEWS)
		{
			looks.add(new Look(v, true, false, true, false));
		}
		looks.add(new Look("TARGET_BARS", false, true, false, true));
		looks.add(new Look("COMPACT", true, true, true, true));
		for (int s = 0; s < 4; s++)
		{
			Sim sim = play(70000 + s, catalog, bosses, s * 13);
			for (Look look : looks)
			{
				Object[] panels = new Object[2];
				Side.Settings st = sim.settings;
				onSwing(() ->
				{
					panels[0] = panel(Side.ORIGINAL, st, look);
					panels[1] = panel(Side.REBUILT, st, look);
				});
				String tag = "seed" + s + "-" + look;
				compare(tag + "-account-bosses", panels, p -> account(p, 0, 0));
				compare(tag + "-account-recent", panels, p -> account(p, 2, 0));
				for (int mode = 0; mode <= 4; mode++)
				{
					int m = mode;
					compare(tag + "-account-items-" + mode, panels, p -> account(p, 1, m));
				}
				if (look.view.equals("TARGET_BARS") && look.gp)
				{
					for (String tv : new String[]{"ITEMS", "CHART", "PETS", "RAIDS"})
					{
						compare(tag + "-time-" + tv, panels, p ->
						{
							setEnum(p, "timeView", "TimeView", tv);
							account(p, 1, 4);
						});
					}
				}
				for (String name : new java.util.LinkedHashSet<>(sim.touched))
				{
					compare(tag + "-boss-" + name, panels, p -> boss(p, name));
				}
			}
		}
		System.out.println("pixel parity: " + pages + " pages, " + pixels + " pixels, all identical");
		assertTrue(pages > 100);
	}
}

package com.onrate.parity;

import com.google.gson.Gson;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;

/**
 * One of the two implementations under test, driven by reflection so that exactly the same
 * scenario script runs against the original ({@code com.expecteddrops}) and the rebuilt
 * ({@code com.onrate.engine}) classes.
 */
final class Side
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	static final Side ORIGINAL = new Side("original", "legacy.expecteddrops");
	static final Side REBUILT = new Side("rebuilt", "com.onrate.engine");

	/** A loot item argument (the nested class differs per side). */
	static final class Loot
	{
		final String name;
		final int quantity;

		Loot(String name, int quantity)
		{
			this.name = name;
			this.quantity = quantity;
		}
	}

	/** A raid record built through its static factory ({@code cox}, {@code toa}, ...). */
	static final class Raid
	{
		final String factory;
		final Object[] args;

		Raid(String factory, Object... args)
		{
			this.factory = factory;
			this.args = args;
		}
	}

	/** Player settings as plain numbers, adapted to each side's {@code RaidSettings}. */
	static final class Settings
	{
		double cox = 0.035, coxCm = 0.05, tob = 0.027, tobHm = 0.032, toaEntry = 0.0075, toa = 0.025, toaExpert = 0.05,
			fractured = 1 / 28.0;
		int tobTeam = 4;
		int tfaTeam = 2;
		/** Share of kills counted as duo at the duo-team bosses, 0..1. */
		double duoShare = 1.0;
	}

	final String name;
	final String prefix;
	final Gson gson = new Gson();
	Object tracker;
	Object catalog;
	/** Saved settings of every account, as RuneLite's profile would hold them (key to JSON). */
	final java.util.Map<String, java.util.Map<String, String>> accounts = new java.util.HashMap<>();
	String account = "main";

	private Side(String name, String prefix)
	{
		this.name = name;
		this.prefix = prefix;
	}

	Class<?> cls(String sub, String simple)
	{
		try
		{
			return Class.forName(prefix + "." + sub + "." + simple);
		}
		catch (ClassNotFoundException e)
		{
			throw new IllegalStateException(e);
		}
	}

	/** Creates a fresh tracker over a fresh catalog from this side's own copy of bosses.json. */
	Object newTracker() throws Exception
	{
		Class<?> catalogClass = cls("data", "BossCatalog");
		String path = this == ORIGINAL ? "/legacy/expecteddrops/bosses.json" : "/com/onrate/bosses.json";
		try (java.io.Reader reader = new java.io.InputStreamReader(Side.class.getResourceAsStream(path),
			java.nio.charset.StandardCharsets.UTF_8))
		{
			catalog = catalogClass.getMethod("load", Gson.class, java.io.Reader.class).invoke(null, new Gson(), reader);
		}
		tracker = cls("tracking", "Tracker").getConstructor(catalogClass).newInstance(catalog);
		accounts.clear();
		account = "main";
		return tracker;
	}

	/**
	 * Runs one step of a simulated player: a public tracker method, or one of the steps that need this
	 * side's own objects (removing an entry from History, switching account).
	 */
	Object apply(Sim.Op op)
	{
		switch (op.method)
		{
			case "SWITCH":
				switchAccount((String) op.args[0]);
				return "switched to " + op.args[0];
			case "REMOVE_HISTORY":
				return removeFromHistory((String) op.args[0], (Integer) op.args[1]);
			default:
				return call(op.method, op.args);
		}
	}

	/** Removes the first drop of the n-th History line that has one, as the panel's menu would. */
	private Object removeFromHistory(String boss, int n)
	{
		List<?> rows = (List<?>) call("history", boss);
		List<Object> withDrops = new ArrayList<>();
		for (Object row : rows)
		{
			Object kill = callOn(row, "getKill");
			if (!((List<?>) callOn(kill, "getDrops")).isEmpty())
			{
				withDrops.add(kill);
			}
		}
		if (withDrops.isEmpty())
		{
			return "nothing to remove";
		}
		Object kill = withDrops.get(n % withDrops.size());
		Object drop = ((List<?>) callOn(kill, "getDrops")).get(0);
		return call("removeFromHistory", boss, kill, drop);
	}

	/**
	 * What the plugin does when another account logs in: save this one as the profile store does (the
	 * main data, then each changed History and raid list, a null meaning "remove"), then load the other
	 * one the same way (state, then every boss's History, then every raid's records).
	 */
	private void switchAccount(String to)
	{
		saveAccount();
		account = to;
		loadAccount(accounts.computeIfAbsent(to, k -> new java.util.HashMap<>()));
	}

	/** Saves the current account into its store, as the profile store does, and returns that store. */
	java.util.Map<String, String> saveAccount()
	{
		Object save = call("saveData", (java.util.function.Function<Object, String>) gson::toJson);
		java.util.Map<String, String> store = accounts.computeIfAbsent(account, k -> new java.util.HashMap<>());
		try
		{
			@SuppressWarnings("unchecked") java.util.Map<String, String> kills = (java.util.Map<String, String>) save.getClass().getField("kills").get(save);
			@SuppressWarnings("unchecked") java.util.Map<String, String> raids = (java.util.Map<String, String>) save.getClass().getField("raids").get(save);
			for (java.util.Map.Entry<String, String> e : kills.entrySet())
			{
				if (e.getValue() == null)
				{
					store.remove("kills." + e.getKey());
				}
				else
				{
					store.put("kills." + e.getKey(), e.getValue());
				}
			}
			for (java.util.Map.Entry<String, String> e : raids.entrySet())
			{
				if (e.getValue() == null)
				{
					store.remove("raids." + e.getKey());
				}
				else
				{
					store.put("raids." + e.getKey(), e.getValue());
				}
			}
			store.put("progress", (String) save.getClass().getField("progress").get(save));
		}
		catch (ReflectiveOperationException e)
		{
			throw new IllegalStateException(e);
		}
		return store;
	}

	/** Loads an account from a store, as the profile store does: state, then every History, then every raid list. */
	void loadAccount(java.util.Map<String, String> next)
	{
		String json = next.get("progress");
		call("setState", json == null || json.isEmpty() ? null : gson.fromJson(json, cls("tracking", "TrackerState")));
		java.lang.reflect.Type killList = com.google.gson.reflect.TypeToken.getParameterized(List.class, cls("tracking", "KillEntry")).getType();
		java.lang.reflect.Type raidList = com.google.gson.reflect.TypeToken.getParameterized(List.class, cls("tracking", "RaidRecord")).getType();
		List<?> bosses = (List<?>) callOn(catalog, "getBosses");
		for (Object boss : bosses)
		{
			String name = (String) callOn(boss, "getName");
			String kills = next.get("kills." + name);
			if (kills != null && !kills.isEmpty())
			{
				call("setKills", name, gson.fromJson(kills, killList));
			}
		}
		for (Object boss : bosses)
		{
			if (callOn(boss, "getRaid") == null)
			{
				continue;
			}
			String name = (String) callOn(boss, "getName");
			String raids = next.get("raids." + name);
			if (raids != null && !raids.isEmpty())
			{
				call("setRaids", name, gson.fromJson(raids, raidList));
			}
		}
	}

	/** Calls a public method of the tracker, converting the argument wrappers to this side's types. */
	Object call(String method, Object... args)
	{
		return callOn(tracker, method, args);
	}

	Object callStatic(String sub, String type, String method, Object... args)
	{
		return callOn(cls(sub, type), method, args);
	}

	Object callOn(Object target, String method, Object... args)
	{
		boolean isClass = target instanceof Class;
		Class<?> type = isClass ? (Class<?>) target : target.getClass();
		Object[] converted = new Object[args.length];
		for (int i = 0; i < args.length; i++)
		{
			converted[i] = convert(args[i]);
		}
		for (Method m : type.getMethods())
		{
			if (!m.getName().equals(method) || m.getParameterCount() != args.length || !fits(m, converted))
			{
				continue;
			}
			if (isClass && !Modifier.isStatic(m.getModifiers()))
			{
				continue;
			}
			try
			{
				return m.invoke(isClass ? null : target, converted);
			}
			catch (InvocationTargetException e)
			{
				Throwable cause = e.getCause();
				if (cause instanceof RuntimeException)
				{
					throw (RuntimeException) cause;
				}
				throw new IllegalStateException(cause);
			}
			catch (IllegalAccessException e)
			{
				throw new IllegalStateException(e);
			}
		}
		throw new IllegalArgumentException("No " + method + "/" + args.length + " on " + type.getName());
	}

	private Object convert(Object arg)
	{
		try
		{
			if (arg instanceof Raid)
			{
				Raid r = (Raid) arg;
				return callOn(cls("tracking", "RaidRecord"), r.factory, r.args);
			}
			if (arg instanceof Settings)
			{
				return settingsProxy((Settings) arg);
			}
			if (arg instanceof List && (((List<?>) arg).isEmpty() || ((List<?>) arg).get(0) instanceof Loot))
			{
				List<Object> items = new ArrayList<>();
				Class<?> lootClass = cls("tracking", "Tracker$LootItem");
				for (Object l : (List<?>) arg)
				{
					Loot loot = (Loot) l;
					items.add(lootClass.getConstructor(String.class, int.class).newInstance(loot.name, loot.quantity));
				}
				return items;
			}
		}
		catch (ReflectiveOperationException e)
		{
			throw new IllegalStateException(e);
		}
		return arg;
	}

	private boolean fits(Method m, Object[] args)
	{
		Class<?>[] types = m.getParameterTypes();
		for (int i = 0; i < types.length; i++)
		{
			Object a = args[i];
			Class<?> t = types[i];
			if (a == null)
			{
				if (t.isPrimitive())
				{
					return false;
				}
				continue;
			}
			if (t.isPrimitive())
			{
				if (!primitiveFits(t, a))
				{
					return false;
				}
			}
			else if (!t.isInstance(a))
			{
				return false;
			}
		}
		return true;
	}

	private static boolean primitiveFits(Class<?> t, Object a)
	{
		return t == int.class && a instanceof Integer || t == long.class && a instanceof Long
			|| t == double.class && a instanceof Double || t == boolean.class && a instanceof Boolean;
	}

	/** This side's RaidSettings for these settings (for building its panel). */
	Object raidSettings(Settings s)
	{
		return settingsProxy(s);
	}

	private Object settingsProxy(Settings s)
	{
		Class<?> iface = cls("stats", "RaidSettings");
		InvocationHandler handler = (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "uniqueChance":
					switch ((String) args[0])
					{
						case "cox": return s.cox;
						case "coxCm": return s.coxCm;
						case "tob": return s.tob;
						case "tobHm": return s.tobHm;
						case "toaEntry": return s.toaEntry;
						case "toa": return s.toa;
						case "toaExpert": return s.toaExpert;
						case "fractured": return s.fractured;
						default: return 0.0;
					}
				case "teamSize":
					String raid = (String) args[0];
					return raid.startsWith("tob") ? s.tobTeam : "fractured".equals(raid) ? s.tfaTeam : 1;
				case "tfaBaseChance":
					return 1 / 14.0;
				case "contribution":
					return "royalTitans".equals(args[0]) || "yama".equals(args[0]) ? 1.0 - 0.5 * s.duoShare : 1.0;
				case "contributionNote":
					return null;
				case "learnedRaids":
					// the parity settings are fixed: nothing learned from recorded raids
					return 0;
				case "toString":
					return "settings";
				case "hashCode":
					return System.identityHashCode(proxy);
				case "equals":
					return proxy == args[0];
				default:
					throw new UnsupportedOperationException(method.getName());
			}
		};
		return Proxy.newProxyInstance(iface.getClassLoader(), new Class<?>[]{iface}, handler);
	}
}

package com.onrate.parity;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.BossPart;
import com.onrate.engine.data.DropDefinition;
import com.onrate.engine.math.Rates;
import com.onrate.parity.Side.Loot;
import com.onrate.parity.Side.Raid;
import com.onrate.parity.Side.Settings;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Random;

/**
 * Plays a plausible player: kills at bosses with drops rolled from the real drop rates, raids with
 * points, delves, colosseum runs, reward rolls, collection log visits, and the odd manual
 * correction. The output is a script of operations that is replayed on both implementations.
 */
final class Sim
{
	/** One step of the script. */
	static final class Op
	{
		final String method;
		final Object[] args;

		Op(String method, Object... args)
		{
			this.method = method;
			this.args = args;
		}

		@Override
		public String toString()
		{
			return method + Arrays.deepToString(args);
		}
	}

	static final long BASE = 1_700_000_000_000L;
	static final String PET_MESSAGE = "You have a funny feeling like you're being followed.";

	final Random r;
	final BossCatalog catalog;
	final List<Op> ops = new ArrayList<>();
	/** Names of bosses touched, for the observations. */
	final List<String> touched = new ArrayList<>();
	Settings settings = new Settings();
	long t = BASE;
	/** Items received per boss page, for the collection log pages. */
	private final Map<String, Map<String, Integer>> got = new LinkedHashMap<>();
	private final Map<String, Map<String, Integer>> counters = new LinkedHashMap<>();

	Sim(long seed, BossCatalog catalog)
	{
		this.r = new Random(seed);
		this.catalog = catalog;
	}

	private void op(String method, Object... args)
	{
		ops.add(new Op(method, args));
	}

	private void tick(int seconds)
	{
		t += seconds * 1000L + r.nextInt(900);
	}

	private static String commas(int n)
	{
		return String.format(Locale.ROOT, "%,d", n);
	}

	private void kcMessage(String name, int kc)
	{
		String[] styles = {"Your %s kill count is: <col=ff0000>%s</col>.", "Your completed %s count is: <col=ff0000>%s</col>.",
			"Your completion count for %s is: <col=ff0000>%s</col>.", "Your %s completion count is: <col=ff0000>%s</col>."};
		op("onChatMessage", String.format(Locale.ROOT, styles[r.nextInt(styles.length)], name, commas(kc)), t);
	}

	/** Items one kill gives: each drop rolled at (boosted) rate so a short run still sees some. */
	private List<Loot> rollLoot(BossDefinition boss, BossPart part, double boost)
	{
		List<Loot> items = new ArrayList<>();
		for (DropDefinition d : boss.getDrops())
		{
			double rate;
			if (d.hasPartRates() && part != null)
			{
				rate = Rates.parse(d.getPartRate(part.getName()));
			}
			else if (d.getRate() != null)
			{
				rate = Rates.parse(d.getRate());
			}
			else
			{
				rate = 1 / 400.0;
			}
			if (r.nextDouble() < Math.min(0.35, rate * boost))
			{
				List<String> names = d.getAllNames();
				items.add(new Loot(names.get(r.nextInt(names.size())), 1));
			}
		}
		// items several bosses share are kept apart from the boss's own drops by the catalogue: roll them too
		for (DropDefinition d : catalog.poolsOf(boss).values())
		{
			double rate = d.getRate() != null ? Rates.parse(d.getRate())
				: part != null && d.hasPartRates() ? Rates.parse(d.getPartRate(part.getName())) : 1 / 400.0;
			if (r.nextDouble() < Math.min(0.2, rate * boost))
			{
				items.add(new Loot(d.getName(), 1));
			}
		}
		if (r.nextInt(3) == 0)
		{
			items.add(new Loot("Bones", 1 + r.nextInt(3)));
		}
		return items;
	}

	private void count(String page, List<Loot> items)
	{
		Map<String, Integer> m = got.computeIfAbsent(page, k -> new LinkedHashMap<>());
		for (Loot l : items)
		{
			if (!"Bones".equals(l.name))
			{
				m.merge(l.name, 1, Integer::sum);
			}
		}
	}

	private void maybeTime(boolean raid)
	{
		if (!raid && r.nextInt(6) == 0)
		{
			op("onTimeMessage", String.format(Locale.ROOT, "Fight duration: <col=ff0000>%d:%02d.40</col>.", 1 + r.nextInt(3), r.nextInt(60)),
				r.nextBoolean() ? t - 200 : t + 500);
			return;
		}
		if (r.nextInt(3) == 0)
		{
			int m = 1 + r.nextInt(raid ? 40 : 4);
			op("onChatMessage", String.format(Locale.ROOT, raid ? "Challenge duration: <col=ff0000>%d:%02d.40</col>." : "Fight duration: <col=ff0000>%d:%02d.20</col>.",
				m, r.nextInt(60)), t + 100);
		}
	}

	/** Plays one boss for a number of kills. */
	void playBoss(BossDefinition boss)
	{
		touched.add(boss.getName());
		int n = 12 + r.nextInt(70);
		if (boss.isDelve())
		{
			playDelve(boss, n);
		}
		else if (boss.getWaves() > 0)
		{
			playWaves(boss, n);
		}
		else if (boss.getRollsPerKill() > 0)
		{
			playRolls(boss, n);
		}
		else if (boss.getRaid() != null)
		{
			playRaid(boss, Math.max(4, n / 4));
		}
		else
		{
			playKills(boss, n);
		}
		// a collection log visit: counters and what the log shows
		if (r.nextInt(4) != 0 && !boss.getClogPages().isEmpty())
		{
			visitLog(boss);
		}
		op("OBSERVE");
	}

	private void playKills(BossDefinition boss, int n)
	{
		int[] kc = new int[Math.max(1, boss.getParts().size())];
		for (int i = 0; i < n; i++)
		{
			tick(20 + r.nextInt(60));
			BossPart part = boss.hasParts() ? boss.getParts().get(r.nextInt(boss.getParts().size())) : null;
			int idx = part == null ? 0 : boss.getParts().indexOf(part);
			kc[idx]++;
			List<String> kcNames = part != null ? part.getKcNames() : boss.getKcNames();
			List<String> lootNames = part != null ? part.getLootNames() : boss.getLootNames();
			if (boss.isDetectTeam() && r.nextInt(4) == 0)
			{
				op("SET_TEAM", 1 + r.nextInt(6));
			}
			List<Loot> items = rollLoot(boss, part, 6);
			counters.computeIfAbsent(boss.getName(), k -> new LinkedHashMap<>()).merge(kcNames.isEmpty() ? "?" : kcNames.get(0), 1, Integer::sum);
			if (!kcNames.isEmpty())
			{
				kcMessage(kcNames.get(r.nextInt(kcNames.size())), kc[idx]);
			}
			maybeTime(false);
			if (!lootNames.isEmpty())
			{
				if (!boss.getMinionLoot().isEmpty() && r.nextInt(3) == 0)
				{
					op("onLoot", boss.getMinionLoot().get(0), 1, Collections.singletonList(new Loot("Bones", 1)), t + 250);
				}
				op("onLoot", lootNames.get(0), 1, items, t + 300);
			}
			count(boss.getName(), items);
			for (Loot l : items)
			{
				DropDefinition d = find(boss, l.name);
				if (d != null && d.isPet())
				{
					op("onChatMessage", PET_MESSAGE, t + 400);
				}
			}
			if (r.nextInt(25) == 0)
			{
				// a shared item from a monster that isn't a boss
				op("onOtherLoot", "Blue dragon", Collections.singletonList(new Loot(r.nextBoolean() ? "Draconic visage" : "Dragon chainbody", 1)));
			}
		}
	}

	private static DropDefinition find(BossDefinition boss, String item)
	{
		for (DropDefinition d : boss.getDrops())
		{
			if (d.getAllNames().contains(item))
			{
				return d;
			}
		}
		return null;
	}

	private void playRaid(BossDefinition boss, int raids)
	{
		int[] kc = new int[boss.getParts().size()];
		for (int i = 0; i < raids; i++)
		{
			tick(1500 + r.nextInt(1500));
			int p = r.nextInt(boss.getParts().size());
			BossPart part = boss.getParts().get(p);
			kc[p]++;
			boolean purple = r.nextInt(5) == 0;
			List<Loot> items = purple ? rollLoot(boss, part, 40) : new ArrayList<>();
			Raid record = null;
			switch (boss.getRaid())
			{
				case "cox":
					int team = 1 + r.nextInt(6);
					int mine = 12_000 + r.nextInt(40_000);
					record = new Raid("cox", mine, mine + (team - 1) * (10_000 + r.nextInt(30_000)), team);
					break;
				case "toa":
					int size = 1 + r.nextInt(4);
					int level = new int[]{0, 150, 250, 300, 350, 420, 500}[r.nextInt(7)];
					record = r.nextBoolean() ? new Raid("toaExact", 4_000 + r.nextInt(30_000), size, level)
						: new Raid("toa", 4_000 + r.nextInt(20_000), r.nextInt(8_000), r.nextBoolean() ? 0 : 30_000 + r.nextInt(30_000), size, level);
					break;
				case "tob":
					record = new Raid("tob", 1 + r.nextInt(5), r.nextInt(3), r.nextInt(4), r.nextBoolean() ? Boolean.TRUE : Boolean.FALSE);
					break;
				case "fractured":
					record = new Raid("fractured", 1 + r.nextInt(6), r.nextInt(3), r.nextBoolean() ? -1.0 : 80 + r.nextInt(500));
					break;
				default:
					break;
			}
			String name = part.getKcNames().get(0);
			boolean pointsFirst = r.nextBoolean();
			if ("toa".equals(boss.getRaid()) && r.nextInt(4) == 0)
			{
				// the Tombs of Amascut plugin's party total can come before the raid's own data
				op("onPartyPoints", 3_000 + r.nextInt(30_000), 40_000 + r.nextInt(40_000), t - 400);
			}
			if (record != null && pointsFirst)
			{
				op("onRaidRecord", record, t);
			}
			op("onChatMessage", String.format(Locale.ROOT, "Your completed %s count is: <col=ff0000>%s</col>.", name, commas(kc[p])), t + 800);
			if (record != null && !pointsFirst)
			{
				op("onRaidRecord", record, t + 1500);
			}
			maybeTime(true);
			raidExtras(boss, part, record, t);
			if (!boss.getLootNames().isEmpty())
			{
				op("onLoot", boss.getLootNames().get(0), 1, items, t + 2500);
			}
			count(boss.getName(), items);
			for (Loot l : items)
			{
				DropDefinition d = find(boss, l.name);
				if (d != null && d.isPet())
				{
					op("onChatMessage", PET_MESSAGE, t + 3000);
				}
			}
		}
	}

	/**
	 * What can follow a raid's completion: the exact Tombs points or the party total (after the raid data),
	 * a time-only message before or after the completion count, and times imported from another plugin.
	 */
	private void raidExtras(BossDefinition boss, BossPart part, Raid record, long at)
	{
		if ("toa".equals(boss.getRaid()))
		{
			switch (r.nextInt(4))
			{
				case 0:
					op("onToaPoints", 2_000 + r.nextInt(40_000), at + 2_000 + r.nextInt(3_000));
					break;
				case 1:
					op("onPartyPoints", 3_000 + r.nextInt(30_000), 40_000 + r.nextInt(40_000), at + 2_000 + r.nextInt(60_000));
					break;
				case 2:
					// too late to belong to this raid
					op("onToaPoints", 2_000 + r.nextInt(40_000), at + 3 * 60_000);
					break;
				default:
					break;
			}
		}
		if (r.nextInt(3) == 0)
		{
			int minutes = 10 + r.nextInt(40);
			String text = "cox".equals(boss.getRaid())
				? String.format(Locale.ROOT, "Congratulations - your raid is complete! Team size: 3 players Duration: %d:%02d.20", minutes, r.nextInt(60))
				: String.format(Locale.ROOT, "%s total completion time: %d:%02d.40", boss.getName(), minutes, r.nextInt(60));
			// time-only messages come either side of the completion count
			op("onTimeMessage", text, r.nextBoolean() ? at + 300 : at + 1_200);
		}
		if (r.nextInt(5) == 0)
		{
			List<long[]> samples = new ArrayList<>();
			// one that is this raid (ends within a few minutes of it), one older, one repeated
			samples.add(new long[]{at + 800 + r.nextInt(120_000), (15 + r.nextInt(30)) * 60_000L});
			long old = at - (2 + r.nextInt(30)) * 86_400_000L;
			samples.add(new long[]{old, (20 + r.nextInt(30)) * 60_000L});
			samples.add(new long[]{old, (20 + r.nextInt(30)) * 60_000L});
			op("importRaidTimes", boss.getName(), part.getName(), samples);
		}
	}

	private void playDelve(BossDefinition boss, int n)
	{
		Map<Integer, Integer> totals = new LinkedHashMap<>();
		for (int i = 0; i < n; i++)
		{
			tick(120 + r.nextInt(200));
			int level = 1 + r.nextInt(9);
			totals.merge(level, 1, Integer::sum);
			String shown = level >= 9 ? "8+ (" + (9 + r.nextInt(6)) + ")" : String.valueOf(level);
			op("onChatMessage", "Delve level: " + shown + " duration: <col=ff0000>" + (1 + r.nextInt(3)) + ":" + String.format("%02d", r.nextInt(60)) + ".20</col>", t);
			List<Loot> items = rollLoot(boss, null, 8);
			op("onLoot", boss.getLootNames().get(0), 1, items, t + 400);
			count(boss.getName(), items);
		}
		if (r.nextBoolean())
		{
			Map<Integer, Integer> scoreboard = new LinkedHashMap<>();
			for (Map.Entry<Integer, Integer> e : totals.entrySet())
			{
				scoreboard.put(e.getKey(), e.getValue() + r.nextInt(3));
			}
			op("onDelveScoreboard", scoreboard);
		}
	}

	private void playWaves(BossDefinition boss, int n)
	{
		for (int i = 0; i < Math.max(4, n / 4); i++)
		{
			tick(600 + r.nextInt(600));
			int wave = 4 + r.nextInt(boss.getWaves() - 3);
			for (int w = 1; w <= wave; w++)
			{
				op("onWaveCompleted", w);
			}
			List<Loot> items = rollLoot(boss, null, 60);
			if (wave == boss.getWaves())
			{
				items.add(new Loot("Dizana's quiver (uncharged)", 1));
			}
			op("onLoot", boss.getLootNames().get(0), 1, items, t);
			count(boss.getName(), items);
		}
	}

	private void playRolls(BossDefinition boss, int n)
	{
		int subdues = 50 + r.nextInt(200);
		op("onRollBaseline", boss.getName(), subdues, r.nextInt(30));
		for (int i = 0; i < n; i++)
		{
			tick(300 + r.nextInt(300));
			op("onRewardRolls", boss.getName(), 1 + r.nextInt(4), t);
			List<Loot> items = rollLoot(boss, null, 25);
			op("onLoot", boss.getLootNames().get(0), 1, items, t + 100);
			count(boss.getName(), items);
		}
	}

	private void visitLog(BossDefinition boss)
	{
		Map<String, Integer> page = new LinkedHashMap<>();
		Map<String, Integer> seen = got.getOrDefault(boss.getName(), Collections.emptyMap());
		for (DropDefinition d : boss.getDrops())
		{
			int extra = r.nextInt(6) == 0 ? 1 + r.nextInt(2) : 0;
			page.put(d.getName(), (seen.getOrDefault(d.getName(), 0) + extra) * (d.isOnce() ? 1 : 1));
		}
		for (DropDefinition d : catalog.poolsOf(boss).values())
		{
			int fromAll = 0;
			for (Map<String, Integer> other : got.values())
			{
				fromAll += other.getOrDefault(d.getName(), 0);
			}
			// sometimes copies On Rate never saw (from before it, or other monsters)
			page.put(d.getName(), fromAll + (r.nextInt(3) == 0 ? 1 + r.nextInt(2) : 0));
		}
		List<String> lines = new ArrayList<>();
		Map<String, Integer> kcs = counters.getOrDefault(boss.getName(), Collections.emptyMap());
		int extraKc = 20 + r.nextInt(300);
		if (boss.hasParts())
		{
			for (BossPart part : boss.getParts())
			{
				lines.add(part.getKcNames().get(0) + " kills: " + (extraKc + r.nextInt(50)));
			}
		}
		else
		{
			lines.add(boss.getName() + " kills: " + (extraKc + kcs.values().stream().mapToInt(Integer::intValue).sum()));
		}
		op("onClogPage", boss.getClogPages().get(0), lines, page);
	}

	/** One of the shared items this boss drops, or null. */
	private String pickPoolItem(BossDefinition boss)
	{
		List<DropDefinition> pooled = new ArrayList<>(catalog.poolsOf(boss).values());
		return pooled.isEmpty() ? null : pooled.get(r.nextInt(pooled.size())).getName();
	}

	/**
	 * Logs into another account, plays a little there, and comes back: what the plugin does on a profile
	 * change (save this account, load the other). Nothing of one account may show in the other.
	 */
	void switchAway()
	{
		op("SWITCH", "alt");
		op("OBSERVE");
		if (!touched.isEmpty())
		{
			BossDefinition boss = catalog.byName(touched.get(r.nextInt(touched.size())));
			if (boss.getRaid() == null && !boss.isDelve() && boss.getWaves() == 0 && boss.getRollsPerKill() == 0)
			{
				playKills(boss, 3 + r.nextInt(8));
			}
		}
		op("OBSERVE");
		op("SWITCH", "main");
		op("OBSERVE");
	}

	/** A few manual corrections and setting changes at random. */
	void sprinkle()
	{
		for (int i = 0; i < 6; i++)
		{
			if (touched.isEmpty())
			{
				return;
			}
			BossDefinition boss = catalog.byName(touched.get(r.nextInt(touched.size())));
			if (boss.getDrops().isEmpty())
			{
				continue;
			}
			DropDefinition drop = boss.getDrops().get(r.nextInt(boss.getDrops().size()));
			switch (r.nextInt(7))
			{
				case 0:
					op("setLeftOut", boss.getName(), drop.getName(), r.nextBoolean());
					break;
				case 1:
					op("addPastDrop", boss.getName(), drop.getName(), 1 + r.nextInt(30), r.nextBoolean());
					break;
				case 2:
					settings = new Settings();
					settings.duoShare = r.nextDouble();
					settings.tobTeam = 1 + r.nextInt(5);
					settings.tfaTeam = 1 + r.nextInt(8);
					settings.cox = 0.02 + r.nextDouble() * 0.06;
					op("SET_SETTINGS", settings);
					break;
				case 3:
					String key = catalog.poolOf(boss, pickPoolItem(boss));
					if (key != null)
					{
						List<BossCatalog.PoolSource> sources = catalog.getPools().get(key);
						String from = r.nextInt(4) == 0 ? "*not from a boss" : sources.get(r.nextInt(sources.size())).getBoss().getName();
						if (r.nextInt(5) == 0)
						{
							op("unsplitPool", key);
						}
						else
						{
							op("splitPool", key, from);
						}
					}
					break;
				case 4:
					op("resetTrip");
					break;
				case 5:
					op("setLeftOut", boss.getName(), drop.getName(), false);
					break;
				default:
					op("onOtherLoot", "Smoke devil", Collections.singletonList(new Loot("Occult necklace", 1)));
					break;
			}
			if (r.nextInt(3) == 0)
			{
				op("REMOVE_HISTORY", boss.getName(), r.nextInt(5));
			}
		}
		// judge one shared item per boss, where a played boss has any
		for (String name : touched)
		{
			BossDefinition boss = catalog.byName(name);
			String key = catalog.poolOf(boss, pickPoolItem(boss));
			if (key != null)
			{
				op("splitPool", key, r.nextInt(3) == 0 ? "*not from a boss" : name);
				op("OBSERVE");
				break;
			}
		}
		if (r.nextInt(2) == 0)
		{
			switchAway();
		}
		op("OBSERVE");
	}
}

package com.onrate.parity;

import static org.junit.Assert.assertTrue;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.Bundled;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.ToIntFunction;
import org.junit.Test;

/**
 * The simulated players must really reach the paths the equivalence tests are meant to guard: a
 * Tombs points message that never matches a raid, or a History removal that never finds an entry,
 * would be compared on both sides and still prove nothing. This counts the steps that had an effect.
 */
public class SimCoverageTest
{
	@Test
	public void everyNewKindOfEventTakesEffectSomewhere() throws Exception
	{
		BossCatalog catalog = Bundled.catalog(new com.google.gson.Gson());
		List<BossDefinition> bosses = new ArrayList<>(catalog.getBosses());
		Map<String, int[]> tally = new TreeMap<>();
		for (int seed = 0; seed < 28; seed++)
		{
			Sim sim = new Sim(1000 + seed, catalog);
			for (int i = 0; i < 6; i++)
			{
				sim.playBoss(bosses.get((seed * 5 + i * 11) % bosses.size()));
			}
			sim.sprinkle();
			tally(sim, tally);
		}
		for (String raid : new String[]{"Tombs of Amascut", "Chambers of Xeric", "Theatre of Blood", "The Fractured Archive"})
		{
			for (int run = 0; run < 6; run++)
			{
				Sim sim = new Sim(88000 + run * 7 + raid.length(), catalog);
				sim.playBoss(catalog.byName(raid));
				sim.playBoss(catalog.byName(raid));
				sim.sprinkle();
				tally(sim, tally);
			}
		}
		StringBuilder report = new StringBuilder();
		tally.forEach((k, v) -> report.append(String.format("%n  %-32s %4d sent, %4d took effect", k, v[0], v[1])));
		System.out.println("simulator coverage:" + report);
		for (String kind : new String[]{"onToaPoints", "onPartyPoints", "onTimeMessage", "importRaidTimes", "REMOVE_HISTORY", "SWITCH",
			"onRaidRecord", "onClogPage", "addPastDrop", "splitPool"})
		{
			int[] v = tally.get(kind);
			assertTrue(kind + " never took effect: " + report, v != null && v[1] > 0);
		}
	}

	private static void tally(Sim sim, Map<String, int[]> tally) throws Exception
	{
		Side side = Side.REBUILT;
		side.newTracker();
		side.call("setSettings", sim.settings);
		AtomicInteger team = new AtomicInteger();
		side.call("setTeamSizeDetectorFor", (ToIntFunction<String>) b -> team.get());
		for (Sim.Op op : sim.ops)
		{
			if (op.method.equals("SET_TEAM"))
			{
				team.set((Integer) op.args[0]);
				continue;
			}
			if (op.method.equals("SET_SETTINGS"))
			{
				side.call("setSettings", op.args[0]);
				continue;
			}
			if (op.method.equals("OBSERVE"))
			{
				continue;
			}
			Object result;
			try
			{
				result = side.apply(op);
			}
			catch (RuntimeException e)
			{
				result = null;
			}
			int[] v = tally.computeIfAbsent(op.method, k -> new int[2]);
			v[0]++;
			if (tookEffect(op.method, result))
			{
				v[1]++;
			}
		}
	}

	private static boolean tookEffect(String method, Object result)
	{
		if (result == null || Boolean.FALSE.equals(result) || "nothing to remove".equals(result))
		{
			return false;
		}
		if (result instanceof Integer)
		{
			return (Integer) result > 0;
		}
		if (result instanceof java.util.Collection)
		{
			return !((java.util.Collection<?>) result).isEmpty();
		}
		return true;
	}
}

package com.onrate.parity;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.Bundled;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.ToIntFunction;
import java.util.function.ToLongFunction;
import org.junit.Test;

/**
 * Every sentence and number the panel prints comes from {@code Texts} and {@code ShareText}. The
 * integrated plugin keeps the original UI classes, now running on the new engine: for the same
 * input they must print exactly the same strings as the original.
 */
public class TextsParityTest
{
	private static final Class<?> OLD = load("legacy.expecteddrops.ui.Texts");
	private static final Class<?> NEW = load("com.expecteddrops.ui.Texts");
	private static long compared;

	private static Class<?> load(String name)
	{
		try
		{
			return Class.forName(name);
		}
		catch (ClassNotFoundException e)
		{
			throw new IllegalStateException(e);
		}
	}

	private static Object call(Class<?> type, String method, Class<?>[] sig, Object... args) throws Exception
	{
		Method m = type.getDeclaredMethod(method, sig);
		m.setAccessible(true);
		return m.invoke(null, args);
	}

	/** Calls the same function on both, with arguments built for each side, and compares the result. */
	private static void same(String method, Class<?>[] oldSig, Object[] oldArgs, Class<?>[] newSig, Object[] newArgs) throws Exception
	{
		Object a = call(OLD, method, oldSig, oldArgs);
		Object b = call(NEW, method, newSig, newArgs);
		compared++;
		assertEquals(method + Arrays.deepToString(newArgs), a, b);
	}

	private static void same(String method, Class<?>[] sig, Object... args) throws Exception
	{
		same(method, sig, args, sig, args);
	}

	private static legacy.expecteddrops.stats.RowStats oldRow(double rate, double e, int got, Integer streak, boolean exact, int cap)
	{
		legacy.expecteddrops.stats.RowStats r = new legacy.expecteddrops.stats.RowStats("Item", "Item", rate, e, got, false).withStreak(streak, exact);
		return cap > 0 ? r.capped(cap, Math.min(got, cap)) : r;
	}

	private static com.onrate.engine.stats.RowStats newRow(double rate, double e, int got, Integer streak, boolean exact, int cap)
	{
		com.onrate.engine.stats.RowStats r = new com.onrate.engine.stats.RowStats("Item", "Item", rate, e, got, false).withStreak(streak, exact);
		return cap > 0 ? r.capped(cap, Math.min(got, cap)) : r;
	}

	private static double[] values()
	{
		List<Double> list = new ArrayList<>();
		for (double e = 0.0004; e < 400; e *= 1.45)
		{
			list.add(e);
		}
		list.addAll(Arrays.asList(0.0, 0.5, 1.0, 0.099, 0.1, 0.35, 0.45, 0.55, 0.65, 0.9, 0.99, 0.995, 0.9999, Double.NaN));
		return list.stream().mapToDouble(Double::doubleValue).toArray();
	}

	@Test
	public void numberFormatsAndLuckWordsAreIdentical() throws Exception
	{
		Class<?>[] d = {double.class};
		for (double v : values())
		{
			same("formatExpected", d, v);
			same("formatMultiple", d, v);
			same("formatPercent", d, v);
			same("pct", d, v);
			same("sharePct", d, v);
			same("luckShort", d, v);
			same("luckPercent", d, v);
			same("plainLuck", d, v);
			same("waitLuck", d, v);
			same("waitLuckShort", new Class<?>[]{double.class, boolean.class}, v, true);
			same("waitLuckShort", new Class<?>[]{double.class, boolean.class}, v, false);
			for (int kills : new int[]{0, 1, 50, 1000})
			{
				same("nextChance", new Class<?>[]{double.class, int.class}, v / 1000, kills);
			}
		}
	}

	@Test
	public void sentencesAboutRowsAreIdentical() throws Exception
	{
		Class<?>[] oldSig = {legacy.expecteddrops.stats.RowStats.class};
		Class<?>[] newSig = {com.onrate.engine.stats.RowStats.class};
		for (double e : values())
		{
			if (Double.isNaN(e))
			{
				continue;
			}
			for (int got = 0; got <= 40; got += got < 6 ? 1 : 9)
			{
				for (int cap : new int[]{0, 1, 2})
				{
					for (Integer streak : new Integer[]{null, 0, 37, 2400})
					{
						for (boolean exact : new boolean[]{true, false})
						{
							legacy.expecteddrops.stats.RowStats o = oldRow(1 / 512.0, e, got, streak, exact, cap);
							com.onrate.engine.stats.RowStats n = newRow(1 / 512.0, e, got, streak, exact, cap);
							Object[] oa = {o};
							Object[] na = {n};
							same("streakText", oldSig, oa, newSig, na);
							same("rateMultiple", oldSig, oa, newSig, na);
							same("rateMultipleLine", oldSig, oa, newSig, na);
							same("gotOfExpected", oldSig, oa, newSig, na);
							same("haveText", oldSig, oa, newSig, na);
							same("isQuiet", oldSig, oa, newSig, na);
							same("streakNote", new Class<?>[]{oldSig[0], String.class}, new Object[]{o, "kill"},
								new Class<?>[]{newSig[0], String.class}, new Object[]{n, "kill"});
							double[] shares = n.getShares();
							assertEquals(Arrays.toString(o.getShares()), Arrays.toString(shares));
							Class<?>[] s = {double[].class, int.class};
							same("luckShort", s, shares, got);
							same("luckPercent", s, shares, got);
							same("sharesLine", s, shares, got);
						}
					}
				}
			}
		}
	}

	@Test
	public void notableLinesAndSmallHelpersAreIdentical() throws Exception
	{
		List<legacy.expecteddrops.stats.RowStats> olds = new ArrayList<>();
		List<com.onrate.engine.stats.RowStats> news = new ArrayList<>();
		for (double e : new double[]{0.05, 0.4, 1.0, 2.6, 5.0, 12.0})
		{
			for (int got : new int[]{0, 1, 4, 9})
			{
				olds.add(oldRow(0.01, e, got, null, true, 0));
				news.add(newRow(0.01, e, got, null, true, 0));
			}
		}
		for (int i = 0; i < olds.size(); i++)
		{
			int to = Math.min(olds.size(), i + 5);
			same("notableLine", new Class<?>[]{List.class}, new Object[]{olds.subList(i, to)}, new Class<?>[]{List.class},
				new Object[]{news.subList(i, to)});
		}
		for (String name : new String[]{"Tumeken's shadow", "Elder maul", "Bandos boots", "", "Onyx"})
		{
			same("withArticle", new Class<?>[]{String.class}, name);
		}
		same("joinAnd", new Class<?>[]{List.class}, Arrays.asList("Vorkath", "Zulrah", "Cerberus"));
		same("mainValueSource", new Class<?>[]{List.class, List.class}, Arrays.asList("A", "B"), Arrays.asList(95.0, 5.0));
		System.out.println("texts parity: " + compared + " calls identical");
	}

	@Test
	public void copyMyLuckIsIdentical() throws Exception
	{
		BossCatalog catalog = Bundled.catalog(new com.google.gson.Gson());
		List<BossDefinition> bosses = new ArrayList<>(catalog.getBosses());
		int texts = 0;
		for (int seed = 0; seed < 10; seed++)
		{
			Sim sim = new Sim(41000 + seed, catalog);
			for (int i = 0; i < 6; i++)
			{
				sim.playBoss(bosses.get((seed * 7 + i * 5) % bosses.size()));
			}
			String[] out = new String[2];
			for (int k = 0; k < 2; k++)
			{
				Side side = k == 0 ? Side.ORIGINAL : Side.REBUILT;
				side.newTracker();
				side.call("setSettings", sim.settings);
				AtomicInteger team = new AtomicInteger();
				side.call("setTeamSizeDetectorFor", (ToIntFunction<String>) b -> team.get());
				for (Sim.Op op : sim.ops)
				{
					if (op.method.equals("SET_TEAM"))
					{
						team.set((Integer) op.args[0]);
					}
					else if (!op.method.equals("SET_SETTINGS") && !op.method.equals("OBSERVE"))
					{
						try
						{
							side.apply(op);
						}
						catch (RuntimeException e)
						{
							// identical on both, checked by the replay test
						}
					}
				}
				Object account = side.call("accountStats", sim.settings, (ToLongFunction<String>) n -> 1_000L * Math.abs(n.hashCode() % 977));
				Class<?> share = load(k == 0 ? "legacy.expecteddrops.ui.ShareText" : "com.expecteddrops.ui.ShareText");
				Method m = share.getDeclaredMethod("account", account.getClass(), boolean.class);
				m.setAccessible(true);
				out[k] = (String) m.invoke(null, account, seed % 2 == 0);
			}
			assertEquals("seed " + seed, out[0], out[1]);
			texts += out[0] == null ? 0 : 1;
		}
		assertTrue(texts > 0);
	}
}

package com.onrate.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.AccountStats;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.ToLongFunction;
import org.junit.Test;

public class AccountPrecomputeTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static final RaidSettings RAIDS = raid -> 0.03;
	private static final ToLongFunction<String> PRICES = n -> 1000L + Math.abs(n.hashCode() % 5000);

	private static Tracker tracker()
	{
		Tracker t = new Tracker(Bundled.catalog(new Gson()));
		t.onClogPage("Vorkath", Collections.singletonList("Vorkath kills: 500"), Collections.singletonMap("Vorkath's head", 9));
		t.onClogPage("Zulrah", Collections.singletonList("Zulrah kills: 900"), Collections.singletonMap("Tanzanite fang", 1));
		return t;
	}

	/** Swing stand-in: runs handed-over tasks when asked, on the test thread. */
	private static final class Queue
	{
		final List<Runnable> tasks = new ArrayList<>();

		synchronized void add(Runnable r)
		{
			tasks.add(r);
		}

		void runAll()
		{
			List<Runnable> now;
			synchronized (this)
			{
				now = new ArrayList<>(tasks);
				tasks.clear();
			}
			now.forEach(Runnable::run);
		}
	}

	@Test
	public void theDrawItStartsGetsTheSameNumbersThePanelWouldWorkOut() throws Exception
	{
		Tracker t = tracker();
		ExecutorService worker = Executors.newSingleThreadExecutor();
		Queue swing = new Queue();
		AccountPrecompute pre = new AccountPrecompute(t, worker, swing::add);
		AccountStats[] seen = new AccountStats[1];
		pre.request(RAIDS, PRICES, () -> seen[0] = pre.account(true));
		worker.shutdown();
		assertTrue(worker.awaitTermination(20, TimeUnit.SECONDS));
		swing.runAll();
		assertNotNull(seen[0]);
		AccountStats direct = t.accountStats(RAIDS, PRICES);
		assertEquals(direct.getTotal().getExpected(), seen[0].getTotal().getExpected(), 0);
		assertEquals(direct.getTotal().getReceived(), seen[0].getTotal().getReceived());
		assertEquals(direct.getTotal().getLuck(), seen[0].getTotal().getLuck(), 0);
		assertEquals(direct.getValueLuck(), seen[0].getValueLuck(), 0);
		assertEquals(direct.getRows().size(), seen[0].getRows().size());
		// lent to that draw only: any other draw works it out itself
		assertNull(pre.account(true));
		assertNull(pre.itemTimes());
	}

	@Test
	public void aMismatchedGpSettingIsNotUsed() throws Exception
	{
		Tracker t = tracker();
		ExecutorService worker = Executors.newSingleThreadExecutor();
		Queue swing = new Queue();
		AccountPrecompute pre = new AccountPrecompute(t, worker, swing::add);
		Object[] seen = new Object[2];
		pre.request(RAIDS, null, () ->
		{
			seen[0] = pre.account(true);
			seen[1] = pre.account(false);
		});
		worker.shutdown();
		worker.awaitTermination(20, TimeUnit.SECONDS);
		swing.runAll();
		assertNull(seen[0]);
		assertNotNull(seen[1]);
	}

	@Test
	public void aBurstDrawsOnceWithTheLatestRequest() throws Exception
	{
		Tracker t = tracker();
		ExecutorService worker = Executors.newSingleThreadExecutor();
		Queue swing = new Queue();
		AccountPrecompute pre = new AccountPrecompute(t, worker, swing::add);
		List<Integer> drawn = new ArrayList<>();
		for (int i = 0; i < 50; i++)
		{
			int n = i;
			pre.request(RAIDS, PRICES, () -> drawn.add(n));
		}
		worker.shutdown();
		assertTrue(worker.awaitTermination(20, TimeUnit.SECONDS));
		swing.runAll();
		assertEquals(Collections.singletonList(49), drawn);
	}

	@Test
	public void stoppedDoesNothing() throws Exception
	{
		ExecutorService worker = Executors.newSingleThreadExecutor();
		Queue swing = new Queue();
		AccountPrecompute pre = new AccountPrecompute(tracker(), worker, swing::add);
		pre.stop();
		List<Integer> drawn = new ArrayList<>();
		pre.request(RAIDS, PRICES, () -> drawn.add(1));
		worker.shutdown();
		worker.awaitTermination(5, TimeUnit.SECONDS);
		swing.runAll();
		assertTrue(drawn.isEmpty());
	}

	/** A tracker that counts how often the whole account is worked out. */
	private static final class CountingTracker extends Tracker
	{
		final AtomicInteger accounts = new AtomicInteger();

